INSERT INTO public.deployment_targets VALUES ('container', 'Container', 'Docker/OCI container runtime', 'box', '["backend-service", "worker", "database", "cache", "message-broker", "monitoring", "logging", "rest-api", "graphql-api", "grpc-service", "websocket-server", "auth-provider", "ai-service", "search-engine"]', '{}', 3, '2026-02-06 23:50:51.037528+00');
