INSERT INTO public.deployment_targets VALUES ('managed-cloud', 'Managed Cloud', 'Fully managed cloud service (RDS, ElastiCache, etc.)', 'cloud', '["database", "cache", "message-broker", "search-engine", "auth-provider", "monitoring", "ai-service"]', '{}', 5, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('bare-metal', 'Bare Metal', 'Physical server or VM', 'hard-drive', '["backend-service", "database", "cache", "message-broker", "k8s-cluster"]', '{}', 6, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('edge', 'Edge', 'Edge computing / CDN worker', 'wifi', '["cdn", "backend-service", "cache"]', '{}', 7, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('desktop-native', 'Desktop Native', 'Native desktop application (Electron, Tauri)', 'monitor', '["desktop-app", "frontend-app"]', '{}', 9, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('embedded', 'Embedded', 'Embedded system or IoT device', 'cpu', '["backend-service", "worker"]', '{}', 10, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('wasm', 'WebAssembly', 'WebAssembly runtime (browser or server)', 'code', '["frontend-app", "backend-service", "worker"]', '{}', 11, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('kubernetes-pod', 'Kubernetes Pod', 'Kubernetes pod execution', 'box', '["backend-service", "worker", "database", "cache", "message-broker"]', '{}', 12, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('static-hosting', 'Static Hosting', 'Static file hosting (S3, Netlify, Vercel)', 'upload-cloud', '["static-site", "frontend-app", "cdn"]', '{}', 13, '2026-02-06 23:50:51.037528+00');
INSERT INTO public.deployment_targets VALUES ('mobile-device', 'Mobile Device', 'iOS or Android device', 'smartphone', '["mobile-app", "frontend-app", "mobile-device"]', '{}', 8, '2026-02-06 23:50:51.037528+00');

-- ── scope_archetypes (7 rows, complete) ──
INSERT INTO public.scope_archetypes VALUES ('simple-web-app', 'Simple Web App', 'Traditional web application with frontend + backend + database. Includes blogs, dashboards, CRUD apps, landing pages with forms, admin panels, small SaaS tools. DEFAULT when no other archetype clearly applies.', '["web app", "website", "dashboard", "CRUD", "landing page", "admin panel", "SaaS", "blog", "todo", "form"]', 'simple-web-app alone: 5-10 requirements', 'SIMPLE WEB APP guidance:
The default shape is one frontend, one backend API, one database. Technical components per feature should converge toward this shape -- only introduce additional components when the specification demands a genuinely distinct deployable unit (e.g., a separate worker process for background jobs, a dedicated search index).
- Authentication, authorization, and session management are PART OF the core application feature unless the spec explicitly describes a standalone identity service.
- The frontend serves the user-facing interface. The backend API handles business logic and data access. The database persists state. That is the complete component picture for most simple web apps.
- File uploads, email sending, payment processing are integration points on existing components, not separate technical components, unless the spec calls for dedicated microservices for them.
- Deployment, hosting, TLS, CI/CD, backups, and security compliance are NOT features. They will be mapped to infrastructure containers or deployment target metadata in the architecture phase.', 'SIMPLE WEB APP -- Reference Architecture:
The canonical shape is: frontend-app + backend-service (or rest-api) + database. Add auth-provider only when authentication is a core requirement with its own data store.

CONTAINER HIERARCHY:
- Logical: ONE application-module boundary groups all primary nodes. This is the only logical container needed.
- Infrastructure (when in scope): cloud-project > vpc > application-module > [primary nodes].
- Do NOT add subnets, compute containers, or docker-containers unless self-hosted. Keep it flat.
- Do NOT split the backend into multiple API nodes per feature domain. One backend handles all routes.
- Do NOT split the database unless the spec explicitly requires separate data stores (e.g., relational + document store).
- Do NOT create nodes for deployment concerns (TLS, backups, CI/CD, monitoring). These are platform-provided.

WHAT THE NODES DO:
- frontend-app: Serves the entire user-facing interface. ALL UI features are implemented here.
- backend-service/rest-api: Handles ALL business logic, data validation, API routes, and integration points. One node, many responsibilities.
- database: Persists ALL application state. Schema design handles multi-domain concerns, not separate database nodes.', '["Database", "Logical", "Networking", "Services"]', '{"max": 10, "min": 5}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 1, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('cloud-native', 'Cloud Native', 'Distributed systems designed for cloud elasticity. Microservices, containerized workloads, managed cloud services, auto-scaling. Signals: multiple independent services, event-driven patterns, service mesh, multi-team ownership.', '["microservice", "containerized", "auto-scaling", "event-driven", "service mesh", "distributed", "kubernetes", "docker", "cloud-native"]', 'cloud-native, enterprise-platform: 10-20 requirements', 'CLOUD-NATIVE guidance:
First determine whether the project expects containerized instances behind a single deployment (Docker Compose, ECS task) or genuinely independent microservices with separate deployment lifecycles. This distinction controls everything:
- Docker-instance style: Features map to logical modules within a shared deployment. Technical components describe the module boundaries (e.g., "User API module", "Order processing module") but they share infrastructure (one load balancer, one database cluster).
- Full microservice style: Each feature maps to an independently deployable service boundary. Technical components per feature describe what that service owns: its API, its data store, and any async channels it produces/consumes.
Infrastructure features (API gateway, service mesh, message broker, observability stack) ARE valid when they represent distinct deployable units the team must build or configure, not when they are managed platform services.
- A message broker is a valid technical component when services communicate asynchronously through it.
- An API gateway is valid when the spec requires custom routing, rate limiting, or auth aggregation beyond what the cloud provider offers natively.
- Observability is valid ONLY when the spec requires a custom metrics/tracing pipeline, not when using managed APM.', 'CLOUD-NATIVE -- Reference Architecture:
Each service domain gets its own microservice-boundary containing the nodes that service owns (typically its API + its data store, or its API + a worker).

CONTAINER HIERARCHY -- DOCKER-INSTANCE STYLE (Docker Compose / single ECS task):
- Logical: ONE application-module boundary wraps all service modules. Individual modules are primary nodes, not sub-containers.
- Infrastructure: docker-compose > [application-module > primary nodes]. Or cloud-project > vpc > application-module.
- Services share infrastructure (one load balancer, one database cluster). Edges between service nodes represent in-process or local-network calls.

CONTAINER HIERARCHY -- FULL MICROSERVICE STYLE:
- Logical: Each service domain gets a microservice-boundary container. Primary nodes (API, database, worker) are children of their boundary.
- Infrastructure: cloud-project > vpc > [microservice-boundary A, microservice-boundary B, ...]. Add k8s-cluster > k8s-namespace when Kubernetes is specified.
- Shared infrastructure nodes (api-gateway, message-broker, load-balancer) sit at the vpc level, NOT inside any microservice boundary.

WHAT THE NODES DO:
- api-gateway / load-balancer: Routes external traffic to the correct service. Only create when multiple services need a unified entry point.
- message-broker / event-stream: Enables async inter-service communication. Create when services decouple via events or queues. The broker is a SHARED node at the infrastructure level.
- Each microservice-boundary''s API node handles that domain''s business logic. Its database node owns that domain''s data.', '["Database", "Infrastructure", "Logical", "Messaging", "Networking", "Services"]', '{"max": 20, "min": 10}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 2, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('desktop-app', 'Desktop App', 'Native or hybrid desktop application (Electron, Tauri, MAUI, WPF, Qt). May or may not have a cloud backend. Signals: "desktop", "native app", "installable", "offline-first", cross-platform desktop.', '["desktop", "native app", "installable", "offline-first", "electron", "tauri", "WPF", "Qt", "MAUI", "cross-platform desktop"]', 'desktop-app, mobile-app alone: 6-12 requirements', 'DESKTOP APP guidance:
The desktop-app runtime (Electron, Tauri, WPF, Qt) is the ROOT CONTAINER in the architecture phase, not a feature. Do not create a feature for "the desktop shell".
- Split features by what the application DOES for the user, not by UI vs backend.
- Local storage vs remote API is a fundamental architectural split. If the app works offline, local persistence is a technical component of the features that need it. If the app requires a remote backend, that backend is ONE shared technical component (not split per API endpoint).
- Distribution, packaging, auto-update, and installers are METADATA on the desktop-app container. They are NOT features and NOT technical components.
- If the app embeds a local database (SQLite, LevelDB), that is a technical component of the features that persist data locally.', 'DESKTOP APP -- Reference Architecture:
The desktop-app container IS the root. It represents the runtime (Electron, Tauri, WPF, Qt).

CONTAINER HIERARCHY:
- desktop-app (root container) > [frontend-app, local database (if offline-capable)].
- If a remote backend exists: create a SEPARATE application-module boundary outside the desktop-app for the backend API + cloud database. The desktop-app''s frontend-app connects to the backend via an edge (rest/graphql/websocket).
- Infrastructure containers are NOT needed unless the remote backend has its own deployment topology.
- Do NOT nest the remote backend inside the desktop-app container. They are separate deployment domains.
- Do NOT create cloud infrastructure (VPC, cloud-project) unless the spec mentions cloud sync or remote storage.

WHAT THE NODES DO:
- desktop-app (container): The installable application shell. Distribution, packaging, auto-update are METADATA on this container, not child nodes.
- frontend-app (inside desktop-app): The UI layer rendered by the desktop runtime.
- database (inside desktop-app, if offline): Local data persistence (SQLite, LevelDB). Handles offline state, caching, and local-first data.
- backend-service (outside desktop-app, if remote): Cloud API serving data to the desktop client.', '["Database", "Logical", "Networking", "Services"]', '{"max": 12, "min": 6}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 3, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('mobile-app', 'Mobile App', 'Native or cross-platform mobile application (React Native, Flutter, Swift, Kotlin). Usually has a cloud backend. Signals: "mobile", "iOS", "Android", "app store".', '["mobile", "iOS", "Android", "app store", "React Native", "Flutter", "Swift", "Kotlin", "cross-platform mobile"]', 'desktop-app, mobile-app alone: 6-12 requirements', 'MOBILE APP guidance:
The mobile client itself is a shared technical component across features -- do not create a separate feature for "the mobile app shell".
- Features should reflect user-facing capability domains (e.g., "User Profile & Settings", "Content Feed", "Messaging").
- Push notifications, offline sync, and deep linking are ASPECTS of the features that use them, not standalone features. Only create a standalone feature for these when the spec describes dedicated backend infrastructure to support them (e.g., a custom push notification service).
- Backend API is typically ONE shared component. Only split into separate services when the spec explicitly calls for microservice decomposition.
- Device-specific capabilities (camera, GPS, biometrics) are technical details of the features that use them, not separate features.', 'MOBILE APP -- Reference Architecture:
The mobile-app node is the client entry point. The cloud backend (if any) is a separate container hierarchy.

CONTAINER HIERARCHY:
- Client side: mobile-app as a primary node (NOT a container unless it has internal sub-components). If the app has distinct modules (e.g., main app + widget extension), use mobile-app as a container.
- Backend side: application-module boundary > [backend-service, database, auth-provider]. Use microservice-boundaries only when the backend is genuinely distributed with separate deployment lifecycles.
- Infrastructure (when in scope): cloud-project > vpc > [application-module > backend nodes]. The mobile-app sits OUTSIDE infrastructure -- it runs on user devices.

WHAT THE NODES DO:
- mobile-app: The client application running on iOS/Android. All device-side capabilities (camera, GPS, biometrics, push notification handling) are implemented here.
- backend-service: ONE shared API serving the mobile client. Handles auth, business logic, and data access.
- auth-provider: Only when the spec requires a dedicated identity service separate from the backend.
- database: Persists all backend state. One node unless the spec requires separate stores.', '["Database", "Logical", "Networking", "Services"]', '{"max": 12, "min": 6}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 4, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('iot-embedded', 'IoT / Embedded', 'Hardware-integrated systems, sensor networks, firmware, edge computing, industrial control. Signals: "sensor", "firmware", "embedded", "IoT", "edge device", "MQTT", "real-time control", "hardware".', '["sensor", "firmware", "embedded", "IoT", "edge device", "MQTT", "real-time control", "hardware", "edge computing", "industrial"]', 'iot-embedded: 6-14 requirements (often has hardware + software split)', 'IOT/EMBEDDED guidance:
Clearly separate device-side concerns from cloud-side concerns. These are fundamentally different deployment domains.
- Device side: The embedded system is the ROOT CONTAINER in the architecture phase. Firmware, sensor drivers, local processing, and edge compute are technical components of device-side features. Do not decompose hardware sub-components unless the spec explicitly requires that granularity (e.g., separate firmware modules for different sensor arrays).
- Cloud side: Data ingestion, storage, dashboards, and device management are cloud-side features with their own technical components (APIs, databases, frontend apps).
- Device-to-cloud communication (MQTT, CoAP, HTTP, gRPC) is an EXPLICIT EDGE between device and cloud in the architecture. In the feature phase, it is a technical component of the connectivity feature describing the protocol and payload format.
- OTA firmware updates are a feature ONLY when the spec requires over-the-air update capability. If mentioned, it spans both device-side (update agent) and cloud-side (firmware repository, rollout management).
- Sensor calibration, diagnostics, and health monitoring are aspects of device management, not standalone features.', 'IOT/EMBEDDED -- Reference Architecture:
Two distinct deployment domains: device-side and cloud-side. They connect via explicit edges representing the communication protocol.

CONTAINER HIERARCHY:
- Device side: embedded-system (root container) > [firmware/application nodes, local storage if needed]. The embedded-system container represents the physical device or device class.
- Cloud side: cloud-project > vpc > [application-module or microservice-boundaries > ingestion API, database, dashboard frontend, device management service].
- The edge between embedded-system children and cloud-side API nodes represents the device-to-cloud protocol (MQTT, CoAP, HTTP, gRPC). This is a RUNTIME EDGE, not containment.
- Do NOT nest cloud nodes inside the embedded-system container or vice versa.
- Do NOT create VPC/subnet unless the cloud side has multiple services requiring network topology.

WHAT THE NODES DO:
- embedded-system (container): Represents the device hardware + runtime. Sensor drivers, local processing, and edge compute are child nodes when the spec requires that granularity; otherwise one firmware node covers it.
- Ingestion API (cloud): Receives telemetry, commands, and status from devices. This is the cloud entry point for device communication.
- Device management service (cloud): Handles device registration, configuration, OTA updates (when OTA is in scope), and fleet management.
- Dashboard/frontend (cloud): Visualizes device data, fleet status, and alerts for human operators.', '["Database", "External", "Hardware", "Logical", "Messaging", "Networking", "Services"]', '{"max": 14, "min": 6}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 5, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('enterprise-platform', 'Enterprise Platform', 'Large-scale multi-domain system with complex business rules, many user roles, compliance requirements, and integration points. Signals: "enterprise", "multi-tenant", "compliance", "audit trail", "role-based access across departments", 10+ distinct business processes.', '["enterprise", "multi-tenant", "compliance", "audit trail", "role-based access", "departments", "business processes", "integration points"]', 'cloud-native, enterprise-platform: 10-20 requirements', 'ENTERPRISE PLATFORM guidance:
Features should align to business domains or bounded contexts. Each feature represents a coherent business capability that could be owned by a team.
- Cross-cutting concerns (authentication, authorization, audit logging, compliance reporting, notification delivery) CAN be standalone features when the spec describes dedicated subsystems with their own APIs, data stores, and operational requirements. An "Audit & Compliance" feature is valid when the spec requires a dedicated audit log store with retention policies and compliance reporting.
- Multi-tenancy is an architectural concern that influences all features. It is NOT a standalone feature. Tenant isolation, data partitioning, and tenant-specific configuration are design constraints on the other features.
- Integration points with external systems (ERP, CRM, payment processor, identity provider) should be grouped by business domain. "ERP Integration" is a valid feature if it has its own API adapter, data mapping, and sync logic. Three separate integrations in the same domain should be ONE feature.
- Role-based access control spanning multiple departments is typically part of the auth/identity feature, not a per-department feature.', 'ENTERPRISE PLATFORM -- Reference Architecture:
Multiple bounded-context or microservice-boundary containers, each owning a business domain. This is the most complex archetype.

CONTAINER HIERARCHY:
- Logical: Each business domain gets a bounded-context or microservice-boundary container. Primary nodes (domain API, domain database, domain workers) are children of their boundary.
- Cross-cutting services (auth, audit, notifications) that are STANDALONE SUBSYSTEMS sit in their own boundary at the same level as domain boundaries. They are NOT children of any single domain.
- Infrastructure (when in scope): cloud-project > vpc > [all domain boundaries, cross-cutting boundaries]. Add k8s-cluster when containerized orchestration is specified.
- api-gateway sits at the vpc level as the unified entry point. message-broker sits at the vpc level for inter-domain events. Neither is inside any domain boundary.

WHAT THE NODES DO:
- Each domain boundary''s API node: Handles that domain''s business logic, enforces domain rules, and exposes the domain''s capabilities. It owns its data and does not directly access another domain''s database.
- Each domain boundary''s database: Stores that domain''s data. Cross-domain queries go through APIs, not direct database access.
- api-gateway: Unified entry point that routes to domain APIs. Handles auth token validation, rate limiting, and request routing.
- message-broker: Enables event-driven communication between domains. Domain A publishes events; Domain B subscribes. The broker is the decoupling layer.
- Cross-cutting service nodes (auth, audit, notifications): Standalone services with their own API and data store. Other domains call them via edges.', '["AI & ML", "Automation", "Database", "Infrastructure", "Logical", "Messaging", "Networking", "Observability", "Services"]', '{"max": 20, "min": 10}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 7, '2026-03-08 04:25:49.210258+00');
INSERT INTO public.scope_archetypes VALUES ('data-pipeline', 'Data Pipeline', 'ETL, analytics, ML training, data warehouse, streaming data processing. Signals: "pipeline", "ETL", "data lake", "warehouse", "batch processing", "streaming", "analytics platform".', '["pipeline", "ETL", "data lake", "warehouse", "batch processing", "streaming", "analytics platform", "ML training", "data processing"]', 'data-pipeline: 5-10 requirements', 'DATA PIPELINE guidance:
Features should follow the source/sink/transform pattern:
- Source features describe where data comes from and how it is ingested (file upload, streaming ingestion, API polling, event capture).
- Transform features describe what processing happens: validation, enrichment, aggregation, ML inference. Each distinct transformation stage with different compute/scaling requirements can be a separate feature.
- Sink/serving features describe where processed data goes: data warehouse, search index, API for downstream consumers, dashboard/visualization.
- Each pipeline stage is a primary node in the architecture. Technical components should describe the actual processing unit (stream processor, batch job, ETL worker) not the orchestration around it.
- Orchestration and scheduling (Airflow, Step Functions, cron) are infrastructure unless the spec requires a CUSTOM workflow engine. Do not create a feature for "pipeline orchestration" when using a managed scheduler.
- Data quality, validation, and schema enforcement are part of the transform feature, not a separate feature.', 'DATA PIPELINE -- Reference Architecture:
Model the pipeline as a directed graph following the source -> transform -> sink pattern. Each stage is a primary node.

CONTAINER HIERARCHY:
- Logical: Use application-module boundaries to group related pipeline stages (e.g., "Ingestion Layer", "Processing Layer", "Serving Layer"). Each boundary contains the nodes for that stage.
- Infrastructure (when in scope): cloud-project > vpc > [pipeline boundaries]. If using managed orchestration (Airflow, Step Functions), the orchestrator is an infrastructure node at the vpc level, not inside a pipeline boundary.
- Streaming pipelines: event-stream or message-broker nodes sit BETWEEN stage boundaries as shared infrastructure, connecting producers to consumers via edges.

WHAT THE NODES DO:
- Source/ingestion nodes (backend-service or external-data): Capture data from external systems, file uploads, streaming sources, or API polling. Each distinct data source with different ingestion patterns can be a separate node.
- Transform nodes (backend-service/worker): Apply business logic, validation, enrichment, aggregation, or ML inference. Separate transform nodes when stages have different compute requirements or scaling profiles.
- Sink/serving nodes (database, search-engine, rest-api): Store processed data and serve it to downstream consumers. A data warehouse, a search index, and an analytics API are three separate nodes because they serve different access patterns.
- event-stream / message-broker: Connects pipeline stages in streaming architectures. This is a shared node, not duplicated per stage.', '["AI & ML", "Database", "Logical", "Messaging", "Networking", "Services"]', '{"max": 10, "min": 5}', 'MULTI-ARCHETYPE NOTE: This project spans ${archetypes}. Ensure features cleanly separate the concerns of each archetype domain. For example:
- iot-embedded + cloud-native: Device-side features are distinct from cloud-side features. The device-to-cloud boundary is an explicit integration point, not merged into one feature.
- mobile-app + cloud-native: The mobile client features are user-facing; the cloud backend features are service-domain-aligned. They connect via API contracts.
- data-pipeline + enterprise-platform: Pipeline stages are separate features from the business domain features that consume the processed data.
Do NOT merge concerns from different archetype domains into a single feature just to reduce count.', 'MULTI-ARCHETYPE: This project spans ${archetypes}. Apply these rules:
- Each archetype''s nodes are visually grouped in their own logical boundary or container hierarchy. Do NOT flatten everything into one boundary.
- Shared infrastructure (cloud-project, vpc) wraps ALL archetype domains. Do not duplicate infrastructure per archetype.
- Edges between archetype domains represent the integration contracts (e.g., device-to-cloud MQTT edge for iot-embedded + cloud-native, mobile-to-backend REST edge for mobile-app + cloud-native).
- When both archetypes prescribe a container hierarchy, nest them: cloud-project > vpc > [archetype-A boundaries, archetype-B boundaries].', 6, '2026-03-08 04:25:49.210258+00');

-- ── cloud_provider_patterns (15 rows, complete) ──
INSERT INTO public.cloud_provider_patterns VALUES (1, 'aws', 'simple-web-app', 'AWS DEPLOYMENT GUIDANCE FOR SIMPLE WEB APP:
- Frontend: S3 + CloudFront (static hosting). Use cdn role with technology "aws-cloudfront".
- Backend: Lambda + API Gateway (serverless) OR ECS Fargate (container). Prefer serverless for simple apps.
- Database: RDS (PostgreSQL/MySQL) or DynamoDB. Use the database role with the appropriate managed technology.
- Auth: Cognito if dedicated auth is needed. Otherwise auth is handled by the backend.
- Storage: S3 for file uploads and static assets. Use object-storage role with technology "aws-s3".
- Monitoring: CloudWatch for logs and metrics. Only create a monitoring node if the spec explicitly requires custom observability.
- Infrastructure hierarchy: cloud-project ("AWS Account") > vpc > application-module > [nodes]. No subnets unless multiple AZs are specified.
- VM compute: When the spec requires explicit VM-level visibility (e.g., custom AMI, GPU, specific instance types), use role "virtual-machine" with technology "ec2" and a descriptive label (e.g., "EC2 - API Server"). Do NOT use cloud-project for compute instances. Prefer Lambda/Fargate over EC2 unless the spec explicitly requires VM control.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (2, 'aws', 'cloud-native', 'AWS DEPLOYMENT GUIDANCE FOR CLOUD-NATIVE:
- Services: ECS Fargate or EKS (Kubernetes). Use ECS for simpler setups, EKS when K8s features are required.
- API Gateway: AWS API Gateway or ALB. Place at the vpc level.
- Messaging: SQS for queues, SNS for pub/sub, EventBridge for event routing, Kinesis for streaming. Choose based on the communication pattern.
- Databases: RDS per service boundary (if data isolation is required) or Aurora Serverless for shared access.
- Storage: S3 for shared data lake, artifacts, or inter-service file exchange. Use object-storage role with technology "aws-s3".
- Infrastructure hierarchy: cloud-project > vpc > [microservice boundaries]. Add k8s-cluster only for EKS.
- VM compute: When a service requires a dedicated VM (e.g., stateful workloads, custom OS, GPU), use role "virtual-machine" with technology "ec2" and label it "EC2 - <purpose>" (e.g., "EC2 - ML Training"). Prefer Fargate/EKS pods for stateless services.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (3, 'aws', 'data-pipeline', 'AWS DEPLOYMENT GUIDANCE FOR DATA PIPELINE:
- Ingestion: Kinesis Data Streams or Kinesis Firehose for streaming; S3 + Lambda for batch.
- Transform: Glue (batch ETL), Lambda (event-driven), EMR (big data).
- Storage: S3 (data lake) with object-storage role and technology "aws-s3", Redshift (warehouse), DynamoDB (serving).
- Orchestration: Step Functions or MWAA (managed Airflow). These are infrastructure nodes, not pipeline stage nodes.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (4, 'azure', 'simple-web-app', 'AZURE DEPLOYMENT GUIDANCE FOR SIMPLE WEB APP:
- Frontend: Azure Static Web Apps or Blob Storage + CDN.
- Backend: Azure Functions (serverless) or App Service (PaaS).
- Database: Azure SQL or Cosmos DB.
- Auth: Azure AD B2C if dedicated auth is needed.
- Storage: Azure Blob Storage for file uploads and static assets. Use object-storage role with technology "azure-blob-storage".
- Infrastructure hierarchy: cloud-project ("Azure Subscription") > vpc ("Virtual Network") > application-module > [nodes].
- VM compute: When the spec requires explicit VM-level visibility, use role "virtual-machine" with technology "azure-vm" and a descriptive label (e.g., "Azure VM - Web Server"). Prefer App Service/Functions over VMs unless explicit VM control is required.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (5, 'azure', 'cloud-native', 'AZURE DEPLOYMENT GUIDANCE FOR CLOUD-NATIVE:
- Services: Azure Container Apps or AKS (Kubernetes).
- API Gateway: Azure API Management or Application Gateway.
- Messaging: Service Bus (queues/topics), Event Grid (events), Event Hubs (streaming).
- Databases: Azure SQL per service or Cosmos DB for multi-model needs.
- Storage: Azure Blob Storage for shared data and artifacts. Use object-storage role with technology "azure-blob-storage".
- VM compute: When a service requires a dedicated VM (e.g., legacy workloads, custom OS, GPU), use role "virtual-machine" with technology "azure-vm" and label it "Azure VM - <purpose>". Prefer Container Apps/AKS for stateless services.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (6, 'gcp', 'simple-web-app', 'GCP DEPLOYMENT GUIDANCE FOR SIMPLE WEB APP:
- Frontend: Cloud Storage + Cloud CDN, or Firebase Hosting.
- Backend: Cloud Run (container) or Cloud Functions (serverless).
- Database: Cloud SQL (PostgreSQL/MySQL) or Firestore.
- Auth: Firebase Auth or Identity Platform.
- Storage: Google Cloud Storage for file uploads and static assets. Use object-storage role with technology "gcs".
- Infrastructure hierarchy: cloud-project ("GCP Project") > vpc > application-module > [nodes].
- VM compute: When the spec requires explicit VM-level visibility, use role "virtual-machine" with technology "gce-instance" and a descriptive label (e.g., "GCE - API Server"). Prefer Cloud Run/Functions over GCE unless explicit VM control is required.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (7, 'gcp', 'cloud-native', 'GCP DEPLOYMENT GUIDANCE FOR CLOUD-NATIVE:
- Services: Cloud Run (simpler) or GKE (Kubernetes).
- API Gateway: Cloud Endpoints or Apigee.
- Messaging: Pub/Sub for all async patterns, Dataflow for streaming.
- Databases: Cloud SQL per service, Spanner for global distribution, Firestore for document needs.
- Storage: Google Cloud Storage for shared data lake and artifacts. Use object-storage role with technology "gcs".
- VM compute: When a service requires a dedicated VM (e.g., stateful workloads, custom OS, GPU/TPU), use role "virtual-machine" with technology "gce-instance" and label it "GCE - <purpose>". Prefer Cloud Run/GKE for stateless services.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (8, 'vercel', 'simple-web-app', 'VERCEL DEPLOYMENT GUIDANCE:
- Frontend: Vercel edge deployment (built-in). No separate CDN or static hosting node needed.
- Backend: Vercel Serverless Functions or API Routes (Next.js). This IS the backend node -- do NOT create a separate server.
- Database: Use an external managed database (Vercel Postgres, PlanetScale, Supabase). Create a database node with the appropriate technology.
- Infrastructure: Vercel handles routing, TLS, CDN automatically. Do NOT create load-balancer, cdn, or vpc nodes. The infrastructure hierarchy is flat: application-module > [frontend-app, backend-service/rest-api, database].', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (9, 'netlify', 'simple-web-app', 'NETLIFY DEPLOYMENT GUIDANCE:
- Frontend: Netlify edge deployment (built-in). No separate CDN node.
- Backend: Netlify Functions (serverless). This IS the backend node.
- Database: External managed database (Supabase, PlanetScale, etc.).
- Infrastructure: Netlify handles routing, TLS, CDN. Keep hierarchy flat: application-module > [frontend-app, backend-service, database].', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (10, 'self-hosted', 'simple-web-app', 'SELF-HOSTED DEPLOYMENT GUIDANCE:
- Use docker-compose as the infrastructure container wrapping all services.
- Frontend: Nginx or Caddy serving static files (frontend-app with appropriate technology).
- Backend: Container running the application server.
- Database: Container running the database engine.
- Infrastructure hierarchy: docker-compose > application-module > [nodes]. Include a load-balancer/reverse-proxy node if TLS termination or routing is needed.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (11, 'self-hosted', 'cloud-native', 'SELF-HOSTED CLOUD-NATIVE DEPLOYMENT GUIDANCE:
- Use docker-compose for single-host or k8s-cluster for multi-host.
- Each microservice boundary maps to a set of containers.
- Include a reverse proxy (Nginx, Traefik, Caddy) as the entry point.
- Message broker: RabbitMQ or Redis for queues; Kafka for streaming.', '2026-08-31 20:06:46.510548+00');
INSERT INTO public.cloud_provider_patterns VALUES (12, 'aws', 'enterprise-platform', 'AWS DEPLOYMENT GUIDANCE FOR ENTERPRISE PLATFORM:
- Compute: EKS (technology "aws-eks") for microservice workloads across multiple teams. Use ECS (technology "aws-ecs") for simpler internal services that don''t need full Kubernetes.
- Networking: Multi-account strategy with AWS Organizations. Use Transit Gateway for cross-account/cross-VPC connectivity. Place shared services (logging, auth, DNS) in a dedicated shared-services account.
- API Layer: API Gateway (technology "aws-api-gateway") for external APIs; internal services communicate via ALB (technology "aws-elb") or service mesh (App Mesh / Istio on EKS).
- Auth: Cognito (technology "aws-cognito") for customer-facing identity; IAM roles + STS for service-to-service auth across accounts.
- Messaging: SNS (technology "aws-sns") for cross-service notifications, SQS for decoupled queues, EventBridge (technology "aws-eventbridge") for event-driven integrations between bounded contexts.
- Databases: RDS (technology "aws-rds") or Aurora per service boundary for data isolation. DynamoDB for high-throughput key-value needs. Redshift (technology "aws-redshift") for enterprise analytics warehouse.
- Observability: CloudWatch (technology "aws-cloudwatch") for centralized logging and metrics across all accounts. Use cross-account log aggregation.
- Secrets: Secrets Manager (technology "aws-secrets-manager") for credentials, API keys, and cross-service secrets rotation.
- Storage: S3 (technology "aws-s3") for shared artifacts, data lake, and inter-service file exchange.
- Infrastructure hierarchy: cloud-project ("AWS Organization") > cloud-project ("Account") > vpc > [bounded-context / microservice-boundary] > [nodes]. Use k8s-cluster for EKS workloads, ecs-cluster for ECS workloads.
- CI/CD: Step Functions (technology "aws-step-functions") for complex deployment orchestration and approval workflows.', '2026-08-31 20:06:46.860628+00');
INSERT INTO public.cloud_provider_patterns VALUES (13, 'aws', 'iot-embedded', 'AWS DEPLOYMENT GUIDANCE FOR IOT / EMBEDDED:
- Device Connectivity: AWS IoT Core for MQTT/HTTPS device connections. Use device shadows for offline state synchronization. Model each device class as a worker node.
- Edge Computing: AWS IoT Greengrass for local compute on edge devices. Run ML inference, data filtering, and local actions at the edge before sending to cloud.
- Ingestion: Kinesis Data Streams (technology "aws-kinesis") for high-throughput telemetry ingestion. Use Kinesis Firehose for auto-delivery to S3/Redshift.
- Processing: Lambda (technology "aws-lambda") for event-driven processing of IoT rules. Step Functions (technology "aws-step-functions") for multi-step device provisioning workflows.
- Storage: S3 (technology "aws-s3") for raw telemetry data lake. DynamoDB for device registry and real-time state lookups. Use object-storage role with technology "aws-s3".
- Analytics: Kinesis Data Analytics or EMR (technology "aws-emr") for streaming analytics on device data.
- Monitoring: CloudWatch (technology "aws-cloudwatch") for fleet health metrics, device connectivity monitoring, and alerting on anomalous telemetry patterns.
- Security: IoT Device Defender for device audit. Secrets Manager (technology "aws-secrets-manager") for certificate and key management.
- Infrastructure hierarchy: cloud-project ("AWS Account") > vpc > [iot-hub / edge-gateway] > [worker nodes for device classes]. Keep cloud-side processing in a separate application-module from the edge tier.', '2026-08-31 20:06:46.860628+00');
INSERT INTO public.cloud_provider_patterns VALUES (14, 'aws', 'desktop-app', 'AWS DEPLOYMENT GUIDANCE FOR DESKTOP APP:
- Auth: Cognito (technology "aws-cognito") for user authentication and token management. Use Cognito User Pools for sign-up/sign-in and Identity Pools for temporary AWS credentials from the desktop client.
- Updates & Distribution: S3 (technology "aws-s3") for hosting auto-update binaries, installers, and delta patches. CloudFront (technology "aws-cloudfront") as CDN for fast global distribution of update artifacts.
- Backend API: API Gateway (technology "aws-api-gateway") + Lambda (technology "aws-lambda") for serverless backend endpoints the desktop app calls. Use REST or WebSocket APIs depending on real-time needs.
- Database: RDS (technology "aws-rds") or DynamoDB for user data, preferences, and licensing state.
- File Sync: S3 for cloud file storage with per-user prefixes. Use pre-signed URLs for secure direct uploads/downloads from the desktop client.
- Monitoring: CloudWatch (technology "aws-cloudwatch") for backend API metrics and error tracking. Client-side telemetry can be sent via Kinesis (technology "aws-kinesis") or direct API calls.
- Infrastructure hierarchy: cloud-project ("AWS Account") > vpc > application-module ("Backend Services") > [api-gateway, lambda, database]. The desktop-app node sits outside the cloud hierarchy as a client.
- Licensing: Use DynamoDB or RDS to track license keys and seat counts. Lambda handles license validation API.', '2026-08-31 20:06:46.860628+00');
INSERT INTO public.cloud_provider_patterns VALUES (15, 'aws', 'mobile-app', 'AWS DEPLOYMENT GUIDANCE FOR MOBILE APP:
- Auth: Cognito (technology "aws-cognito") for user authentication, social sign-in (Google, Apple, Facebook), and token management. Use Hosted UI or embed Cognito SDK in the mobile app.
- API: AppSync (technology "aws-appsync") for GraphQL API with real-time subscriptions (ideal for chat, feeds, live updates). Use API Gateway (technology "aws-api-gateway") + Lambda (technology "aws-lambda") for REST endpoints where GraphQL is not needed.
- Push Notifications: SNS (technology "aws-sns") for cross-platform push notifications (APNs for iOS, FCM for Android). Model as a message-broker node with technology "aws-sns".
- Media Storage: S3 (technology "aws-s3") for user-uploaded photos, videos, and documents. Use CloudFront (technology "aws-cloudfront") for fast media delivery. Pre-signed URLs for secure direct upload from mobile devices.
- Database: DynamoDB for user profiles, session data, and high-velocity reads. RDS (technology "aws-rds") for relational data needs.
- Offline & Sync: AppSync provides built-in offline data sync and conflict resolution for mobile clients.
- Monitoring: CloudWatch (technology "aws-cloudwatch") for backend metrics. Use Kinesis (technology "aws-kinesis") for client-side analytics event ingestion at scale.
- Infrastructure hierarchy: cloud-project ("AWS Account") > vpc > application-module ("Backend") > [appsync/api-gateway, lambda, database, sns]. The mobile-app node sits outside the cloud hierarchy as a client device (mobile-device role).
- Real-time: EventBridge (technology "aws-eventbridge") for backend event routing between services (e.g., order placed triggers notification).', '2026-08-31 20:06:46.860628+00');

