INSERT INTO public.technology_catalog VALUES ('aws-sns', 'AWS SNS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-sns.png', '#FF4F8B', '["event-stream", "message-broker"]', '{"purpose": "AWS-native pub/sub messaging service for fan-out notifications, A2A and A2P messaging. Best for decoupling microservices via topic-based fan-out, sending push notifications, and triggering multiple SQS queues or Lambda functions from a single event. Use SNS+SQS fan-out pattern for reliable multi-subscriber delivery. Not suited for ordered message processing (use SQS FIFO) or event replay (use Kinesis).", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using SNS for ordered processing without FIFO topics", "Relying on SNS for durable event replay (use Kinesis or EventBridge)", "Sending large payloads directly (use S3 references for >256KB)", "Not setting up DLQs on subscriptions", "Using SNS when simple point-to-point queuing suffices (use SQS directly)"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/sns/"}, "bestPractices": ["Use SNS+SQS fan-out pattern for reliable multi-subscriber delivery", "Enable message filtering policies to reduce unnecessary processing", "Use FIFO topics when message ordering and deduplication matter", "Set up dead-letter queues on subscriptions for failed deliveries", "Use message attributes for metadata instead of embedding in body"], "sdkInitPattern": "import { SNSClient, PublishCommand } from ''@aws-sdk/client-sns'';\r\n\r\nconst sns = new SNSClient({});\r\nawait sns.send(new PublishCommand({\r\n  TopicArn: process.env.ORDERS_TOPIC_ARN,\r\n  Message: JSON.stringify({ orderId }),\r\n}));", "securityGuidance": "Topic access policies name specific principals — a \"*\" principal on a topic is an open publish/subscribe door. HTTPS subscribers must VERIFY the message signature (the signing certificate flow) before trusting a delivery; confirmation and notification requests are forgeable otherwise. Encrypt topics with KMS where payloads are sensitive, and give every delivery path a dead-letter queue so failures are visible instead of silent."}', '[{"kind": "source", "path": "src/messaging/sns-client.ts", "priority": "essential", "description": "SNS publish and topic management client"}, {"kind": "config", "path": "src/messaging/sns-topics.ts", "priority": "recommended", "description": "Topic ARN definitions and subscription config"}, {"kind": "config", "path": "terraform/sns.tf", "priority": "recommended", "description": "SNS topic and subscription infrastructure"}]', '{"topicType": {"enum": ["standard", "fifo"], "type": "string", "label": "Topic Type", "default": "standard"}, "encryption": {"type": "boolean", "label": "Server-Side Encryption", "default": true}, "messageFiltering": {"type": "boolean", "label": "Message Filtering", "default": false}}', '["message-broker", "serverless-function", "worker"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''/client-sns'':80C ''a2a'':16B ''a2p'':18B ''access'':97C ''arn'':92C ''aw'':1A,3A,6B,78C ''await'':85C ''aws-nat'':5B ''aws-sdk'':77C ''base'':27B ''best'':20B ''certif'':121C ''confirm'':127C ''const'':81C ''dead'':149C ''dead-lett'':148C ''decoupl'':22B ''deliveri'':58B,126C,145C ''door'':111C ''encrypt'':134C ''event'':45B,69B ''everi'':144C ''failur'':153C ''fan'':13B,29B,50B ''fan-out'':12B,28B,49B ''fifo'':67B ''flow'':122C ''forgeabl'':132C ''function'':41B ''give'':143C ''https'':112C ''import'':73C ''instead'':156C ''json.stringify'':94C ''kinesi'':72B ''kms'':137C ''lambda'':40B ''letter'':150C ''messag'':9B,19B,63B,93C,117C ''microservic'':23B ''multi'':56B ''multi-subscrib'':55B ''multipl'':36B ''must'':114C ''name'':99C ''nativ'':7B ''new'':83C,87C ''notif'':15B,33B,129C ''open'':109C ''order'':62B ''orderid'':95C ''otherwis'':133C ''path'':146C ''pattern'':52B ''payload'':139C ''polici'':98C ''princip'':101C,103C ''process'':64B ''process.env.orders'':90C ''pub/sub'':8B ''publish/subscribe'':110C ''publishcommand'':75C,88C ''push'':32B ''queue'':38B,151C ''reliabl'':54B ''replay'':70B ''request'':130C ''sdk'':79C ''send'':31B ''sensit'':141C ''servic'':10B ''sign'':120C ''signatur'':118C ''silent'':158C ''singl'':44B ''sns'':2A,4A,47B,82C ''sns.send'':86C ''snsclient'':74C,84C ''specif'':100C ''sqs'':37B,48B,66B ''subscrib'':57B,113C ''suit'':60B ''topic'':26B,91C,96C,106C,135C ''topic-bas'':25B ''topicarn'':89C ''trigger'':35B ''trust'':124C ''use'':46B,65B,71B ''verifi'':115C ''via'':24B ''visibl'':155C');
INSERT INTO public.technology_catalog VALUES ('dotnet-worker', '.NET Worker Service (C#)', NULL, '#512BD4', '["worker", "backend-service"]', '{"purpose": "Long-running .NET background services (BackgroundService/IHostedService on the Generic Host): queue consumers, scheduled jobs, continuous processors. The worker-side sibling of ASP.NET Core (C#) — same DI/config/logging model without the HTTP stack.", "configMode": "code", "provenance": {"notes": "Stable hosting model (Generic Host/BackgroundService unchanged for years); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["BackgroundService", "Generic Host DI", "Serilog", "Polly", "Azure Service Bus / RabbitMQ clients", ".NET LTS"], "antiPatterns": ["async void event handlers — exceptions vanish; everything returns Task", "Scoped-service capture in singletons — resolve scopes per message, not per process", "Timer loops hand-rolled where the host''s PeriodicTimer/hosted scheduling does it correctly", "Swallowing poison messages in a catch-all — route them to a dead-letter with context"], "apiReference": {"docsUrl": "https://learn.microsoft.com/dotnet/"}, "bestPractices": ["One worker responsibility per service — a queue consumer and a scheduler are two nodes, not one process", "Honor the CancellationToken end-to-end; graceful shutdown IS the correctness story for consumers", "Idempotent message handling + explicit dead-letter policy — redelivery is a certainty", "Health checks even without HTTP (liveness file/port) so orchestrators can restart wedged workers", "Target the current .NET LTS; pin the SDK in global.json"], "sdkInitPattern": "dotnet new worker -n MyWorker --framework net8.0\\ndotnet add package Microsoft.Extensions.Http\\n// Program.cs\\nusing MyWorker;\\nvar builder = Host.CreateApplicationBuilder(args);\\nbuilder.Services.AddHostedService<Worker>();\\nawait builder.Build().RunAsync();", "securityGuidance": "Use User Secrets in development and managed identity or vault integration in production for connection strings and API keys. Implement health checks for all external dependencies. Use IServiceScopeFactory for scoped services inside BackgroundService. Run workers with least-privilege permissions. Implement circuit breaker patterns for external service calls.", "commonApiPatterns": [{"name": "Queue Consumer", "description": "Message queue consumer with scoped DI per message", "codeTemplate": "class QueueWorker : BackgroundService {\\n    private readonly IServiceScopeFactory _scopeFactory;\\n    protected override async Task ExecuteAsync(CancellationToken ct) {\\n        await foreach (var message in _queue.ReadAllAsync(ct)) {\\n            using var scope = _scopeFactory.CreateScope();\\n            var handler = scope.ServiceProvider.GetRequiredService<IMessageHandler>();\\n            await handler.HandleAsync(message, ct);\\n        }\\n    }\\n}"}, {"name": "Timed Worker", "description": "Periodic timer-based worker using PeriodicTimer", "codeTemplate": "class TimedWorker : BackgroundService {\\n    private readonly PeriodicTimer _timer = new(TimeSpan.FromMinutes(5));\\n    protected override async Task ExecuteAsync(CancellationToken ct) {\\n        while (await _timer.WaitForNextTickAsync(ct)) {\\n            await DoWorkAsync(ct);\\n        }\\n    }\\n}"}, {"name": "Health Check", "description": "Health checks for dependencies with custom publisher", "codeTemplate": "builder.Services.AddHealthChecks()\\n    .AddSqlServer(connectionString)\\n    .AddRabbitMQ(rabbitConnectionString);\\nbuilder.Services.AddHostedService<HealthCheckPublisher>();"}], "integrationPatterns": ["Microsoft.Extensions.Hosting for worker lifecycle and DI", "MassTransit or Azure Service Bus SDK for message consumption", "Polly for retry and circuit breaker resilience patterns", "OpenTelemetry .NET SDK for distributed tracing", "Docker + Kubernetes for containerized worker deployment"], "configurationTemplate": "// appsettings.json\\n{\\n  \"Logging\": {\\n    \"LogLevel\": { \"Default\": \"Information\" }\\n  },\\n  \"Worker\": {\\n    \"PollingInterval\": \"00:05:00\",\\n    \"BatchSize\": 100,\\n    \"MaxRetries\": 3\\n  },\\n  \"ConnectionStrings\": {\\n    \"DefaultConnection\": \"Server=...;Database=...\"\\n  }\\n}"}', '[{"kind": "source", "path": "Program.cs", "language": "csharp", "description": "Host builder and service registration"}, {"kind": "source", "path": "Worker.cs", "language": "csharp", "description": "Background worker implementation"}, {"kind": "config", "path": "App.csproj", "language": "xml", "description": ".NET project file"}, {"kind": "config", "path": "appsettings.json", "language": "json", "description": "Worker configuration"}]', '{"hosting": {"type": "enum", "label": "Hosting", "default": "container", "options": ["container", "windows-service"]}, "workKind": {"type": "enum", "label": "Work kind", "default": "queue-consumer", "options": ["queue-consumer", "scheduled", "continuous-loop"], "description": "What drives the worker — a queue binding, a timer, or a continuous BackgroundService loop"}}', '["database", "cache", "message-broker", "event-stream"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-31 20:06:52.233344+00', '.NET Worker', NULL, '''add'':61C ''api'':93C ''arg'':71C ''asp.net'':30B ''azur'':46C ''background'':11B ''backgroundservic'':40C,108C ''backgroundservice/ihostedservice'':13B ''breaker'':118C ''builder'':69C ''builder.build'':74C ''bus'':48C ''c'':4A,32B ''call'':123C ''check'':97C ''circuit'':117C ''client'':50C ''connect'':90C ''consum'':19B ''continu'':22B ''core'':31B ''depend'':101C ''develop'':80C ''di'':43C ''di/config/logging'':34B ''dotnet'':5A,53C ''extern'':100C,121C ''framework'':58C ''generic'':16B,41C ''health'':96C ''host'':17B,42C ''host.createapplicationbuilder'':70C ''http'':38B ''ident'':83C ''implement'':95C,116C ''insid'':107C ''integr'':86C ''iservicescopefactori'':103C ''job'':21B ''key'':94C ''least'':113C ''least-privileg'':112C ''long'':8B ''long-run'':7B ''lts'':52C ''manag'':82C ''microsoft.extensions.http'':63C ''model'':35B ''mywork'':57C,67C ''n'':56C,64C ''nawait'':73C ''nbuilder.services.addhostedservice'':72C ''ndotnet'':60C ''net'':1A,10B,51C ''net8.0'':59C ''new'':54C ''nuse'':66C ''nvar'':68C ''packag'':62C ''pattern'':119C ''permiss'':115C ''polli'':45C ''privileg'':114C ''processor'':23B ''product'':88C ''program.cs'':65C ''queue'':18B ''rabbitmq'':49C ''run'':9B,109C ''runasync'':75C ''schedul'':20B ''scope'':105C ''secret'':78C ''serilog'':44C ''servic'':3A,12B,47C,106C,122C ''sibl'':28B ''side'':27B ''stack'':39B ''string'':91C ''use'':76C,102C ''user'':77C ''vault'':85C ''without'':36B ''worker'':2A,6A,26B,55C,110C ''worker-sid'':25B');
INSERT INTO public.technology_catalog VALUES ('aws-s3', 'AWS S3', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-s3.png', '#FF9900', '["object-storage"]', '{"purpose": "AWS''s object storage service providing virtually unlimited, highly durable (99.999999999%) storage for any type of data. Use for static asset hosting, file uploads, data lake storage, backups, log archival, and as an origin for CloudFront CDN. S3 supports storage classes (Standard, Intelligent-Tiering, Glacier) for cost optimization across access patterns. Its event notification system integrates with Lambda, SQS, and SNS for event-driven processing. S3 is the default choice for storing files, media, and unstructured data in AWS architectures. Don''t use for data requiring POSIX filesystem semantics (use EFS instead). Don''t use for structured data that needs querying -- use a database. Avoid S3 Standard for archival data accessed less than once per year -- use S3 Glacier Deep Archive for massive cost savings.", "configMode": "declarative", "provenance": {"notes": "Storage classes incl. EXPRESS_ONEZONE + the July 2026 IA-transition change verified live.", "method": "live-docs", "sources": ["https://docs.aws.amazon.com/AmazonS3/latest/userguide/storage-class-intro.html", "https://aws.amazon.com/s3/storage-classes/", "https://aws.amazon.com/about-aws/whats-new/2026/07/s3-removes-30-day-transitions-standard-ia-one-zone-ia/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Amazon S3", "AWS SDK", "S3 Transfer Acceleration", "CloudFront", "S3 Event Notifications", "S3 Glacier", "S3 Intelligent-Tiering", "Terraform aws_s3_bucket"], "antiPatterns": ["Leaving buckets publicly accessible without a clear, justified reason", "Not enabling versioning for buckets storing user-uploaded content", "Storing all data in S3 Standard when lifecycle policies could save costs", "Using S3 for real-time database operations requiring low-latency queries", "Not encrypting buckets containing any form of user or business data", "Uploading large files without multipart upload causing timeout failures"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/s3/"}, "bestPractices": ["Block all public access by default and use presigned URLs for temporary access", "Enable versioning for buckets storing important data to protect against accidental deletion", "Use S3 Lifecycle rules to transition objects to cheaper storage classes automatically", "Use server-side encryption (SSE-S3 or SSE-KMS) for all buckets", "Use multipart upload for files larger than 100MB", "Enable S3 access logging or CloudTrail for audit trails", "Use intelligent-tiering for unpredictable access patterns to optimize costs automatically"], "sdkInitPattern": "// Node.js with @aws-sdk/client-s3\\nimport { S3Client, PutObjectCommand, GetObjectCommand } from \"@aws-sdk/client-s3\";\\nimport { getSignedUrl } from \"@aws-sdk/s3-request-presigner\";\\nconst s3 = new S3Client({ region: process.env.AWS_REGION });\\n// [Tailor to project language: Python=boto3.client(\"s3\"), Go=s3.NewFromConfig, Java=S3Client.builder()]", "securityGuidance": "Enable S3 Block Public Access at the account level as a guardrail. Use bucket policies with least-privilege IAM principals. Enable server-side encryption on all buckets. Use VPC endpoints for S3 access from private subnets. Use presigned URLs for temporary access instead of making objects public. Enable MFA Delete for versioned buckets containing critical data.", "commonApiPatterns": [{"name": "Upload Object", "description": "Upload file with server-side encryption", "codeTemplate": "await s3.send(new PutObjectCommand({\\n  Bucket: \"my-bucket\",\\n  Key: `uploads/${userId}/${filename}`,\\n  Body: fileBuffer,\\n  ContentType: contentType,\\n  ServerSideEncryption: \"AES256\"\\n}));"}, {"name": "Presigned URL", "description": "Generate time-limited presigned URL for secure download", "codeTemplate": "const url = await getSignedUrl(s3, new GetObjectCommand({\\n  Bucket: \"my-bucket\",\\n  Key: `uploads/${userId}/${filename}`\\n}), { expiresIn: 3600 });\\n// Return url to client for temporary download access"}, {"name": "List Objects", "description": "List objects by prefix with pagination", "codeTemplate": "import { ListObjectsV2Command } from \"@aws-sdk/client-s3\";\\nconst { Contents = [] } = await s3.send(new ListObjectsV2Command({\\n  Bucket: \"my-bucket\",\\n  Prefix: `uploads/${userId}/`,\\n  MaxKeys: 100\\n}));"}, {"name": "Delete Object", "description": "Delete a single object", "codeTemplate": "import { DeleteObjectCommand } from \"@aws-sdk/client-s3\";\\nawait s3.send(new DeleteObjectCommand({ Bucket: \"my-bucket\", Key: objectKey }));"}], "setupInstructions": [{"url": "https://console.aws.amazon.com/s3/", "type": "dashboard_config", "title": "Create S3 Bucket", "required": true, "instructions": "In AWS Console > S3 > Create Bucket. Choose a globally unique name and region. Enable or disable versioning based on your needs."}, {"type": "permissions", "title": "Configure Bucket Access", "required": true, "instructions": "Set the bucket to private by default. Configure a bucket policy for least-privilege access. For public assets, use CloudFront distribution instead of making the bucket public."}, {"type": "dashboard_config", "title": "Configure CORS for Browser Uploads", "required": false, "instructions": "Under Permissions > CORS, add a CORS configuration allowing your application origin to perform PUT/POST for direct uploads from the browser."}, {"type": "permissions", "title": "Create IAM User or Role", "required": true, "instructions": "Create an IAM user (for server-side) or IAM role (for AWS services) with minimum S3 permissions: s3:GetObject, s3:PutObject, s3:DeleteObject on the specific bucket ARN."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AWS_ACCESS_KEY_ID=<from-iam-user>", "export AWS_SECRET_ACCESS_KEY=<from-iam-user>", "export AWS_S3_BUCKET_NAME=my-app-uploads", "export AWS_REGION=us-east-1"], "required": true, "instructions": "Add AWS credentials and bucket info to your application environment."}], "integrationPatterns": ["CloudFront as CDN origin for global static asset delivery", "S3 Event Notifications + Lambda for serverless file processing pipelines", "S3 Lifecycle rules for automated archival to Glacier for long-term storage"], "configurationTemplate": "resource \"aws_s3_bucket\" \"assets\" {\\n  bucket = \"${var.project}-assets\"\\n}\\nresource \"aws_s3_bucket_versioning\" \"assets\" {\\n  bucket = aws_s3_bucket.assets.id\\n  versioning_configuration { status = \"Enabled\" }\\n}\\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"assets\" {\\n  bucket = aws_s3_bucket.assets.id\\n  rule { apply_server_side_encryption_by_default { sse_algorithm = \"AES256\" } }\\n}\\nresource \"aws_s3_bucket_public_access_block\" \"assets\" {\\n  bucket                  = aws_s3_bucket.assets.id\\n  block_public_acls       = true\\n  block_public_policy     = true\\n  ignore_public_acls      = true\\n  restrict_public_buckets = true\\n}"}', '[{"kind": "config", "path": "infra/aws/s3.tf"}]', '{"encryption": {"type": "enum", "label": "Encryption", "default": "SSE-S3", "options": ["SSE-S3", "SSE-KMS", "DSSE-KMS"], "description": "Server-side encryption mode"}, "versioning": {"type": "boolean", "label": "Versioning", "default": true, "description": "Protects user-uploaded content against accidental deletion/overwrite"}, "storageClass": {"type": "enum", "label": "Default storage class", "default": "STANDARD", "options": ["STANDARD", "INTELLIGENT_TIERING", "EXPRESS_ONEZONE", "STANDARD_IA", "ONEZONE_IA", "GLACIER_IR", "GLACIER", "DEEP_ARCHIVE"], "description": "Per-object default; lifecycle rules can transition later (the 30-day minimum for IA transitions was removed July 2026)"}, "blockPublicAccess": {"type": "boolean", "label": "Block public access", "default": true, "description": "Keep ON; use presigned URLs for temporary access"}, "staticWebsiteHosting": {"type": "boolean", "label": "Static website hosting", "default": false, "description": "Serve as a website origin (usually behind CloudFront)"}}', '["backend-service", "serverless-function", "frontend-app", "cdn"]', false, NULL, NULL, '2026-02-20 14:51:11.165373+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''/client-s3'':158C,167C ''/s3-request-presigner'':174C ''99.999999999'':15B ''acceler'':138C ''access'':55B,117B,198C,228C,237C ''account'':201C ''across'':54B ''amazon'':132C ''architectur'':86B ''archiv'':34B,115B,127B ''asset'':25B ''avoid'':111B ''aw'':1A,3A,5B,85B,134C,150C,156C,165C,172C ''aws-sdk'':155C,164C,171C ''backup'':32B ''block'':196C ''boto3.client'':188C ''bucket'':152C,207C,222C,248C ''cdn'':41B ''choic'':76B ''class'':45B ''cloudfront'':40B,139C ''contain'':249C ''cost'':52B,130B ''critic'':250C ''data'':21B,29B,83B,91B,104B,116B,251C ''databas'':110B ''deep'':126B ''default'':75B ''delet'':245C ''driven'':70B ''durabl'':14B ''ef'':97B ''enabl'':194C,215C,243C ''encrypt'':219C ''endpoint'':225C ''event'':58B,69B,141C ''event-driven'':68B ''file'':27B,79B ''filesystem'':94B ''getobjectcommand'':162C ''getsignedurl'':169C ''glacier'':50B,125B,144C ''go'':190C ''guardrail'':205C ''high'':13B ''host'':26B ''iam'':213C ''instead'':98B,238C ''integr'':61B ''intellig'':48B,147C ''intelligent-ti'':47B,146C ''java'':192C ''lake'':30B ''lambda'':63B ''languag'':186C ''least'':211C ''least-privileg'':210C ''less'':118B ''level'':202C ''log'':33B ''make'':240C ''massiv'':129B ''media'':80B ''mfa'':244C ''n'':182C ''nconst'':175C ''need'':106B ''new'':177C ''nimport'':159C,168C ''node.js'':153C ''notif'':59B,142C ''object'':7B,241C ''optim'':53B ''origin'':38B ''pattern'':56B ''per'':121B ''polici'':208C ''posix'':93B ''presign'':233C ''princip'':214C ''privat'':230C ''privileg'':212C ''process'':71B ''process.env.aws'':180C ''project'':185C ''provid'':10B ''public'':197C,242C ''putobjectcommand'':161C ''python'':187C ''queri'':107B ''region'':179C,181C ''requir'':92B ''s3'':2A,4A,42B,72B,112B,124B,133C,136C,140C,143C,145C,151C,176C,189C,195C,227C ''s3.newfromconfig'':191C ''s3client'':160C,178C ''s3client.builder'':193C ''save'':131B ''sdk'':135C,157C,166C,173C ''semant'':95B ''server'':217C ''server-sid'':216C ''servic'':9B ''side'':218C ''sns'':66B ''sqs'':64B ''standard'':46B,113B ''static'':24B ''storag'':8B,16B,31B,44B ''store'':78B ''structur'':103B ''subnet'':231C ''support'':43B ''system'':60B ''tailor'':183C ''temporari'':236C ''terraform'':149C ''tier'':49B,148C ''transfer'':137C ''type'':19B ''unlimit'':12B ''unstructur'':82B ''upload'':28B ''url'':234C ''use'':22B,89B,96B,101B,108B,123B,206C,223C,232C ''version'':247C ''virtual'':11B ''vpc'':224C ''year'':122B');
INSERT INTO public.technology_catalog VALUES ('aws-lambda', 'AWS Lambda', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-lambda.png', '#6b7280', '["serverless-function"]', '{"purpose": "Serverless compute service that runs code in response to events and automatically manages the underlying compute resources. Supports Node.js, Python, Java, Go, .NET, Ruby, and custom runtimes.", "configMode": "code", "provenance": {"notes": "Phase B1 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Lambda Functions", "API Gateway", "EventBridge", "SQS", "SNS", "DynamoDB Streams", "S3 Events", "Lambda Layers", "Step Functions"], "antiPatterns": ["Monolithic Lambda functions doing too many things", "Not setting appropriate memory and timeout limits", "Storing state inside the function", "Not handling cold starts", "Synchronous invocation chains across multiple Lambdas", "Ignoring concurrency limits"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/lambda/"}, "bestPractices": ["Keep functions small and single-purpose", "Use environment variables for configuration", "Implement proper error handling and dead letter queues", "Use Lambda Layers for shared dependencies", "Set appropriate memory allocation for cost/performance balance", "Use provisioned concurrency for latency-sensitive workloads", "Use Step Functions for orchestrating multiple Lambda invocations", "Monitor with CloudWatch and X-Ray tracing"], "sdkInitPattern": "// handler.mjs — Node.js Lambda handler (ES module)\r\nexport const handler = async (event) => {\r\n  return { statusCode: 200, body: JSON.stringify({ ok: true }) };\r\n};", "securityGuidance": "One execution role per function with least-privilege IAM — never share a broad role across functions. Pull secrets from Secrets Manager or SSM Parameter Store at runtime instead of plaintext environment variables. If you expose a Function URL or API Gateway route, require auth (IAM or an authorizer) — no wildcard resource policies. Attach to a VPC only when the function truly needs private resources; it adds cold-start and egress complexity."}', '[{"kind": "source", "path": "src/handlers/index.ts"}, {"kind": "config", "path": "infra/aws/lambda.tf"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "nodejs22.x", "options": ["nodejs24.x", "nodejs22.x", "nodejs20.x", "python3.14", "python3.13", "python3.12", "java25", "java21", "dotnet10", "dotnet8", "ruby3.4", "provided.al2023"], "description": "Lambda execution runtime"}, "memoryMb": {"type": "number", "label": "Memory (MB)", "default": 256, "description": "128-10240; CPU scales with memory"}, "triggerType": {"type": "enum", "label": "Primary trigger", "options": ["api-gateway", "sqs", "eventbridge", "s3", "schedule", "dynamodb-stream", "direct-invoke"], "description": "What invokes this function"}, "architecture": {"type": "enum", "label": "Architecture", "default": "arm64", "options": ["arm64", "x86_64"], "description": "arm64 (Graviton) is cheaper for most workloads"}, "timeoutSeconds": {"type": "number", "label": "Timeout (seconds)", "default": 30, "description": "Maximum 900 (15 minutes)"}}', '["api-gateway", "queue", "database", "object-storage", "event-stream"]', false, NULL, NULL, '2026-02-21 04:24:52.574678+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''200'':60C ''across'':80C ''add'':131C ''api'':34C,105C ''async'':56C ''attach'':118C ''auth'':109C ''author'':113C ''automat'':16B ''aw'':1A,3A ''bodi'':61C ''broad'':78C ''code'':10B ''cold'':133C ''cold-start'':132C ''complex'':137C ''comput'':6B,20B ''const'':54C ''custom'':30B ''dynamodb'':39C ''egress'':136C ''environ'':96C ''es'':51C ''event'':14B,42C,57C ''eventbridg'':36C ''execut'':66C ''export'':53C ''expos'':100C ''function'':33C,46C,69C,81C,102C,125C ''gateway'':35C,106C ''go'':26B ''handler'':50C,55C ''handler.mjs'':47C ''iam'':74C,110C ''instead'':93C ''java'':25B ''json.stringify'':62C ''lambda'':2A,4A,32C,43C,49C ''layer'':44C ''least'':72C ''least-privileg'':71C ''manag'':17B,86C ''modul'':52C ''need'':127C ''net'':27B ''never'':75C ''node.js'':23B,48C ''ok'':63C ''one'':65C ''paramet'':89C ''per'':68C ''plaintext'':95C ''polici'':117C ''privat'':128C ''privileg'':73C ''pull'':82C ''python'':24B ''requir'':108C ''resourc'':21B,116C,129C ''respons'':12B ''return'':58C ''role'':67C,79C ''rout'':107C ''rubi'':28B ''run'':9B ''runtim'':31B,92C ''s3'':41C ''secret'':83C,85C ''serverless'':5B ''servic'':7B ''share'':76C ''sns'':38C ''sqs'':37C ''ssm'':88C ''start'':134C ''statuscod'':59C ''step'':45C ''store'':90C ''stream'':40C ''support'':22B ''true'':64C ''truli'':126C ''under'':19B ''url'':103C ''variabl'':97C ''vpc'':121C ''wildcard'':115C');
INSERT INTO public.technology_catalog VALUES ('nextjs', 'Next.js', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nextjs.png', '#000000', '["frontend-app", "backend-service"]', '{"purpose": "Full-stack React framework with server-side rendering, static generation, API routes, and edge middleware", "configMode": "code", "provenance": {"notes": "Turbopack is stable and the DEFAULT bundler for dev and build since Next.js 16; App Router is the default template. Model knowledge would have shipped webpack-default.", "method": "live-docs", "sources": ["https://nextjs.org/blog/next-16", "https://nextjs.org/docs/app/api-reference/turbopack"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Next.js 14+", "React 18+", "TypeScript", "App Router", "Server Components", "Server Actions", "Prisma/Drizzle"], "antiPatterns": ["Adding \"use client\" to every component instead of keeping components server-rendered by default", "Fetching data in Client Components when Server Components can access the DB directly", "Not using loading.tsx and error.tsx for streaming and error boundaries", "Importing server-only code in Client Components leaking secrets", "Using getServerSideProps/getStaticProps patterns from Pages Router in App Router"], "apiReference": {"docsUrl": "https://nextjs.org/docs"}, "bestPractices": ["Use App Router with server components by default", "Implement proper loading.tsx and error.tsx boundaries", "Use server actions for form mutations", "Leverage ISR for content that changes occasionally", "Use Route Handlers for API endpoints", "Implement middleware for auth and redirects", "Use next/image for automatic image optimization", "Implement proper metadata for SEO"], "sdkInitPattern": "npx create-next-app@latest my-app --typescript --tailwind --eslint --app --src-dir && cd my-app\\n// src/app/page.tsx\\nexport default function Home() {\\n  return <main><h1>Hello Next.js</h1></main>;\\n}", "securityGuidance": "Server Components run on the server only -- never expose secrets in Client Components. Use environment variables with NEXT_PUBLIC_ prefix only for truly public values. Validate all Server Action inputs. Use next/headers for reading cookies server-side. Set security headers in next.config.js or middleware. Use middleware.ts for route-level authentication checks before rendering.", "commonApiPatterns": [{"name": "Server Component with Data", "description": "React Server Component with direct database access (no API needed)", "codeTemplate": "// src/app/users/page.tsx\\nexport default async function UsersPage() {\\n  const users = await db.user.findMany();\\n  return (\\n    <ul>\\n      {users.map(u => <li key={u.id}>{u.name}</li>)}\\n    </ul>\\n  );\\n}"}, {"name": "Server Action", "description": "Server Action for form mutation with cache revalidation", "codeTemplate": "\"use server\";\\nexport async function createUser(formData: FormData) {\\n  const name = formData.get(\"name\") as string;\\n  const user = await db.user.create({ data: { name } });\\n  revalidatePath(\"/users\");\\n  return user;\\n}"}, {"name": "Route Handler", "description": "API Route Handler with GET and POST methods", "codeTemplate": "// src/app/api/users/route.ts\\nexport async function GET() {\\n  const users = await db.user.findMany();\\n  return Response.json(users);\\n}\\nexport async function POST(request: Request) {\\n  const body = await request.json();\\n  const user = await db.user.create({ data: body });\\n  return Response.json(user, { status: 201 });\\n}"}], "integrationPatterns": ["App Router with Server Components for zero-JS server rendering", "Prisma or Drizzle for type-safe database access from Server Components", "NextAuth.js (Auth.js) for authentication with session management", "Vercel or self-hosted Node.js for deployment", "Playwright or Cypress for end-to-end testing"], "configurationTemplate": "// next.config.ts\\nimport type { NextConfig } from \"next\";\\nconst config: NextConfig = {\\n  experimental: {\\n    typedRoutes: true,\\n  },\\n  images: {\\n    remotePatterns: [{ hostname: \"images.example.com\" }],\\n  },\\n};\\nexport default config;"}', '[{"kind": "source", "path": "src/app/layout.tsx", "language": "typescript", "description": "Root layout"}, {"kind": "source", "path": "src/app/page.tsx", "language": "typescript", "description": "Home page"}, {"kind": "config", "path": "next.config.js", "language": "javascript", "description": "Next.js configuration"}]', '{"router": {"type": "enum", "label": "Router", "default": "app-router", "options": ["app-router", "pages-router-legacy"], "description": "App Router (server components) is the default; Pages Router is maintained for existing apps"}, "bundler": {"type": "enum", "label": "Bundler", "default": "turbopack-default", "options": ["turbopack-default", "webpack-legacy"], "description": "Turbopack is stable and the default for dev AND build since Next.js 16"}, "apiSurface": {"type": "enum", "label": "API surface", "default": "both", "options": ["route-handlers", "server-actions", "both", "none-external-api"]}, "deployment": {"type": "enum", "label": "Deployment", "default": "vercel", "options": ["vercel", "self-hosted-node", "docker", "static-export"], "description": "static-export disables server features (RSC payloads still prerender, but no server actions/ISR)"}, "renderingPosture": {"type": "enum", "label": "Rendering posture", "default": "server-first", "options": ["server-first", "static-heavy", "client-heavy"], "description": "Server-first = RSC by default with client islands; static-heavy leans on prerendering; client-heavy marks most of the tree use-client"}}', '["database", "cache", "auth-provider", "external-service"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#333333', '''14'':21C ''18'':23C ''action'':30C,91C ''api'':15B ''app'':25C,36C,40C,44C,51C ''authent'':114C ''cd'':48C ''check'':115C ''client'':74C ''compon'':28C,64C,75C ''cooki'':97C ''creat'':34C ''create-next-app'':33C ''default'':55C ''dir'':47C ''edg'':18B ''environ'':77C ''eslint'':43C ''expos'':71C ''framework'':7B ''full'':4B ''full-stack'':3B ''function'':56C ''generat'':14B ''header'':103C ''hello'':60C ''home'':57C ''input'':92C ''latest'':37C ''level'':113C ''middlewar'':19B,107C ''middleware.ts'':109C ''my-app'':38C,49C ''n'':52C,58C,62C ''never'':70C ''nexport'':54C ''next'':35C,80C ''next.config.js'':105C ''next.js'':1A,20C,61C ''next/headers'':94C ''nextj'':2A ''npx'':32C ''prefix'':82C ''prisma/drizzle'':31C ''public'':81C,86C ''react'':6B,22C ''read'':96C ''render'':12B,117C ''return'':59C ''rout'':16B,112C ''route-level'':111C ''router'':26C ''run'':65C ''secret'':72C ''secur'':102C ''server'':10B,27C,29C,63C,68C,90C,99C ''server-sid'':9B,98C ''set'':101C ''side'':11B,100C ''src'':46C ''src-dir'':45C ''src/app/page.tsx'':53C ''stack'':5B ''static'':13B ''tailwind'':42C ''truli'':85C ''typescript'':24C,41C ''use'':76C,93C,108C ''valid'':88C ''valu'':87C ''variabl'':78C');
INSERT INTO public.technology_catalog VALUES ('cpp-backend', 'C++', NULL, '#00599C', '["backend-service", "worker"]', '{"purpose": "High-performance systems programming language for latency-critical backend services, game servers, embedded systems, and compute-intensive workloads", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["C++20/23", "CMake", "Conan/vcpkg", "gRPC", "Boost.Beast/Crow/Drogon", "GoogleTest", "spdlog", "Protocol Buffers"], "antiPatterns": ["Manual memory management with raw new/delete", "Undefined behavior from uninitialized variables or dangling references", "Using C-style casts instead of static_cast/dynamic_cast", "Not using const correctness", "Ignoring compiler warnings", "Global mutable state without synchronization", "Not using move semantics for large objects", "Header-only libraries for large codebases causing slow builds"], "apiReference": {"docsUrl": "https://en.cppreference.com/w/"}, "bestPractices": ["Use RAII for all resource management", "Prefer smart pointers (unique_ptr, shared_ptr) over raw pointers", "Use CMake as the build system with modern target-based configuration", "Leverage constexpr and compile-time computation where possible", "Use std::expected or Result types for error handling over exceptions in hot paths", "Implement structured logging with spdlog or similar", "Use sanitizers (ASan, TSan, UBSan) during development", "Write unit tests with GoogleTest or Catch2", "Use vcpkg or Conan for dependency management"], "securityGuidance": "Memory safety is the threat model: every parser of untrusted input is the attack surface, so fuzz them, run AddressSanitizer/UBSan in CI, and prefer std::span/string_view bounds-honesty plus smart pointers over raw new/delete. Ban the classic footguns at review (strcpy/sprintf/unchecked memcpy, signed-overflow arithmetic on sizes). Build hardened in release (stack protector, FORTIFY_SOURCE, RELRO, PIE), vendor dependencies with pinned versions and CVE scanning, and treat any deserialization of external bytes as hostile until length-checked.", "configurationTemplate": "# CMakeLists.txt\ncmake_minimum_required(VERSION 3.24)\nproject(app CXX)\nset(CMAKE_CXX_STANDARD 20)\nset(CMAKE_CXX_STANDARD_REQUIRED ON)\nadd_executable(app src/main.cpp)\ntarget_compile_options(app PRIVATE -Wall -Wextra -Werror)\n# sanitizer build: -fsanitize=address,undefined in the Debug preset"}', '[{"kind": "source", "path": "src/main.cpp", "language": "cpp", "description": "Application entry point"}, {"kind": "source", "path": "src/server.cpp", "language": "cpp", "description": "Server implementation"}, {"kind": "source", "path": "include/server.h", "language": "cpp", "description": "Public headers"}, {"kind": "config", "path": "CMakeLists.txt", "language": "cmake", "description": "CMake build configuration"}, {"kind": "config", "path": "conanfile.txt", "language": "ini", "description": "Conan dependency manifest"}]', '{"sanitizers": {"type": "boolean", "label": "Sanitizers in CI", "default": true}, "buildSystem": {"type": "enum", "label": "Build system", "default": "cmake", "options": ["cmake", "bazel", "meson"]}, "packageManager": {"type": "enum", "label": "Dependencies", "default": "vcpkg", "options": ["vcpkg", "conan", "system-none"]}}', '["database", "cache", "message-broker", "grpc-service"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-31 20:06:52.233344+00', 'C++', NULL, '''+20'':26C ''/23'':27C ''/crow/drogon'':33C ''addresssanitizer/ubsan'':57C ''arithmet'':84C ''attack'':51C ''backend'':3A,14B ''ban'':73C ''boost.beast'':32C ''boost.beast/crow/drogon'':31C ''bound'':65C ''bounds-honesti'':64C ''buffer'':37C ''build'':87C ''byte'':111C ''c'':1A,25C ''check'':117C ''ci'':59C ''classic'':75C ''cmake'':28C ''comput'':22B ''compute-intens'':21B ''conan/vcpkg'':29C ''cpp'':2A ''critic'':13B ''cve'':103C ''depend'':98C ''deseri'':108C ''embed'':18B ''everi'':44C ''extern'':110C ''footgun'':76C ''fortifi'':93C ''fuzz'':54C ''game'':16B ''googletest'':34C ''grpc'':30C ''harden'':88C ''high'':5B ''high-perform'':4B ''honesti'':66C ''hostil'':113C ''input'':48C ''intens'':23B ''languag'':9B ''latenc'':12B ''latency-crit'':11B ''length'':116C ''length-check'':115C ''memcpi'':80C ''memori'':38C ''model'':43C ''new/delete'':72C ''overflow'':83C ''parser'':45C ''perform'':6B ''pie'':96C ''pin'':100C ''plus'':67C ''pointer'':69C ''prefer'':61C ''program'':8B ''protector'':92C ''protocol'':36C ''raw'':71C ''releas'':90C ''relro'':95C ''review'':78C ''run'':56C ''safeti'':39C ''scan'':104C ''server'':17B ''servic'':15B ''sign'':82C ''signed-overflow'':81C ''size'':86C ''smart'':68C ''sourc'':94C ''span/string_view'':63C ''spdlog'':35C ''stack'':91C ''std'':62C ''strcpy/sprintf/unchecked'':79C ''surfac'':52C ''system'':7B,19B ''threat'':42C ''treat'':106C ''untrust'':47C ''vendor'':97C ''version'':101C ''workload'':24B');
INSERT INTO public.technology_catalog VALUES ('supabase-storage', 'Supabase Storage', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["object-storage"]', '{"purpose": "S3-compatible object storage integrated with Supabase Auth and RLS. Provides buckets for file uploads (images, documents, media) with access control via RLS policies on storage.objects. Supports signed URLs for temporary access, image transformations, resumable uploads, and CDN-backed delivery. Ideal when your project already uses Supabase and you want unified auth-based file access without managing a separate S3 setup.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["@supabase/supabase-js", "Supabase Storage API", "PostgreSQL RLS", "S3-compatible API", "Image Transformations", "Resumable Uploads (TUS protocol)"], "antiPatterns": ["Creating public buckets for user-uploaded content without size/type restrictions", "Not setting RLS policies on storage.objects table (defaults to no access)", "Storing files larger than 5GB without resumable uploads", "Using storage for structured data that belongs in the database", "Hardcoding bucket names instead of using environment configuration", "Not validating file MIME types server-side before accepting uploads"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/storage"}, "bestPractices": ["Use RLS policies on storage.objects to restrict file access by auth.uid()", "Create separate buckets for different access patterns (public assets vs private uploads)", "Use signed URLs for private file downloads with short expiry (1 hour max)", "Validate file size and MIME type before accepting uploads", "Use image transformations for responsive image delivery instead of storing multiple sizes", "Organize files by user: {bucket}/{user_id}/{filename} for simple RLS policies", "Use resumable uploads (TUS) for files larger than 6MB", "Set appropriate cache-control headers for CDN optimization"], "freshnessNote": "Placement decides the lane: managed includes image transformations; self-hosted this is the open-source storage-api container, and transforms require running imgproxy beside it.", "sdkInitPattern": "import { createClient } from \"@supabase/supabase-js\";\nconst supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);\n\n// Upload file\nconst { data, error } = await supabase.storage\n  .from(\"avatars\")\n  .upload(`${userId}/${filename}`, file, {\n    contentType: file.type,\n    upsert: true\n  });\n\n// Get public URL\nconst { data: { publicUrl } } = supabase.storage\n  .from(\"avatars\")\n  .getPublicUrl(`${userId}/${filename}`);", "securityGuidance": "Enable RLS on storage.objects and storage.buckets tables. Create policies scoped to auth.uid() for user-owned files. Use signed URLs for private content delivery. Restrict allowed MIME types and file sizes in bucket configuration. Never expose service_role key to client code.", "commonApiPatterns": [{"name": "Upload File", "description": "Upload a file to a private bucket with user scoping", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .upload(`${userId}/${filename}`, file, {\n    contentType: file.type,\n    cacheControl: \"3600\",\n    upsert: false\n  });"}, {"name": "Download with Signed URL", "description": "Generate a time-limited download URL for private files", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .createSignedUrl(`${userId}/${filename}`, 3600);\n// data.signedUrl is valid for 1 hour"}, {"name": "List Files", "description": "List files in a user-scoped folder", "codeTemplate": "const { data, error } = await supabase.storage\n  .from(\"uploads\")\n  .list(userId, {\n    limit: 100,\n    offset: 0,\n    sortBy: { column: \"created_at\", order: \"desc\" }\n  });"}, {"name": "Delete File", "description": "Remove a file from storage", "codeTemplate": "const { error } = await supabase.storage\n  .from(\"uploads\")\n  .remove([`${userId}/${filename}`]);"}], "setupInstructions": [{"url": "https://supabase.com/dashboard/project/_/storage/buckets", "type": "dashboard_config", "title": "Create Storage Bucket", "required": true, "instructions": "In Supabase Dashboard > Storage > New Bucket. Choose public (for assets like avatars) or private (for user files). Name it descriptively (e.g., avatars, documents)."}, {"type": "permissions", "title": "Write RLS Policies on storage.objects", "required": true, "instructions": "Storage uses RLS on the storage.objects table. Write policies that check auth.uid() and bucket_id to control who can upload, download, and delete files."}, {"type": "dashboard_config", "title": "Configure Image Transformations", "required": false, "instructions": "For image buckets, enable image transformations in bucket settings. This allows on-the-fly resizing via URL parameters (width, height, quality)."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export SUPABASE_URL=https://your-project.supabase.co", "export SUPABASE_SERVICE_ROLE_KEY=<from-project-settings>"], "required": true, "instructions": "Use your existing Supabase project credentials. The service role key bypasses RLS for server-side operations."}], "integrationPatterns": ["RLS policies on storage.objects for auth-scoped file access", "Image transformations for responsive delivery (width, height, quality params)", "Database trigger to clean up storage objects when parent record is deleted", "Edge Function for post-upload processing (virus scan, image optimization)"], "configurationTemplate": "-- Create a private bucket\nINSERT INTO storage.buckets (id, name, public)\nVALUES (''uploads'', ''uploads'', false);\n\n-- RLS: Users can upload to their own folder\nCREATE POLICY \"Users can upload own files\"\nON storage.objects FOR INSERT TO authenticated\nWITH CHECK (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);\n\n-- RLS: Users can view own files\nCREATE POLICY \"Users can view own files\"\nON storage.objects FOR SELECT TO authenticated\nUSING (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);\n\n-- RLS: Users can delete own files\nCREATE POLICY \"Users can delete own files\"\nON storage.objects FOR DELETE TO authenticated\nUSING (bucket_id = ''uploads'' AND (storage.foldername(name))[1] = auth.uid()::text);"}', '[{"kind": "config", "path": "supabase/migrations/storage-buckets.sql", "language": "sql", "priority": "essential", "description": "Storage bucket creation and RLS policies"}, {"kind": "source", "path": "src/lib/storage.ts", "language": "typescript", "priority": "essential", "description": "Storage helper functions for upload, download, and signed URLs"}, {"kind": "source", "path": "src/components/FileUpload.tsx", "language": "typescript", "priority": "recommended", "description": "Reusable file upload component with progress and validation"}]', '{"uploads": {"type": "enum", "label": "Upload path", "default": "client-direct", "options": ["client-direct", "server-mediated", "resumable-tus"], "description": "Resumable (TUS) for large files; client-direct with RLS is the default lane"}, "bucketPolicy": {"type": "enum", "label": "Bucket policy", "default": "private-rls", "options": ["private-rls", "public-read", "mixed"], "description": "Access control is Postgres RLS on storage.objects — the policy IS the security model"}, "imageTransforms": {"type": "boolean", "label": "Image transformations", "default": false, "description": "On-the-fly resize/format. Managed: built in. Self-hosted OSS: requires running the imgproxy container"}}', '[]', false, NULL, NULL, '2026-05-16 17:56:17.93653+00', '2026-08-31 20:07:01.887163+00', 'Supabase Storage', NULL, '''access'':25B,37B,62B ''allow'':151C ''alreadi'':51B ''anon'':95C ''api'':72C,78C ''auth'':13B,59B ''auth-bas'':58B ''auth.uid'':137C ''avatar'':105C,122C ''await'':102C ''back'':45B ''base'':60B ''bucket'':17B,158C ''cdn'':44B ''cdn-back'':43B ''client'':166C ''code'':167C ''compat'':7B,77C ''configur'':159C ''const'':89C,99C,117C ''content'':148C ''contenttyp'':110C ''control'':26B ''creat'':133C ''createcli'':86C,91C ''data'':100C,118C ''deliveri'':46B,149C ''document'':22B ''enabl'':126C ''error'':101C ''expos'':161C ''file'':19B,61B,98C,109C,142C,155C ''file.type'':111C ''filenam'':108C,125C ''get'':114C ''getpublicurl'':123C ''ideal'':47B ''imag'':21B,38B,79C ''import'':85C ''integr'':10B ''key'':96C,164C ''manag'':64B ''media'':23B ''mime'':152C ''never'':160C ''object'':8B ''own'':141C ''polici'':29B,134C ''postgresql'':73C ''privat'':147C ''project'':50B ''protocol'':84C ''provid'':16B ''public'':115C ''publicurl'':119C ''restrict'':150C ''resum'':40B,81C ''rls'':15B,28B,74C,127C ''role'':163C ''s3'':6B,67B,76C ''s3-compatible'':5B,75C ''scope'':135C ''separ'':66B ''servic'':162C ''setup'':68B ''sign'':33B,144C ''size'':156C ''storag'':2A,4A,9B,71C ''storage.buckets'':131C ''storage.objects'':31B,129C ''supabas'':1A,3A,12B,53B,70C,90C,92C,94C ''supabase.storage'':103C,120C ''supabase/supabase-js'':69C,88C ''support'':32B ''tabl'':132C ''temporari'':36B ''transform'':39B,80C ''true'':113C ''tus'':83C ''type'':153C ''unifi'':57B ''upload'':20B,41B,82C,97C,106C ''upsert'':112C ''url'':34B,93C,116C,145C ''use'':52B,143C ''user'':140C ''user-own'':139C ''userid'':107C,124C ''via'':27B ''want'':56B ''without'':63B');
INSERT INTO public.technology_catalog VALUES ('nakama', 'Nakama', NULL, '#6b7280', '["game-server"]', '{"purpose": "Open-source game backend server: matchmaking, realtime multiplayer, leaderboards, chat, friends and IAP validation built in, with custom logic in TypeScript/Go/Lua. The self-hostable full-featured lane (Photon is the managed relay alternative); costs are real ops (server + database) and a smaller community.", "configMode": "declarative", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-28. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["matchmaker", "authoritative match handlers", "leaderboards/chat/friends", "TypeScript runtime", "Postgres"], "antiPatterns": ["Client-authoritative gameplay with the server as a relay — cheating is the default outcome", "Fat Lua/TS modules holding business logic that belongs in your own services", "Self-hosting without monitoring the socket + DB pressure"], "apiReference": {"docsUrl": "https://heroiclabs.com/docs/"}, "bestPractices": ["Use the built-in systems before writing custom RPCs — leaderboards/matchmaking re-implementations are wasted work", "Server-authoritative match handlers for anything competitive", "Postgres sizing and backup discipline — Nakama''s state lives there", "Version custom modules like an app deploy, not hot-edited scripts"], "sdkInitPattern": "// server runtime module (TypeScript) — privileged logic lives HERE, not the client\nconst rpcGrantReward: nkruntime.RpcFunction = (ctx, logger, nk, payload) => {\n  if (!ctx.userId) throw Error(''unauthenticated'');\n  const { matchId } = JSON.parse(payload);\n  const result = nk.matchGet(matchId);      // server-verifiable facts only\n  if (!wonMatch(result, ctx.userId)) throw Error(''not eligible'');\n  nk.walletUpdate(ctx.userId, { coins: 100 });\n  return JSON.stringify({ granted: true });\n};\n\nfunction InitModule(ctx: nkruntime.Context, logger: nkruntime.Logger, nk: nkruntime.Nakama, initializer: nkruntime.Initializer) {\n  initializer.registerRpc(''grant_reward'', rpcGrantReward);\n}", "securityGuidance": "The client SDK''s socket is player-scoped by design — everything privileged (wallet grants, leaderboard writes that matter, match results) runs in server runtime modules keyed off ctx.userId, never trusted from client payloads. Change the default server key and console credentials before exposure (the console is full admin), put the gRPC/HTTP API behind TLS, validate storage-engine writes with permission checks (public-read objects are readable by every player), and rate-limit custom RPCs — each one you register is an internet-facing endpoint with your database behind it."}', '[{"kind": "code", "path": "server/main.ts", "language": "typescript", "description": "Runtime module: privileged RPCs keyed off ctx.userId"}, {"kind": "config", "path": "local.yml", "language": "yaml", "description": "Server config: non-default server key, console credentials, TLS"}]', '{"hosting": {"type": "enum", "label": "Hosting", "default": "self-hosted", "options": ["heroic-cloud", "self-hosted"]}, "runtime": {"type": "enum", "label": "Server runtime", "default": "typescript", "options": ["typescript", "go", "lua"], "description": "Custom server logic language"}, "features": {"type": "multiselect", "label": "Features used", "options": ["matchmaking", "realtime-multiplayer", "leaderboards", "chat", "iap-validation", "friends-groups"], "description": "Which built-in social/game systems this game relies on"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''100'':104C ''admin'':171C ''altern'':38B ''api'':175C ''authorit'':50C ''backend'':7B ''behind'':176C,214C ''built'':18B ''chang'':157C ''chat'':13B ''check'':185C ''client'':67C,124C,155C ''coin'':103C ''communiti'':48B ''consol'':163C,168C ''const'':68C,80C,84C ''cost'':39B ''credenti'':164C ''ctx'':71C,111C ''ctx.userid'':76C,96C,102C,151C ''custom'':21B,199C ''databas'':44B,213C ''default'':159C ''design'':133C ''elig'':100C ''endpoint'':210C ''engin'':181C ''error'':78C,98C ''everi'':193C ''everyth'':134C ''exposur'':166C ''face'':209C ''fact'':91C ''featur'':31B ''friend'':14B ''full'':30B,170C ''full-featur'':29B ''function'':109C ''game'':6B ''grant'':107C,120C,137C ''grpc/http'':174C ''handler'':52C ''hostabl'':28B ''iap'':16B ''initi'':117C ''initializer.registerrpc'':119C ''initmodul'':110C ''internet'':208C ''internet-fac'':207C ''json.parse'':82C ''json.stringify'':106C ''key'':149C,161C ''lane'':32B ''leaderboard'':12B,138C ''leaderboards/chat/friends'':53C ''limit'':198C ''live'':63C ''logger'':72C,113C ''logic'':22B,62C ''manag'':36B ''match'':51C,142C ''matchid'':81C,87C ''matchmak'':9B,49C ''matter'':141C ''modul'':59C,148C ''multiplay'':11B ''nakama'':1A,2A ''never'':152C ''nk'':73C,115C ''nk.matchget'':86C ''nk.walletupdate'':101C ''nkruntime.context'':112C ''nkruntime.initializer'':118C ''nkruntime.logger'':114C ''nkruntime.nakama'':116C ''nkruntime.rpcfunction'':70C ''object'':189C ''one'':202C ''op'':42B ''open'':4B ''open-sourc'':3B ''payload'':74C,83C,156C ''permiss'':184C ''photon'':33B ''player'':130C,194C ''player-scop'':129C ''postgr'':56C ''privileg'':61C,135C ''public'':187C ''public-read'':186C ''put'':172C ''rate'':197C ''rate-limit'':196C ''read'':188C ''readabl'':191C ''real'':41B ''realtim'':10B ''regist'':204C ''relay'':37B ''result'':85C,95C,143C ''return'':105C ''reward'':121C ''rpcgrantreward'':69C,122C ''rpcs'':200C ''run'':144C ''runtim'':55C,58C,147C ''scope'':131C ''sdk'':125C ''self'':27B ''self-host'':26B ''server'':8B,43B,57C,89C,146C,160C ''server-verifi'':88C ''smaller'':47B ''socket'':127C ''sourc'':5B ''storag'':180C ''storage-engin'':179C ''throw'':77C,97C ''tls'':177C ''true'':108C ''trust'':153C ''typescript'':54C,60C ''typescript/go/lua'':24B ''unauthent'':79C ''valid'':17B,178C ''verifi'':90C ''wallet'':136C ''wonmatch'':94C ''write'':139C,182C');
INSERT INTO public.technology_catalog VALUES ('aws-ecs', 'AWS ECS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-ecs.png', '#FF9900', '["ecs-cluster", "docker-container"]', '{"purpose": "AWS-native container orchestration service for running Docker containers at scale. ECS Fargate provides serverless container execution without managing EC2 instances; ECS on EC2 gives full control over underlying compute. Best for teams already on AWS who want simpler container orchestration than Kubernetes. Use ECS Fargate for most containerized workloads; use ECS on EC2 for GPU workloads, specific instance types, or cost optimization with Spot/Reserved instances. Choose EKS over ECS when you need Kubernetes ecosystem compatibility.", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using EC2 launch type when Fargate suffices (unnecessary operational overhead)", "Running sidecar containers without proper health checks", "Not using task definitions versioning for rollback capability", "Hardcoding secrets in task definitions instead of using Secrets Manager references", "Ignoring Fargate platform version updates"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ecs/"}, "bestPractices": ["Use Fargate launch type unless you need specific EC2 instance control", "Use ECS Service Connect or Cloud Map for service discovery", "Configure task-level IAM roles (not instance roles) for least privilege", "Enable Container Insights for monitoring and logging", "Use capacity providers for mixed Fargate/EC2/Spot strategies", "Store secrets in Secrets Manager or Parameter Store, not environment variables"], "securityGuidance": "Two roles, two jobs: the EXECUTION role pulls images and writes logs; the TASK role is what your code runs as — scope it per service, least privilege. Inject secrets via the secrets/valueFrom binding to Secrets Manager or SSM, never plaintext environment. Use awsvpc networking with a security group per service, keep privileged mode off, and gate deploys on ECR image scanning.", "configurationTemplate": "{\r\n  \"family\": \"api\",\r\n  \"networkMode\": \"awsvpc\",\r\n  \"requiresCompatibilities\": [\"FARGATE\"],\r\n  \"cpu\": \"256\", \"memory\": \"512\",\r\n  \"taskRoleArn\": \"arn:aws:iam::ACCOUNT:role/api-task-role\",\r\n  \"executionRoleArn\": \"arn:aws:iam::ACCOUNT:role/api-execution-role\",\r\n  \"containerDefinitions\": [{\r\n    \"name\": \"api\", \"image\": \"ACCOUNT.dkr.ecr.REGION.amazonaws.com/api:TAG\",\r\n    \"portMappings\": [{ \"containerPort\": 3000 }],\r\n    \"secrets\": [{ \"name\": \"DB_PASSWORD\", \"valueFrom\": \"arn:aws:secretsmanager:...:secret:db-password\" }]\r\n  }]\r\n}"}', '[{"kind": "build", "path": "Dockerfile", "priority": "essential", "description": "Container image definition"}, {"kind": "config", "path": "ecs-task-definition.json", "priority": "essential", "description": "ECS task definition"}, {"kind": "config", "path": "terraform/ecs.tf", "priority": "recommended", "description": "ECS cluster and service infrastructure"}, {"kind": "config", "path": "docker-compose.yml", "priority": "recommended", "description": "Local development Docker Compose"}]', '{"cpu": {"type": "string", "label": "CPU (vCPU units)", "default": "256"}, "memory": {"type": "string", "label": "Memory (MB)", "default": "512"}, "launchType": {"enum": ["FARGATE", "EC2"], "type": "string", "label": "Launch Type", "default": "FARGATE"}, "desiredCount": {"type": "number", "label": "Desired Task Count", "default": 2}, "serviceConnect": {"type": "boolean", "label": "Service Connect", "default": true}}', '["load-balancer", "database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''alreadi'':39B ''aw'':1A,3A,6B,41B ''aws-nat'':5B ''awsvpc'':124C ''best'':36B ''bind'':114C ''choos'':72B ''code'':100C ''compat'':81B ''comput'':35B ''contain'':8B,14B,21B,45B ''container'':54B ''control'':32B ''cost'':67B ''deploy'':138C ''docker'':13B ''ec'':2A,4A,17B,27B,50B,57B,75B ''ec2'':25B,29B,59B ''ecosystem'':80B ''ecr'':140C ''ek'':73B ''environ'':122C ''execut'':22B,87C ''fargat'':18B,51B ''full'':31B ''gate'':137C ''give'':30B ''gpu'':61B ''group'':129C ''imag'':90C,141C ''inject'':109C ''instanc'':26B,64B,71B ''job'':85C ''keep'':132C ''kubernet'':48B,79B ''least'':107C ''log'':93C ''manag'':24B,117C ''mode'':134C ''nativ'':7B ''need'':78B ''network'':125C ''never'':120C ''optim'':68B ''orchestr'':9B,46B ''per'':105C,130C ''plaintext'':121C ''privileg'':108C,133C ''provid'':19B ''pull'':89C ''role'':83C,88C,96C ''run'':12B,101C ''scale'':16B ''scan'':142C ''scope'':103C ''secret'':110C,116C ''secrets/valuefrom'':113C ''secur'':128C ''serverless'':20B ''servic'':10B,106C,131C ''simpler'':44B ''specif'':63B ''spot/reserved'':70B ''ssm'':119C ''task'':95C ''team'':38B ''two'':82C,84C ''type'':65B ''under'':34B ''use'':49B,56B,123C ''via'':111C ''want'':43B ''without'':23B ''workload'':55B,62B ''write'':92C');
INSERT INTO public.technology_catalog VALUES ('aws-dynamodb-streams', 'AWS DynamoDB Streams', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-DynamoDB_64@5x.png', '#FF4F8B', '["event-stream"]', '{"purpose": "Amazon DynamoDB Streams is AWS''s change data capture stream for DynamoDB tables that emits ordered item-level change records for inserts, updates, and deletes. Use it for event-driven reactions to table mutations, denormalization pipelines, projections, audit trails, and downstream processing tied directly to DynamoDB state changes. Choose DynamoDB Streams over general-purpose event buses when the source of truth is a DynamoDB table and ordered per-item change capture matters, and over polling patterns when near real-time change propagation is required. Do not use it as a general enterprise messaging backbone, a long-retention event store, or a substitute for broader publish-subscribe patterns across many unrelated producers.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon DynamoDB Streams", "AWS Lambda", "Amazon DynamoDB", "Amazon EventBridge Pipes", "Amazon Kinesis Data Streams", "Amazon CloudWatch", "AWS Step Functions"], "antiPatterns": ["Using DynamoDB Streams as a general-purpose event bus for producers outside DynamoDB", "Assuming infinite replay retention or long-term archival semantics from the stream itself", "Building non-idempotent consumers that fail under retries or partial reprocessing", "Triggering many tightly coupled side effects from one consumer without isolation or failure control", "Using stream records as the only audit store without considering retention and downstream durability", "Polling DynamoDB tables directly when change data capture from streams is the actual requirement"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/Streams.html"}, "bestPractices": ["Treat stream records as change events derived from a DynamoDB table rather than as an independent system of record", "Keep consumers idempotent because retries, replays, and duplicate processing scenarios can occur", "Use filters, batching, and parallelization settings intentionally so downstream processing matches table write behavior", "Separate stream consumers by business responsibility instead of overloading one consumer with unrelated side effects", "Monitor iterator age, throttling, failure rates, and backlog as part of production operations", "Use stream processing to build projections, notifications, or integrations rather than embedding cross-service logic in table writes", "Design table keys and write patterns with downstream stream volume and partition behavior in mind"], "securityGuidance": "The stream is a change-log of the whole table — a consumer role with GetRecords sees every write including attributes the consumer''s feature never needed, so pick NEW_IMAGE/KEYS_ONLY view types deliberately and scope consumer roles per stream. Configure retry limits + bisect + an on-failure destination or one poison record blocks the shard forever, and write idempotent handlers: at-least-once delivery is the contract.", "configurationTemplate": "# Lambda event source mapping — the standard consumer\naws lambda create-event-source-mapping \\\n  --function-name orders-projector \\\n  --event-source-arn arn:aws:dynamodb:us-east-1:123:table/orders/stream/2026-01-01T00:00:00.000 \\\n  --starting-position LATEST --batch-size 100 \\\n  --maximum-retry-attempts 3 --bisect-batch-on-function-error \\\n  --destination-config ''{\"OnFailure\":{\"Destination\":\"arn:aws:sqs:...:orders-dlq\"}}''"}', '[{"kind": "source", "path": "src/streams/dynamodb-stream-handler.ts", "priority": "essential", "description": "Primary consumer for processing DynamoDB Streams change records"}, {"kind": "schema", "path": "src/streams/dynamodb-stream-events.json", "priority": "recommended", "description": "Expected change record shapes and downstream projection contracts"}, {"kind": "config", "path": "infra/dynamodb-streams.yaml", "priority": "recommended", "description": "Infrastructure and event source mapping configuration for DynamoDB Streams consumers"}]', '{"viewType": {"type": "string", "label": "Stream View Type", "default": "NEW_AND_OLD_IMAGES", "options": ["KEYS_ONLY", "NEW_IMAGE", "OLD_IMAGE", "NEW_AND_OLD_IMAGES"], "description": "Image view exposed in DynamoDB Streams records"}, "batchProcessing": {"type": "boolean", "label": "Batch Processing", "default": true, "description": "Process stream records in batches for throughput and efficiency"}, "filteringEnabled": {"type": "boolean", "label": "Filtering Enabled", "default": false, "description": "Apply event filtering before records reach downstream consumers"}}', '["serverless-function", "worker", "database", "monitoring", "backend-service"]', false, NULL, NULL, '2026-03-14 22:32:41.504306+00', '2026-08-31 20:07:01.887163+00', NULL, '#C0125F', '''across'':121B ''amazon'':7B,125C,130C,132C,135C,139C ''at-least-onc'':205C ''attribut'':164C ''audit'':46B ''aw'':1A,4A,11B,128C,141C ''backbon'':105B ''bisect'':187C ''block'':197C ''broader'':116B ''buse'':65B ''captur'':15B,81B ''chang'':13B,26B,56B,80B,92B,149C ''change-log'':148C ''choos'':57B ''cloudwatch'':140C ''configur'':184C ''consum'':156C,166C,180C ''contract'':212C ''data'':14B,137C ''delet'':32B ''deliber'':177C ''deliveri'':209C ''denorm'':43B ''destin'':192C ''direct'':52B ''downstream'':49B ''driven'':38B ''dynamodb'':2A,5A,8B,18B,54B,58B,73B,126C,131C ''emit'':21B ''enterpris'':103B ''event'':37B,64B,110B ''event-driven'':36B ''eventbridg'':133C ''everi'':161C ''failur'':191C ''featur'':168C ''forev'':200C ''function'':143C ''general'':62B,102B ''general-purpos'':61B ''getrecord'':159C ''handler'':204C ''idempot'':203C ''image/keys_only'':174C ''includ'':163C ''insert'':29B ''item'':24B,79B ''item-level'':23B ''kinesi'':136C ''lambda'':129C ''least'':207C ''level'':25B ''limit'':186C ''log'':150C ''long'':108B ''long-retent'':107B ''mani'':122B ''matter'':82B ''messag'':104B ''mutat'':42B ''near'':88B ''need'':170C ''never'':169C ''new'':173C ''on-failur'':189C ''one'':194C ''order'':22B,76B ''pattern'':86B,120B ''per'':78B,182C ''per-item'':77B ''pick'':172C ''pipe'':134C ''pipelin'':44B ''poison'':195C ''poll'':85B ''process'':50B ''produc'':124B ''project'':45B ''propag'':93B ''publish'':118B ''publish-subscrib'':117B ''purpos'':63B ''reaction'':39B ''real'':90B ''real-tim'':89B ''record'':27B,196C ''requir'':95B ''retent'':109B ''retri'':185C ''role'':157C,181C ''scope'':179C ''see'':160C ''shard'':199C ''sourc'':68B ''state'':55B ''step'':142C ''store'':111B ''stream'':3A,6A,9B,16B,59B,127C,138C,145C,183C ''subscrib'':119B ''substitut'':114B ''tabl'':19B,41B,74B,154C ''tie'':51B ''time'':91B ''trail'':47B ''truth'':70B ''type'':176C ''unrel'':123B ''updat'':30B ''use'':33B,98B ''view'':175C ''whole'':153C ''write'':162C,202C');
INSERT INTO public.technology_catalog VALUES ('aws-fargate', 'AWS Fargate', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-fargate.png', '#FF9900', '["docker-container", "serverless-function"]', '{"purpose": "AWS Fargate is AWS''s serverless compute engine for containers that runs Amazon ECS tasks and Amazon EKS pods without managing EC2 instances or cluster nodes. Use it for containerized services, background workers, batch-style tasks, and event-driven containers when you want right-sized compute and reduced infrastructure operations. Choose AWS Fargate over App Runner when you need deeper ECS or EKS integration and over EC2-backed containers when you do not want to manage host capacity. Do not use it when you need full host-level control, specialized daemon patterns, or cluster economics that favor self-managed nodes at very large scale.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS Fargate", "Amazon ECS", "Amazon EKS", "Amazon ECR", "Application Load Balancer", "Amazon CloudWatch", "AWS App Mesh"], "antiPatterns": ["Treating Fargate tasks as long-lived pets with host-level assumptions", "Using local ephemeral storage as the system of record for business data", "Packing many unrelated services into one task definition or pod without lifecycle alignment", "Choosing Fargate when workloads require privileged host access or custom daemon behavior", "Ignoring task sizing and overpaying for container resources that do not match demand", "Assuming serverless containers eliminate the need for observability, deployment discipline, or network design"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/AWS_Fargate.html"}, "bestPractices": ["Use Fargate for stateless containers and externalize durable state to managed backing services", "Size CPU and memory explicitly for each task or pod instead of relying on broad defaults", "Store images in trusted registries and pin production deployments by immutable image references", "Use task roles or pod execution identities instead of embedding credentials in container environments", "Separate service workloads from job-style workloads so scaling and retry behavior stay clear", "Monitor startup time, compute cost, memory pressure, and network behavior continuously", "Choose Fargate intentionally for operational simplicity rather than by default for every container workload"], "securityGuidance": "Two roles, two jobs: the execution role pulls images and secrets, the task role is what YOUR CODE can do — scope it per service and never reuse one broad task role across the fleet. Inject secrets via the secrets block (Secrets Manager/SSM references), not environment plaintext; run tasks in private subnets behind a load balancer; and pin images by digest so a task definition is an audit record, not a moving target.", "configurationTemplate": "{\n  \"family\": \"api\",\n  \"requiresCompatibilities\": [\"FARGATE\"],\n  \"networkMode\": \"awsvpc\",\n  \"cpu\": \"512\", \"memory\": \"1024\",\n  \"executionRoleArn\": \"arn:aws:iam::123:role/ecsExecRole\",\n  \"taskRoleArn\": \"arn:aws:iam::123:role/apiTaskRole\",\n  \"containerDefinitions\": [{ \"name\": \"api\", \"image\": \"123.dkr.ecr.us-east-1.amazonaws.com/api:sha\",\n    \"secrets\": [{ \"name\": \"DB_URL\", \"valueFrom\": \"arn:aws:secretsmanager:...:secret:db-url\" }] }]\n}"}', '[{"kind": "config", "path": "ecs/task-definition.json", "priority": "essential", "description": "Task definition or pod configuration for workloads launched on AWS Fargate"}, {"kind": "config", "path": "infra/fargate-service.yaml", "priority": "recommended", "description": "Infrastructure configuration for ECS or EKS services using AWS Fargate"}, {"kind": "source", "path": "src/containers/entrypoint.sh", "priority": "recommended", "description": "Container entrypoint script or startup command for Fargate workloads"}]', '{"launchType": {"type": "string", "label": "Launch Type", "default": "service", "options": ["service", "task", "job"], "description": "Primary runtime pattern for Fargate workloads"}, "orchestrator": {"type": "string", "label": "Orchestrator", "default": "ecs", "options": ["ecs", "eks", "batch"], "description": "Primary container orchestration platform for Fargate workloads"}, "publicIngress": {"type": "boolean", "label": "Public Ingress", "default": false, "description": "Expose Fargate workloads publicly through a load balancer or ingress layer"}}', '["object-storage", "load-balancer", "monitoring", "backend-service", "worker"]', false, NULL, NULL, '2026-03-14 21:45:27.163157+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''across'':162C ''amazon'':17B,21B,117C,119C,121C,126C ''app'':62B,129C ''applic'':123C ''audit'':197C ''aw'':1A,3A,5B,8B,59B,115C,128C ''back'':76B ''background'':36B ''balanc'':125C,185C ''batch'':39B ''batch-styl'':38B ''behind'':182C ''block'':170C ''broad'':159C ''capac'':86B ''choos'':58B ''cloudwatch'':127C ''cluster'':29B,103B ''code'':148C ''comput'':11B,53B ''contain'':14B,46B,77B ''container'':34B ''control'':98B ''daemon'':100B ''deeper'':67B ''definit'':194C ''digest'':190C ''driven'':45B ''ec'':18B,68B,118C ''ec2'':26B,75B ''ec2-backed'':74B ''econom'':104B ''ecr'':122C ''ek'':22B,70B,120C ''engin'':12B ''environ'':175C ''event'':44B ''event-driven'':43B ''execut'':136C ''fargat'':2A,4A,6B,60B,116C ''favor'':106B ''fleet'':164C ''full'':94B ''host'':85B,96B ''host-level'':95B ''imag'':139C,188C ''infrastructur'':56B ''inject'':165C ''instanc'':27B ''integr'':71B ''job'':134C ''larg'':113B ''level'':97B ''load'':124C,184C ''manag'':25B,84B,109B ''manager/ssm'':172C ''mesh'':130C ''move'':201C ''need'':66B,93B ''never'':156C ''node'':30B,110B ''one'':158C ''oper'':57B ''pattern'':101B ''per'':153C ''pin'':187C ''plaintext'':176C ''pod'':23B ''privat'':180C ''pull'':138C ''record'':198C ''reduc'':55B ''refer'':173C ''reus'':157C ''right'':51B ''right-siz'':50B ''role'':132C,137C,144C,161C ''run'':16B,177C ''runner'':63B ''scale'':114B ''scope'':151C ''secret'':141C,166C,169C,171C ''self'':108B ''self-manag'':107B ''serverless'':10B ''servic'':35B,154C ''size'':52B ''special'':99B ''style'':40B ''subnet'':181C ''target'':202C ''task'':19B,41B,143C,160C,178C,193C ''two'':131C,133C ''use'':31B,89B ''via'':167C ''want'':49B,82B ''without'':24B ''worker'':37B');
INSERT INTO public.technology_catalog VALUES ('solid', 'SolidJS', NULL, '#2c4f7c', '["frontend-app"]', '{"purpose": "Reactive JavaScript UI framework with fine-grained reactivity and no virtual DOM. SolidJS compiles components to direct DOM operations, delivering performance that rivals vanilla JavaScript while maintaining a developer experience similar to React. Use when you need the highest possible runtime performance for interactive web applications, when you want React-like JSX syntax without the VDOM overhead, or when you''re building performance-critical dashboards, visualizations, or real-time interfaces. Solid''s reactivity model (signals, memos, effects) updates only the exact DOM nodes that changed. Don''t use when your team is heavily invested in React ecosystem libraries that don''t have Solid equivalents. Don''t use for content-heavy sites where Astro or Next.js SSG would be simpler. Avoid if your project needs a mature, battle-tested ecosystem with extensive third-party component libraries -- React and Vue have larger ecosystems.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["SolidJS", "SolidStart", "Solid Router", "Vite", "Tailwind CSS", "solid-primitives", "Kobalte UI", "Vitest"], "antiPatterns": ["Destructuring signal accessors (props.count) in component body breaking reactivity tracking", "Using React mental model with re-renders -- Solid components run once, only signals update", "Creating unnecessary effects when derived state (createMemo) is sufficient", "Not using For component for lists causing unnecessary DOM recreation", "Importing React-specific libraries that depend on virtual DOM reconciliation", "Using createEffect for synchronous derived values instead of createMemo"], "apiReference": {"docsUrl": "https://docs.solidjs.com"}, "bestPractices": ["Use createSignal for reactive state and createMemo for derived computations", "Use createResource for async data fetching with built-in loading/error states", "Destructure props carefully -- use mergeProps or splitProps to maintain reactivity", "Use SolidStart for full-stack applications with SSR and file-based routing", "Leverage Solid''s fine-grained reactivity instead of React patterns like useMemo", "Use Show, For, Switch/Match control flow components instead of ternary expressions"], "sdkInitPattern": "npx degit solidjs/templates/ts my-app && cd my-app && npm install\\n// src/App.tsx\\nimport { createSignal } from \"solid-js\";\\nexport default function App() {\\n  const [count, setCount] = createSignal(0);\\n  return <button onClick={() => setCount(c => c + 1)}>Count: {count()}</button>;\\n}", "securityGuidance": "Solid auto-escapes JSX text content preventing XSS. Never use innerHTML prop with unsanitized user input. Validate and sanitize URLs passed to href or src attributes. Use Content Security Policy headers in production. Avoid storing sensitive tokens in signals that might be exposed via devtools -- use httpOnly cookies for auth.", "commonApiPatterns": [{"name": "Reactive Signal", "description": "Signal with derived memo for reactive state", "codeTemplate": "const [name, setName] = createSignal(\"\");\\nconst greeting = createMemo(() => `Hello, ${name() || \"World\"}!`);\\nreturn <div>\\n  <input value={name()} onInput={(e) => setName(e.target.value)} />\\n  <p>{greeting()}</p>\\n</div>;"}, {"name": "Async Resource", "description": "createResource for async data with Show/For control flow", "codeTemplate": "const [users] = createResource(async () => {\\n  const res = await fetch(\"/api/users\");\\n  return res.json() as Promise<User[]>;\\n});\\nreturn <Show when={!users.loading} fallback={<p>Loading...</p>}>\\n  <For each={users()}>{(user) => <div>{user.name}</div>}</For>\\n</Show>;"}, {"name": "Store for Complex State", "description": "Solid store with produce for nested immutable-style updates", "codeTemplate": "import { createStore, produce } from \"solid-js/store\";\\nconst [state, setState] = createStore({ todos: [] as Todo[] });\\nconst addTodo = (text: string) => setState(produce((s) => { s.todos.push({ id: Date.now(), text, done: false }); }));\\nconst toggle = (id: number) => setState(\"todos\", (t) => t.id === id, \"done\", (d) => !d);"}], "integrationPatterns": ["SolidStart for full-stack SSR/SSG with file-based routing and server functions", "Tailwind CSS for utility-first styling with Solid components", "Vitest + Solid Testing Library for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport solid from \"vite-plugin-solid\";\\nexport default defineConfig({\\n  plugins: [solid()],\\n  server: { port: 3000 },\\n  build: { target: \"esnext\" }\\n});"}', '[{"kind": "source", "path": "src/App.tsx", "language": "typescript", "description": "Root component"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "solidstart", "options": ["solidstart", "spa-vite"]}, "rendering": {"type": "enum", "label": "Rendering", "default": "ssr", "options": ["ssr", "csr", "static"]}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}}', '["rest-api", "graphql-api"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#234A6E', '''0'':193C ''1'':201C ''app'':169C,173C,187C ''applic'':49B ''astro'':120B ''attribut'':231C ''auth'':255C ''auto'':207C ''auto-escap'':206C ''avoid'':127B,239C ''battl'':135B ''battle-test'':134B ''build'':66B ''button'':196C ''c'':199C,200C ''cd'':170C ''chang'':91B ''compil'':17B ''compon'':18B,143B ''const'':189C ''content'':116B,211C,233C ''content-heavi'':115B ''cooki'':253C ''count'':190C,202C,203C '