INSERT INTO public.technology_catalog VALUES ('aws-ecr', 'AWS ECR', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-ecr.png', '#FF9900', '["container-registry"]', '{"purpose": "Fully managed Docker container registry from AWS that stores, manages, and deploys container images. Use when running containerized workloads on AWS services (ECS, EKS, Fargate, Lambda) and you need a private registry integrated with IAM for access control. ECR provides image scanning for vulnerabilities, lifecycle policies for automated cleanup of old images, and cross-region replication. It is the natural choice for CI/CD pipelines deploying to AWS container services. Don''t use when deploying outside AWS exclusively -- Docker Hub, GitHub Container Registry, or Google Artifact Registry may be more convenient. Don''t use ECR Public for private images that should not be openly accessible. Avoid if you have a simple deployment without containers where ECR adds unnecessary complexity.", "configMode": "declarative", "provenance": {"notes": "configMode assigned by deliverable shape during the N8.4r sweep. The rest of this row predates the enrichment chunks and has NOT been re-verified against live vendor docs — it is a candidate for the freshness pass, not a verified row.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Amazon ECR", "ECR Public", "AWS CLI", "Docker", "Amazon ECS", "Amazon EKS", "AWS CodeBuild", "Terraform aws_ecr_repository"], "antiPatterns": ["Not configuring lifecycle policies causing unlimited image accumulation and storage costs", "Using mutable tags (latest) in production causing inconsistent deployments", "Storing base images in ECR without vulnerability scanning", "Using access keys for ECR authentication instead of IAM roles and credential helpers", "Not encrypting repositories when storing images with sensitive configuration layers", "Pushing images without CI/CD pipeline validation (lint, test, scan)"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ecr/"}, "bestPractices": ["Enable image scanning on push to detect vulnerabilities before deployment", "Configure lifecycle policies to automatically clean up untagged and old images", "Use immutable image tags in production to prevent accidental overwrites", "Use ECR pull-through cache for upstream public images (Docker Hub, GitHub)", "Tag images with git SHA and semantic version for traceability", "Use cross-region replication for multi-region deployment architectures", "Authenticate with IAM roles instead of docker login with long-lived credentials"], "sdkInitPattern": "# Authenticate Docker with ECR\\naws ecr get-login-password --region us-east-1 | docker login --username AWS --password-stdin 123456789.dkr.ecr.us-east-1.amazonaws.com\\n# Build, tag, and push\\ndocker build -t myapp:v1.0.0 .\\ndocker tag myapp:v1.0.0 123456789.dkr.ecr.us-east-1.amazonaws.com/myapp:v1.0.0\\ndocker push 123456789.dkr.ecr.us-east-1.amazonaws.com/myapp:v1.0.0", "securityGuidance": "Use IAM policies to restrict who can push and pull images per repository. Enable image scanning on push and fail CI/CD pipelines on critical vulnerabilities. Use immutable tags to prevent image replacement attacks. Enable encryption at rest with KMS for repositories storing sensitive configurations. Use VPC endpoints to keep ECR traffic within the AWS network.", "commonApiPatterns": [{"name": "Create Repository", "description": "Create repository with scanning, immutable tags, and encryption", "codeTemplate": "aws ecr create-repository --repository-name myapp --image-scanning-configuration scanOnPush=true --image-tag-mutability IMMUTABLE --encryption-configuration encryptionType=AES256"}, {"name": "Lifecycle Policy", "description": "Lifecycle policy to auto-expire old and untagged images", "codeTemplate": "aws ecr put-lifecycle-policy --repository-name myapp --lifecycle-policy-text ''{\\n  \"rules\": [{\\n    \"rulePriority\": 1,\\n    \"description\": \"Keep last 20 tagged images\",\\n    \"selection\": { \"tagStatus\": \"tagged\", \"tagPrefixList\": [\"v\"], \"countType\": \"imageCountMoreThan\", \"countNumber\": 20 },\\n    \"action\": { \"type\": \"expire\" }\\n  },{\\n    \"rulePriority\": 2,\\n    \"description\": \"Expire untagged images after 7 days\",\\n    \"selection\": { \"tagStatus\": \"untagged\", \"countType\": \"sinceImagePushed\", \"countUnit\": \"days\", \"countNumber\": 7 },\\n    \"action\": { \"type\": \"expire\" }\\n  }]\\n}''"}, {"name": "Scan Results", "description": "Check vulnerability scan results for an image", "codeTemplate": "aws ecr describe-image-scan-findings --repository-name myapp --image-id imageTag=v1.0.0 --query \"imageScanFindings.findingSeverityCounts\""}], "integrationPatterns": ["CI/CD pipeline (CodeBuild, GitHub Actions) for automated build, scan, and push", "ECS/EKS task definitions referencing ECR image URIs for deployment", "EventBridge rules on ECR scan completion for automated vulnerability alerting"], "configurationTemplate": "resource \"aws_ecr_repository\" \"app\" {\\n  name                 = var.app_name\\n  image_tag_mutability = \"IMMUTABLE\"\\n  image_scanning_configuration {\\n    scan_on_push = true\\n  }\\n  encryption_configuration {\\n    encryption_type = \"AES256\"\\n  }\\n}\\nresource \"aws_ecr_lifecycle_policy\" \"app\" {\\n  repository = aws_ecr_repository.app.name\\n  policy = jsonencode({\\n    rules = [{\\n      rulePriority = 1\\n      description  = \"Keep last 20 images\"\\n      selection    = { tagStatus = \"any\", countType = \"imageCountMoreThan\", countNumber = 20 }\\n      action       = { type = \"expire\" }\\n    }]\\n  })\\n}"}', '[{"kind": "config", "path": "terraform/ecr.tf", "priority": "recommended", "description": "ECR repository and lifecycle policy definitions"}, {"kind": "config", "path": "docker/Dockerfile", "priority": "required", "description": "Container image build definition"}, {"kind": "config", "path": "ci/ecr-push.yml", "priority": "recommended", "description": "CI pipeline for building and pushing images"}]', '{"scanOnPush": {"type": "boolean", "label": "Scan on Push", "default": true}, "imageTagMutability": {"type": "string", "label": "Tag Mutability", "default": "IMMUTABLE"}, "lifecyclePolicyMaxImages": {"type": "number", "label": "Max Image Count", "default": 50}}', '["ecs-cluster", "k8s-cluster", "serverless-function", "worker"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''/myapp:v1.0.0'':180C,185C ''1'':155C ''123456789.dkr.ecr.us-east-1.amazonaws.com'':163C,179C,184C ''123456789.dkr.ecr.us-east-1.amazonaws.com/myapp:v1.0.0'':178C,183C ''access'':41B,109B ''add'':121B ''amazon'':124C,131C,133C ''artifact'':90B ''attack'':218C ''authent'':141C ''autom'':52B ''avoid'':110B ''aw'':1A,3A,11B,25B,72B,81B,128C,135C,138C,159C,239C ''build'':165C,170C ''choic'':66B ''ci/cd'':68B,206C ''cleanup'':53B ''cli'':129C ''codebuild'':136C ''complex'':123B ''configur'':229C ''contain'':8B,17B,73B,86B,118B ''container'':22B ''control'':42B ''conveni'':95B ''critic'':209C ''cross'':59B ''cross-region'':58B ''deploy'':16B,70B,79B,116B ''docker'':7B,83B,130C,142C,156C ''east'':154C ''ec'':27B,132C ''ecr'':2A,4A,43B,99B,120B,125C,126C,139C,144C,146C,235C ''ek'':28B,134C ''enabl'':199C,219C ''encrypt'':220C ''endpoint'':232C ''exclus'':82B ''fail'':205C ''fargat'':29B ''fulli'':5B ''get'':148C ''get-login-password'':147C ''github'':85B ''googl'':89B ''hub'':84B ''iam'':39B,187C ''imag'':18B,45B,56B,103B,196C,200C,216C ''immut'':212C ''integr'':37B ''keep'':234C ''kms'':224C ''lambda'':30B ''lifecycl'':49B ''login'':149C,157C ''manag'':6B,14B ''may'':92B ''myapp'':172C,176C ''n'':164C ''natur'':65B ''naw'':145C ''ndocker'':169C,174C,181C ''need'':33B ''network'':240C ''old'':55B ''open'':108B ''outsid'':80B ''password'':150C,161C ''password-stdin'':160C ''per'':197C ''pipelin'':69B,207C ''polici'':50B,188C ''prevent'':215C ''privat'':35B,102B ''provid'':44B ''public'':100B,127C ''pull'':195C ''push'':168C,182C,193C,203C ''region'':60B,151C ''registri'':9B,36B,87B,91B ''replac'':217C ''replic'':61B ''repositori'':140C,198C,226C ''rest'':222C ''restrict'':190C ''run'':21B ''scan'':46B,201C ''sensit'':228C ''servic'':26B,74B ''simpl'':115B ''stdin'':162C ''store'':13B,227C ''tag'':166C,175C,213C ''terraform'':137C ''traffic'':236C ''unnecessari'':122B ''us'':153C ''us-east'':152C ''use'':19B,77B,98B,186C,211C,230C ''usernam'':158C ''v1.0.0'':173C,177C ''vpc'':231C ''vulner'':48B,210C ''within'':237C ''without'':117B ''workload'':23B');
INSERT INTO public.technology_catalog VALUES ('aws-appsync', 'AWS AppSync', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-appsync.png', '#E7157B', '["backend-service"]', '{"purpose": "Fully managed GraphQL API service that simplifies application development with real-time data synchronization and offline programming. Connects to DynamoDB, Lambda, RDS, OpenSearch, and HTTP data sources. Supports subscriptions for real-time updates, pipeline resolvers for complex operations, and built-in caching. Best for mobile and web apps needing real-time data sync.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using AppSync for purely REST-style CRUD when API Gateway would be simpler", "Writing overly complex VTL templates instead of delegating to Lambda resolvers", "Not implementing proper authorization on resolver level", "Using a single monolithic schema instead of modular schema stitching"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/appsync/"}, "bestPractices": ["Use pipeline resolvers to compose multiple data sources in a single query", "Enable API caching for frequently queried fields to reduce data source calls", "Use VTL resolver mapping templates for simple transformations, Lambda for complex logic", "Implement fine-grained authorization with Cognito groups or IAM policies", "Use subscriptions for real-time features instead of polling", "Enable WAF integration for API protection"], "securityGuidance": "API keys are for prototypes — production APIs authenticate with Cognito user pools, OIDC, or IAM, and authorization lives IN the resolvers: filter by $ctx.identity (sub/claims) so a query can only reach the caller''s rows. Each data source role is scoped to its table/function; depth and complexity limits bound abusive queries; and subscriptions authorize on connect AND on the filtered payload.", "configurationTemplate": "# schema.graphql + resolver mapping\ntype Order @aws_cognito_user_pools {\n  id: ID!\n  total: Float!\n}\ntype Query {\n  myOrders: [Order] @aws_cognito_user_pools\n}\n# resolver: DynamoDB Query on ownerId = $ctx.identity.sub"}', '[{"kind": "schema", "path": "graphql/schema.graphql", "priority": "required", "description": "AppSync GraphQL schema definition"}, {"kind": "config", "path": "terraform/appsync.tf", "priority": "recommended", "description": "AppSync API and data source configuration"}, {"kind": "source", "path": "graphql/resolvers/", "priority": "recommended", "description": "Resolver mapping templates"}]', '{"xrayEnabled": {"type": "boolean", "label": "X-Ray Tracing", "default": false}, "cachingEnabled": {"type": "boolean", "label": "API Caching", "default": false}, "authenticationType": {"type": "string", "label": "Auth Type", "default": "AMAZON_COGNITO_USER_POOLS"}}', '["database", "serverless-function", "auth-provider", "frontend-app"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''abus'':111C ''api'':8B,62C,68C ''app'':55B ''applic'':12B ''appsync'':2A,4A ''authent'':69C ''author'':78C,115C ''aw'':1A,3A ''best'':50B ''bound'':110C ''built'':47B ''built-in'':46B ''cach'':49B ''caller'':94C ''cognito'':71C ''complex'':43B,108C ''connect'':23B,117C ''ctx.identity'':85C ''data'':18B,31B,60B,98C ''depth'':106C ''develop'':13B ''dynamodb'':25B ''filter'':83C,121C ''fulli'':5B ''graphql'':7B ''http'':30B ''iam'':76C ''key'':63C ''lambda'':26B ''limit'':109C ''live'':79C ''manag'':6B ''mobil'':52B ''need'':56B ''offlin'':21B ''oidc'':74C ''opensearch'':28B ''oper'':44B ''payload'':122C ''pipelin'':40B ''pool'':73C ''product'':67C ''program'':22B ''prototyp'':66C ''queri'':89C,112C ''rds'':27B ''reach'':92C ''real'':16B,37B,58B ''real-tim'':15B,36B,57B ''resolv'':41B,82C ''role'':100C ''row'':96C ''scope'':102C ''servic'':9B ''simplifi'':11B ''sourc'':32B,99C ''sub/claims'':86C ''subscript'':34B,114C ''support'':33B ''sync'':61B ''synchron'':19B ''table/function'':105C ''time'':17B,38B,59B ''updat'':39B ''user'':72C ''web'':54B');
INSERT INTO public.technology_catalog VALUES ('unreal-engine', 'Unreal Engine', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/unreal-engine.svg', '#0E1128', '["desktop-app", "game-client"]', '{"purpose": "AAA game engine for high-fidelity 3D games, simulations, and real-time experiences using C++ and Blueprints visual scripting", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Unreal Engine 5", "C++", "Blueprints", "Gameplay Ability System", "Niagara VFX", "Nanite", "Lumen", "MetaSounds"], "antiPatterns": ["Tick-heavy actors without proper tick management or timers", "Not using object pooling for projectiles and effects", "Hard references causing entire asset chains to load into memory", "Putting game logic in level Blueprints instead of reusable actors", "Not using the Gameplay Tag system for flexible categorization", "Ignoring the Garbage Collector by holding raw pointers to UObjects", "Not implementing proper network relevancy for multiplayer games"], "apiReference": {"docsUrl": "https://dev.epicgames.com/documentation/en-us/unreal-engine"}, "bestPractices": ["Use the Gameplay Framework (GameMode, GameState, PlayerController, Pawn/Character)", "Leverage Blueprints for rapid prototyping, C++ for performance-critical systems", "Use Gameplay Ability System for combat and ability mechanics", "Implement proper asset management with soft references and async loading", "Use Subsystems for singleton-like functionality with proper lifecycle", "Follow Unreal naming conventions (A for Actors, U for UObjects, F for structs)", "Use Unreal Header Tool macros (UPROPERTY, UFUNCTION, UCLASS) for reflection", "Implement proper replication for multiplayer with RPCs and replicated properties"], "sdkInitPattern": "// PlayerCharacter.cpp — replicated movement intent with server validation\nvoid APlayerCharacter::MoveForward(float Value)\n{\n    if (IsLocallyControlled())\n        ServerMove(Value);\n}\n\nbool APlayerCharacter::ServerMove_Validate(float Value)\n{\n    return FMath::Abs(Value) <= 1.0f;  // reject impossible inputs — failing validation kicks the client\n}\n\nvoid APlayerCharacter::ServerMove_Implementation(float Value)\n{\n    AddMovementInput(GetActorForwardVector(), Value);  // server simulates; replication sends state down\n}", "securityGuidance": "Use the dedicated-server model for anything competitive — listen servers hand one player the authority — and put real checks in every Server RPC''s _Validate (impossible inputs kick the sender) plus rate limits in _Implementation; the client build is unpackable (pak/utoc mining is routine), so no secrets, no loot tables, no authoritative economy client-side. Property replication conditions (COND_OwnerOnly) keep hidden information hidden — replicating every player''s hand to everyone is wallhack-by-design. Online-subsystem keys and platform credentials belong to your backend, and UGC (pak mods) executes native code: sign what you load or sandbox what you cannot."}', '[{"kind": "source", "path": "Source/MyGame/Private/MyGameCharacter.cpp", "language": "cpp", "description": "Character implementation"}, {"kind": "source", "path": "Source/MyGame/Public/MyGameCharacter.h", "language": "cpp", "description": "Character header"}, {"kind": "config", "path": "MyGame.uproject", "language": "json", "description": "Unreal project descriptor"}, {"kind": "config", "path": "Config/DefaultEngine.ini", "language": "ini", "description": "Engine configuration"}, {"kind": "config", "path": "Config/DefaultGame.ini", "language": "ini", "description": "Game configuration"}]', '{"targets": {"type": "multiselect", "label": "Targets", "options": ["pc-console", "mobile"], "description": "One project, one node — build targets are configuration"}, "language": {"type": "enum", "label": "Authoring", "default": "mixed", "options": ["blueprints", "cpp", "mixed"]}}', '["rest-api", "database"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-31 20:06:52.233344+00', 'Unreal Engine', NULL, '''1.0'':65C ''3d'':12B ''5'':28C ''aaa'':5B ''ab'':63C ''abil'':32C ''addmovementinput'':81C ''anyth'':96C ''aplayercharact'':47C,56C,76C ''author'':104C ''authorit'':141C ''backend'':177C ''belong'':174C ''blueprint'':23B,30C ''bool'':55C ''build'':127C ''c'':21B,29C ''cannot'':193C ''check'':108C ''client'':74C,126C,144C ''client-sid'':143C ''code'':184C ''competit'':97C ''cond'':149C ''condit'':148C ''credenti'':173C ''dedic'':92C ''dedicated-serv'':91C ''design'':166C ''economi'':142C ''engin'':2A,4A,7B,27C ''everi'':110C,156C ''everyon'':161C ''execut'':182C ''experi'':19B ''f'':66C ''fail'':70C ''fidel'':11B ''float'':49C,59C,79C ''fmath'':62C ''game'':6B,13B ''gameplay'':31C ''getactorforwardvector'':82C ''hand'':100C,159C ''hidden'':152C,154C ''high'':10B ''high-fidel'':9B ''implement'':78C,124C ''imposs'':68C,115C ''inform'':153C ''input'':69C,116C ''intent'':42C ''islocallycontrol'':52C ''keep'':151C ''key'':170C ''kick'':72C,117C ''limit'':122C ''listen'':98C ''load'':188C ''loot'':138C ''lumen'':37C ''metasound'':38C ''mine'':131C ''mod'':181C ''model'':94C ''moveforward'':48C ''movement'':41C ''nanit'':36C ''nativ'':183C ''niagara'':34C ''one'':101C ''onlin'':168C ''online-subsystem'':167C ''owneron'':150C ''pak'':180C ''pak/utoc'':130C ''platform'':172C ''player'':102C,157C ''playercharacter.cpp'':39C ''plus'':120C ''properti'':146C ''put'':106C ''rate'':121C ''real'':17B,107C ''real-tim'':16B ''reject'':67C ''replic'':40C,86C,147C,155C ''return'':61C ''routin'':133C ''rpc'':112C ''sandbox'':190C ''script'':25B ''secret'':136C ''send'':87C ''sender'':119C ''server'':44C,84C,93C,99C,111C ''servermov'':53C,57C,77C ''side'':145C ''sign'':185C ''simul'':14B,85C ''state'':88C ''subsystem'':169C ''system'':33C ''tabl'':139C ''time'':18B ''ugc'':179C ''unpack'':129C ''unreal'':1A,3A,26C ''use'':20B,89C ''valid'':45C,58C,71C,114C ''valu'':50C,54C,60C,64C,80C,83C ''vfx'':35C ''visual'':24B ''void'':46C,75C ''wallhack'':164C ''wallhack-by-design'':163C');
INSERT INTO public.technology_catalog VALUES ('flutter', 'Flutter', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/flutter.png', '#02569B', '["mobile-app"]', '{"purpose": "Google''s cross-platform UI toolkit for building natively compiled applications for mobile, web, and desktop from a single Dart codebase. Flutter uses its own rendering engine (Skia/Impeller) rather than platform widgets, giving pixel-perfect control across platforms. Use when building mobile apps that need to run on both iOS and Android with a single codebase and a highly custom UI. Flutter excels at apps with rich animations, custom designs, and when team velocity across platforms matters more than native look-and-feel. Don''t use when you need deeply integrated platform-native UI that must look exactly like stock iOS/Android controls -- native SwiftUI/Jetpack Compose will feel more natural. Don''t use for simple content apps where React Native or a PWA would suffice with less toolchain complexity. Avoid if your team has no Dart experience and the project timeline is tight.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Flutter", "Dart", "Riverpod", "Bloc", "go_router", "freezed", "Hive/Drift", "Flutter DevTools"], "antiPatterns": ["Deeply nested widget trees making code unreadable (extract into separate widgets)", "Using setState everywhere instead of structured state management", "Not separating business logic from UI widgets", "Ignoring platform-specific adaptations (navigation patterns, keyboard behavior)", "Not using const constructors causing unnecessary widget rebuilds", "Building one massive widget instead of composing smaller specialized widgets"], "apiReference": {"docsUrl": "https://docs.flutter.dev"}, "bestPractices": ["Use Riverpod or Bloc for state management with clear separation from UI", "Follow widget composition over inheritance -- break UI into small, reusable widgets", "Implement go_router for declarative, deep-link-capable routing", "Use freezed for immutable data classes with union types", "Follow platform design guidelines (Material on Android, Cupertino on iOS)", "Write widget tests and golden tests for UI regression detection", "Use const constructors aggressively to optimize widget rebuild performance"], "sdkInitPattern": "flutter create my_app && cd my_app && flutter run\\n// lib/main.dart\\nimport ''package:flutter/material.dart'';\\nvoid main() => runApp(const MyApp());\\nclass MyApp extends StatelessWidget {\\n  const MyApp({super.key});\\n  @override\\n  Widget build(BuildContext context) {\\n    return MaterialApp(home: Scaffold(body: Center(child: Text(''Hello Flutter''))));\\n  }\\n}", "securityGuidance": "Never embed API keys or secrets in Dart code -- they are extractable from compiled binaries. Use platform-specific secure storage (flutter_secure_storage) for tokens. Implement certificate pinning for sensitive API connections. Validate and sanitize all user inputs. Use ProGuard/R8 on Android and bitcode on iOS to obfuscate release builds.", "commonApiPatterns": [{"name": "Stateful Widget", "description": "Stateful widget with setState for local state", "codeTemplate": "class Counter extends StatefulWidget {\\n  const Counter({super.key});\\n  @override\\n  State<Counter> createState() => _CounterState();\\n}\\nclass _CounterState extends State<Counter> {\\n  int _count = 0;\\n  @override\\n  Widget build(BuildContext context) {\\n    return ElevatedButton(\\n      onPressed: () => setState(() => _count++),\\n      child: Text(''Count: $_count''),\\n    );\\n  }\\n}"}, {"name": "Riverpod Provider", "description": "Riverpod async data fetching with loading/error states", "codeTemplate": "final usersProvider = FutureProvider<List<User>>((ref) async {\\n  final response = await http.get(Uri.parse(''$baseUrl/api/users''));\\n  return (jsonDecode(response.body) as List).map((j) => User.fromJson(j)).toList();\\n});\\n// In widget:\\nfinal users = ref.watch(usersProvider);\\nreturn users.when(\\n  data: (list) => ListView.builder(itemCount: list.length, itemBuilder: (_, i) => Text(list[i].name)),\\n  loading: () => const CircularProgressIndicator(),\\n  error: (e, _) => Text(''Error: $e''),\\n);"}, {"name": "Navigation", "description": "Declarative routing with go_router and path parameters", "codeTemplate": "final router = GoRouter(routes: [\\n  GoRoute(path: ''/'', builder: (_, __) => const HomeScreen()),\\n  GoRoute(path: ''/user/:id'', builder: (_, state) => UserScreen(id: state.pathParameters[''id'']!)),\\n]);"}], "setupInstructions": [{"url": "https://docs.flutter.dev/get-started/install", "type": "toolchain_install", "title": "Install Flutter SDK", "commands": ["git clone https://github.com/flutter/flutter.git -b stable", "export PATH=\"$PATH:$(pwd)/flutter/bin\"", "flutter doctor"], "required": true, "instructions": "Download and install the Flutter SDK. Add flutter/bin to your PATH."}, {"type": "toolchain_install", "title": "Configure Android SDK", "commands": ["flutter doctor --android-licenses"], "required": true, "instructions": "Install Android Studio and configure the Android SDK for Android builds. Accept Android licenses."}, {"type": "toolchain_install", "title": "Configure iOS Development (macOS only)", "commands": ["sudo xcode-select --switch /Applications/Xcode.app/Contents/Developer", "sudo xcodebuild -license accept"], "required": false, "instructions": "Install Xcode from the Mac App Store. Configure Xcode command line tools and accept the license."}, {"type": "dashboard_config", "title": "Configure App Signing", "required": false, "instructions": "Set up signing configurations for release builds. Android: generate a keystore. iOS: configure provisioning profiles in Apple Developer portal."}], "integrationPatterns": ["Firebase or Supabase for backend services (auth, database, storage)", "Platform channels for accessing native iOS/Android APIs not available in Dart", "CI/CD with Codemagic or GitHub Actions for automated builds and store deployment"], "configurationTemplate": "# pubspec.yaml\\nname: my_app\\ndescription: My Flutter application\\npublish_to: none\\nversion: 1.0.0+1\\n\\nenvironment:\\n  sdk: \">=3.2.0 <4.0.0\"\\n\\ndependencies:\\n  flutter:\\n    sdk: flutter\\n  flutter_riverpod: ^2.4.0\\n  go_router: ^13.0.0\\n  freezed_annotation: ^2.4.0\\n  json_annotation: ^4.8.0\\n\\ndev_dependencies:\\n  flutter_test:\\n    sdk: flutter\\n  build_runner: ^2.4.0\\n  freezed: ^2.4.0\\n  json_serializable: ^6.7.0"}', '[{"kind": "config", "path": "pubspec.yaml", "language": "yaml", "description": "Flutter project dependencies and configuration"}, {"kind": "source", "path": "lib/main.dart", "language": "dart", "description": "Application entry point"}, {"kind": "source", "path": "lib/app.dart", "language": "dart", "description": "Root application widget"}, {"kind": "source", "path": "lib/screens/home_screen.dart", "language": "dart", "description": "Home screen widget"}, {"kind": "source", "path": "test/widget_test.dart", "language": "dart", "description": "Widget test suite"}, {"kind": "config", "path": "analysis_options.yaml", "language": "yaml", "description": "Dart analyzer configuration"}]', '{"codegen": {"type": "enum", "label": "Serialization", "default": "freezed-json-serializable", "options": ["freezed-json-serializable", "manual"]}, "flavors": {"type": "boolean", "label": "Build flavors", "default": true, "description": "dev/staging/prod app ids and configs — retrofitting flavors later is painful"}, "targets": {"type": "multiselect", "label": "Targets", "options": ["ios", "android", "web", "windows", "macos", "linux"], "description": "One codebase, one node — say where it actually ships; each desktop target adds CI and signing work"}, "stateManagement": {"type": "enum", "label": "State management", "default": "riverpod", "options": ["riverpod", "bloc", "provider", "setState-only"]}, "platformChannels": {"type": "boolean", "label": "Native platform channels", "default": false, "description": "The Dart↔native boundary — every channel is code written twice, plan them"}}', '["web.rest-api", "auth.supabase-auth", "auth.firebase-auth"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-31 20:06:52.233344+00', NULL, '#01467D', '''across'':41B,79B ''android'':56B,248C ''anim'':72B ''api'':208C,237C ''app'':47B,69B,122B,162C,165C ''applic'':14B ''avoid'':135B ''binari'':220C ''bitcod'':250C ''bloc'':152C ''bodi'':198C ''build'':11B,45B,190C,256C ''buildcontext'':191C ''cd'':163C ''center'':199C ''certif'':233C ''child'':200C ''code'':214C ''codebas'':24B,60B ''compil'':13B,219C ''complex'':134B ''compos'':111B ''connect'':238C ''const'':176C,183C ''content'':121B ''context'':192C ''control'':40B,108B ''creat'':160C ''cross'':6B ''cross-platform'':5B ''custom'':64B,73B ''dart'':23B,141B,150C,213C ''deepli'':95B ''design'':74B ''desktop'':19B ''devtool'':158C ''emb'':207C ''engin'':30B ''exact'':104B ''excel'':67B ''experi'':142B ''extend'':180C ''extract'':217C ''feel'':88B,113B ''flutter'':1A,2A,25B,66B,149C,157C,159C,166C,203C,227C ''flutter/material.dart'':172C ''freez'':155C ''give'':36B ''go'':153C ''googl'':3B ''hello'':202C ''high'':63B ''hive/drift'':156C ''home'':196C ''implement'':232C ''input'':244C ''integr'':96B ''io'':54B,252C ''ios/android'':107B ''key'':209C ''less'':132B ''lib/main.dart'':169C ''like'':105B ''look'':86B,103B ''look-and-feel'':85B ''main'':174C ''materialapp'':195C ''matter'':81B ''mobil'':16B,46B ''must'':102B ''myapp'':177C,179C,184C ''n'':168C,182C,186C,188C,193C,204C,205C ''nativ'':12B,84B,99B,109B,125B ''natur'':115B ''nclass'':178C ''need'':49B,94B ''never'':206C ''nimport'':170C ''nvoid'':173C ''obfusc'':254C ''overrid'':187C ''packag'':171C ''perfect'':39B ''pin'':234C ''pixel'':38B ''pixel-perfect'':37B ''platform'':7B,34B,42B,80B,98B,223C ''platform-n'':97B ''platform-specif'':222C ''proguard/r8'':246C ''project'':145B ''pwa'':128B ''rather'':32B ''react'':124B ''releas'':255C ''render'':29B ''return'':194C ''rich'':71B ''riverpod'':151C ''router'':154C ''run'':51B,167C ''runapp'':175C ''sanit'':241C ''scaffold'':197C ''secret'':211C ''secur'':225C,228C ''sensit'':236C ''simpl'':120B ''singl'':22B,59B ''skia/impeller'':31B ''specif'':224C ''statelesswidget'':181C ''stock'':106B ''storag'':226C,229C ''suffic'':130B ''super.key'':185C ''swiftui/jetpack'':110B ''team'':77B,138B ''text'':201C ''tight'':148B ''timelin'':146B ''token'':231C ''toolchain'':133B ''toolkit'':9B ''ui'':8B,65B,100B ''use'':26B,43B,91B,118B,221C,245C ''user'':243C ''valid'':239C ''veloc'':78B ''web'':17B ''widget'':35B,189C ''would'':129B');
INSERT INTO public.technology_catalog VALUES ('photon', 'Photon Engine', NULL, '#6b7280', '["game-server"]', '{"purpose": "Managed multiplayer networking platform (global relay network, matchmaking, Unity/Unreal SDKs): Fusion for state-sync games, Quantum for deterministic rollback simulation — PUN 2 is the legacy product. The zero-ops lane priced per CCU; server-side logic control is limited compared to Nakama/self-hosted.", "configMode": "declarative", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-28. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Photon Fusion", "Photon Quantum", "matchmaking", "Unity/Unreal SDKs", "global relays"], "antiPatterns": ["Starting new projects on PUN 2 — legacy lane; Fusion is the successor", "Competitive gameplay logic client-side because the relay makes it easy", "Ignoring per-CCU economics until launch week"], "apiReference": {"docsUrl": "https://doc.photonengine.com/"}, "bestPractices": ["Pick the product by netcode model: Fusion (state sync) vs Quantum (deterministic lockstep/rollback) — migrating between them is a rewrite", "Regions + relay selection tuned to the player base; test cross-region latency early", "Budget CCU pricing against projected concurrency BEFORE the architecture hardens"], "sdkInitPattern": "// Photon Fusion — server/host authority with input transfer\npublic class PlayerMovement : NetworkBehaviour\n{\n    public override void FixedUpdateNetwork()\n    {\n        if (GetInput(out NetworkInputData input))   // host receives INPUT, not positions\n        {\n            var dir = Vector3.ClampMagnitude(input.Direction, 1f);\n            _controller.Move(dir * Runner.DeltaTime * Speed);  // authority simulates\n        }\n    }\n}", "securityGuidance": "The AppId is discoverable in any shipped client — it identifies your app, it does not authenticate players, so wire Photon''s custom authentication to YOUR backend and treat unauthenticated rooms as public spaces. In shared-mode/client-hosted topologies every peer can lie: use server/host authority (Fusion) for anything competitive, transfer input rather than state, and validate what the authority receives. Webhooks back to your services must verify the configured secret, room properties are visible to all joiners (no hidden data there), and the dashboard credential is production access to your realtime traffic."}', '[{"kind": "code", "path": "Assets/Scripts/Network/NetworkBootstrap.cs", "language": "csharp", "description": "Fusion runner bootstrap — server/host authority, custom auth wired to your backend"}]', '{"hosting": {"type": "enum", "label": "Hosting", "default": "photon-cloud", "options": ["photon-cloud", "enterprise-dedicated"]}, "product": {"type": "enum", "label": "Product", "default": "fusion", "options": ["fusion", "quantum", "pun-2-legacy", "realtime-sdk"], "description": "Fusion is the current state-sync product (PUN 2 is the legacy lane); Quantum for deterministic/rollback simulation (fighting/RTS)"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/client-hosted'':131C ''1f'':87C ''2'':26B ''access'':182C ''anyth'':142C ''app'':105C ''appid'':95C ''authent'':109C,116C ''author'':61C,92C,139C,153C ''back'':156C ''backend'':119C ''ccu'':38B ''class'':66C ''client'':101C ''compar'':46B ''competit'':143C ''configur'':163C ''control'':43B ''controller.move'':88C ''credenti'':179C ''custom'':115C ''dashboard'':178C ''data'':174C ''determinist'':22B ''dir'':84C,89C ''discover'':97C ''engin'':2A ''everi'':133C ''fixedupdatenetwork'':72C ''fusion'':14B,50C,59C,140C ''game'':19B ''getinput'':74C ''global'':8B,56C ''hidden'':173C ''host'':78C ''identifi'':103C ''input'':63C,77C,80C,145C ''input.direction'':86C ''joiner'':171C ''lane'':35B ''legaci'':29B ''lie'':136C ''limit'':45B ''logic'':42B ''manag'':4B ''matchmak'':11B,53C ''mode'':130C ''multiplay'':5B ''must'':160C ''nakama/self-hosted'':48B ''network'':6B,10B ''networkbehaviour'':68C ''networkinputdata'':76C ''op'':34B ''overrid'':70C ''peer'':134C ''per'':37B ''photon'':1A,3A,49C,51C,58C,113C ''platform'':7B ''player'':110C ''playermov'':67C ''posit'':82C ''price'':36B ''product'':30B,181C ''properti'':166C ''public'':65C,69C,125C ''pun'':25B ''quantum'':20B,52C ''rather'':146C ''realtim'':185C ''receiv'':79C,154C ''relay'':9B,57C ''rollback'':23B ''room'':123C,165C ''runner.deltatime'':90C ''sdks'':13B,55C ''secret'':164C ''server'':40B ''server-sid'':39B ''server/host'':60C,138C ''servic'':159C ''share'':129C ''shared-mod'':128C ''ship'':100C ''side'':41B ''simul'':24B,93C ''space'':126C ''speed'':91C ''state'':17B,148C ''state-sync'':16B ''sync'':18B ''topolog'':132C ''traffic'':186C ''transfer'':64C,144C ''treat'':121C ''unauthent'':122C ''unity/unreal'':12B,54C ''use'':137C ''valid'':150C ''var'':83C ''vector3.clampmagnitude'':85C ''verifi'':161C ''visibl'':168C ''void'':71C ''webhook'':155C ''wire'':112C ''zero'':33B ''zero-op'':32B');
INSERT INTO public.technology_catalog VALUES ('aws-rds', 'AWS RDS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-rds.png', '#3B48CC', '["database"]', '{"purpose": "AWS managed relational database service supporting PostgreSQL, MySQL, MariaDB, Oracle, and SQL Server engines with automated backups, patching, and Multi-AZ failover. Best for traditional relational workloads on AWS where you want managed infrastructure without the enhanced performance of Aurora. Use RDS when you need a specific engine version, Oracle/SQL Server compatibility, or lower cost than Aurora for smaller workloads. Choose Aurora over RDS when you need higher throughput, auto-scaling storage, or global databases.", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Placing RDS in public subnets", "Not enabling Multi-AZ for production", "Using RDS when Aurora Serverless v2 would be more cost-effective for variable workloads", "Hardcoding database credentials instead of using Secrets Manager", "Not setting up CloudWatch alarms for critical metrics"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/rds/"}, "bestPractices": ["Enable Multi-AZ for production workloads", "Use read replicas for read-heavy applications", "Enable automated backups with appropriate retention period", "Use IAM database authentication where possible", "Place RDS in private subnets with security groups", "Enable Performance Insights for query analysis"], "securityGuidance": "No public accessibility; the security group admits only the application tier. Let RDS manage the master password in Secrets Manager (--manage-master-user-password) and use IAM database authentication for application access where the engine supports it. Encrypt storage with KMS and require TLS in transit. Keep automated backups + deletion protection on for production — an unprotected prod instance is one API call from gone.", "configurationTemplate": "# Private Postgres instance, encrypted, no public access\r\naws rds create-db-instance --db-instance-identifier app-db \\\r\n  --engine postgres --db-instance-class db.t4g.medium --allocated-storage 50 \\\r\n  --master-username appadmin --manage-master-user-password \\\r\n  --no-publicly-accessible --storage-encrypted \\\r\n  --vpc-security-group-ids sg-app-tier --deletion-protection"}', '[{"kind": "schema", "path": "database/schema.sql", "priority": "essential", "description": "Database schema definitions"}, {"kind": "schema", "path": "database/migrations/", "priority": "essential", "description": "Database migration files"}, {"kind": "config", "path": "terraform/rds.tf", "priority": "recommended", "description": "RDS instance infrastructure definition"}, {"kind": "source", "path": "src/database/db-client.ts", "priority": "essential", "description": "Database connection client"}]', '{"engine": {"enum": ["postgresql", "mysql", "mariadb", "oracle", "sqlserver"], "type": "string", "label": "Engine", "default": "postgresql"}, "multiAz": {"type": "boolean", "label": "Multi-AZ", "default": true}, "storageType": {"enum": ["gp3", "io1", "io2"], "type": "string", "label": "Storage Type", "default": "gp3"}, "readReplicas": {"type": "number", "label": "Read Replicas", "default": 0}, "engineVersion": {"type": "string", "label": "Engine Version"}, "instanceClass": {"type": "string", "label": "Instance Class", "default": "db.t3.medium"}}', '["rest-api", "worker", "serverless-function"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', 'AWS RDS', '#2F3AA3', '''access'':84C,114C ''admit'':88C ''api'':143C ''applic'':91C,113C ''aurora'':45B,62B,67B ''authent'':111C ''auto'':76B ''auto-sc'':75B ''autom'':20B,130C ''aw'':1A,3A,5B,34B ''az'':26B ''backup'':21B,131C ''best'':28B ''call'':144C ''choos'':66B ''compat'':57B ''cost'':60B ''databas'':8B,81B,110C ''delet'':132C ''encrypt'':120C ''engin'':18B,53B,117C ''enhanc'':42B ''failov'':27B ''global'':80B ''gone'':146C ''group'':87C ''higher'':73B ''iam'':109C ''infrastructur'':39B ''instanc'':140C ''keep'':129C ''kms'':123C ''let'':93C ''lower'':59B ''manag'':6B,38B,95C,101C,103C ''manage-master-user-password'':102C ''mariadb'':13B ''master'':97C,104C ''multi'':25B ''multi-az'':24B ''mysql'':12B ''need'':50B,72B ''one'':142C ''oracl'':14B ''oracle/sql'':55B ''password'':98C,106C ''patch'':22B ''perform'':43B ''postgresql'':11B ''prod'':139C ''product'':136C ''protect'':133C ''public'':83C ''rds'':2A,4A,47B,69B,94C ''relat'':7B,31B ''requir'':125C ''scale'':77B ''secret'':100C ''secur'':86C ''server'':17B,56B ''servic'':9B ''smaller'':64B ''specif'':52B ''sql'':16B ''storag'':78B,121C ''support'':10B,118C ''throughput'':74B ''tier'':92C ''tls'':126C ''tradit'':30B ''transit'':128C ''unprotect'':138C ''use'':46B,108C ''user'':105C ''version'':54B ''want'':37B ''without'':40B ''workload'':32B,65B');
INSERT INTO public.technology_catalog VALUES ('java-backend', 'Java', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/java.png', '#E76F00', '["backend-service", "worker", "webhook-handler", "shared-library", "realtime-service"]', '{"purpose": "Enterprise-grade, cross-platform programming language for building scalable backend services, microservices, and data processing systems on the JVM", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Java 21+", "Spring Boot 3", "Quarkus", "Micronaut", "Maven/Gradle", "Hibernate/JPA", "JUnit 5", "Lombok", "MapStruct"], "antiPatterns": ["God classes with too many responsibilities", "Not closing database connections or using try-with-resources", "Catching generic Exception instead of specific types", "Using field injection making classes hard to test", "Exposing JPA entities directly in REST responses", "N+1 query problems from lazy loading without fetch joins", "Not using connection pooling (HikariCP)", "Mutable shared state without proper synchronization"], "apiReference": {"docsUrl": "https://docs.oracle.com/en/java/"}, "bestPractices": ["Use Spring Boot for rapid application development with convention over configuration", "Implement proper layered architecture (Controller, Service, Repository)", "Use Spring Data JPA or Hibernate for ORM with proper entity lifecycle management", "Leverage constructor injection over field injection", "Use records for DTOs and immutable data transfer objects", "Implement proper exception handling with @ControllerAdvice", "Use virtual threads (Project Loom) for I/O-bound workloads on Java 21+", "Write tests with JUnit 5 and Mockito", "Use Spring Actuator for health checks and metrics"], "sdkInitPattern": "@SpringBootApplication\npublic class Application {\n    public static void main(String[] args) {\n        SpringApplication.run(Application.class, args);\n    }\n}\n\n@RestController\n@RequestMapping(\"/api/orders\")\nclass OrderController {\n    @GetMapping\n    List<Order> list(@AuthenticationPrincipal AppUser user) {\n        return orders.findByOwnerId(user.getId());\n    }\n}", "securityGuidance": "Parameterized queries everywhere (JPA/JDBC PreparedStatement — string-concatenated JPQL is injection), bean validation on request DTOs at the boundary, and explicit DTOs rather than entity exposure so mass assignment and lazy-loading leaks cannot happen. Never deserialize untrusted data with Java native serialization — it is the classic RCE class; keep Jackson polymorphic typing off. Secrets come from environment/vault config, dependencies ride a scanned BOM (the ecosystem''s CVE surface is the supply chain), and pin JVM/base images by digest."}', '[{"kind": "source", "path": "src/main/java/com/example/Application.java", "language": "java", "description": "Spring Boot application entry point"}, {"kind": "source", "path": "src/main/java/com/example/controller/", "language": "java", "description": "REST controller definitions"}, {"kind": "source", "path": "src/main/java/com/example/service/", "language": "java", "description": "Business logic services"}, {"kind": "config", "path": "pom.xml", "language": "xml", "description": "Maven project definition"}, {"kind": "config", "path": "src/main/resources/application.yml", "language": "yaml", "description": "Spring Boot configuration"}]', '{"buildTool": {"type": "enum", "label": "Build tool", "default": "maven", "options": ["maven", "gradle"]}, "framework": {"type": "enum", "label": "Framework", "default": "spring-boot", "options": ["spring-boot", "quarkus", "micronaut", "plain-jvm"], "description": "Spring Boot 4.x is the ecosystem default (JDK 17+ baseline, Java 25 LTS current); Quarkus/Micronaut where startup time and footprint drive the design"}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-31 20:06:52.233344+00', 'Java', NULL, '''/api/orders'':53C ''21'':26C ''3'':29C ''5'':35C ''applic'':41C ''application.class'':49C ''appus'':60C ''arg'':47C,50C ''assign'':93C ''authenticationprincip'':59C ''backend'':3A,15B ''bean'':76C ''bom'':129C ''boot'':28C ''boundari'':83C ''build'':13B ''cannot'':99C ''chain'':138C ''class'':40C,54C,114C ''classic'':112C ''come'':121C ''concaten'':72C ''config'':124C ''cross'':8B ''cross-platform'':7B ''cve'':133C ''data'':19B,104C ''depend'':125C ''deseri'':102C ''digest'':144C ''dtos'':80C,86C ''ecosystem'':131C ''enterpris'':5B ''enterprise-grad'':4B ''entiti'':89C ''environment/vault'':123C ''everywher'':67C ''explicit'':85C ''exposur'':90C ''getmap'':56C ''grade'':6B ''happen'':100C ''hibernate/jpa'':33C ''imag'':142C ''inject'':75C ''jackson'':116C ''java'':1A,2A,25C,106C ''jpa/jdbc'':68C ''jpql'':73C ''junit'':34C ''jvm'':24B ''jvm/base'':141C ''keep'':115C ''languag'':11B ''lazi'':96C ''lazy-load'':95C ''leak'':98C ''list'':57C,58C ''load'':97C ''lombok'':36C ''main'':45C ''mapstruct'':37C ''mass'':92C ''maven/gradle'':32C ''micronaut'':31C ''microservic'':17B ''nativ'':107C ''never'':101C ''ordercontrol'':55C ''orders.findbyownerid'':63C ''parameter'':65C ''pin'':140C ''platform'':9B ''polymorph'':117C ''preparedstat'':69C ''process'':20B ''program'':10B ''public'':39C,42C ''quarkus'':30C ''queri'':66C ''rather'':87C ''rce'':113C ''request'':79C ''requestmap'':52C ''restcontrol'':51C ''return'':62C ''ride'':126C ''scalabl'':14B ''scan'':128C ''secret'':120C ''serial'':108C ''servic'':16B ''spring'':27C ''springapplication.run'':48C ''springbootappl'':38C ''static'':43C ''string'':46C,71C ''string-concaten'':70C ''suppli'':137C ''surfac'':134C ''system'':21B ''type'':118C ''untrust'':103C ''user'':61C ''user.getid'':64C ''valid'':77C ''void'':44C');
INSERT INTO public.technology_catalog VALUES ('aws-cognito', 'AWS Cognito', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-cognito.png', '#dd344c', '["auth-provider"]', '{"purpose": "AWS managed identity service providing User Pools for user directory and authentication, Identity Pools for AWS credential federation, Lambda triggers for custom workflows, and deep integration with API Gateway, ALB, and other AWS services", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon Cognito", "Amplify Auth", "aws-amplify", "@aws-sdk/client-cognito-identity-provider", "Cognito User Pools", "Cognito Identity Pools", "AWS CDK", "Terraform AWS Provider"], "antiPatterns": ["Using Identity Pools when User Pools alone suffice", "Not implementing MFA for production applications", "Complex Lambda trigger chains that create brittle auth flows", "Not configuring account recovery options", "Hardcoding User Pool IDs in application code", "Not handling token refresh properly", "Using admin-level SDK calls from client-side code"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cognito/"}, "bestPractices": ["Use User Pools for user directory management and authentication", "Use Identity Pools only when AWS credential federation is needed", "Configure proper password policies and account recovery", "Use Lambda triggers (pre-signup, post-confirmation, custom-message) for custom workflows", "Implement MFA for sensitive applications", "Use Cognito Groups for role-based access with IAM role mapping", "Deploy infrastructure as code with CDK or Terraform", "Use Advanced Security Features for adaptive authentication", "Configure proper app client settings (token validity, OAuth scopes)", "Implement proper token refresh handling in the client"], "sdkInitPattern": "import { CognitoIdentityProviderClient, InitiateAuthCommand } from ''@aws-sdk/client-cognito-identity-provider'';\n\nconst cognito = new CognitoIdentityProviderClient({});\nconst res = await cognito.send(new InitiateAuthCommand({\n  AuthFlow: ''USER_PASSWORD_AUTH'',\n  ClientId: process.env.COGNITO_CLIENT_ID,\n  AuthParameters: { USERNAME: email, PASSWORD: password },\n}));\n// verify res.AuthenticationResult.IdToken server-side (issuer, audience, expiry) on every request", "securityGuidance": "Verify JWTs server-side on every request — signature against the pool''s JWKS, issuer, audience (client id), expiry, and token_use; client-asserted identity is not identity. Public app clients get no secret (use SRP/authorization-code + PKCE flows), enable advanced security features (adaptive auth, compromised-credential checks) and MFA, and scope any identity-pool role mappings least-privilege — the credentials they vend are real AWS access.", "setupInstructions": [{"url": "https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-user-pools.html", "type": "dashboard_config", "title": "Create User Pool", "required": true, "instructions": "Create a Cognito User Pool in the AWS Console. Configure sign-in options (email, phone, username) and password policies."}, {"type": "dashboard_config", "title": "Create App Client", "required": true, "instructions": "Create an App Client in the User Pool settings. Configure OAuth 2.0 grant types and callback URLs."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export COGNITO_USER_POOL_ID=us-east-1_xxxxx", "export COGNITO_CLIENT_ID=your-client-id", "export COGNITO_REGION=us-east-1"], "required": true, "instructions": "Configure your Cognito User Pool ID, Client ID, and region in environment variables."}, {"type": "dashboard_config", "title": "Configure Identity Pool (Optional)", "required": false, "instructions": "If you need AWS service access from the client, create an Identity Pool linked to the User Pool for temporary AWS credentials."}]}', '[{"kind": "config", "path": "infra/cognito/user-pool.tf", "language": "hcl", "priority": "essential", "description": "Terraform configuration for Cognito User Pool"}, {"kind": "config", "path": "infra/cognito/identity-pool.tf", "language": "hcl", "priority": "recommended", "description": "Terraform configuration for Cognito Identity Pool"}, {"kind": "config", "path": "infra/cognito/triggers.tf", "language": "hcl", "priority": "recommended", "description": "Lambda trigger definitions for Cognito events"}, {"kind": "config", "path": "src/auth/cognito-config.ts", "language": "typescript", "priority": "essential", "description": "Amplify Auth or Cognito client configuration"}, {"kind": "source", "path": "src/auth/cognito-provider.tsx", "language": "typescript", "priority": "essential", "description": "React authentication provider using Amplify"}, {"kind": "source", "path": "lambdas/pre-signup/index.ts", "language": "typescript", "priority": "recommended", "description": "Pre Sign-Up Lambda trigger for validation"}, {"kind": "source", "path": "lambdas/post-confirmation/index.ts", "language": "typescript", "priority": "recommended", "description": "Post Confirmation Lambda trigger for provisioning"}, {"kind": "source", "path": "lambdas/custom-message/index.ts", "language": "typescript", "priority": "recommended", "description": "Custom Message Lambda trigger for email/SMS customization"}]', '{"mfa": {"type": "boolean", "label": "MFA Enabled", "default": false, "description": "Require multi-factor authentication"}, "region": {"type": "string", "label": "AWS Region", "default": "us-east-1", "description": "AWS region for Cognito resources"}, "hostedUI": {"type": "boolean", "label": "Hosted UI", "default": false, "description": "Use Cognito Hosted UI for authentication"}, "selfSignUp": {"type": "boolean", "label": "Self Sign-Up", "default": true, "description": "Allow users to register themselves"}, "userPoolId": {"type": "string", "label": "User Pool ID", "description": "Cognito User Pool identifier"}, "identityPoolId": {"type": "string", "label": "Identity Pool ID", "description": "Cognito Identity Pool identifier for AWS credential federation"}}', '["backend-service", "serverless-function", "frontend-app", "api-gateway", "rest-api"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-31 20:06:52.233344+00', NULL, '#B82A3E', '''/client-cognito-identity-provider'':49C,68C ''access'':172C ''adapt'':146C ''advanc'':143C ''alb'':34B ''amazon'':39C ''amplifi'':41C,45C ''api'':32B ''app'':133C ''assert'':127C ''audienc'':98C,118C ''auth'':42C,82C,147C ''authent'':16B ''authflow'':79C ''authparamet'':87C ''aw'':1A,3A,5B,20B,37B,44C,47C,56C,59C,66C,171C ''await'':75C ''aws-amplifi'':43C ''aws-sdk'':46C,65C ''cdk'':57C ''check'':151C ''client'':85C,119C,126C,134C ''client-assert'':125C ''clientid'':83C ''cognito'':2A,4A,40C,50C,53C,70C ''cognito.send'':76C ''cognitoidentityprovidercli'':62C,72C ''compromis'':149C ''compromised-credenti'':148C ''const'':69C,73C ''credenti'':21B,150C,166C ''custom'':26B ''deep'':29B ''directori'':14B ''email'':89C ''enabl'':142C ''everi'':101C,109C ''expiri'':99C,121C ''featur'':145C ''feder'':22B ''flow'':141C ''gateway'':33B ''get'':135C ''id'':86C,120C ''ident'':7B,17B,54C,128C,131C,158C ''identity-pool'':157C ''import'':61C ''initiateauthcommand'':63C,78C ''integr'':30B ''issuer'':97C,117C ''jwks'':116C ''jwts'':104C ''lambda'':23B ''least'':163C ''least-privileg'':162C ''manag'':6B ''map'':161C ''mfa'':153C ''new'':71C,77C ''password'':81C,90C,91C ''pkce'':140C ''pool'':11B,18B,52C,55C,114C,159C ''privileg'':164C ''process.env.cognito'':84C ''provid'':9B,60C ''public'':132C ''real'':170C ''request'':102C,110C ''res'':74C ''res.authenticationresult.idtoken'':93C ''role'':160C ''scope'':155C ''sdk'':48C,67C ''secret'':137C ''secur'':144C ''server'':95C,106C ''server-sid'':94C,105C ''servic'':8B,38B ''side'':96C,107C ''signatur'':111C ''srp/authorization-code'':139C ''terraform'':58C ''token'':123C ''trigger'':24B ''use'':124C,138C ''user'':10B,13B,51C,80C ''usernam'':88C ''vend'':168C ''verifi'':92C,103C ''workflow'':27B');
INSERT INTO public.technology_catalog VALUES ('aws-batch', 'AWS Batch', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-batch.png', '#FF9900', '["worker", "scheduled-trigger"]', '{"purpose": "Fully managed batch computing service that dynamically provisions EC2 or Fargate compute resources based on job queue volume and requirements. Supports containerized workloads, job dependencies, array jobs for parallel processing, and automatic retry logic. Best for HPC, genomics, rendering, financial modeling, and any embarrassingly parallel workloads.", "configMode": "declarative", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using Batch for real-time or low-latency workloads (use Lambda or ECS instead)", "Not setting job timeouts causing runaway jobs to consume resources indefinitely", "Running single-threaded jobs without leveraging array jobs for parallelism", "Not using Spot Instances for fault-tolerant batch workloads"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/batch/"}, "bestPractices": ["Use Fargate compute environment for simple container jobs to avoid EC2 management", "Define job dependencies for multi-step pipelines", "Use array jobs for embarrassingly parallel workloads", "Configure automatic retry with exponential backoff for transient failures", "Use Spot Instances in managed compute environments for cost optimization", "Set appropriate memory and vCPU requirements to avoid over-provisioning"], "securityGuidance": "Every job definition carries its own jobRoleArn scoped to what that job touches — a shared broad job role turns the queue into a privilege escalator, and container command overrides at submit time are visible in the API: secrets ride the secrets block, never command args. Compute environments live in private subnets, submit rights are IAM-scoped per queue so one team cannot submit into another''s queue, and bounded retryStrategy plus idempotent jobs keep poison work from looping.", "configurationTemplate": "{\n  \"jobDefinitionName\": \"nightly-etl\",\n  \"type\": \"container\",\n  \"containerProperties\": {\n    \"image\": \"123.dkr.ecr.us-east-1.amazonaws.com/etl:sha\",\n    \"resourceRequirements\": [\n      { \"type\": \"VCPU\", \"value\": \"2\" }, { \"type\": \"MEMORY\", \"value\": \"4096\" }\n    ],\n    \"jobRoleArn\": \"arn:aws:iam::123:role/etlJobRole\",\n    \"secrets\": [{ \"name\": \"DB_URL\", \"valueFrom\": \"arn:aws:secretsmanager:...:secret:db-url\" }]\n  },\n  \"retryStrategy\": { \"attempts\": 2 }\n}"}', '[{"kind": "config", "path": "terraform/batch.tf", "priority": "recommended", "description": "Batch compute environment, job queue, and job definitions"}, {"kind": "config", "path": "batch/job-definition.json", "priority": "required", "description": "Container-based job definition"}, {"kind": "source", "path": "batch/submit-job.ts", "priority": "recommended", "description": "Job submission client"}]', '{"maxvCpus": {"type": "number", "label": "Max vCPUs", "default": 256}, "jobTimeout": {"type": "number", "label": "Job Timeout (seconds)", "default": 3600}, "computeType": {"type": "string", "label": "Compute Type", "default": "FARGATE"}, "retryAttempts": {"type": "number", "label": "Retry Attempts", "default": 3}}', '["object-storage", "database", "monitoring", "event-stream"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''anoth'':116C ''api'':87C ''arg'':95C ''array'':30B ''automat'':36B ''aw'':1A,3A ''base'':18B ''batch'':2A,4A,7B ''best'':39B ''block'':92C ''bound'':120C ''broad'':66C ''cannot'':113C ''carri'':54C ''command'':78C,94C ''comput'':8B,16B,96C ''contain'':77C ''container'':26B ''definit'':53C ''depend'':29B ''dynam'':11B ''ec2'':13B ''embarrass'':48B ''environ'':97C ''escal'':75C ''everi'':51C ''fargat'':15B ''financi'':44B ''fulli'':5B ''genom'':42B ''hpc'':41B ''iam'':106C ''iam-scop'':105C ''idempot'':123C ''job'':20B,28B,31B,52C,62C,67C,124C ''jobrolearn'':57C ''keep'':125C ''live'':98C ''logic'':38B ''loop'':129C ''manag'':6B ''model'':45B ''never'':93C ''one'':111C ''overrid'':79C ''parallel'':33B,49B ''per'':108C ''plus'':122C ''poison'':126C ''privat'':100C ''privileg'':74C ''process'':34B ''provis'':12B ''queue'':21B,71C,109C,118C ''render'':43B ''requir'':24B ''resourc'':17B ''retri'':37B ''retrystrategi'':121C ''ride'':89C ''right'':103C ''role'':68C ''scope'':58C,107C ''secret'':88C,91C ''servic'':9B ''share'':65C ''submit'':81C,102C,114C ''subnet'':101C ''support'':25B ''team'':112C ''time'':82C ''touch'':63C ''turn'':69C ''visibl'':84C ''volum'':22B ''work'':127C ''workload'':27B,50B');
INSERT INTO public.technology_catalog VALUES ('ruby-backend', 'Ruby', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/ruby.png', '#CC342D', '["backend-service", "worker", "webhook-handler"]', '{"purpose": "Dynamic, expressive programming language optimized for developer productivity, powering web applications and background processing with Rails and its ecosystem", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Ruby 3.3+", "Ruby on Rails 7+", "Sinatra", "Sidekiq", "ActiveRecord", "RSpec", "Puma", "Bundler", "Devise"], "antiPatterns": ["Fat controllers with business logic", "N+1 queries from not using includes/eager_load", "Monkey-patching core classes in production code", "Not using database indexes for frequently queried columns", "Skipping database migrations and modifying schema directly", "Using callbacks for complex business logic instead of service objects", "Not implementing proper error handling in background jobs"], "apiReference": {"docsUrl": "https://docs.ruby-lang.org/en/"}, "bestPractices": ["Follow Rails conventions (MVC, RESTful routes, ActiveRecord patterns)", "Use Sidekiq or GoodJob for background job processing", "Implement proper database migrations with reversible changes", "Use RSpec with FactoryBot for comprehensive testing", "Leverage concerns and service objects to keep controllers thin", "Use strong parameters for mass assignment protection", "Implement proper caching strategies (fragment, Russian doll, low-level)", "Use Bundler for dependency management with Gemfile.lock"], "sdkInitPattern": "# Rails controller — scope every query by the authenticated user\nclass OrdersController < ApplicationController\n  before_action :authenticate_user!\n\n  def index\n    render json: current_user.orders\n  end\n\n  def create\n    order = current_user.orders.create!(order_params)\n    render json: order, status: :created\n  end\n\n  private\n\n  def order_params\n    params.require(:order).permit(:product_id, :quantity)\n  end\nend", "securityGuidance": "Strong parameters on every write path — params.permit is the mass-assignment defense, and current_user-scoped queries (never Model.find on a client-supplied id without an ownership check) are the authorization floor. ActiveRecord parameterization protects you until someone string-interpolates into where/order — never do it. Never Marshal.load or YAML.unsafe_load untrusted data (both are RCE), keep secrets in credentials/environment not the repo, html_escape by default stays on, and bundle-audit the gemfile in CI."}', '[{"kind": "source", "path": "app/controllers/application_controller.rb", "language": "ruby", "description": "Base controller"}, {"kind": "source", "path": "config/routes.rb", "language": "ruby", "description": "Route definitions"}, {"kind": "source", "path": "app/models/", "language": "ruby", "description": "ActiveRecord models"}, {"kind": "config", "path": "Gemfile", "language": "ruby", "description": "Ruby dependency manifest"}, {"kind": "config", "path": "config/database.yml", "language": "yaml", "description": "Database configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "rails", "options": ["rails", "sinatra", "plain-ruby"], "description": "Rails (8.x era) is the reason to be in Ruby — full-stack conventions; Sinatra for tiny services"}, "backgroundJobs": {"type": "enum", "label": "Background jobs", "default": "solid-queue", "options": ["solid-queue", "sidekiq", "none"], "description": "Solid Queue is the Rails-8-era database-backed default; Sidekiq where Redis-backed throughput is needed"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-31 20:06:52.233344+00', 'Ruby', NULL, '''3.3'':24C ''7'':28C ''action'':49C ''activerecord'':31C,117C ''applic'':14B ''applicationcontrol'':47C ''assign'':93C ''audit'':157C ''authent'':43C,50C ''author'':115C ''backend'':3A ''background'':16B ''bundl'':156C ''bundle-audit'':155C ''bundler'':34C ''check'':112C ''ci'':161C ''class'':45C ''client'':106C ''client-suppli'':105C ''control'':37C ''creat'':59C,68C ''credentials/environment'':144C ''current'':96C ''current_user.orders'':56C ''current_user.orders.create'':61C ''data'':137C ''def'':52C,58C,71C ''default'':151C ''defens'':94C ''develop'':10B ''devis'':35C ''dynam'':4B ''ecosystem'':22B ''end'':57C,69C,80C,81C ''escap'':149C ''everi'':39C,85C ''express'':5B ''floor'':116C ''gemfil'':159C ''html'':148C ''id'':78C,108C ''index'':53C ''interpol'':125C ''json'':55C,65C ''keep'':141C ''languag'':7B ''load'':135C ''marshal.load'':132C ''mass'':92C ''mass-assign'':91C ''model.find'':102C ''never'':101C,128C,131C ''optim'':8B ''order'':60C,62C,66C,72C,75C ''orderscontrol'':46C ''ownership'':111C ''param'':63C,73C ''paramet'':83C ''parameter'':118C ''params.permit'':88C ''params.require'':74C ''path'':87C ''permit'':76C ''power'':12B ''privat'':70C ''process'':17B ''product'':11B,77C ''program'':6B ''protect'':119C ''puma'':33C ''quantiti'':79C ''queri'':40C,100C ''rail'':19B,27C,36C ''rce'':140C ''render'':54C,64C ''repo'':147C ''rspec'':32C ''rubi'':1A,2A,23C,25C ''scope'':38C,99C ''secret'':142C ''sidekiq'':30C ''sinatra'':29C ''someon'':122C ''status'':67C ''stay'':152C ''string'':124C ''string-interpol'':123C ''strong'':82C ''suppli'':107C ''untrust'':136C ''user'':44C,51C,98C ''user-scop'':97C ''web'':13B ''where/order'':127C ''without'':109C ''write'':86C ''yaml.unsafe'':134C');
INSERT INTO public.technology_catalog VALUES ('dioxus', 'Dioxus', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/dioxus.png', '#0080ff', '["frontend-app", "desktop-app", "mobile-app"]', '{"purpose": "Cross-platform Rust UI framework supporting web, desktop, mobile, and TUI from a single codebase", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Dioxus", "Rust", "WebAssembly", "Tauri (desktop)"], "antiPatterns": ["Blocking the async runtime with synchronous operations in components", "Not leveraging Rust ownership for state management correctness", "Using web-only APIs when targeting desktop or mobile platforms", "Excessive cloning instead of using references and signals properly", "Not using the type-safe router leading to runtime URL errors"], "apiReference": {"docsUrl": "https://dioxuslabs.com/"}, "bestPractices": ["Use hooks for state management", "Leverage cross-platform rendering", "Use proper signal-based reactivity", "Implement platform-specific code with cfg attributes"], "sdkInitPattern": "cargo install dioxus-cli && dx new my-app && cd my-app\\n// src/main.rs\\nuse dioxus::prelude::*;\\nfn main() { launch(App); }\\nfn App() -> Element {\\n    rsx! { h1 { \"Hello Dioxus\" } }\\n}", "securityGuidance": "Dioxus RSX auto-escapes text content. Validate all user inputs before processing. Use Rust type system to enforce invariants at compile time. For desktop targets, restrict filesystem and network access. Audit dependencies with cargo-audit. Never embed API keys in client-compiled WASM bundles.", "commonApiPatterns": [{"name": "Component with State", "description": "Component with reactive signal state", "codeTemplate": "fn Counter() -> Element {\\n    let mut count = use_signal(|| 0);\\n    rsx! {\\n        button { onclick: move |_| count += 1, \"Count: {count}\" }\\n    }\\n}"}, {"name": "Async Data Loading", "description": "Async resource for data fetching with loading/error states", "codeTemplate": "fn UserList() -> Element {\\n    let users = use_resource(|| async {\\n        reqwest::get(\"http://api/users\").await?.json::<Vec<User>>().await\\n    });\\n    match &*users.read_unchecked() {\\n        Some(Ok(list)) => rsx! { for user in list { div { \"{user.name}\" } } },\\n        Some(Err(e)) => rsx! { \"Error: {e}\" },\\n        None => rsx! { \"Loading...\" },\\n    }\\n}"}, {"name": "Router", "description": "Type-safe router with derive macro", "codeTemplate": "#[derive(Routable, Clone)]\\nenum Route {\\n    #[route(\"/\")]\\n    Home {},\\n    #[route(\"/users/:id\")]\\n    UserDetail { id: String },\\n}\\nfn App() -> Element {\\n    rsx! { Router::<Route> {} }\\n}"}], "integrationPatterns": ["Multi-platform rendering: web (WASM), desktop (WebView), mobile, SSR", "Dioxus Router for type-safe client-side routing", "use_resource and use_coroutine for async operations", "Tailwind CSS via dioxus CLI integration", "Server functions for fullstack Dioxus with server-side logic"], "configurationTemplate": "# Cargo.toml\\n[package]\\nname = \"my-app\"\\nversion = \"0.1.0\"\\nedition = \"2021\"\\n\\n[dependencies]\\ndioxus = { version = \"0.5\", features = [\"web\"] }\\n# For desktop: features = [\"desktop\"]\\n# For mobile: features = [\"mobile\"]\\nserde = { version = \"1\", features = [\"derive\"] }\\nreqwest = { version = \"0.12\", features = [\"json\"] }\\n\\n# Dioxus.toml\\n[application]\\nname = \"my-app\"\\n[web.app]\\ntitle = \"My App\""}', '[{"kind": "source", "path": "src/main.rs", "language": "rust", "description": "Application entry point"}, {"kind": "config", "path": "Cargo.toml", "language": "toml", "description": "Project configuration"}]', '{"styling": {"type": "enum", "label": "Styling", "default": "tailwind", "options": ["tailwind", "vanilla-css"]}, "fullstack": {"type": "boolean", "label": "Server functions", "default": false, "description": "Dioxus fullstack colocates server endpoints with UI code — the node then has a real backend surface"}, "platformTargets": {"type": "multiselect", "label": "Platform targets", "options": ["web-wasm", "desktop", "mobile", "fullstack-server-functions"], "description": "Dioxus is one Rust codebase across all of these — which the node IS on the canvas is the drop-role choice; which it SHIPS to is this field"}}', '["rest-api", "database"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#CA9A06', '''access'':86C ''api'':95C ''app'':33C,37C,46C,48C ''audit'':87C,92C ''auto'':59C ''auto-escap'':58C ''bundl'':102C ''cargo'':24C,91C ''cargo-audit'':90C ''cd'':34C ''cli'':28C ''client'':99C ''client-compil'':98C ''codebas'':18B ''compil'':77C,100C ''content'':62C ''cross'':4B ''cross-platform'':3B ''depend'':88C ''desktop'':11B,23C,80C ''dioxus'':1A,2A,19C,27C,41C,54C,56C ''dioxus-c'':26C ''dx'':29C ''element'':49C ''emb'':94C ''enforc'':74C ''escap'':60C ''filesystem'':83C ''framework'':8B ''h1'':52C ''hello'':53C ''input'':66C ''instal'':25C ''invari'':75C ''key'':96C ''launch'':45C ''main'':44C ''mobil'':12B ''my-app'':31C,35C ''n'':38C,50C,55C ''network'':85C ''never'':93C ''new'':30C ''nfn'':43C,47C ''nuse'':40C ''platform'':5B ''prelud'':42C ''process'':68C ''restrict'':82C ''rsx'':51C,57C ''rust'':6B,20C,70C ''singl'':17B ''src/main.rs'':39C ''support'':9B ''system'':72C ''target'':81C ''tauri'':22C ''text'':61C ''time'':78C ''tui'':14B ''type'':71C ''ui'':7B ''use'':69C ''user'':65C ''valid'':63C ''wasm'':101C ''web'':10B ''webassembl'':21C');
INSERT INTO public.technology_catalog VALUES ('rust-backend', 'Rust', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/rust-backend.png', '#dea584', '["backend-service", "worker", "cli-tool", "shared-library"]', '{"purpose": "Memory-safe systems language for services where performance and correctness both matter: high-throughput APIs, proxies, parsers, CLIs and shared native libraries other stacks bind to. Costs more engineering time per feature than Go/TS — the right node when that trade is deliberate.", "configMode": "code", "provenance": {"notes": "Stable stack (axum/tokio/sqlx/serde standard for years); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["axum + tokio + tower", "sqlx", "serde", "thiserror/anyhow", "clippy", "cargo workspaces"], "antiPatterns": ["unwrap()/expect() on I/O paths — every one is a latent panic", "Cloning to satisfy the borrow checker instead of restructuring ownership — a smell the compiler is pointing at real design debt", "Async trait gymnastics where a simple sync design would do", "Choosing Rust for a CRUD API where iteration speed matters more than the performance envelope"], "apiReference": {"docsUrl": "https://doc.rust-lang.org/"}, "bestPractices": ["axum + tokio + tower is the service stack; reach for it whole, not piecemeal", "sqlx with compile-time-checked queries (offline mode in CI so builds do not need a database)", "thiserror in libraries, anyhow in binaries; ? everywhere — no unwrap() on fallible paths in production code", "Clippy pedantic in CI from day one — retrofitting lints onto a Rust codebase is misery", "Keep async boundaries clean: spawn_blocking for CPU/sync work, never block the executor"], "sdkInitPattern": "cargo init myapp\\ncargo add axum tokio --features tokio/full serde --features serde/derive sqlx --features sqlx/postgres,sqlx/runtime-tokio\\n// src/main.rs\\nuse axum::{Router, routing::get};\\n#[tokio::main]\\nasync fn main() {\\n    let app = Router::new().route(\"/health\", get(|| async { \"ok\" }));\\n    let listener = tokio::net::TcpListener::bind(\"0.0.0.0:3000\").await.unwrap();\\n    axum::serve(listener, app).await.unwrap();\\n}", "securityGuidance": "Leverage the type system and ownership model for memory safety. Use sqlx compile-time checked queries to prevent SQL injection. Validate input using serde and custom deserialization. Set timeouts on all async operations. Use secrecy crate for sensitive values to prevent accidental logging. Audit dependencies with cargo-audit in CI.", "commonApiPatterns": [{"name": "Axum Handler", "description": "Axum handler with state extraction, path params, and typed errors", "codeTemplate": "async fn get_user(\\n    State(pool): State<PgPool>,\\n    Path(id): Path<i64>,\\n) -> Result<Json<User>, AppError> {\\n    let user = sqlx::query_as!(User, \"SELECT id, name FROM users WHERE id = $1\", id)\\n        .fetch_optional(&pool).await?\\n        .ok_or(AppError::NotFound)?;\\n    Ok(Json(user))\\n}"}, {"name": "Error Handling", "description": "Custom error type implementing IntoResponse for consistent API errors", "codeTemplate": "enum AppError { NotFound, Internal(anyhow::Error) }\\nimpl IntoResponse for AppError {\\n    fn into_response(self) -> Response {\\n        match self {\\n            Self::NotFound => (StatusCode::NOT_FOUND, \"not found\").into_response(),\\n            Self::Internal(e) => {\\n                tracing::error!(\"Internal error: {e:?}\");\\n                (StatusCode::INTERNAL_SERVER_ERROR, \"internal error\").into_response()\\n            }\\n        }\\n    }\\n}"}, {"name": "Middleware Layer", "description": "Tower middleware for tracing and CORS", "codeTemplate": "use tower_http::{cors::CorsLayer, trace::TraceLayer};\\nlet app = Router::new()\\n    .route(\"/api/users\", get(list_users))\\n    .layer(TraceLayer::new_for_http())\\n    .layer(CorsLayer::permissive());"}], "integrationPatterns": ["Axum or Actix-web for HTTP framework", "SQLx with compile-time query checking for database access", "tonic for gRPC services with protobuf", "tracing + tracing-subscriber for structured observability", "cargo-nextest for faster parallel test execution"], "configurationTemplate": "# Cargo.toml\\n[package]\\nname = \"myapp\"\\nversion = \"0.1.0\"\\nedition = \"2021\"\\n\\n[dependencies]\\naxum = \"0.7\"\\ntokio = { version = \"1\", features = [\"full\"] }\\nserde = { version = \"1\", features = [\"derive\"] }\\nsqlx = { version = \"0.7\", features = [\"postgres\", \"runtime-tokio\", \"macros\"] }\\ntower-http = { version = \"0.5\", features = [\"cors\", \"trace\"] }\\ntracing = \"0.1\"\\ntracing-subscriber = \"0.3\"\\nanyhow = \"1\"\\n\\n[profile.release]\\nlto = true\\nstrip = true"}', '[{"kind": "source", "path": "src/main.rs", "language": "rust", "description": "Application entry point"}, {"kind": "source", "path": "src/routes/mod.rs", "language": "rust", "description": "Route handlers"}, {"kind": "config", "path": "Cargo.toml", "language": "toml", "description": "Rust project manifest"}]', '{"dataAccess": {"type": "enum", "label": "Data access", "default": "sqlx", "options": ["sqlx", "diesel", "none"], "description": "sqlx = async, compile-time-checked SQL; diesel = sync ORM"}, "webFramework": {"type": "enum", "label": "Web framework", "default": "axum", "options": ["axum", "actix-web", "none-lib-or-cli"], "description": "axum (tokio-native, tower middleware) is the standing default for services; none for library/CLI deliverables"}, "errorStrategy": {"type": "enum", "label": "Error handling", "default": "thiserror-anyhow", "options": ["thiserror-anyhow", "custom-enums-only"], "description": "thiserror for library errors, anyhow at the application edge — the community-standard split"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', 'Rust', '#B5876D', '''/health'':92C ''0.0.0.0'':103C ''3000'':104C ''accident'':155C ''add'':61C ''api'':20B ''app'':88C,110C ''async'':94C,145C ''audit'':157C,162C ''await.unwrap'':105C,111C ''axum'':48C,62C,76C,107C ''backend'':3A ''bind'':30B,102C ''cargo'':55C,57C,161C ''cargo-audit'':160C ''check'':128C ''ci'':164C ''clippi'':54C ''clis'':23B ''compil'':126C ''compile-tim'':125C ''correct'':14B ''cost'':32B ''crate'':149C ''custom'':139C ''deliber'':47B ''depend'':158C ''deseri'':140C ''engin'':34B ''featur'':37B,64C,67C,70C ''fn'':84C ''get'':79C,93C ''go/ts'':39B ''high'':18B ''high-throughput'':17B ''init'':58C ''inject'':133C ''input'':135C ''languag'':8B ''let'':87C,97C ''leverag'':113C ''librari'':27B ''listen'':98C,109C ''log'':156C ''main'':82C,85C ''matter'':16B ''memori'':5B,121C ''memory-saf'':4B ''model'':119C ''myapp'':59C ''n'':73C,80C,86C,96C,106C,112C ''nasync'':83C ''nativ'':26B ''ncargo'':60C ''net'':100C ''new'':90C ''node'':42B ''nuse'':75C ''ok'':95C ''oper'':146C ''ownership'':118C ''parser'':22B ''per'':36B ''perform'':12B ''prevent'':131C,154C ''proxi'':21B ''queri'':129C ''right'':41B ''rout'':78C,91C ''router'':77C,89C ''rust'':1A,2A ''safe'':6B ''safeti'':122C ''secreci'':148C ''sensit'':151C ''serd'':52C,66C,137C ''serde/derive'':68C ''serv'':108C ''servic'':10B ''set'':141C ''share'':25B ''sql'':132C ''sqlx'':51C,69C,124C ''sqlx/postgres'':71C ''sqlx/runtime-tokio'':72C ''src/main.rs'':74C ''stack'':29B ''system'':7B,116C ''tcplisten'':101C ''thiserror/anyhow'':53C ''throughput'':19B ''time'':35B,127C ''timeout'':142C ''tokio'':49C,63C,81C,99C ''tokio/full'':65C ''tower'':50C ''trade'':45B ''type'':115C ''use'':123C,136C,147C ''valid'':134C ''valu'':152C ''workspac'':56C');
INSERT INTO public.technology_catalog VALUES ('phoenix-elixir', 'Phoenix (Elixir)', NULL, '#6b7280', '["realtime-service", "backend-service"]', '{"purpose": "Elixir web framework on the BEAM VM — the realtime specialist: Channels/PubSub/Presence handle millions of concurrent connections per node with supervision-tree fault tolerance, and LiveView builds interactive UIs server-side without a JS framework. Costs: the Elixir learning curve and a smaller ecosystem than Node — the right node when realtime/concurrency IS the product.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Phoenix LiveView", "Channels/PubSub/Presence", "Ecto + Postgres", "Oban", "OTP releases", "BEAM VM"], "antiPatterns": ["Treating processes like threads — GenServers hold state and serialize access; a GenServer as a shared bottleneck is the classic scaling bug", "Ecto queries in LiveView mount without preloads — N+1s surface as latency on every socket join", "Ignoring the supervision tree design — a flat tree under one supervisor loses the fault-isolation the BEAM is for"], "apiReference": {"docsUrl": "https://hexdocs.pm/phoenix/"}, "bestPractices": ["LiveView first for interactive UI — reach for a JS frontend only when offline/native interactions demand it", "Lean on OTP: supervisors restart crashed processes — let it crash beats defensive rescue everywhere", "PubSub + Presence are built in — do not bolt on an external realtime service beside Phoenix", "Oban for durable background jobs (database-backed, observable)", "Deploy as OTP releases (mix release) in containers"], "sdkInitPattern": "# router.ex\npipeline :api do\n  plug :accepts, [\"json\"]\n  plug AppWeb.Plugs.RequireAuth\nend\n\nscope \"/api\", AppWeb do\n  pipe_through :api\n  resources \"/orders\", OrderController, only: [:index, :show, :create]\nend", "securityGuidance": "Secrets (SECRET_KEY_BASE, signing salts, DB URLs) resolve in config/runtime.exs from the environment — never compiled into releases or committed in config/*.exs. Authorize in context functions, not just router pipelines (scope every Repo query by the authenticated actor), verify channel/LiveView socket auth on connect AND on every topic join, and keep force_ssl + secure cookie flags on in prod. Ecto changesets with explicit cast lists are your mass-assignment defense — never cast params wholesale."}', '[{"kind": "config", "path": "config/runtime.exs", "language": "elixir", "description": "Runtime config resolving secrets from the environment"}, {"kind": "code", "path": "lib/app_web/router.ex", "language": "elixir", "description": "Pipelines with auth plugs, scoped routes"}]', '{"liveView": {"type": "boolean", "label": "LiveView UI", "default": true, "description": "Server-rendered interactive UI — the reason to pick Phoenix; a separate JS frontend is the exception, not the default"}, "deployment": {"type": "enum", "label": "Deployment", "default": "otp-releases-docker", "options": ["otp-releases-docker", "fly-io-optimized"]}, "backgroundJobs": {"type": "enum", "label": "Background jobs", "default": "oban", "options": ["oban", "none"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/api'':81C ''/orders'':88C ''accept'':75C ''actor'':133C ''api'':72C,86C ''appweb'':82C ''appweb.plugs.requireauth'':78C ''assign'':165C ''auth'':137C ''authent'':132C ''author'':118C ''base'':98C ''beam'':10B,68C ''build'':31B ''cast'':159C,168C ''changeset'':156C ''channel/liveview'':135C ''channels/pubsub/presence'':15B,62C ''commit'':114C ''compil'':110C ''concurr'':19B ''config'':116C ''config/runtime.exs'':105C ''connect'':20B,139C ''context'':120C ''cooki'':150C ''cost'':41B ''creat'':93C ''curv'':45B ''db'':101C ''defens'':166C ''ecosystem'':49B ''ecto'':63C,155C ''elixir'':2A,4A,5B,43B ''end'':79C,94C ''environ'':108C ''everi'':127C,142C ''ex'':117C ''explicit'':158C ''fault'':27B ''flag'':151C ''forc'':147C ''framework'':7B,40B ''function'':121C ''handl'':16B ''index'':91C ''interact'':32B ''join'':144C ''js'':39B ''json'':76C ''keep'':146C ''key'':97C ''learn'':44B ''list'':160C ''liveview'':30B,61C ''mass'':164C ''mass-assign'':163C ''million'':17B ''never'':109C,167C ''node'':22B,51B,54B ''oban'':65C ''ordercontrol'':89C ''otp'':66C ''param'':169C ''per'':21B ''phoenix'':1A,3A,60C ''pipe'':84C ''pipelin'':71C,125C ''plug'':74C,77C ''postgr'':64C ''prod'':154C ''product'':59B ''queri'':129C ''realtim'':13B ''realtime/concurrency'':56B ''releas'':67C,112C ''repo'':128C ''resolv'':103C ''resourc'':87C ''right'':53B ''router'':124C ''router.ex'':70C ''salt'':100C ''scope'':80C,126C ''secret'':95C,96C ''secur'':149C ''server'':35B ''server-sid'':34B ''show'':92C ''side'':36B ''sign'':99C ''smaller'':48B ''socket'':136C ''specialist'':14B ''ssl'':148C ''supervis'':25B ''supervision-tre'':24B ''toler'':28B ''topic'':143C ''tree'':26B ''ui'':33B ''url'':102C ''verifi'':134C ''vm'':11B,69C ''web'':6B ''wholesal'':170C ''without'':37B');
INSERT INTO public.technology_catalog VALUES ('aspnet-core', 'ASP.NET Core (C#)', NULL, '#512BD4', '["backend-service", "worker", "realtime-service"]', '{"purpose": "Cross-platform, high-performance .NET framework for building modern web APIs, real-time services, and cloud-native backend applications", "configMode": "code", "provenance": {"notes": "Phase B3 additions authored from model knowledge — no prior provenance. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": [".NET 8+", "C#", "Entity Framework Core", "MediatR", "FluentValidation", "Serilog", "xUnit", "Swashbuckle/NSwag"], "antiPatterns": ["Using the Service Locator pattern instead of constructor injection", "Fat controllers with business logic instead of using services/handlers", "Not using async/await for I/O-bound operations", "Exposing Entity Framework entities directly in API responses", "Not validating input models", "Catching and swallowing exceptions without logging", "Not implementing proper CORS configuration", "Using synchronous database calls in request handlers"], "apiReference": {"docsUrl": "https://learn.microsoft.com/aspnet/core/"}, "bestPractices": ["Use built-in dependency injection for all services", "Implement the middleware pipeline for cross-cutting concerns", "Use Minimal APIs for lightweight endpoints or Controllers for complex domains", "Implement health checks with Microsoft.Extensions.Diagnostics.HealthChecks", "Use Options pattern for strongly-typed configuration", "Implement proper exception handling middleware", "Use async/await throughout the request pipeline", "Leverage IHttpClientFactory for outbound HTTP calls", "Use response caching and output caching where appropriate"], "sdkInitPattern": "// Program.cs — minimal API\r\nvar builder = WebApplication.CreateBuilder(args);\r\nbuilder.Services.AddAuthentication();\r\nbuilder.Services.AddAuthorization();\r\n\r\nvar app = builder.Build();\r\napp.UseHttpsRedirection();\r\napp.UseAuthentication();\r\napp.UseAuthorization();\r\napp.MapGet(\"/health\", () => Results.Ok(new { ok = true }));\r\napp.Run();", "securityGuidance": "Middleware ORDER is security: UseAuthentication before UseAuthorization, and both before the endpoints they protect. Keep secrets out of appsettings.json — user-secrets in development, a vault (Key Vault, etc.) in production. Enforce HTTPS redirection + HSTS, use the antiforgery services for cookie-authenticated form posts, and lean on the framework''s model binding + validation instead of reading raw request bodies."}', '[{"kind": "source", "path": "Program.cs", "language": "csharp", "description": "Application entry point and service configuration"}, {"kind": "source", "path": "Controllers/ApiController.cs", "language": "csharp", "description": "API controller definitions"}, {"kind": "source", "path": "Services/", "language": "csharp", "description": "Business logic services"}, {"kind": "config", "path": "App.csproj", "language": "xml", "description": ".NET project file with NuGet dependencies"}, {"kind": "config", "path": "appsettings.json", "language": "json", "description": "Application configuration"}, {"kind": "config", "path": "appsettings.Development.json", "language": "json", "description": "Development environment overrides"}]', '{"openApi": {"type": "boolean", "label": "OpenAPI generation", "default": true}, "apiStyle": {"type": "enum", "label": "API style", "default": "minimal-apis", "options": ["minimal-apis", "controllers"], "description": "Minimal APIs are the current-.NET default for services; controllers for large conventional codebases"}, "dataAccess": {"type": "enum", "label": "Data access", "default": "ef-core", "options": ["ef-core", "dapper"]}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-03-31 13:54:56.372888+00', '2026-08-31 20:06:52.233344+00', 'ASP.NET Core', NULL, '''/health'':56C ''8'':30C ''antiforgeri'':99C ''api'':18B,42C ''app'':50C ''app.mapget'