INSERT INTO public.technology_catalog VALUES ('electron', 'Electron', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/electron.png', '#47848f', '["desktop-app"]', '{"purpose": "Framework for building cross-platform desktop applications using web technologies (HTML, CSS, JavaScript/TypeScript) with full Node.js access and native OS integration", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Electron", "Node.js", "Chromium", "electron-builder", "electron-forge", "electron-vite", "electron-updater", "electron-store"], "antiPatterns": ["Disabling web security or context isolation for convenience", "Running Node.js APIs directly in the renderer process", "Not implementing IPC validation allowing renderer-to-main injection", "Large application bundles from including unneeded Chromium features", "Memory leaks from unclosed BrowserWindow instances", "Shipping without code signing causing OS security warnings"], "apiReference": {"docsUrl": "https://www.electronjs.org/docs/latest/"}, "bestPractices": ["Enable context isolation and sandbox for all renderer processes", "Use preload scripts for IPC instead of exposing Node.js to renderers", "Implement auto-updates with electron-updater and code signing", "Minimize main process work to keep the app responsive", "Use electron-builder for cross-platform packaging (MSI, DMG, AppImage, DEB)", "Implement proper Content Security Policy (CSP) headers", "Sign and notarize macOS builds for Gatekeeper approval", "Use session partition for multi-window isolation", "Store user preferences with electron-store in AppData/Library"], "sdkInitPattern": "// main.js — secure defaults\nconst { app, BrowserWindow, ipcMain } = require(''electron'');\n\napp.whenReady().then(() => {\n  const win = new BrowserWindow({\n    webPreferences: {\n      contextIsolation: true,\n      nodeIntegration: false,\n      sandbox: true,\n      preload: path.join(__dirname, ''preload.js''),\n    },\n  });\n  win.loadFile(''index.html'');\n});\n\nipcMain.handle(''orders:list'', async (event) => {\n  return await listOrdersForCurrentUser();  // validate sender + args on every handler\n});", "securityGuidance": "contextIsolation on, nodeIntegration off, sandbox on — the renderer is a browser tab and must stay one; capabilities cross only through a minimal preload contextBridge API, and every ipcMain handler validates the sender frame and its arguments (a compromised renderer will call anything you expose). Never load remote URLs into a privileged window, deny-by-default in setWindowOpenHandler and will-navigate, keep webSecurity on, ship through the signed auto-updater (electron-updater with a pinned feed), and remember asar is not protection — bundled secrets are extractable by anyone with the binary.", "setupInstructions": [{"type": "toolchain_install", "title": "Install Build Tools", "commands": ["xcode-select --install", "sudo apt-get install build-essential libnss3-dev libatk-bridge2.0-0"], "required": true, "instructions": "Install platform-specific build tools. On macOS: Xcode Command Line Tools. On Windows: Visual Studio Build Tools. On Linux: build-essential and related packages."}, {"url": "https://www.electronjs.org/docs/latest/tutorial/code-signing", "type": "dashboard_config", "title": "Configure Code Signing (Production)", "required": false, "instructions": "For production distribution, configure code signing certificates. macOS requires an Apple Developer account; Windows requires an EV code signing certificate."}, {"type": "manual_workflow", "title": "Configure Auto-Update Server", "required": false, "instructions": "Set up an update server (e.g., electron-updater with GitHub Releases, S3, or a custom server) for distributing application updates."}]}', '[{"kind": "source", "path": "src/main/index.ts", "language": "typescript", "description": "Electron main process entry point"}, {"kind": "source", "path": "src/preload/index.ts", "language": "typescript", "description": "Preload script for secure IPC bridge"}, {"kind": "source", "path": "src/main/ipc-handlers.ts", "language": "typescript", "description": "IPC message handlers for main process APIs"}, {"kind": "source", "path": "src/main/updater.ts", "language": "typescript", "description": "Auto-update logic using electron-updater"}, {"kind": "config", "path": "electron-builder.json", "language": "json", "description": "electron-builder configuration for all platform targets"}, {"kind": "config", "path": "electron.vite.config.ts", "language": "typescript", "description": "Electron Vite build configuration"}, {"kind": "config", "path": "build/entitlements.mac.plist", "language": "xml", "description": "macOS entitlements for hardened runtime and notarization"}, {"kind": "config", "path": "build/installer.nsh", "description": "NSIS custom installer script for Windows"}]', '{"targets": {"type": "multiselect", "label": "Build targets", "options": ["windows", "macos", "linux"], "description": "Signing and notarization are per-OS MANUAL setup, not code"}, "packager": {"type": "enum", "label": "Packager", "default": "electron-builder", "options": ["electron-builder", "electron-forge"]}, "autoUpdate": {"type": "boolean", "label": "Auto-update", "default": true}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "react", "options": ["react", "vue", "svelte", "angular", "solid", "vanilla"], "description": "The web framework rendering inside Electron — this node IS the desktop app; do not model a second frontend node for the same UI"}, "contextIsolation": {"type": "boolean", "label": "Context isolation", "default": true, "description": "The security baseline — renderer never gets Node APIs directly; expose narrow bridges via preload"}}', '["rest-api", "database", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-31 20:06:52.233344+00', NULL, '#3D7078', '''access'':20B ''anyon'':175C ''anyth'':126C ''api'':109C ''app'':47C ''app.whenready'':52C ''applic'':10B ''arg'':81C ''argument'':120C ''asar'':166C ''async'':74C ''auto'':155C ''auto-updat'':154C ''await'':77C ''binari'':178C ''browser'':95C ''browserwindow'':48C,57C ''build'':5B ''builder'':30C ''bundl'':170C ''call'':125C ''capabl'':101C ''chromium'':27C ''compromis'':122C ''const'':46C,54C ''contextbridg'':108C ''contextisol'':59C,85C ''cross'':7B,102C ''cross-platform'':6B ''css'':15B ''default'':45C,140C ''deni'':138C ''deny-by-default'':137C ''desktop'':9B ''dirnam'':67C ''electron'':1A,2A,25C,29C,32C,35C,38C,41C,51C,158C ''electron-build'':28C ''electron-forg'':31C ''electron-stor'':40C ''electron-updat'':37C,157C ''electron-vit'':34C ''event'':75C ''everi'':83C,111C ''expos'':128C ''extract'':173C ''fals'':62C ''feed'':163C ''forg'':33C ''frame'':117C ''framework'':3B ''full'':18B ''handler'':84C,113C ''html'':14B ''index.html'':70C ''integr'':24B ''ipcmain'':49C,112C ''ipcmain.handle'':71C ''javascript/typescript'':16B ''keep'':147C ''list'':73C ''listordersforcurrentus'':78C ''load'':130C ''main.js'':43C ''minim'':106C ''must'':98C ''nativ'':22B ''navig'':146C ''never'':129C ''new'':56C ''node.js'':19B,26C ''nodeintegr'':61C,87C ''one'':100C ''order'':72C ''os'':23B ''path.join'':66C ''pin'':162C ''platform'':8B ''preload'':65C,107C ''preload.js'':68C ''privileg'':135C ''protect'':169C ''rememb'':165C ''remot'':131C ''render'':92C,123C ''requir'':50C ''return'':76C ''sandbox'':63C,89C ''secret'':171C ''secur'':44C ''sender'':80C,116C ''setwindowopenhandl'':142C ''ship'':150C ''sign'':153C ''stay'':99C ''store'':42C ''tab'':96C ''technolog'':13B ''true'':60C,64C ''updat'':39C,156C,159C ''url'':132C ''use'':11B ''valid'':79C,114C ''vite'':36C ''web'':12B ''webprefer'':58C ''websecur'':148C ''will-navig'':144C ''win'':55C ''win.loadfile'':69C ''window'':136C');
INSERT INTO public.technology_catalog VALUES ('aws-eventbridge', 'AWS EventBridge', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-eventbridge.png', '#FF4F8B', '["event-stream", "message-broker", "scheduled-trigger"]', '{"purpose": "AWS serverless event bus for building event-driven architectures with native integrations to 90+ AWS services, SaaS partners, and custom applications. Best for decoupling microservices with schema-validated events, routing AWS service events (e.g., S3 uploads, ECS state changes), and building cross-account event architectures. Use EventBridge over SNS when you need content-based routing rules, schema registry, event replay, or SaaS integrations. Use EventBridge over Kinesis when events are discrete and order is not critical.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using EventBridge for high-throughput ordered streaming (use Kinesis)", "Putting large payloads in events instead of S3 references", "Creating overly broad event patterns that match unintended events", "Not using schema registry for cross-team event contracts", "Relying on EventBridge for synchronous request-reply patterns"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/eventbridge/"}, "bestPractices": ["Use schema registry for event validation and discovery", "Design event patterns with content-based filtering rules", "Use archive and replay for debugging and reprocessing", "Create dedicated event buses per domain or team", "Use DLQs on rules for failed event delivery", "Keep event payloads small; reference large data via S3"], "sdkInitPattern": "import { EventBridgeClient, PutEventsCommand } from ''@aws-sdk/client-eventbridge'';\n\nconst eb = new EventBridgeClient({});\nawait eb.send(new PutEventsCommand({\n  Entries: [{ EventBusName: ''app-bus'', Source: ''app.orders'', DetailType: ''OrderPlaced'', Detail: JSON.stringify(order) }],\n}));", "securityGuidance": "Scope events:PutEvents by bus and by source condition — a producer that can publish arbitrary sources can impersonate other services on the bus. Rules route to targets via per-rule IAM roles: scope each to its one target. Event detail is visible to every matched consumer, so payloads carry references, not secrets, and cross-account buses need explicit resource policies naming the trusted accounts."}', '[{"kind": "source", "path": "src/events/eventbridge-publisher.ts", "priority": "essential", "description": "EventBridge event publishing client"}, {"kind": "config", "path": "src/events/eventbridge-rules.ts", "priority": "recommended", "description": "Event rule and pattern definitions"}, {"kind": "schema", "path": "src/events/schemas/", "priority": "recommended", "description": "Event schema definitions"}, {"kind": "config", "path": "terraform/eventbridge.tf", "priority": "recommended", "description": "EventBridge infrastructure definition"}]', '{"busType": {"enum": ["default", "custom", "partner"], "type": "string", "label": "Event Bus Type", "default": "custom"}, "archiveEnabled": {"type": "boolean", "label": "Event Archive", "default": false}, "schemaRegistry": {"type": "boolean", "label": "Schema Registry", "default": true}}', '["serverless-function", "message-broker", "worker", "rest-api"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''/client-eventbridge'':92C ''90'':19B ''account'':50B,169C,178C ''app'':104C ''app-bus'':103C ''app.orders'':107C ''applic'':26B ''arbitrari'':127C ''architectur'':14B,52B ''aw'':1A,3A,5B,20B,37B,90C ''await'':97C ''aws-sdk'':89C ''base'':62B ''best'':27B ''build'':10B,47B ''bus'':8B,105C,117C,135C ''buse'':170C ''carri'':162C ''chang'':45B ''condit'':121C ''const'':93C ''consum'':159C ''content'':61B ''content-bas'':60B ''critic'':84B ''cross'':49B,168C ''cross-account'':48B,167C ''custom'':25B ''decoupl'':29B ''detail'':110C,153C ''detailtyp'':108C ''discret'':79B ''driven'':13B ''e.g'':40B ''eb'':94C ''eb.send'':98C ''ec'':43B ''entri'':101C ''event'':7B,12B,35B,39B,51B,67B,77B,114C,152C ''event-driven'':11B ''eventbridg'':2A,4A,54B,73B ''eventbridgecli'':86C,96C ''eventbusnam'':102C ''everi'':157C ''explicit'':172C ''iam'':144C ''imperson'':130C ''import'':85C ''integr'':17B,71B ''json.stringify'':111C ''kinesi'':75B ''match'':158C ''microservic'':30B ''name'':175C ''nativ'':16B ''need'':59B,171C ''new'':95C,99C ''one'':150C ''order'':81B,112C ''orderplac'':109C ''partner'':23B ''payload'':161C ''per'':142C ''per-rul'':141C ''polici'':174C ''produc'':123C ''publish'':126C ''putev'':115C ''puteventscommand'':87C,100C ''refer'':163C ''registri'':66B ''replay'':68B ''resourc'':173C ''role'':145C ''rout'':36B,63B,137C ''rule'':64B,136C,143C ''s3'':41B ''saa'':22B,70B ''schema'':33B,65B ''schema-valid'':32B ''scope'':113C,146C ''sdk'':91C ''secret'':165C ''serverless'':6B ''servic'':21B,38B,132C ''sns'':56B ''sourc'':106C,120C,128C ''state'':44B ''target'':139C,151C ''trust'':177C ''upload'':42B ''use'':53B,72B ''valid'':34B ''via'':140C ''visibl'':155C');
INSERT INTO public.technology_catalog VALUES ('supabase-edge-functions', 'Supabase Edge Functions', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#6b7280', '["serverless-function"]', '{"purpose": "Server-side TypeScript functions deployed to Deno runtime at the edge. Use for webhooks, third-party API integrations, and custom server logic within the Supabase ecosystem.", "configMode": "code", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Deno", "TypeScript", "Supabase CLI"], "antiPatterns": ["Importing from deno.land/x or esm.sh CDNs", "Not handling OPTIONS preflight requests", "Using bare specifiers without npm: or jsr: prefix", "Sharing code between functions via relative imports"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/functions"}, "bestPractices": ["Use Deno.serve() for request handling", "Import npm packages with npm: prefix", "Handle CORS with Access-Control headers", "Use Supabase client with service role key for admin operations", "Keep functions focused on a single responsibility"], "freshnessNote": "Placement decides the lane: managed deploys via supabase functions deploy; self-hosted this is the open-source edge-runtime container — functions arrive by folder mount + restart. Runtime details (Deno, npm: specifiers, execution limits) live on the deno-edge technology row.", "sdkInitPattern": "// supabase/functions/orders/index.ts\nimport { createClient } from ''npm:@supabase/supabase-js@2'';\n\nDeno.serve(async (req: Request) => {\n  const authHeader = req.headers.get(''Authorization'')!;\n  const supabase = createClient(\n    Deno.env.get(''SUPABASE_URL'')!,\n    Deno.env.get(''SUPABASE_ANON_KEY'')!,\n    { global: { headers: { Authorization: authHeader } } },\n  );\n  const { data, error } = await supabase.from(''orders'').select(''*''); // RLS applies as the CALLER\n  if (error) return new Response(error.message, { status: 400 });\n  return Response.json(data);\n});", "securityGuidance": "Forward the caller''s JWT into the client so Row Level Security evaluates as the USER — constructing the client with the service-role key bypasses RLS entirely and must be a deliberate, endpoint-by-endpoint decision, never the default. Secrets come from function env (supabase secrets set), verify_jwt stays on unless the endpoint is intentionally public (webhooks verify their own signatures instead), and validate all input server-side — the function is your trust boundary, not the browser that called it.", "setupInstructions": [{"url": "https://supabase.com/docs/guides/cli", "type": "toolchain_install", "title": "Install Supabase CLI", "commands": ["npm install -g supabase", "supabase login"], "required": true, "instructions": "Install the Supabase CLI for local development and deployment of Edge Functions."}, {"type": "toolchain_install", "title": "Create a New Function", "commands": ["supabase functions new my-function"], "required": true, "instructions": "Use the CLI to scaffold a new Edge Function. This creates the function directory and index.ts file."}, {"type": "manual_workflow", "title": "Deploy Function", "commands": ["supabase functions deploy my-function"], "required": true, "instructions": "Deploy to your Supabase project. The function will be available at your project URL under /functions/v1/function-name."}, {"type": "environment_variable", "title": "Manage Secrets", "commands": ["supabase secrets set MY_API_KEY=value", "supabase secrets list"], "required": false, "instructions": "Set environment variables (secrets) for your Edge Functions. These are available via Deno.env.get() at runtime."}]}', '[{"kind": "code", "path": "supabase/functions/orders/index.ts", "language": "typescript", "description": "Edge function forwarding the caller JWT so RLS applies as the user"}]', '{"verifyJwt": {"type": "boolean", "label": "Verify JWT", "default": true, "description": "Default-on gateway check; turn off ONLY for public webhooks that verify their own signatures (Stripe, GitHub)"}, "secretsSource": {"type": "enum", "label": "Secrets", "default": "supabase-secrets-cli", "options": ["supabase-secrets-cli", "env-file-self-hosted"]}, "boundResources": {"type": "multiselect", "label": "Talks to", "options": ["supabase-db", "supabase-storage", "external-apis"], "description": "What the function reaches — drives the env/secret checklist in the packet"}}', '[]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-31 20:07:01.887163+00', 'Supabase Edge Functions', NULL, '''2'':45C ''400'':87C ''anon'':62C ''api'':25B ''appli'':76C ''async'':47C ''authhead'':51C,67C ''author'':53C,66C ''await'':71C ''boundari'':168C ''browser'':171C ''bypass'':116C ''call'':173C ''caller'':79C,93C ''cli'':38C ''client'':98C,109C ''come'':133C ''const'':50C,54C,68C ''construct'':107C ''createcli'':41C,56C ''custom'':28B ''data'':69C,90C ''decis'':128C ''default'':131C ''deliber'':123C ''deno'':14B,35C ''deno.env.get'':57C,60C ''deno.serve'':46C ''deploy'':12B ''ecosystem'':34B ''edg'':2A,5A,18B ''endpoint'':125C,127C,146C ''endpoint-by-endpoint'':124C ''entir'':118C ''env'':136C ''error'':70C,81C ''error.message'':85C ''evalu'':103C ''forward'':91C ''function'':3A,6A,11B,135C,164C ''global'':64C ''header'':65C ''import'':40C ''input'':159C ''instead'':155C ''integr'':26B ''intent'':148C ''jwt'':95C,141C ''key'':63C,115C ''level'':101C ''logic'':30B ''must'':120C ''never'':129C ''new'':83C ''npm'':43C ''order'':73C ''parti'':24B ''public'':149C ''req'':48C ''req.headers.get'':52C ''request'':49C ''respons'':84C ''response.json'':89C ''return'':82C,88C ''rls'':75C,117C ''role'':114C ''row'':100C ''runtim'':15B ''secret'':132C,138C ''secur'':102C ''select'':74C ''server'':8B,29B,161C ''server-sid'':7B,160C ''servic'':113C ''service-rol'':112C ''set'':139C ''side'':9B,162C ''signatur'':154C ''status'':86C ''stay'':142C ''supabas'':1A,4A,33B,37C,55C,58C,61C,137C ''supabase.from'':72C ''supabase/functions/orders/index.ts'':39C ''supabase/supabase-js'':44C ''third'':23B ''third-parti'':22B ''trust'':167C ''typescript'':10B,36C ''unless'':144C ''url'':59C ''use'':19B ''user'':106C ''valid'':157C ''verifi'':140C,151C ''webhook'':21B,150C ''within'':31B');
INSERT INTO public.technology_catalog VALUES ('supabase-auth', 'Supabase Auth', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ecf8e', '["auth-provider"]', '{"purpose": "Managed authentication service built on GoTrue, deeply integrated with PostgreSQL Row Level Security. Provides email/password, magic links, phone auth, OAuth social providers, and SAML SSO. Auth state is stored in the auth schema and accessible via auth.uid() and auth.jwt() in RLS policies and database functions.", "configMode": "external", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["GoTrue", "@supabase/supabase-js", "@supabase/auth-helpers-nextjs", "@supabase/auth-helpers-react", "@supabase/ssr", "PostgreSQL RLS", "JWT", "PKCE"], "antiPatterns": ["Using service_role key in client-side code (exposes full database access)", "Storing authorization data in raw_user_meta_data (user can modify it)", "Not enabling RLS on tables that store user data", "Creating RLS policies with USING (true) which allows unrestricted access", "Using async callbacks directly with onAuthStateChange (causes deadlocks)", "Not handling token refresh or session expiration", "Directly querying auth.users or auth schema tables from client code", "Exposing JWT secrets or service_role key in frontend bundles", "Relying solely on client-side auth checks without server-side RLS enforcement", "Not using email confirmation in production (allows unverified signups)"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/auth"}, "bestPractices": ["Use Row Level Security (RLS) policies with auth.uid() as the primary authorization mechanism", "Use onAuthStateChange listener for reactive session management", "Wrap async logic inside onAuthStateChange in an IIFE to avoid deadlocks", "Use @supabase/ssr for server-side rendering frameworks (Next.js, SvelteKit, Remix)", "Enable email confirmation for production deployments", "Use PKCE flow for mobile and SPA applications", "Store custom user data in a public.profiles table with RLS, not in auth.users metadata", "Use auth.jwt() -> app_metadata for authorization claims (cannot be modified by user)", "Use Supabase Edge Functions with service_role key for admin auth operations", "Implement proper error handling for signUp, signIn, and signOut flows", "Use auth.admin for server-side privileged operations like user management", "Add auth hooks (database webhooks) for post-signup provisioning", "Use custom claims via database functions for role-based access control"], "freshnessNote": "Placement decides the lane: inside Supabase (Managed), auth is the managed service (dashboard provider toggles, SMS/SSO config). Self-hosted, this node is the open-source GoTrue container — OAuth providers, SMTP and redirect URLs are environment configuration, and phone auth needs your own provider wiring.", "sdkInitPattern": "import { createClient } from ''@supabase/supabase-js'';\n\nconst supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_ANON_KEY!);\nconst { data, error } = await supabase.auth.signInWithOAuth({\n  provider: ''github'',\n  options: { redirectTo: `${origin}/auth/callback` },\n});\n// server-side: verify the session JWT on every request via supabase.auth.getUser()", "securityGuidance": "The anon key is public by design — security comes from RLS plus auth server settings, not key secrecy; the service-role key bypasses everything and never leaves the server. Verify sessions server-side with getUser() (which validates against the auth server) rather than trusting a decoded JWT alone, keep redirect URLs exact (a wildcard redirect is token exfiltration), enable email confirmation and sensible OTP expiries, and require MFA for admin-tier users. Auth hooks/triggers that mint claims are access-policy code — review them like RLS.", "setupInstructions": [{"url": "https://supabase.com/docs/guides/auth", "type": "dashboard_config", "title": "Enable Auth in Supabase Dashboard", "required": true, "instructions": "Navigate to Authentication > Providers in your Supabase dashboard to enable email/password and any social providers."}, {"type": "dashboard_config", "title": "Configure Redirect URLs", "required": true, "instructions": "Add your application URLs to Authentication > URL Configuration > Redirect URLs in the Supabase dashboard."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export VITE_SUPABASE_URL=https://your-project.supabase.co", "export VITE_SUPABASE_ANON_KEY=your-anon-key"], "required": true, "instructions": "Ensure SUPABASE_URL and SUPABASE_ANON_KEY are set in your application environment."}]}', '[{"kind": "config", "path": "src/lib/supabase.ts", "language": "typescript", "priority": "essential", "description": "Supabase client singleton with auth configuration"}, {"kind": "source", "path": "src/auth/AuthProvider.tsx", "language": "typescript", "priority": "essential", "description": "React auth context provider using onAuthStateChange"}, {"kind": "source", "path": "src/auth/ProtectedRoute.tsx", "language": "typescript", "priority": "essential", "description": "Route guard component checking auth session state"}, {"kind": "source", "path": "src/auth/useAuth.ts", "language": "typescript", "priority": "essential", "description": "Auth hook for accessing session, user, signIn, signOut"}, {"kind": "schema", "path": "supabase/migrations/create_profiles.sql", "language": "sql", "priority": "essential", "description": "Public profiles table with RLS policies linked to auth.uid()"}, {"kind": "schema", "path": "supabase/migrations/rls-policies.sql", "language": "sql", "priority": "essential", "description": "Row Level Security policies using auth.uid() for data access control"}, {"kind": "source", "path": "supabase/functions/auth-webhook/index.ts", "language": "typescript", "priority": "recommended", "description": "Edge Function for post-signup provisioning webhook"}, {"kind": "config", "path": "supabase/config.toml", "language": "toml", "priority": "recommended", "description": "Local Supabase config with auth settings (email confirmation, providers)"}, {"kind": "source", "path": "src/middleware/auth.ts", "language": "typescript", "priority": "recommended", "description": "Server middleware for SSR auth with @supabase/ssr"}]', '{"pkceFlow": {"type": "boolean", "label": "PKCE Flow", "default": true, "description": "Use PKCE auth flow for SPAs and mobile apps (recommended)"}, "emailAuth": {"type": "boolean", "label": "Email/Password Auth", "default": true, "description": "Enable email and password authentication"}, "phoneAuth": {"type": "boolean", "label": "Phone Auth", "default": false, "description": "Enable phone number (SMS) authentication"}, "magicLinks": {"type": "boolean", "label": "Magic Links", "default": false, "description": "Enable passwordless magic link authentication"}, "mfaEnabled": {"type": "boolean", "label": "MFA", "default": false, "description": "Enable multi-factor authentication with TOTP"}, "projectUrl": {"type": "string", "label": "Supabase Project URL", "description": "Supabase project API URL"}, "customClaims": {"type": "boolean", "label": "Custom Claims", "default": false, "description": "Use app_metadata custom claims for role-based access control"}, "sessionTimeout": {"type": "number", "label": "Session Timeout (seconds)", "default": 3600, "description": "JWT token expiration time in seconds"}, "socialProviders": {"type": "array", "label": "OAuth Providers", "description": "Enabled social login providers (Google, GitHub, Discord, etc.)"}, "emailConfirmation": {"type": "boolean", "label": "Email Confirmation", "default": false, "description": "Require email confirmation before allowing sign-in"}}', '["database", "backend-service", "frontend-app", "edge-function"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-31 20:07:01.887163+00', NULL, '#32A872', '''/auth/callback'':81C ''access'':39B,176C ''access-polici'':175C ''admin'':166C ''admin-ti'':165C ''alon'':143C ''anon'':69C,95C ''auth'':2A,4A,23B,30B,36B,106C,135C,169C ''auth.jwt'':43B ''auth.uid'':41B ''authent'':6B ''await'':74C ''built'':8B ''bypass'':117C ''claim'':173C ''code'':178C ''come'':102C ''confirm'':156C ''const'':63C,71C ''createcli'':60C,65C ''data'':72C ''databas'':48B ''decod'':141C ''deepli'':11B ''design'':100C ''email'':155C ''email/password'':19B ''enabl'':154C ''error'':73C ''everi'':90C ''everyth'':118C ''exact'':147C ''exfiltr'':153C ''expiri'':160C ''function'':49B ''getus'':130C ''github'':77C ''gotru'':10B,50C ''hooks/triggers'':170C ''import'':59C ''integr'':12B ''jwt'':57C,88C,142C ''keep'':144C ''key'':70C,96C,110C,116C ''leav'':121C ''level'':16B ''like'':181C ''link'':21B ''magic'':20B ''manag'':5B ''mfa'':163C ''mint'':172C ''never'':120C ''oauth'':24B ''option'':78C ''origin'':80C ''otp'':159C ''phone'':22B ''pkce'':58C ''plus'':105C ''polici'':46B,177C ''postgresql'':14B,55C ''process.env.supabase'':66C,68C ''provid'':18B,26B,76C ''public'':98C ''rather'':137C ''redirect'':145C,150C ''redirectto'':79C ''request'':91C ''requir'':162C ''review'':179C ''rls'':45B,56C,104C,182C ''role'':115C ''row'':15B ''saml'':28B ''schema'':37B ''secreci'':111C ''secur'':17B,101C ''sensibl'':158C ''server'':83C,107C,123C,127C,136C ''server-sid'':82C,126C ''servic'':7B,114C ''service-rol'':113C ''session'':87C,125C ''set'':108C ''side'':84C,128C ''social'':25B ''sso'':29B ''state'':31B ''store'':33B ''supabas'':1A,3A,64C ''supabase.auth.getuser'':93C ''supabase.auth.signinwithoauth'':75C ''supabase/auth-helpers-nextjs'':52C ''supabase/auth-helpers-react'':53C ''supabase/ssr'':54C ''supabase/supabase-js'':51C,62C ''tier'':167C ''token'':152C ''trust'':139C ''url'':67C,146C ''user'':168C ''valid'':132C ''verifi'':85C,124C ''via'':40B,92C ''wildcard'':149C');
INSERT INTO public.technology_catalog VALUES ('aws-amplify-hosting', 'AWS Amplify Hosting', NULL, '#DD344C', '["frontend-app"]', '{"purpose": "Managed CI/CD and hosting for static and SSR web apps on the AWS edge network", "configMode": "code", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["amplify.yml", "Next.js", "React", "Vite", "CloudFront edge delivery"], "antiPatterns": ["Committing environment secrets into amplify.yml", "Using Amplify Hosting for heavy server workloads better suited to ECS", "Skipping preview branches and testing only in production"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/amplify/"}, "bestPractices": ["Define build settings in amplify.yml and commit it to the repository", "Use branch-based preview deployments for pull request review", "Store secrets in per-branch environment variables, never in the build file", "Connect custom domains for automatic SSL provisioning", "Enable SSR compute only for frameworks that need it"], "sdkInitPattern": "version: 1\nfrontend:\n  phases:\n    build:\n      commands:\n        - npm ci\n        - npm run build\n  artifacts:\n    baseDirectory: dist\n    files:\n      - \"**/*\"", "securityGuidance": "Amplify builds run your repo''s build spec — protect who can edit amplify.yml and branch settings like deploy access. Keep secrets in environment variables backed by the console/SSM (server-side rendering only; anything exposed to the browser bundle is public), and use branch-level access control or basic auth on preview branches that render real data."}', '[{"kind": "config", "path": "amplify.yml", "priority": "essential", "description": "Amplify build specification"}]', '{"branch": {"type": "string", "label": "Deploy branch", "default": "main"}, "framework": {"type": "enum", "label": "Framework", "default": "nextjs", "options": ["nextjs", "react", "vue", "angular", "static"]}, "buildCommand": {"type": "string", "label": "Build command", "default": "npm run build"}, "customDomain": {"type": "boolean", "label": "Custom domain", "default": false}}', '[{"id": "react", "reason": "Common frontend framework"}, {"id": "nextjs", "reason": "SSR framework support"}, {"id": "aws-cloudfront", "reason": "Underlying edge delivery"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''1'':30C ''access'':62C,90C ''amplifi'':2A,5A,44C ''amplify.yml'':22C,56C ''anyth'':77C ''app'':16B ''artifact'':40C ''auth'':94C ''aw'':1A,4A,19B ''back'':68C ''basedirectori'':41C ''basic'':93C ''branch'':58C,88C,97C ''branch-level'':87C ''browser'':81C ''build'':33C,39C,45C,50C ''bundl'':82C ''ci'':36C ''ci/cd'':8B ''cloudfront'':26C ''command'':34C ''console/ssm'':71C ''control'':91C ''data'':101C ''deliveri'':28C ''deploy'':61C ''dist'':42C ''edg'':20B,27C ''edit'':55C ''environ'':66C ''expos'':78C ''file'':43C ''frontend'':31C ''host'':3A,6A,10B ''keep'':63C ''level'':89C ''like'':60C ''manag'':7B ''network'':21B ''next.js'':23C ''npm'':35C,37C ''phase'':32C ''preview'':96C ''protect'':52C ''public'':84C ''react'':24C ''real'':100C ''render'':75C,99C ''repo'':48C ''run'':38C,46C ''secret'':64C ''server'':73C ''server-sid'':72C ''set'':59C ''side'':74C ''spec'':51C ''ssr'':14B ''static'':12B ''use'':86C ''variabl'':67C ''version'':29C ''vite'':25C ''web'':15B');
INSERT INTO public.technology_catalog VALUES ('aws-eks', 'AWS EKS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-eks.png', '#FF9900', '["k8s-cluster", "k8s-namespace"]', '{"purpose": "AWS managed Kubernetes service providing a certified Kubernetes control plane without managing master nodes. Best for teams with existing Kubernetes expertise, multi-cloud portability requirements, or complex workloads needing the Kubernetes ecosystem (Helm, Istio, Argo, etc.). EKS Fargate enables serverless Kubernetes pods; EKS on EC2 provides full node control. Choose EKS over ECS when Kubernetes compatibility, ecosystem, or portability matters. Choose ECS over EKS for simpler AWS-native container workloads.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Managing Kubernetes on EC2 manually instead of using managed node groups", "Not using IRSA, falling back to node-level IAM roles", "Skipping cluster autoscaler causing resource waste or pod scheduling failures", "Using EKS for simple stateless services where ECS Fargate suffices", "Not upgrading Kubernetes versions, accumulating version drift"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/eks/"}, "bestPractices": ["Use managed node groups for simplified node lifecycle management", "Enable cluster autoscaler or Karpenter for dynamic scaling", "Use AWS Load Balancer Controller for ALB/NLB integration", "Implement IRSA (IAM Roles for Service Accounts) for pod-level AWS access", "Use EKS Fargate profiles for serverless pods where appropriate", "Enable control plane logging for audit and diagnostics"], "securityGuidance": "Map pods to AWS permissions with IRSA/Pod Identity — one scoped role per service account, never node-instance-role permissions shared by every pod. Make the API endpoint private (or CIDR-restricted), keep aws-auth/access-entries mappings least-privilege, enable control-plane audit logs, and enforce baseline Pod Security Standards so a compromised container cannot become a privileged node process.", "configurationTemplate": "# eksctl cluster config\napiVersion: eksctl.io/v1alpha5\nkind: ClusterConfig\nmetadata:\n  name: app-cluster\n  region: us-east-1\nmanagedNodeGroups:\n  - name: workers\n    instanceType: m6i.large\n    desiredCapacity: 3\n    privateNetworking: true\niam:\n  withOIDC: true"}', '[{"kind": "config", "path": "k8s/deployment.yaml", "priority": "essential", "description": "Kubernetes deployment manifest"}, {"kind": "config", "path": "k8s/service.yaml", "priority": "essential", "description": "Kubernetes service manifest"}, {"kind": "config", "path": "k8s/ingress.yaml", "priority": "recommended", "description": "Kubernetes ingress rules"}, {"kind": "config", "path": "terraform/eks.tf", "priority": "recommended", "description": "EKS cluster infrastructure definition"}, {"kind": "build", "path": "Dockerfile", "priority": "essential", "description": "Container image definition"}]', '{"nodeType": {"enum": ["managed", "fargate", "self-managed"], "type": "string", "label": "Node Type", "default": "managed"}, "clusterAutoscaler": {"type": "boolean", "label": "Cluster Autoscaler", "default": true}, "kubernetesVersion": {"type": "string", "label": "Kubernetes Version", "default": "1.29"}}', '["load-balancer", "database", "cache", "monitoring"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''/access-entries'':114C ''account'':90C ''api'':103C ''argo'':40B ''audit'':123C ''auth'':113C ''aw'':1A,3A,5B,73B,80C,112C ''aws-auth'':111C ''aws-nat'':72B ''baselin'':127C ''becom'':136C ''best'':19B ''cannot'':135C ''certifi'':11B ''choos'':55B,66B ''cidr'':108C ''cidr-restrict'':107C ''cloud'':28B ''compat'':61B ''complex'':32B ''compromis'':133C ''contain'':75B,134C ''control'':13B,54B,121C ''control-plan'':120C ''ec'':58B,67B ''ec2'':50B ''ecosystem'':37B,62B ''ek'':2A,4A,42B,48B,56B,69B ''enabl'':44B,119C ''endpoint'':104C ''enforc'':126C ''etc'':41B ''everi'':99C ''exist'':23B ''expertis'':25B ''fargat'':43B ''full'':52B ''helm'':38B ''ident'':84C ''instanc'':94C ''irsa/pod'':83C ''istio'':39B ''keep'':110C ''kubernet'':7B,12B,24B,36B,46B,60B ''least'':117C ''least-privileg'':116C ''log'':124C ''make'':101C ''manag'':6B,16B ''map'':77C,115C ''master'':17B ''matter'':65B ''multi'':27B ''multi-cloud'':26B ''nativ'':74B ''need'':34B ''never'':91C ''node'':18B,53B,93C,139C ''node-instance-rol'':92C ''one'':85C ''per'':88C ''permiss'':81C,96C ''plane'':14B,122C ''pod'':47B,78C,100C,128C ''portabl'':29B,64B ''privat'':105C ''privileg'':118C,138C ''process'':140C ''provid'':9B,51B ''requir'':30B ''restrict'':109C ''role'':87C,95C ''scope'':86C ''secur'':129C ''serverless'':45B ''servic'':8B,89C ''share'':97C ''simpler'':71B ''standard'':130C ''team'':21B ''without'':15B ''workload'':33B,76B');
INSERT INTO public.technology_catalog VALUES ('aws-aurora', 'AWS Aurora', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aurora.png', '#ff9900', '["database"]', '{"purpose": "AWS cloud-native relational database compatible with MySQL and PostgreSQL with up to 5x MySQL / 3x PostgreSQL throughput and automatic storage scaling to 128TB. Best for AWS-centric architectures needing higher performance than standard RDS. Aurora Serverless v2 enables auto-scaling for variable workloads. Use Aurora over standard RDS when performance, auto-scaling, or global distribution matters.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Aurora PostgreSQL", "Aurora MySQL", "Aurora Serverless v2", "Global Database", "Parallel Query", "RDS Proxy"], "antiPatterns": ["Not using reader endpoint, routing all traffic to writer", "Ignoring Performance Insights", "Choosing Aurora for simple low-traffic apps where standard RDS is cheaper"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/aurora/"}, "bestPractices": ["Use Aurora Serverless v2 for variable workloads", "Route read traffic through reader endpoints", "Enable Global Database for cross-region DR", "Use Performance Insights and Enhanced Monitoring", "Use RDS Proxy for connection pooling with serverless apps", "Enable backtrack for point-in-time recovery"], "securityGuidance": "No public accessibility — private subnets, security groups admitting only the app tier, and --manage-master-user-password so the master credential lives in Secrets Manager with rotation from day one. Applications connect as least-privilege database users (ideally via RDS Proxy with IAM auth, which also absorbs serverless connection storms), TLS enforced, and backtrack/PITR windows sized to your actual recovery story.", "configurationTemplate": "# Cluster: private subnets, IAM auth on, secrets managed\naws rds create-db-cluster --db-cluster-identifier app-cluster \\\n  --engine aurora-postgresql --engine-version 15 \\\n  --master-username appadmin --manage-master-user-password \\\n  --vpc-security-group-ids sg-0123 --db-subnet-group-name private-db\n# App connects via RDS Proxy with IAM auth or Secrets Manager credentials"}', '[{"kind": "config", "path": "infra/aws/aurora.tf"}, {"kind": "source", "path": "db/migrations/"}]', '{"engine": {"type": "enum", "label": "Engine", "default": "aurora-postgresql", "options": ["aurora-postgresql", "aurora-mysql"], "description": "Aurora edition"}, "capacityMode": {"type": "enum", "label": "Capacity mode", "default": "serverless", "options": ["serverless", "provisioned"], "description": "Aurora serverless (ACU-billed, scales to zero; the Serverless v2 successor, renamed April 2026) vs provisioned instances"}, "readReplicas": {"type": "number", "label": "Read replicas", "default": 0, "description": "Up to 15 Aurora replicas share the storage volume"}, "instanceClass": {"type": "string", "label": "Instance class (provisioned)", "default": "db.r6g.large", "description": "Provisioned mode only; Graviton (…g) classes are cheaper"}, "globalDatabase": {"type": "boolean", "label": "Global database", "default": false, "description": "Cross-region replication for DR / read locality"}}', '["backend-service", "serverless-function"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', NULL, '#1F5A96', '''128tb'':29B ''3x'':21B ''5x'':19B ''absorb'':127C ''access'':81C ''actual'':139C ''admit'':86C ''also'':126C ''app'':89C ''applic'':110C ''architectur'':35B ''aurora'':2A,4A,42B,53B,66C,68C,70C ''auth'':124C ''auto'':47B,60B ''auto-sc'':46B,59B ''automat'':25B ''aw'':1A,3A,5B,33B ''aws-centr'':32B ''backtrack/pitr'':134C ''best'':30B ''centric'':34B ''cloud'':7B ''cloud-nat'':6B ''compat'':11B ''connect'':111C,129C ''credenti'':100C ''databas'':10B,74C,116C ''day'':108C ''distribut'':64B ''enabl'':45B ''enforc'':132C ''global'':63B,73C ''group'':85C ''higher'':37B ''iam'':123C ''ideal'':118C ''least'':114C ''least-privileg'':113C ''live'':101C ''manag'':93C,104C ''manage-master-user-password'':92C ''master'':94C,99C ''matter'':65B ''mysql'':13B,20B,69C ''nativ'':8B ''need'':36B ''one'':109C ''parallel'':75C ''password'':96C ''perform'':38B,58B ''postgresql'':15B,22B,67C ''privat'':82C ''privileg'':115C ''proxi'':78C,121C ''public'':80C ''queri'':76C ''rds'':41B,56B,77C,120C ''recoveri'':140C ''relat'':9B ''rotat'':106C ''scale'':27B,48B,61B ''secret'':103C ''secur'':84C ''serverless'':43B,71C,128C ''size'':136C ''standard'':40B,55B ''storag'':26B ''stori'':141C ''storm'':130C ''subnet'':83C ''throughput'':23B ''tier'':90C ''tls'':131C ''use'':52B ''user'':95C,117C ''v2'':44B,72C ''variabl'':50B ''via'':119C ''window'':135C ''workload'':51B');
INSERT INTO public.technology_catalog VALUES ('aws-waf', 'AWS WAF', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-waf.png', '#DD344C', '["waf"]', '{"purpose": "Web application firewall that protects web applications from common exploits and bots. Attaches to ALB, API Gateway, CloudFront, or AppSync to filter HTTP/HTTPS requests. Provides managed rule groups (OWASP Top 10, bot control, IP reputation) and custom rules using rate limiting, geo-matching, and regex patterns.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Deploying rules directly in Block mode without testing in Count mode first", "Not monitoring WAF metrics and logs for false positives", "Applying WAF only to ALB while leaving CloudFront or API Gateway unprotected", "Creating overly broad rules that block legitimate traffic"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/waf/"}, "bestPractices": ["Use AWS Managed Rules as a baseline (AWSManagedRulesCommonRuleSet for OWASP Top 10)", "Enable logging to S3 or CloudWatch for audit and debugging", "Start with Count mode before switching rules to Block to avoid false positives", "Use rate-based rules to protect against DDoS and brute-force attacks", "Apply IP reputation lists to block known malicious sources", "Create custom rules for application-specific protections"], "securityGuidance": "A web ACL protects only what it is associated with — audit that every internet-facing ALB, CloudFront distribution, and API stage actually has one. Start managed rule groups in count mode, review the samples, then enforce; tune scoped-down statements rather than disabling whole groups on false positives. Rate-based rules bound per-IP abuse, and WAF logs (to a locked destination) are the forensic record — enable them before the incident, and lock origins so traffic cannot route around the WAF.", "configurationTemplate": "# Web ACL: managed rules + rate limit, associated to the ALB/CloudFront/API GW\naws wafv2 create-web-acl --name app-acl --scope REGIONAL \\\n  --default-action Allow={} \\\n  --rules ''[\n    {\"Name\":\"common\",\"Priority\":1,\"Statement\":{\"ManagedRuleGroupStatement\":{\"VendorName\":\"AWS\",\"Name\":\"AWSManagedRulesCommonRuleSet\"}},\"OverrideAction\":{\"None\":{}},\"VisibilityConfig\":{\"SampledRequestsEnabled\":true,\"CloudWatchMetricsEnabled\":true,\"MetricName\":\"common\"}},\n    {\"Name\":\"rate\",\"Priority\":2,\"Statement\":{\"RateBasedStatement\":{\"Limit\":2000,\"AggregateKeyType\":\"IP\"}},\"Action\":{\"Block\":{}},\"VisibilityConfig\":{\"SampledRequestsEnabled\":true,\"CloudWatchMetricsEnabled\":true,\"MetricName\":\"rate\"}}\n  ]'' --visibility-config SampledRequestsEnabled=true,CloudWatchMetricsEnabled=true,MetricName=appacl"}', '[{"kind": "config", "path": "terraform/waf.tf", "priority": "recommended", "description": "WAF web ACL and rule definitions"}, {"kind": "config", "path": "terraform/waf-logging.tf", "priority": "recommended", "description": "WAF logging configuration"}]', '{"rateLimit": {"type": "number", "label": "Rate Limit (req/5min)", "default": 2000}, "managedRules": {"type": "boolean", "label": "AWS Managed Rules", "default": true}, "defaultAction": {"type": "string", "label": "Default Action", "default": "allow"}, "ddosProtection": {"type": "enum", "label": "DDoS protection", "default": "shield-standard", "options": ["shield-standard", "shield-advanced"], "description": "Shield Standard is automatic and free; Shield Advanced (paid) adds cost protection, the Shield Response Team, and advanced mitigations - a tier of this node, not a separate one"}}', '["load-balancer", "api-gateway", "cdn", "graphql-api"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.578953+00', NULL, '#B82A3E', '''10'':35B ''abus'':110C ''acl'':54C ''actual'':74C ''alb'':19B,68C ''api'':20B,72C ''applic'':6B,11B ''appsync'':24B ''around'':134C ''associ'':60C ''attach'':17B ''audit'':62C ''aw'':1A,3A ''base'':104C ''bot'':16B,36B ''bound'':106C ''cannot'':132C ''cloudfront'':22B,69C ''common'':13B ''control'':37B ''count'':82C ''custom'':41B ''destin'':117C ''disabl'':96C ''distribut'':70C ''enabl'':122C ''enforc'':88C ''everi'':64C ''exploit'':14B ''face'':67C ''fals'':100C ''filter'':26B ''firewal'':7B ''forens'':120C ''gateway'':21B ''geo'':47B ''geo-match'':46B ''group'':32B,80C,98C ''http/https'':27B ''incid'':126C ''internet'':66C ''internet-fac'':65C ''ip'':38B,109C ''limit'':45B ''lock'':116C,128C ''log'':113C ''manag'':30B,78C ''match'':48B ''mode'':83C ''one'':76C ''origin'':129C ''owasp'':33B ''pattern'':51B ''per'':108C ''per-ip'':107C ''posit'':101C ''protect'':9B,55C ''provid'':29B ''rate'':44B,103C ''rate-bas'':102C ''rather'':94C ''record'':121C ''regex'':50B ''reput'':39B ''request'':28B ''review'':84C ''rout'':133C ''rule'':31B,42B,79C,105C ''sampl'':86C ''scope'':91C ''scoped-down'':90C ''stage'':73C ''start'':77C ''statement'':93C ''top'':34B ''traffic'':131C ''tune'':89C ''use'':43B ''waf'':2A,4A,112C,136C ''web'':5B,10B,53C ''whole'':97C');
INSERT INTO public.technology_catalog VALUES ('aws-iam', 'AWS IAM', NULL, '#DD344C', '["auth-provider"]', '{"purpose": "Identity and access management controlling permissions for all AWS resources", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["IAM Roles", "IAM Policies", "STS", "IAM Identity Center", "Access Analyzer"], "antiPatterns": ["Using the root account for daily operations", "Attaching AdministratorAccess to application roles", "Embedding long-lived access keys in application code", "Sharing IAM users between humans and services"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/iam/"}, "bestPractices": ["Grant least privilege with narrowly scoped policies", "Use roles and temporary credentials instead of long-lived access keys", "Enforce MFA for human users", "Apply permission boundaries when delegating administration", "Audit unused permissions with Access Analyzer", "Use resource tags with condition keys for attribute-based access control"], "sdkInitPattern": "{\n  \"Version\": \"2012-10-17\",\n  \"Statement\": [{\n    \"Effect\": \"Allow\",\n    \"Action\": [\"s3:GetObject\"],\n    \"Resource\": \"arn:aws:s3:::my-bucket/*\"\n  }]\n}", "securityGuidance": "Least privilege is the product: no wildcard actions/resources in application policies, permission boundaries on delegated-admin roles, and conditions (source, tags, MFA) on sensitive grants. Prefer ROLES with temporary credentials everywhere — long-lived access keys are legacy debt; where they exist, rotate and alarm on use. Review with IAM Access Analyzer; unused permissions are attack surface."}', '[{"kind": "config", "path": "infra/aws/iam.tf"}]', '{"mfaEnforced": {"type": "boolean", "label": "MFA enforced", "default": true, "description": "Required for human principals"}, "oidcFederation": {"type": "boolean", "label": "OIDC federation", "default": false, "description": "Keyless CI/workload identity (GitHub Actions, EKS IRSA style)"}, "serviceRolesOnly": {"type": "boolean", "label": "Service roles only", "default": true, "description": "Workloads assume roles — no long-lived user access keys"}, "permissionBoundaries": {"type": "boolean", "label": "Permission boundaries", "default": false, "description": "Cap delegated-admin created roles"}}', '[{"id": "aws-lambda", "reason": "Execution role permissions"}, {"id": "aws-ecs", "reason": "Task role permissions"}, {"id": "aws-s3", "reason": "Bucket access policies"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''-10'':27C ''-17'':28C ''2012'':26C ''access'':7B,23C,77C,93C ''action'':32C ''actions/resources'':49C ''admin'':58C ''alarm'':87C ''allow'':31C ''analyz'':24C,94C ''applic'':51C ''arn'':36C ''attack'':98C ''aw'':1A,3A,13B,37C ''boundari'':54C ''bucket'':41C ''center'':22C ''condit'':61C ''control'':9B ''credenti'':72C ''debt'':81C ''deleg'':57C ''delegated-admin'':56C ''effect'':30C ''everywher'':73C ''exist'':84C ''getobject'':34C ''grant'':67C ''iam'':2A,4A,15C,17C,20C,92C ''ident'':5B,21C ''key'':78C ''least'':42C ''legaci'':80C ''live'':76C ''long'':75C ''long-liv'':74C ''manag'':8B ''mfa'':64C ''my-bucket'':39C ''permiss'':10B,53C,96C ''polici'':18C,52C ''prefer'':68C ''privileg'':43C ''product'':46C ''resourc'':14B,35C ''review'':90C ''role'':16C,59C,69C ''rotat'':85C ''s3'':33C,38C ''sensit'':66C ''sourc'':62C ''statement'':29C ''sts'':19C ''surfac'':99C ''tag'':63C ''temporari'':71C ''unus'':95C ''use'':89C ''version'':25C ''wildcard'':48C');
INSERT INTO public.technology_catalog VALUES ('aws-vpc', 'AWS VPC', NULL, '#FF9900', '["vpc", "subnet"]', '{"purpose": "AWS Virtual Private Cloud for isolated network boundaries. Use this as the technology for vpc roles when the deployment is on AWS. Provides CIDR-based IP address management, subnet segmentation, routing, and network access control.", "configMode": "declarative", "provenance": {"notes": "Schema kept to stable API surface; live-docs upgrade rides the 4a-4 family close-out pass.", "method": "model-knowledge", "sources": ["https://docs.aws.amazon.com/"], "verifiedAt": "2026-07-27"}, "antiPatterns": ["Using a single large subnet instead of segmenting by tier and AZ", "Opening all ports in security groups for debugging and forgetting to close them", "Overlapping CIDR ranges across VPCs that need to communicate", "Running NAT Gateway in a single AZ creating a single point of failure", "Ignoring VPC Flow Logs making security incidents harder to investigate"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/vpc/"}, "bestPractices": ["Use /16 CIDR for VPCs to allow ample IP space; subdivide into /24 subnets", "Deploy subnets across at least 2 availability zones for high availability", "Separate public subnets (with IGW route) from private subnets (with NAT route)", "Use VPC Flow Logs for network traffic auditing and troubleshooting", "Plan CIDR ranges to avoid overlap when VPC peering or Transit Gateway is needed", "Use separate security groups per tier (web, app, data) with least-privilege rules"], "sdkInitPattern": "aws ec2 create-vpc --cidr-block 10.0.0.0/16 --tag-specifications \"ResourceType=vpc,Tags=[{Key=Name,Value=my-vpc}]\"", "securityGuidance": "Use security groups as stateful firewalls with deny-by-default posture. Add NACLs for subnet-level defense-in-depth. Never open 0.0.0.0/0 on SSH (22) or RDP (3389) in production. Enable VPC Flow Logs to CloudWatch or S3 for audit. Use VPC endpoints (PrivateLink) for AWS service access without traversing the internet. Restrict outbound traffic from private subnets to known destinations.", "commonApiPatterns": [{"name": "Create Subnets", "description": "Create public and private subnets across availability zones", "codeTemplate": "aws ec2 create-subnet --vpc-id vpc-xxx --cidr-block 10.0.1.0/24 --availability-zone us-east-1a --tag-specifications \"ResourceType=subnet,Tags=[{Key=Name,Value=public-1a}]\""}, {"name": "Security Group", "description": "Create security group with ingress rules", "codeTemplate": "aws ec2 create-security-group --group-name web-sg --description \"Web tier\" --vpc-id vpc-xxx && aws ec2 authorize-security-group-ingress --group-id sg-xxx --protocol tcp --port 443 --cidr 0.0.0.0/0"}, {"name": "NAT Gateway", "description": "Create NAT gateway for private subnet internet access", "codeTemplate": "aws ec2 create-nat-gateway --subnet-id subnet-public --allocation-id eipalloc-xxx"}, {"name": "VPC Peering", "description": "Establish VPC peering for cross-VPC communication", "codeTemplate": "aws ec2 create-vpc-peering-connection --vpc-id vpc-requester --peer-vpc-id vpc-accepter --peer-region us-west-2"}], "integrationPatterns": ["Internet Gateway for public subnet internet access", "NAT Gateway in public subnet for private subnet outbound access", "VPC Endpoints (Gateway for S3/DynamoDB, Interface for other AWS services)", "Transit Gateway for hub-and-spoke multi-VPC networking", "AWS PrivateLink for exposing services to other VPCs without peering"], "configurationTemplate": "resource \"aws_vpc\" \"main\" {\\n  cidr_block = \"10.0.0.0/16\"\\n  enable_dns_support = true\\n  enable_dns_hostnames = true\\n}\\nresource \"aws_subnet\" \"public\" {\\n  count = 2\\n  vpc_id = aws_vpc.main.id\\n  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)\\n  map_public_ip_on_launch = true\\n  availability_zone = data.aws_availability_zones.available.names[count.index]\\n}\\nresource \"aws_subnet\" \"private\" {\\n  count = 2\\n  vpc_id = aws_vpc.main.id\\n  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)\\n  availability_zone = data.aws_availability_zones.available.names[count.index]\\n}"}', '[{"kind": "terraform", "path": "infra/vpc/main.tf"}, {"kind": "terraform", "path": "infra/vpc/variables.tf"}, {"kind": "terraform", "path": "infra/vpc/outputs.tf"}]', '{"azCount": {"type": "number", "label": "Availability zones", "default": 2, "description": "2+ for production HA"}, "flowLogs": {"type": "boolean", "label": "VPC flow logs", "default": true, "description": "Network audit trail to CloudWatch/S3"}, "cidrBlock": {"type": "string", "label": "CIDR block", "default": "10.0.0.0/16", "description": "Address space; /16 leaves room for per-AZ subnetting"}, "natGateway": {"type": "enum", "label": "NAT gateway", "default": "single", "options": ["none", "single", "per-az"], "description": "per-az removes the single point of failure; single is cheaper"}, "publicSubnets": {"type": "boolean", "label": "Public subnets", "default": true, "description": "For load balancers / NAT; workloads live in private subnets"}}', '[{"targetRole": "subnet", "contractKind": "sdk"}, {"targetRole": "load-balancer", "contractKind": "sdk"}, {"targetRole": "k8s-cluster", "contractKind": "sdk"}]', false, NULL, NULL, '2026-03-26 14:42:44.780496+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/0'':88C ''/16'':50C ''0.0.0.0'':87C ''10.0.0.0'':49C ''22'':91C ''3389'':94C ''access'':39B,114C ''add'':75C ''address'':32B ''audit'':106C ''aw'':1A,3A,5B,26B,41C,112C ''base'':30B ''block'':48C ''boundari'':12B ''cidr'':29B,47C ''cidr-bas'':28B ''cidr-block'':46C ''cloud'':8B ''cloudwatch'':102C ''control'':40B ''creat'':44C ''create-vpc'':43C ''default'':73C ''defens'':82C ''defense-in-depth'':81C ''deni'':71C ''deny-by-default'':70C ''deploy'':23B ''depth'':84C ''destin'':127C ''ec2'':42C ''enabl'':97C ''endpoint'':109C ''firewal'':68C ''flow'':99C ''group'':65C ''internet'':118C ''ip'':31B ''isol'':10B ''key'':57C ''known'':126C ''level'':80C ''log'':100C ''manag'':33B ''my-vpc'':60C ''nacl'':76C ''name'':58C ''network'':11B,38B ''never'':85C ''open'':86C ''outbound'':120C ''postur'':74C ''privat'':7B,123C ''privatelink'':110C ''product'':96C ''provid'':27B ''rdp'':93C ''resourcetyp'':54C ''restrict'':119C ''role'':20B ''rout'':36B ''s3'':104C ''secur'':64C ''segment'':35B ''servic'':113C ''specif'':53C ''ssh'':90C ''state'':67C ''subnet'':34B,79C,124C ''subnet-level'':78C ''tag'':52C,56C ''tag-specif'':51C ''technolog'':17B ''traffic'':121C ''travers'':116C ''use'':13B,63C,107C ''valu'':59C ''virtual'':6B ''vpc'':2A,4A,19B,45C,55C,62C,98C,108C ''without'':115C');
INSERT INTO public.technology_catalog VALUES ('aws-athena', 'AWS Athena', NULL, '#8C4FFF', '["data-warehouse"]', '{"purpose": "Serverless SQL query engine analyzing data directly in S3 with pay-per-scan pricing", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Trino/Presto SQL", "S3", "Glue Data Catalog", "Parquet", "CTAS transformations"], "antiPatterns": ["Querying raw uncompressed JSON or CSV at scale", "Using SELECT * on wide tables when few columns are needed", "Skipping partitioning on time-series data", "Treating Athena as an OLTP database for point lookups"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/athena/"}, "bestPractices": ["Partition data by the columns most queries filter on", "Convert raw data to Parquet or ORC with compression", "Register schemas in the Glue Data Catalog", "Use CTAS statements for repeatable transformations", "Set per-workgroup scan limits to cap query cost"], "sdkInitPattern": "SELECT date_trunc(month, order_date) AS month, sum(total) AS revenue\nFROM sales_lake.orders\nWHERE year = 2026 AND month >= 1\nGROUP BY 1 ORDER BY 1;", "securityGuidance": "Athena''s reach is S3''s reach: scope the caller''s IAM to the exact buckets/prefixes and Glue catalog databases queried, and lock the query-results bucket down (results inherit the data''s sensitivity — encrypt it and expire objects). Use workgroups to enforce per-team result locations, KMS encryption, and bytes-scanned limits. Parameterize queries built from user input."}', '[{"kind": "config", "path": "infra/aws/athena.tf"}, {"kind": "source", "path": "sql/athena/"}]', '{"workgroup": {"type": "string", "label": "Workgroup", "default": "primary", "description": "Query isolation + per-workgroup cost controls"}, "dataFormats": {"type": "multiselect", "label": "Data formats queried", "options": ["parquet", "orc", "json", "csv", "avro"], "description": "Columnar (parquet/orc) cuts scanned bytes — Athena bills per TB scanned"}, "resultLocation": {"type": "string", "label": "Query result location", "default": "s3://<bucket>/athena-results/", "description": "S3 prefix for query output (required)"}, "partitionProjection": {"type": "boolean", "label": "Partition projection", "default": true, "description": "Derive partitions from templates instead of Glue crawls where layouts are predictable"}}', '[{"id": "aws-s3", "reason": "Data lake storage layer"}, {"id": "aws-glue", "reason": "Schema catalog and ETL"}, {"id": "aws-redshift", "reason": "Complementary warehouse for hot data"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''1'':48C,51C,54C ''2026'':45C ''analyz'':9B ''athena'':2A,4A,55C ''aw'':1A,3A ''bucket'':82C ''buckets/prefixes'':70C ''built'':113C ''byte'':108C ''bytes-scan'':107C ''caller'':64C ''catalog'':25C,73C ''ctas'':27C ''data'':10B,24C,87C ''databas'':74C ''date'':30C,34C ''direct'':11B ''encrypt'':90C,105C ''enforc'':98C ''engin'':8B ''exact'':69C ''expir'':93C ''glue'':23C,72C ''group'':49C ''iam'':66C ''inherit'':85C ''input'':116C ''kms'':104C ''limit'':110C ''locat'':103C ''lock'':77C ''month'':32C,36C,47C ''object'':94C ''order'':33C,52C ''parameter'':111C ''parquet'':26C ''pay'':16B ''pay-per-scan'':15B ''per'':17B,100C ''per-team'':99C ''price'':19B ''queri'':7B,75C,80C,112C ''query-result'':79C ''reach'':57C,61C ''result'':81C,84C,102C ''revenu'':40C ''s3'':13B,22C,59C ''sales_lake.orders'':42C ''scan'':18B,109C ''scope'':62C ''select'':29C ''sensit'':89C ''serverless'':5B ''sql'':6B,21C ''sum'':37C ''team'':101C ''total'':38C ''transform'':28C ''trino/presto'':20C ''trunc'':31C ''use'':95C ''user'':115C ''workgroup'':96C ''year'':44C');
INSERT INTO public.technology_catalog VALUES ('aws-dynamodb', 'AWS DynamoDB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/dynamodb.png', '#4053d6', '["database"]', '{"purpose": "AWS-native serverless NoSQL database delivering single-digit millisecond latency at any scale. Best for AWS-centric architectures with predictable access patterns, serverless billing, and tight Lambda/EventBridge integration. Ideal for session stores, shopping carts, IoT telemetry, and gaming leaderboards. Not suited for complex relational queries or ad-hoc analytics.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS DynamoDB", "DynamoDB Streams", "DAX", "PartiQL", "AWS SDK", "Single-Table Design"], "antiPatterns": ["Hot partition keys causing throttling", "Scanning instead of querying", "Creating a table per entity (relational thinking)", "Choosing DynamoDB when complex joins or ad-hoc queries are required"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/dynamodb/"}, "bestPractices": ["Design partition keys for even data distribution", "Use single-table design patterns for related entities", "Implement GSIs strategically (max 20 per table)", "Use DynamoDB Streams for change data capture", "Enable point-in-time recovery", "Use on-demand billing for unpredictable workloads"], "sdkInitPattern": "import { DynamoDBClient } from ''@aws-sdk/client-dynamodb'';\nimport { DynamoDBDocumentClient, QueryCommand } from ''@aws-sdk/lib-dynamodb'';\n\nconst doc = DynamoDBDocumentClient.from(new DynamoDBClient({}));\nconst { Items } = await doc.send(new QueryCommand({\n  TableName: ''orders'',\n  KeyConditionExpression: ''pk = :pk'',\n  ExpressionAttributeValues: { '':pk'': `USER#${userId}` },\n}));", "securityGuidance": "Key design is access control''s substrate: prefix partition keys by owner (USER#id) and Query, never Scan, in request paths — a Scan bug on a multi-tenant table is a cross-tenant read. IAM can enforce it: dynamodb:LeadingKeys conditions bind a role to its own partitions. Always ExpressionAttributeValues (no string-built expressions), enable PITR on tables you cannot lose, and deletion protection on production tables."}', '[{"kind": "config", "path": "infra/aws/dynamodb.tf"}]', '{"streams": {"type": "boolean", "label": "DynamoDB Streams", "default": false, "description": "Change events for Lambda/Kinesis consumers"}, "tableClass": {"type": "enum", "label": "Table class", "default": "STANDARD", "options": ["STANDARD", "STANDARD_INFREQUENT_ACCESS"], "description": "IA trades storage cost for higher request cost"}, "ttlEnabled": {"type": "boolean", "label": "TTL", "default": false, "description": "Auto-expire items via a timestamp attribute"}, "billingMode": {"type": "enum", "label": "Billing mode", "default": "PAY_PER_REQUEST", "options": ["PAY_PER_REQUEST", "PROVISIONED"], "description": "On-demand per-request pricing vs provisioned capacity units"}, "pointInTimeRecovery": {"type": "boolean", "label": "Point-in-time recovery", "default": true, "description": "Continuous backup (35-day window)"}}', '["backend-service", "serverless-function"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', NULL, '#3344B5', '''/client-dynamodb'':76C ''/lib-dynamodb'':84C ''access'':28B,108C ''ad'':55B ''ad-hoc'':54B ''alway'':155C ''analyt'':57B ''architectur'':25B ''aw'':1A,3A,6B,23B,58C,64C,74C,82C ''await'':92C ''aws-centr'':22B ''aws-nat'':5B ''aws-sdk'':73C,81C ''best'':20B ''bill'':31B ''bind'':148C ''bug'':128C ''built'':160C ''cannot'':167C ''cart'':41B ''centric'':24B ''complex'':50B ''condit'':147C ''const'':85C,90C ''control'':109C ''cross'':138C ''cross-ten'':137C ''databas'':10B ''dax'':62C ''delet'':170C ''deliv'':11B ''design'':69C,106C ''digit'':14B ''doc'':86C ''doc.send'':93C ''dynamodb'':2A,4A,59C,60C,145C ''dynamodbcli'':71C,89C ''dynamodbdocumentcli'':78C ''dynamodbdocumentclient.from'':87C ''enabl'':162C ''enforc'':143C ''express'':161C ''expressionattributevalu'':101C,156C ''game'':45B ''hoc'':56B ''iam'':141C ''id'':118C ''ideal'':36B ''import'':70C,77C ''integr'':35B ''iot'':42B ''item'':91C ''key'':105C,114C ''keyconditionexpress'':98C ''lambda/eventbridge'':34B ''latenc'':16B ''leaderboard'':46B ''leadingkey'':146C ''lose'':168C ''millisecond'':15B ''multi'':132C ''multi-ten'':131C ''nativ'':7B ''never'':121C ''new'':88C,94C ''nosql'':9B ''order'':97C ''owner'':116C ''partiql'':63C ''partit'':113C,154C ''path'':125C ''pattern'':29B ''pitr'':163C ''pk'':99C,100C,102C ''predict'':27B ''prefix'':112C ''product'':173C ''protect'':171C ''queri'':52B,120C ''querycommand'':79C,95C ''read'':140C ''relat'':51B ''request'':124C ''role'':150C ''scale'':19B ''scan'':122C,127C ''sdk'':65C,75C,83C ''serverless'':8B,30B ''session'':38B ''shop'':40B ''singl'':13B,67C ''single-digit'':12B ''single-t'':66C ''store'':39B ''stream'':61C ''string'':159C ''string-built'':158C ''substrat'':111C ''suit'':48B ''tabl'':68C,134C,165C,174C ''tablenam'':96C ''telemetri'':43B ''tenant'':133C,139C ''tight'':33B ''user'':103C,117C ''userid'':104C');
INSERT INTO public.technology_catalog VALUES ('aws-ec2', 'AWS EC2', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/ec2.png', '#ff9900', '["virtual-machine"]', '{"purpose": "AWS Elastic Compute Cloud (EC2) instance providing resizable compute capacity. Use when the architecture requires explicit VM-level visibility for workloads that need full OS control, GPU access, or specific instance types.", "configMode": "declarative", "provenance": {"notes": "Schema kept to stable API surface (instance families, AMI families); full live verify rides 4a-3. Stray id kept; N9b owns the aws-ec2 rename.", "method": "model-knowledge", "sources": ["https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Amazon Linux 2", "Ubuntu", "Docker on EC2", "EBS volumes", "Elastic IP", "Auto Scaling Groups", "Application Load Balancer"], "antiPatterns": ["SSH-ing into production instances instead of using immutable AMI deployments", "Using access keys on instances instead of IAM instance profiles", "Running a single instance without auto-scaling or health checks", "Using IMDSv1 which is vulnerable to SSRF credential theft", "Not encrypting EBS volumes containing sensitive data"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ec2/"}, "bestPractices": ["Use Auto Scaling Groups for high availability", "Place instances in private subnets behind ALB", "Use IAM instance profiles instead of access keys", "Enable detailed monitoring", "Use EBS-optimized instance types", "Tag all resources for cost allocation"], "sdkInitPattern": "aws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.medium --key-name my-key --subnet-id subnet-xxx --security-group-ids sg-xxx --iam-instance-profile Name=my-profile", "securityGuidance": "Never use access keys on instances -- always use IAM instance profiles. Place instances in private subnets and use SSM Session Manager instead of SSH bastion hosts. Apply security groups with least-privilege inbound rules. Enable IMDSv2 (require token-based metadata) to prevent SSRF attacks. Use encrypted EBS volumes. Patch instances via AWS Systems Manager Patch Manager. Disable password-based SSH login.", "commonApiPatterns": [{"name": "Auto Scaling Group", "description": "Create ASG with launch template across multiple AZs behind a target group", "codeTemplate": "aws autoscaling create-auto-scaling-group --auto-scaling-group-name my-asg --launch-template LaunchTemplateId=lt-xxx,Version=$Latest --min-size 2 --max-size 10 --desired-capacity 2 --vpc-zone-identifier \"subnet-a,subnet-b\" --target-group-arns arn:aws:elasticloadbalancing:..."}, {"name": "Launch Template", "description": "Define reusable instance configuration with launch template", "codeTemplate": "aws ec2 create-launch-template --launch-template-name my-lt --launch-template-data ''{\"ImageId\":\"ami-xxx\",\"InstanceType\":\"t3.medium\",\"IamInstanceProfile\":{\"Name\":\"my-profile\"},\"SecurityGroupIds\":[\"sg-xxx\"],\"UserData\":\"...\"}''"}, {"name": "SSM Session", "description": "Connect to instance via Session Manager without SSH keys", "codeTemplate": "aws ssm start-session --target i-xxx"}], "integrationPatterns": ["Application Load Balancer for HTTP/HTTPS traffic distribution", "Auto Scaling Groups for elasticity and high availability", "Systems Manager for patching, session management, and automation", "CloudWatch agent for custom metrics and log collection", "EBS snapshots and AMI pipeline for backup and recovery"], "configurationTemplate": "resource \"aws_launch_template\" \"app\" {\\n  name_prefix   = \"app-\"\\n  image_id      = data.aws_ami.latest.id\\n  instance_type = var.instance_type\\n  iam_instance_profile {\\n    name = aws_iam_instance_profile.app.name\\n  }\\n  vpc_security_group_ids = [aws_security_group.app.id]\\n  user_data = base64encode(templatefile(\"userdata.sh\", {}))\\n}\\nresource \"aws_autoscaling_group\" \"app\" {\\n  min_size         = 2\\n  max_size         = 10\\n  desired_capacity = 2\\n  launch_template {\\n    id      = aws_launch_template.app.id\\n    version = \"$Latest\"\\n  }\\n  vpc_zone_identifier = module.vpc.private_subnets\\n  target_group_arns   = [aws_lb_target_group.app.arn]\\n}"}', '[{"kind": "config", "path": "infra/aws/ec2.tf"}, {"kind": "source", "path": "scripts/user-data.sh"}]', '{"os": {"type": "enum", "label": "Operating system", "default": "amazon-linux-2023", "options": ["amazon-linux-2023", "ubuntu-24.04", "ubuntu-22.04", "debian-12", "windows-server-2022"], "description": "AMI family"}, "spot": {"type": "boolean", "label": "Spot instances", "default": false, "description": "Deeply discounted but interruptible — fault-tolerant workloads only"}, "ebsGb": {"type": "number", "label": "Root EBS volume (GB)", "default": 30}, "publicIp": {"type": "boolean", "label": "Public IP", "default": false, "description": "Prefer private subnets + load balancer / SSM Session Manager access"}, "autoScaling": {"type": "boolean", "label": "Auto Scaling group", "default": false, "description": "Instances managed by an ASG (launch template + scaling policies) rather than standing alone"}, "instanceType": {"type": "string", "label": "Instance type", "default": "t4g.small", "description": "e.g. t4g.small, m7g.large — Graviton (…g) families are cheaper for most workloads"}}', '["load-balancer", "database", "cache", "message-broker", "backend-service"]', false, NULL, NULL, '2026-02-10 22:05:39.905006+00', '2026-08-31 20:06:52.578953+00', NULL, '#CC7A00', '''0abcdef1234567890'':65C ''2'':40C ''access'':33B,99C ''alway'':103C ''amazon'':38C ''ami'':64C ''ami-0abcdef1234567890'':63C ''appli'':123C ''applic'':52C ''architectur'':18B ''attack'':142C ''auto'':49C ''aw'':1A,3A,5B,55C,150C ''balanc'':54C ''base'':137C,158C ''bastion'':121C ''capac'':14B ''cloud'':8B ''comput'':7B,13B ''control'':31B ''disabl'':155C ''docker'':42C ''eb'':45C,145C ''ec2'':2A,4A,9B,44C,56C ''elast'':6B,47C ''enabl'':