INSERT INTO public.technology_catalog VALUES ('aws-ses', 'AWS SES', NULL, '#DD344C', '["external-service"]', '{"purpose": "Managed email service for transactional and bulk sending at high deliverability", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS SDK v3 (@aws-sdk/client-sesv2)", "Nodemailer", "Lambda", "SNS feedback loops", "Configuration Sets"], "antiPatterns": ["Sending from an unverified domain in production", "Ignoring bounce and complaint feedback loops until reputation drops", "Staying in sandbox mode for production workloads", "Hardcoding SMTP credentials instead of using IAM roles"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/ses/"}, "bestPractices": ["Verify sending domains with DKIM, SPF, and DMARC before production traffic", "Use configuration sets to track bounces, complaints, and deliveries", "Route bounce and complaint notifications to SNS and suppress bad addresses", "Request production access early to exit the sandbox", "Warm up sending volume gradually on new domains", "Use SES templates for personalized transactional email"], "sdkInitPattern": "import { SESv2Client, SendEmailCommand } from \"@aws-sdk/client-sesv2\";\nconst ses = new SESv2Client({ region: \"us-east-1\" });\nawait ses.send(new SendEmailCommand({ FromEmailAddress: \"noreply@example.com\", Destination: { ToAddresses: [\"user@example.com\"] }, Content: { Simple: { Subject: { Data: \"Welcome\" }, Body: { Text: { Data: \"Hello\" } } } } }));", "securityGuidance": "Authenticate your domain fully — SPF, DKIM, and a DMARC policy — or deliverability and spoofing-resistance both suffer. Scope ses:SendEmail by identity/from-address conditions so a compromised service cannot send as your whole domain. Process bounces and complaints (SNS destinations) — ignoring them degrades your sender reputation, and never emit user-controlled content unsanitized into HTML mail."}', '[{"kind": "config", "path": "infra/aws/ses.tf"}, {"kind": "source", "path": "emails/templates/"}]', '{"dkim": {"type": "enum", "label": "DKIM", "default": "easy-dkim-2048", "options": ["easy-dkim-2048", "deed", "byodkim"], "description": "Easy DKIM (2048-bit, SES-managed keys) is the default; DEED = deterministic; BYODKIM = your own keys"}, "dedicatedIp": {"type": "enum", "label": "Dedicated IPs", "default": "none", "options": ["none", "standard", "managed"], "description": "Shared IPs until volume warrants it; managed pools auto-scale/warm"}, "configurationSet": {"type": "boolean", "label": "Configuration set", "default": true, "description": "Event destinations (bounces/complaints) + IP-pool association"}, "productionAccess": {"type": "boolean", "label": "Production access", "default": true, "description": "Exit the SES sandbox — a console request; see Manual Steps"}}', '[{"id": "aws-lambda", "reason": "Event-driven email sending"}, {"id": "aws-sns", "reason": "Bounce and complaint notifications"}, {"id": "nodejs", "reason": "Common application runtime"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/client-sesv2'':22C,37C ''1'':46C ''authent'':65C ''aw'':1A,3A,16C,20C,35C ''await'':47C ''aws-sdk'':19C,34C ''bodi'':61C ''bounc'':100C ''bulk'':11B ''cannot'':93C ''complaint'':102C ''compromis'':91C ''condit'':88C ''configur'':28C ''const'':38C ''content'':56C,117C ''control'':116C ''data'':59C,63C ''degrad'':107C ''deliver'':15B,76C ''destin'':53C,104C ''dkim'':70C ''dmarc'':73C ''domain'':67C,98C ''east'':45C ''email'':6B ''emit'':113C ''feedback'':26C ''fromemailaddress'':51C ''fulli'':68C ''hello'':64C ''high'':14B ''html'':120C ''identity/from-address'':87C ''ignor'':105C ''import'':30C ''lambda'':24C ''loop'':27C ''mail'':121C ''manag'':5B ''never'':112C ''new'':40C,49C ''nodemail'':23C ''noreply@example.com'':52C ''polici'':74C ''process'':99C ''region'':42C ''reput'':110C ''resist'':80C ''scope'':83C ''sdk'':17C,21C,36C ''send'':12B,94C ''sendemail'':85C ''sendemailcommand'':32C,50C ''sender'':109C ''servic'':7B,92C ''ses'':2A,4A,39C,84C ''ses.send'':48C ''sesv2client'':31C,41C ''set'':29C ''simpl'':57C ''sns'':25C,103C ''spf'':69C ''spoof'':79C ''spoofing-resist'':78C ''subject'':58C ''suffer'':82C ''text'':62C ''toaddress'':54C ''transact'':9B ''unsanit'':118C ''us'':44C ''us-east'':43C ''user'':115C ''user-control'':114C ''user@example.com'':55C ''v3'':18C ''welcom'':60C ''whole'':97C');
INSERT INTO public.technology_catalog VALUES ('aws-sqs', 'AWS SQS', NULL, '#6b7280', '["queue"]', '{"purpose": "Fully managed message queuing service for decoupling distributed systems. Supports standard (best-effort ordering) and FIFO (exactly-once processing) queue types.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS SDK", "Node.js", "Python", "Lambda triggers"], "antiPatterns": ["Using SQS for real-time communication", "Setting visibility timeout shorter than processing time", "Not handling duplicate messages in standard queues", "Ignoring dead-letter queue messages"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/sqs/"}, "bestPractices": ["Use FIFO queues when message ordering matters", "Configure dead-letter queues for failed messages", "Set appropriate visibility timeout based on processing time", "Use long polling to reduce empty receives and cost", "Batch send/receive/delete operations for throughput"], "sdkInitPattern": "import { SQSClient, SendMessageCommand, ReceiveMessageCommand } from ''@aws-sdk/client-sqs'';\n\nconst sqs = new SQSClient({});\nawait sqs.send(new SendMessageCommand({ QueueUrl: queueUrl, MessageBody: JSON.stringify({ orderId }) }));\nconst { Messages } = await sqs.send(new ReceiveMessageCommand({ QueueUrl: queueUrl, WaitTimeSeconds: 20 }));", "securityGuidance": "Split send from receive in IAM — producers get sqs:SendMessage on their one queue, consumers get Receive/Delete, nobody gets sqs:*. Configure a dead-letter queue with a bounded maxReceiveCount so poison messages surface instead of looping, enable SSE (KMS for cross-service reads), and keep queue policies free of Principal:* — an open queue policy is an open write path into your workers.", "setupInstructions": [{"url": "https://console.aws.amazon.com/sqs/", "type": "dashboard_config", "title": "Create SQS Queue", "required": true, "instructions": "In AWS Console > SQS > Create Queue. Choose Standard (high throughput, at-least-once) or FIFO (exactly-once, ordered). Set visibility timeout to match your expected processing time."}, {"type": "dashboard_config", "title": "Configure Dead-Letter Queue", "required": true, "instructions": "Create a separate DLQ and configure the main queue to send failed messages (after N receive attempts) to the DLQ. Monitor the DLQ for stuck messages."}, {"type": "permissions", "title": "Set IAM Permissions", "required": true, "instructions": "Create an IAM policy granting sqs:SendMessage, sqs:ReceiveMessage, sqs:DeleteMessage, and sqs:GetQueueAttributes on the specific queue ARN. Attach to your application role or user."}, {"type": "environment_variable", "title": "Set Environment Variables", "commands": ["export AWS_SQS_QUEUE_URL=https://sqs.us-east-1.amazonaws.com/123456789/my-queue", "export AWS_REGION=us-east-1", "export AWS_ACCESS_KEY_ID=<from-iam>", "export AWS_SECRET_ACCESS_KEY=<from-iam>"], "required": true, "instructions": "Add SQS queue URL and AWS credentials to your application environment."}]}', '[{"kind": "config", "path": "infra/aws/sqs.tf"}]', '{"queueType": {"type": "enum", "label": "Queue type", "default": "standard", "options": ["standard", "fifo"], "description": "Standard: at-least-once, unlimited throughput; FIFO: exactly-once, ordered"}, "retentionDays": {"type": "number", "label": "Retention (days)", "default": 4, "description": "1-14 days"}, "deadLetterQueue": {"type": "boolean", "label": "Dead-letter queue", "default": true, "description": "Route poison messages after maxReceiveCount"}, "maxReceiveCount": {"type": "number", "label": "Max receives before DLQ", "default": 5}, "visibilityTimeoutSeconds": {"type": "number", "label": "Visibility timeout (s)", "default": 30, "description": "Set >= your consumer''s processing time"}}', '["serverless-function", "worker", "backend-service"]', false, NULL, NULL, '2026-05-18 02:38:14.715381+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/client-sqs'':42C ''20'':65C ''aw'':1A,3A,28C,40C ''await'':47C,58C ''aws-sdk'':39C ''best'':17B ''best-effort'':16B ''bound'':94C ''configur'':86C ''const'':43C,56C ''consum'':80C ''cross'':108C ''cross-servic'':107C ''dead'':89C ''dead-lett'':88C ''decoupl'':11B ''distribut'':12B ''effort'':18B ''enabl'':103C ''exact'':23B ''exactly-onc'':22B ''fifo'':21B ''free'':115C ''fulli'':5B ''get'':73C,81C,84C ''iam'':71C ''import'':34C ''instead'':100C ''json.stringify'':54C ''keep'':112C ''kms'':105C ''lambda'':32C ''letter'':90C ''loop'':102C ''manag'':6B ''maxreceivecount'':95C ''messag'':7B,57C,98C ''messagebodi'':53C ''new'':45C,49C,60C ''nobodi'':83C ''node.js'':30C ''one'':78C ''open'':119C,124C ''order'':19B ''orderid'':55C ''path'':126C ''poison'':97C ''polici'':114C,121C ''princip'':117C ''process'':25B ''produc'':72C ''python'':31C ''queu'':8B ''queue'':26B,79C,91C,113C,120C ''queueurl'':51C,52C,62C,63C ''read'':110C ''receiv'':69C ''receive/delete'':82C ''receivemessagecommand'':37C,61C ''sdk'':29C,41C ''send'':67C ''sendmessag'':75C ''sendmessagecommand'':36C,50C ''servic'':9B,109C ''split'':66C ''sqs'':2A,4A,44C,74C,85C ''sqs.send'':48C,59C ''sqsclient'':35C,46C ''sse'':104C ''standard'':15B ''support'':14B ''surfac'':99C ''system'':13B ''trigger'':33C ''type'':27B ''waittimesecond'':64C ''worker'':129C ''write'':125C');
INSERT INTO public.technology_catalog VALUES ('aws-documentdb', 'AWS DocumentDB', NULL, '#3B48CC', '["database"]', '{"purpose": "Managed MongoDB-compatible document database with replication and automated backups", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["MongoDB drivers", "Mongoose", "TLS connections", "Change streams", "VPC networking"], "antiPatterns": ["Assuming full parity with the latest MongoDB API features", "Connecting without TLS", "Running unindexed queries on large collections", "Exposing the cluster endpoint outside the VPC"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/documentdb/"}, "bestPractices": ["Connect in replica set mode so drivers fail over automatically", "Enforce TLS on all connections", "Create indexes matching real query patterns", "Use change streams for downstream event processing", "Size instances so the working set fits in memory"], "sdkInitPattern": "import { MongoClient } from \"mongodb\";\nconst client = new MongoClient(process.env.DOCDB_URI, { tls: true, replicaSet: \"rs0\", readPreference: \"secondaryPreferred\", retryWrites: false });\nawait client.connect();", "securityGuidance": "Cluster lives in private subnets — there is no public-access mode to misuse, so the risk is your security groups: admit only the app tier. Enforce TLS connections, store the master credential in Secrets Manager with rotation, enable audit logging, and give applications least-privilege database users, not the master."}', '[{"kind": "config", "path": "infra/aws/documentdb.tf"}]', '{"tlsEnabled": {"type": "boolean", "label": "TLS required", "default": true}, "instanceClass": {"type": "string", "label": "Instance class", "default": "db.r6g.large"}, "instanceCount": {"type": "number", "label": "Instances", "default": 2, "description": "2+ for automatic failover"}, "backupRetentionDays": {"type": "number", "label": "Backup retention (days)", "default": 7}}', '[{"id": "mongodb", "reason": "API-compatible migration source"}, {"id": "aws-lambda", "reason": "Serverless data access"}, {"id": "nodejs", "reason": "Common application runtime"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''access'':55C ''admit'':66C ''app'':69C ''applic'':88C ''audit'':84C ''autom'':14B ''aw'':1A,3A ''await'':43C ''backup'':15B ''chang'':21C ''client'':30C ''client.connect'':44C ''cluster'':45C ''compat'':8B ''connect'':20C,73C ''const'':29C ''credenti'':77C ''databas'':10B,92C ''document'':9B ''documentdb'':2A,4A ''driver'':17C ''enabl'':83C ''enforc'':71C ''fals'':42C ''give'':87C ''group'':65C ''import'':25C ''least'':90C ''least-privileg'':89C ''live'':46C ''log'':85C ''manag'':5B,80C ''master'':76C,96C ''misus'':58C ''mode'':56C ''mongocli'':26C,32C ''mongodb'':7B,16C,28C ''mongodb-compat'':6B ''mongoos'':18C ''network'':24C ''new'':31C ''privat'':48C ''privileg'':91C ''process.env.docdb'':33C ''public'':54C ''public-access'':53C ''readprefer'':39C ''replic'':12B ''replicaset'':37C ''retrywrit'':41C ''risk'':61C ''rotat'':82C ''rs0'':38C ''secondarypref'':40C ''secret'':79C ''secur'':64C ''store'':74C ''stream'':22C ''subnet'':49C ''tier'':70C ''tls'':19C,35C,72C ''true'':36C ''uri'':34C ''user'':93C ''vpc'':23C');
INSERT INTO public.technology_catalog VALUES ('aws-amazon-mq', 'AWS MQ', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-amazon-mq.png', '#FF4F8B', '["message-broker"]', '{"purpose": "Amazon MQ is AWS''s managed message broker service for Apache ActiveMQ Classic and RabbitMQ, designed to support industry-standard messaging protocols and ease migration of existing broker-based applications. Use it for enterprise messaging patterns, legacy integration, JMS workloads, and protocol-compatible broker scenarios where off-the-shelf brokers are required. Choose Amazon MQ over Amazon SQS or Amazon SNS when protocol compatibility and broker semantics are necessary, and over self-managed brokers when you want managed operations and patching. Do not use it for hyperscale event streaming, simple cloud-native queueing, or publish-subscribe patterns that fit better with SQS, SNS, or EventBridge.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon MQ", "Amazon ECS", "AWS Lambda", "Amazon CloudWatch", "Amazon EC2", "AWS Secrets Manager", "Amazon VPC"], "antiPatterns": ["Choosing Amazon MQ for simple cloud-native messaging that fits SQS or SNS more naturally", "Treating the broker as a database or long-term analytics store", "Running many unrelated domains through one shared broker without ownership boundaries", "Ignoring protocol, client library, and failover compatibility during migration planning", "Opening broker access broadly instead of using private networking and least privilege", "Using Amazon MQ as a high-throughput streaming backbone instead of dedicated streaming services"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/amazon-mq/"}, "bestPractices": ["Choose the broker engine based on application protocol requirements and migration constraints", "Design broker topology, network placement, and client connection strategy explicitly for availability goals", "Use private networking, encryption, and secret management for broker access in production", "Monitor queue depth, connection counts, disk usage, and broker health continuously", "Separate workloads by broker, virtual host, or environment to reduce blast radius and simplify ownership", "Plan failover, maintenance, and broker upgrades around explicit recovery objectives", "Use Amazon MQ only when broker semantics are actually required rather than by default"], "securityGuidance": "Never enable public accessibility on a broker — private subnets plus security groups admitting only the app tier. Per-service broker users with destination-scoped permissions (ActiveMQ authorization map / RabbitMQ vhosts), credentials in Secrets Manager with rotation, TLS-only listeners, and keep the web console reachable only over VPN/bastion paths — it is a full admin surface.", "configurationTemplate": "# Broker: private subnets, no public accessibility\n# App connects over AMQPS/OpenWire-TLS with per-service credentials\nconst amqp = require(''amqplib'');\nconst conn = await amqp.connect({\n  protocol: ''amqps'', hostname: process.env.MQ_HOST, port: 5671,\n  username: process.env.MQ_USER, password: process.env.MQ_PASS, // from Secrets Manager\n});"}', '[{"kind": "config", "path": "messaging/broker-config.xml", "priority": "essential", "description": "Broker configuration and destination settings for Amazon MQ"}, {"kind": "source", "path": "src/messaging/mq-client.ts", "priority": "recommended", "description": "Application client configuration for connecting to Amazon MQ brokers"}, {"kind": "config", "path": "infra/amazon-mq.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for Amazon MQ brokers, networking, and maintenance settings"}]', '{"engineType": {"type": "string", "label": "Engine Type", "default": "rabbitmq", "options": ["rabbitmq", "activemq"], "description": "Managed broker engine used by Amazon MQ"}, "privateAccess": {"type": "boolean", "label": "Private Access", "default": true, "description": "Restrict broker access through private networking controls"}, "deploymentMode": {"type": "string", "label": "Deployment Mode", "default": "multi-az", "options": ["single-instance", "multi-az"], "description": "Availability model for the managed broker"}}', '["worker", "backend-service", "monitoring", "auth-provider", "subnet"]', false, NULL, NULL, '2026-03-14 21:45:27.163157+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''access'':136C ''activemq'':17B,160C ''admin'':189C ''admit'':145C ''amazon'':4A,6B,63B,66B,69B,118C,120C,124C,126C,131C ''apach'':16B ''app'':148C ''applic'':37B ''author'':161C ''aw'':1A,3A,9B,122C,128C ''base'':36B ''better'':112B ''broker'':13B,35B,52B,59B,75B,84B,139C,153C ''broker-bas'':34B ''choos'':62B ''classic'':18B ''cloud'':102B ''cloud-nat'':101B ''cloudwatch'':125C ''compat'':51B,73B ''consol'':179C ''credenti'':165C ''design'':21B ''destin'':157C ''destination-scop'':156C ''eas'':30B ''ec'':121C ''ec2'':127C ''enabl'':134C ''enterpris'':41B ''event'':98B ''eventbridg'':117B ''exist'':33B ''fit'':111B ''full'':188C ''group'':144C ''hyperscal'':97B ''industri'':25B ''industry-standard'':24B ''integr'':45B ''jms'':46B ''keep'':176C ''lambda'':123C ''legaci'':44B ''listen'':174C ''manag'':11B,83B,88B,130C,168C ''map'':162C ''messag'':12B,27B,42B ''migrat'':31B ''mq'':2A,5A,7B,64B,119C ''nativ'':103B ''necessari'':78B ''never'':133C ''off-the-shelf'':55B ''oper'':89B ''patch'':91B ''path'':184C ''pattern'':43B,109B ''per'':151C ''per-servic'':150C ''permiss'':159C ''plus'':142C ''privat'':140C ''protocol'':28B,50B,72B ''protocol-compat'':49B ''public'':135C ''publish'':107B ''publish-subscrib'':106B ''queue'':104B ''rabbitmq'':20B,163C ''reachabl'':180C ''requir'':61B ''rotat'':170C ''scenario'':53B ''scope'':158C ''secret'':129C,167C ''secur'':143C ''self'':82B ''self-manag'':81B ''semant'':76B ''servic'':14B,152C ''shelf'':58B ''simpl'':100B ''sns'':70B,115B ''sqs'':67B,114B ''standard'':26B ''stream'':99B ''subnet'':141C ''subscrib'':108B ''support'':23B ''surfac'':190C ''tier'':149C ''tls'':172C ''tls-on'':171C ''use'':38B,94B ''user'':154C ''vhost'':164C ''vpc'':132C ''vpn/bastion'':183C ''want'':87B ''web'':178C ''workload'':47B');
INSERT INTO public.technology_catalog VALUES ('aws-step-functions', 'AWS Step Functions', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-step-functions.png', '#FF4F8B', '["worker", "scheduled-trigger"]', '{"purpose": "AWS serverless workflow orchestration service for coordinating distributed applications using visual state machines. Express Workflows handle high-volume short-duration tasks; Standard Workflows support long-running processes up to one year. Best for multi-step business processes, ETL orchestration, order processing pipelines, and human approval workflows. Use Step Functions over SQS chains when you need visual workflow definition, built-in error handling with retries and catch blocks, and parallel execution branches.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using Standard Workflows for high-volume, short tasks (expensive; use Express)", "Wrapping simple AWS API calls in Lambda functions instead of using SDK integrations", "Not designing idempotent tasks causing duplicate processing on retries", "Creating monolithic state machines instead of composing nested workflows", "Exceeding payload size limits (256KB) by passing large data between states"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/step-functions/"}, "bestPractices": ["Use Express Workflows for high-volume, short-duration workflows (< 5 minutes)", "Use Standard Workflows for long-running processes needing exactly-once execution", "Use SDK integrations (200+ AWS services) instead of Lambda for simple API calls", "Design idempotent task states for safe retries", "Use Map state for parallel processing of collections", "Include Catch blocks for error handling at each critical step"], "securityGuidance": "The state machine''s execution role is the union of everything it can invoke — scope it to the exact Lambda/SQS/service ARNs in the definition, one role per state machine. Execution history records every state''s full input and output within retention: payloads carry references, not secrets or raw PII. Model failure explicitly (Retry with backoff, Catch to compensation states) and make tasks idempotent — Standard workflows retry, and StartExecution callers can resubmit; use the execution-name idempotency key for exactly-once starts.", "configurationTemplate": "{\n  \"Comment\": \"Order fulfillment\",\n  \"StartAt\": \"Charge\",\n  \"States\": {\n    \"Charge\": {\n      \"Type\": \"Task\",\n      \"Resource\": \"arn:aws:states:::lambda:invoke\",\n      \"Parameters\": { \"FunctionName\": \"charge\", \"Payload.$\": \"$\" },\n      \"Retry\": [{ \"ErrorEquals\": [\"States.TaskFailed\"], \"MaxAttempts\": 2, \"BackoffRate\": 2 }],\n      \"Catch\": [{ \"ErrorEquals\": [\"States.ALL\"], \"Next\": \"Refund\" }],\n      \"Next\": \"Fulfill\"\n    },\n    \"Fulfill\": { \"Type\": \"Task\", \"Resource\": \"arn:aws:states:::sqs:sendMessage\", \"Parameters\": { \"QueueUrl\": \"...\", \"MessageBody.$\": \"$\" }, \"End\": true },\n    \"Refund\": { \"Type\": \"Task\", \"Resource\": \"arn:aws:states:::lambda:invoke\", \"Parameters\": { \"FunctionName\": \"refund\" }, \"End\": true }\n  }\n}"}', '[{"kind": "config", "path": "state-machine.asl.json", "priority": "essential", "description": "Amazon States Language state machine definition"}, {"kind": "source", "path": "src/workflows/tasks/", "priority": "essential", "description": "Step Functions task implementations"}, {"kind": "config", "path": "terraform/step-functions.tf", "priority": "recommended", "description": "Step Functions infrastructure definition"}]', '{"loggingLevel": {"enum": ["ALL", "ERROR", "FATAL", "OFF"], "type": "string", "label": "Logging Level", "default": "ERROR"}, "workflowType": {"enum": ["standard", "express"], "type": "string", "label": "Workflow Type", "default": "standard"}}', '["serverless-function", "database", "message-broker", "rest-api"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''applic'':15B ''approv'':55B ''arn'':103C ''aw'':1A,4A,7B ''backoff'':137C ''best'':41B ''block'':78B ''branch'':82B ''built'':70B ''built-in'':69B ''busi'':46B ''caller'':151C ''carri'':125C ''catch'':77B,138C ''chain'':62B ''compens'':140C ''coordin'':13B ''definit'':68B,106C ''distribut'':14B ''durat'':28B ''error'':72B ''etl'':48B ''everi'':115C ''everyth'':93C ''exact'':101C,163C ''exactly-onc'':162C ''execut'':81B,87C,112C,157C ''execution-nam'':156C ''explicit'':134C ''express'':20B ''failur'':133C ''full'':118C ''function'':3A,6A,59B ''handl'':22B,73B ''high'':24B ''high-volum'':23B ''histori'':113C ''human'':54B ''idempot'':145C,159C ''input'':119C ''invok'':96C ''key'':160C ''lambda/sqs/service'':102C ''long'':34B ''long-run'':33B ''machin'':19B,85C,111C ''make'':143C ''model'':132C ''multi'':44B ''multi-step'':43B ''name'':158C ''need'':65B ''one'':39B,107C ''orchestr'':10B,49B ''order'':50B ''output'':121C ''parallel'':80B ''payload'':124C ''per'':109C ''pii'':131C ''pipelin'':52B ''process'':36B,47B,51B ''raw'':130C ''record'':114C ''refer'':126C ''resubmit'':153C ''retent'':123C ''retri'':75B,135C,148C ''role'':88C,108C ''run'':35B ''scope'':97C ''secret'':128C ''serverless'':8B ''servic'':11B ''short'':27B ''short-dur'':26B ''sqs'':61B ''standard'':30B,146C ''start'':165C ''startexecut'':150C ''state'':18B,84C,110C,116C,141C ''step'':2A,5A,45B,58B ''support'':32B ''task'':29B,144C ''union'':91C ''use'':16B,57B,154C ''visual'':17B,66B ''volum'':25B ''within'':122C ''workflow'':9B,21B,31B,56B,67B,147C ''year'':40B');
INSERT INTO public.technology_catalog VALUES ('kotlin-backend', 'Kotlin (Backend)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kotlin-android.png', '#7F52FF', '["backend-service", "worker", "webhook-handler"]', '{"purpose": "Modern JVM language combining conciseness and safety for building backend services with coroutines-first concurrency and full Java interoperability", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Kotlin 2.0+", "Ktor", "Spring Boot", "Exposed/Ktorm", "Coroutines", "Koin/Hilt", "Gradle Kotlin DSL", "kotest"], "antiPatterns": ["Using GlobalScope for coroutine launches", "Not using structured concurrency", "Overusing nullable types when non-null is appropriate", "Ignoring Kotlin idioms and writing Java-style code", "Not cancelling coroutine scopes properly", "Using mutable collections when immutable ones suffice"], "apiReference": {"docsUrl": "https://kotlinlang.org/docs/"}, "bestPractices": ["Use Kotlin coroutines for async and concurrent programming", "Leverage data classes for DTOs and domain models", "Use sealed classes for exhaustive state modeling", "Implement dependency injection with Koin or Spring", "Use Ktor for lightweight, coroutine-native HTTP services", "Leverage extension functions for clean API design", "Use Flow for reactive streams", "Write tests with kotest and MockK"], "sdkInitPattern": "fun main() {\n    embeddedServer(Netty, port = 8080) {\n        install(ContentNegotiation) { json() }\n        install(Authentication) { jwt { /* verifier + validate */ } }\n        routing {\n            authenticate {\n                get(\"/api/orders\") {\n                    val userId = call.principal<JWTPrincipal>()!!.subject\n                    call.respond(orderService.listFor(userId))\n                }\n            }\n        }\n    }.start(wait = true)\n}", "securityGuidance": "Type safety is not input safety: validate and bound request payloads at the boundary (kotlinx.serialization with explicit models), scope every data access by the authenticated principal, and use parameterized queries through Exposed/JDBC — string templates into SQL are injection with nicer syntax. Coroutine contexts must not smuggle authority across requests (never cache a principal in a shared scope), secrets resolve from environment config, and the JVM supply-chain discipline applies: scanned, pinned dependencies."}', '[{"kind": "source", "path": "src/main/kotlin/Application.kt", "language": "kotlin", "description": "Application entry point"}, {"kind": "source", "path": "src/main/kotlin/routes/Routes.kt", "language": "kotlin", "description": "Route definitions"}, {"kind": "config", "path": "build.gradle.kts", "language": "kotlin", "description": "Gradle Kotlin DSL build file"}, {"kind": "config", "path": "src/main/resources/application.conf", "language": "hocon", "description": "Ktor/application configuration"}]', '{"buildTool": {"type": "enum", "label": "Build tool", "default": "gradle-kotlin-dsl", "options": ["gradle-kotlin-dsl", "maven"]}, "framework": {"type": "enum", "label": "Framework", "default": "spring-boot", "options": ["spring-boot", "ktor"], "description": "Spring Boot for teams on the Spring ecosystem; Ktor for Kotlin-native coroutine-first services"}}', '["database", "cache", "message-broker"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-31 20:06:52.233344+00', 'Kotlin', NULL, '''/api/orders'':54C ''2.0'':26C ''8080'':42C ''access'':86C ''across'':112C ''appli'':134C ''authent'':47C,52C,89C ''author'':111C ''backend'':2A,4A,14B ''boot'':29C ''bound'':73C ''boundari'':78C ''build'':13B ''cach'':115C ''call.principal'':57C ''call.respond'':59C ''chain'':132C ''combin'':8B ''concis'':9B ''concurr'':20B ''config'':126C ''contentnegoti'':44C ''context'':107C ''coroutin'':18B,31C,106C ''coroutines-first'':17B ''data'':85C ''depend'':137C ''disciplin'':133C ''dsl'':35C ''embeddedserv'':39C ''environ'':125C ''everi'':84C ''explicit'':81C ''exposed/jdbc'':96C ''exposed/ktorm'':30C ''first'':19B ''full'':22B ''fun'':37C ''get'':53C ''gradl'':33C ''inject'':102C ''input'':69C ''instal'':43C,46C ''interoper'':24B ''java'':23B ''json'':45C ''jvm'':6B,129C ''jwt'':48C ''koin/hilt'':32C ''kotest'':36C ''kotlin'':1A,3A,25C,34C ''kotlinx.serialization'':79C ''ktor'':27C ''languag'':7B ''main'':38C ''model'':82C ''modern'':5B ''must'':108C ''netti'':40C ''never'':114C ''nicer'':104C ''orderservice.listfor'':60C ''parameter'':93C ''payload'':75C ''pin'':136C ''port'':41C ''princip'':90C,117C ''queri'':94C ''request'':74C,113C ''resolv'':123C ''rout'':51C ''safeti'':11B,66C,70C ''scan'':135C ''scope'':83C,121C ''secret'':122C ''servic'':15B ''share'':120C ''smuggl'':110C ''spring'':28C ''sql'':100C ''start'':62C ''string'':97C ''subject'':58C ''suppli'':131C ''supply-chain'':130C ''syntax'':105C ''templat'':98C ''true'':64C ''type'':65C ''use'':92C ''userid'':56C,61C ''val'':55C ''valid'':50C,71C ''verifi'':49C ''wait'':63C');
INSERT INTO public.technology_catalog VALUES ('aws-elasticache', 'AWS ElastiCache', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/elasticache.png', '#c7131f', '["cache"]', '{"purpose": "Fully managed in-memory cache compatible with Valkey, Redis OSS, and Memcached. Use for microsecond-latency reads, session storage, hot-key lookups, rate limiting, and taking read pressure off the primary database. Serverless mode removes capacity management; node-based clusters give fine-grained control over node types and placement. Valkey is the forward path (open-source Redis successor); prefer it for new workloads.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Caching without an invalidation story (stale reads become correctness bugs)", "Using the cache as a durable store or queue", "One giant shared cache for unrelated workloads — blast radius and noisy neighbors", "Skipping AUTH/encryption on caches holding user data"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/elasticache/"}, "bestPractices": ["Prefer serverless for new workloads — instant scaling, no node management", "Choose Valkey over Redis OSS for new caches (open governance, lower cost on ElastiCache)", "Set TTLs on every key class — an unbounded cache is a memory leak with latency", "Use cluster mode / multi-AZ for anything a cache outage would take down", "Never treat the cache as a source of truth — rebuildable from the database by design"], "sdkInitPattern": "import { createClient } from ''redis'';\n\nconst redis = createClient({\n  url: `rediss://${process.env.ELASTICACHE_ENDPOINT}:6379`,\n  password: process.env.ELASTICACHE_AUTH, // AUTH token from Secrets Manager\n});\nawait redis.connect();", "securityGuidance": "Private subnets and security groups admitting only the app tier — ElastiCache has no business near an internet path. Enable in-transit encryption + AUTH (or RBAC user groups on Redis 6+, scoping commands and key patterns per service), at-rest encryption for regulated data, and never park secrets, tokens, or session-embedded PII as cache values — the cache inherits none of your database''s audit story."}', '[{"kind": "config", "path": "infra/aws/elasticache.tf"}]', '{"engine": {"type": "enum", "label": "Engine", "default": "valkey", "options": ["valkey", "redis-oss", "memcached"], "description": "Valkey is the forward path; Redis OSS for legacy compatibility; Memcached for simple multi-threaded caching"}, "multiAz": {"type": "boolean", "label": "Multi-AZ", "default": true, "description": "Automatic failover for node-based clusters"}, "nodeType": {"type": "string", "label": "Node type (node-based)", "default": "cache.r7g.large", "description": "Node-based only; Graviton (…g) classes are cheaper"}, "deployment": {"type": "enum", "label": "Deployment", "default": "serverless", "options": ["serverless", "node-based"], "description": "Serverless: zero capacity management; node-based: control node type/count/placement"}, "defaultTtlSeconds": {"type": "number", "label": "Default TTL (s)", "default": 3600, "description": "Baseline expiry for cached entries"}}', '["backend-service", "worker", "serverless-function"]', false, NULL, NULL, '2026-08-31 20:06:50.060304+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''6'':125C ''6379'':84C ''admit'':100C ''app'':103C ''at-rest'':133C ''audit'':161C ''auth'':87C,88C,118C ''aw'':1A,3A ''await'':93C ''base'':47B ''busi'':108C ''cach'':10B,151C,154C ''capac'':43B ''cluster'':48B ''command'':127C ''compat'':11B ''const'':78C ''control'':53B ''createcli'':75C,80C ''data'':139C ''databas'':39B,159C ''elasticach'':2A,4A,105C ''embed'':148C ''enabl'':113C ''encrypt'':117C,136C ''endpoint'':83C ''fine'':51B ''fine-grain'':50B ''forward'':62B ''fulli'':5B ''give'':49B ''grain'':52B ''group'':99C,122C ''hot'':27B ''hot-key'':26B ''import'':74C ''in-memori'':7B ''in-transit'':114C ''inherit'':155C ''internet'':111C ''key'':28B,129C ''latenc'':22B ''limit'':31B ''lookup'':29B ''manag'':6B,44B,92C ''memcach'':17B ''memori'':9B ''microsecond'':21B ''microsecond-lat'':20B ''mode'':41B ''near'':109C ''never'':141C ''new'':72B ''node'':46B,55B ''node-bas'':45B ''none'':156C ''open'':65B ''open-sourc'':64B ''oss'':15B ''park'':142C ''password'':85C ''path'':63B,112C ''pattern'':130C ''per'':131C ''pii'':149C ''placement'':58B ''prefer'':69B ''pressur'':35B ''primari'':38B ''privat'':95C ''process.env.elasticache'':82C,86C ''rate'':30B ''rbac'':120C ''read'':23B,34B ''redi'':14B,67B,77C,79C,124C ''redis.connect'':94C ''regul'':138C ''remov'':42B ''rest'':135C ''scope'':126C ''secret'':91C,143C ''secur'':98C ''serverless'':40B ''servic'':132C ''session'':24B,147C ''session-embed'':146C ''sourc'':66B ''storag'':25B ''stori'':162C ''subnet'':96C ''successor'':68B ''take'':33B ''tier'':104C ''token'':89C,144C ''transit'':116C ''type'':56B ''url'':81C ''use'':18B ''user'':121C ''valkey'':13B,59B ''valu'':152C ''workload'':73B');
INSERT INTO public.technology_catalog VALUES ('aws-neptune', 'AWS Neptune', NULL, '#3B48CC', '["graph-db"]', '{"purpose": "Managed graph database supporting Gremlin, openCypher, and SPARQL workloads", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Gremlin", "openCypher", "SPARQL", "Neptune bulk loader", "Neptune ML"], "antiPatterns": ["Using a graph database for simple relational lookups", "Running unbounded traversals across the full graph", "Loading large datasets through individual inserts instead of the bulk loader"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/neptune/"}, "bestPractices": ["Model access patterns before choosing property graph versus RDF", "Use the S3 bulk loader for initial data ingest", "Send read-heavy traversals to read replicas", "Keep traversals bounded with limits and depth caps", "Use parameterized queries to enable plan caching"], "sdkInitPattern": "import { driver, process as gprocess } from \"gremlin\";\nconst g = gprocess.AnonymousTraversalSource.traversal().withRemote(new driver.DriverRemoteConnection(\"wss://my-cluster.cluster-xyz.us-east-1.neptune.amazonaws.com:8182/gremlin\"));", "securityGuidance": "Private subnets and security groups only — Neptune has no public endpoint mode. Enforce IAM database authentication (SigV4-signed requests) for applications, TLS in transit, KMS at rest, and audit logs on. Gremlin/SPARQL queries built from user input need the same injection discipline as SQL."}', '[{"kind": "config", "path": "infra/aws/neptune.tf"}]', '{"iamAuth": {"type": "boolean", "label": "IAM database auth", "default": true}, "replicaCount": {"type": "number", "label": "Read replicas", "default": 1}, "instanceClass": {"type": "string", "label": "Instance class", "default": "db.r6g.large"}, "queryLanguage": {"type": "enum", "label": "Query language", "default": "opencypher", "options": ["gremlin", "opencypher", "sparql"], "description": "Neptune speaks all three over the same graph"}}', '[{"id": "aws-s3", "reason": "Bulk load data source"}, {"id": "aws-lambda", "reason": "Query layer"}, {"id": "aws-sagemaker", "reason": "Neptune ML integration"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/gremlin'':37C ''applic'':59C ''audit'':67C ''authent'':53C ''aw'':1A,3A ''built'':72C ''bulk'':18C ''const'':29C ''databas'':7B,52C ''disciplin'':80C ''driver'':23C ''driver.driverremoteconnection'':34C ''endpoint'':48C ''enforc'':50C ''g'':30C ''gprocess'':26C ''gprocess.anonymoustraversalsource.traversal'':31C ''graph'':6B ''gremlin'':9B,14C,28C ''gremlin/sparql'':70C ''group'':42C ''iam'':51C ''import'':22C ''inject'':79C ''input'':75C ''kms'':63C ''loader'':19C ''log'':68C ''manag'':5B ''ml'':21C ''mode'':49C ''my-cluster.cluster-xyz.us-east-1.neptune.amazonaws.com:8182'':36C ''my-cluster.cluster-xyz.us-east-1.neptune.amazonaws.com:8182/gremlin'':35C ''need'':76C ''neptun'':2A,4A,17C,20C,44C ''new'':33C ''opencyph'':10B,15C ''privat'':38C ''process'':24C ''public'':47C ''queri'':71C ''request'':57C ''rest'':65C ''secur'':41C ''sign'':56C ''sigv4'':55C ''sigv4-signed'':54C ''sparql'':12B,16C ''sql'':82C ''subnet'':39C ''support'':8B ''tls'':60C ''transit'':62C ''user'':74C ''withremot'':32C ''workload'':13B');
INSERT INTO public.technology_catalog VALUES ('aws-glue', 'AWS Glue', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-glue.png', '#8C4FFF', '["ml-pipeline", "worker"]', '{"purpose": "Serverless data integration service for discovering, preparing, moving, and integrating data from multiple sources. Provides a Data Catalog (Hive-compatible metastore), visual and code-based ETL job authoring (PySpark/Python), crawlers for automatic schema discovery, and DataBrew for no-code data preparation. Best for building data lakes and ETL pipelines feeding into Redshift, S3, or analytics services.", "configMode": "code", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Running Glue jobs on small datasets where Lambda would be simpler and cheaper", "Not using bookmarks causing full re-processing on every run", "Writing deeply nested PySpark without testing locally first", "Not partitioning output data in S3"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/glue/"}, "bestPractices": ["Use Glue crawlers to automatically discover and catalog schemas in S3", "Use bookmarks to process only new/changed data on subsequent runs", "Partition data in S3 by date or category for efficient query pruning", "Use Glue Studio visual editor for simple transformations before writing code", "Enable job metrics in CloudWatch for monitoring and optimization", "Use Glue Data Quality to validate data before loading into targets"], "sdkInitPattern": "# Glue job script boilerplate (PySpark)\r\nimport sys\r\nfrom awsglue.utils import getResolvedOptions\r\nfrom awsglue.context import GlueContext\r\nfrom pyspark.context import SparkContext\r\n\r\nargs = getResolvedOptions(sys.argv, [''JOB_NAME''])\r\nglue_context = GlueContext(SparkContext.getOrCreate())\r\nspark = glue_context.spark_session", "securityGuidance": "One IAM role per job, scoped to exactly the S3 paths and catalog databases it touches — a shared broad Glue role turns every job into every job''s blast radius. Pass credentials via Glue connections or Secrets Manager, never job parameters (they are visible in the console and API). Enable encryption for S3 targets, job bookmarks, and CloudWatch logs, and govern table access through Lake Formation grants where it is in play."}', '[{"kind": "config", "path": "terraform/glue.tf", "priority": "recommended", "description": "Glue jobs, crawlers, and catalog definitions"}, {"kind": "source", "path": "etl/glue-job.py", "priority": "required", "description": "PySpark ETL job script"}, {"kind": "schema", "path": "etl/glue-schema.json", "priority": "recommended", "description": "Data catalog schema definition"}]', '{"workerType": {"type": "string", "label": "Worker Type", "default": "G.1X"}, "glueVersion": {"type": "string", "label": "Glue Version", "default": "4.0"}, "bookmarkEnabled": {"type": "boolean", "label": "Job Bookmark", "default": true}, "numberOfWorkers": {"type": "number", "label": "Number of Workers", "default": 2}}', '["object-storage", "database", "event-stream", "ml-pipeline"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''access'':157C ''analyt'':62B ''api'':143C ''arg'':83C ''author'':34B ''automat'':38B ''aw'':1A,3A ''awsglue.context'':76C ''awsglue.utils'':72C ''base'':31B ''best'':49B ''blast'':123C ''boilerpl'':67C ''bookmark'':150C ''broad'':113C ''build'':51B ''catalog'':22B,107C ''cloudwatch'':152C ''code'':30B,46B ''code-bas'':29B ''compat'':25B ''connect'':129C ''consol'':141C ''context'':89C ''crawler'':36B ''credenti'':126C ''data'':6B,15B,21B,47B,52B ''databas'':108C ''databrew'':42B ''discov'':10B ''discoveri'':40B ''enabl'':144C ''encrypt'':145C ''etl'':32B,55B ''everi'':117C,120C ''exact'':102C ''feed'':57B ''format'':160C ''getresolvedopt'':74C,84C ''glue'':2A,4A,64C,88C,114C,128C ''glue_context.spark'':93C ''gluecontext'':78C,90C ''govern'':155C ''grant'':161C ''hive'':24B ''hive-compat'':23B ''iam'':96C ''import'':69C,73C,77C,81C ''integr'':7B,14B ''job'':33B,65C,86C,99C,118C,121C,134C,149C ''lake'':53B,159C ''log'':153C ''manag'':132C ''metastor'':26B ''move'':12B ''multipl'':17B ''name'':87C ''never'':133C ''no-cod'':44B ''one'':95C ''paramet'':135C ''pass'':125C ''path'':105C ''per'':98C ''pipelin'':56B ''play'':166C ''prepar'':11B,48B ''provid'':19B ''pyspark'':68C ''pyspark.context'':80C ''pyspark/python'':35B ''radius'':124C ''redshift'':59B ''role'':97C,115C ''s3'':60B,104C,147C ''schema'':39B ''scope'':100C ''script'':66C ''secret'':131C ''serverless'':5B ''servic'':8B,63B ''session'':94C ''share'':112C ''sourc'':18B ''spark'':92C ''sparkcontext'':82C ''sparkcontext.getorcreate'':91C ''sys'':70C ''sys.argv'':85C ''tabl'':156C ''target'':148C ''touch'':110C ''turn'':116C ''via'':127C ''visibl'':138C ''visual'':27B');
INSERT INTO public.technology_catalog VALUES ('aws-msk', 'AWS MSK', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-msk.png', '#FF9900', '["event-stream", "message-broker"]', '{"purpose": "Fully managed Apache Kafka service that handles broker provisioning, patching, and cluster operations. MSK Serverless automatically provisions and scales capacity. Compatible with existing Kafka applications and tools including Kafka Connect, MirrorMaker, and Schema Registry. Best for organizations already invested in the Kafka ecosystem that want managed infrastructure.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using MSK Provisioned with fixed capacity for highly variable workloads", "Not enabling encryption in transit between clients and brokers", "Using a single broker or single AZ for production workloads", "Not setting topic-level retention policies causing unbounded storage growth"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/msk/"}, "bestPractices": ["Use MSK Serverless for variable or unpredictable workloads", "Enable TLS encryption in transit and at-rest encryption with KMS", "Use IAM authentication instead of SASL/SCRAM for simplified access control", "Configure multi-AZ deployment with minimum 3 brokers for production", "Use tiered storage for cost-effective long-term data retention", "Monitor with CloudWatch enhanced monitoring and open monitoring with Prometheus"], "securityGuidance": "Use IAM authentication (SASL_SSL) and turn OFF unauthenticated cluster access — an open Kafka listener inside a shared VPC is an open data plane. Author kafka-cluster IAM policies per principal down to topic granularity (WriteData on its topics, ReadData on its groups), keep brokers in private subnets with tight security groups, and encrypt in transit between clients AND between brokers.", "configurationTemplate": "# client.properties — IAM auth over TLS\nsecurity.protocol=SASL_SSL\nsasl.mechanism=AWS_MSK_IAM\nsasl.jaas.config=software.amazon.msk.auth.iam.IAMLoginModule required;\nsasl.client.callback.handler.class=software.amazon.msk.auth.iam.IAMClientCallbackHandler"}', '[{"kind": "config", "path": "terraform/msk.tf", "priority": "recommended", "description": "MSK cluster configuration and security settings"}, {"kind": "source", "path": "kafka/producer.ts", "priority": "recommended", "description": "Kafka producer client"}, {"kind": "source", "path": "kafka/consumer.ts", "priority": "recommended", "description": "Kafka consumer client"}]', '{"serverless": {"type": "boolean", "label": "Serverless Mode", "default": false}, "kafkaVersion": {"type": "string", "label": "Kafka Version", "default": "3.6.0"}, "encryptionInTransit": {"type": "boolean", "label": "TLS Encryption", "default": true}, "numberOfBrokerNodes": {"type": "number", "label": "Broker Nodes", "default": 3}}', '["backend-service", "worker", "serverless-function", "monitoring"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''access'':62C ''alreadi'':42B ''apach'':7B ''applic'':29B ''authent'':54C ''author'':76C ''automat'':20B ''aw'':1A,3A ''best'':39B ''broker'':12B,97C,113C ''capac'':24B ''client'':110C ''cluster'':16B,61C,79C ''compat'':25B ''connect'':34B ''data'':74C ''ecosystem'':47B ''encrypt'':106C ''exist'':27B ''fulli'':5B ''granular'':87C ''group'':95C,104C ''handl'':11B ''iam'':53C,80C ''includ'':32B ''infrastructur'':51B ''insid'':67C ''invest'':43B ''kafka'':8B,28B,33B,46B,65C,78C ''kafka-clust'':77C ''keep'':96C ''listen'':66C ''manag'':6B,50B ''mirrormak'':35B ''msk'':2A,4A,18B ''open'':64C,73C ''oper'':17B ''organ'':41B ''patch'':14B ''per'':82C ''plane'':75C ''polici'':81C ''princip'':83C ''privat'':99C ''provis'':13B,21B ''readdata'':92C ''registri'':38B ''sasl'':55C ''scale'':23B ''schema'':37B ''secur'':103C ''serverless'':19B ''servic'':9B ''share'':69C ''ssl'':56C ''subnet'':100C ''tight'':102C ''tool'':31B ''topic'':86C,91C ''transit'':108C ''turn'':58C ''unauthent'':60C ''use'':52C ''vpc'':70C ''want'':49B ''writedata'':88C');
INSERT INTO public.technology_catalog VALUES ('aws-emr', 'AWS EMR', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-emr.png', '#8C4FFF', '["worker", "ml-pipeline"]', '{"purpose": "Managed big data platform for running Apache Spark, Hive, Presto, HBase, and other open-source frameworks on scalable EC2 clusters or EKS. EMR Serverless auto-scales without cluster management. Best for large-scale data processing, machine learning training, real-time analytics, and genomics workloads that require open-source framework flexibility.", "configMode": "declarative", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Running persistent clusters for batch workloads that could use transient clusters", "Storing processing data on HDFS instead of S3", "Not using Spot Instances for fault-tolerant task nodes", "Over-provisioning cluster size instead of relying on auto-scaling"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/emr/"}, "bestPractices": ["Use EMR Serverless for intermittent workloads to eliminate idle cluster costs", "Use Spot Instances for task nodes to reduce costs by up to 90%", "Store data in S3 rather than HDFS for durability and decoupled compute/storage", "Use EMR on EKS to share Kubernetes infrastructure with other workloads", "Enable auto-scaling with managed scaling policies", "Use EMR Studio notebooks for interactive development and debugging"], "securityGuidance": "Turn on EMR block public access (a public master node is a public Spark shell) and keep clusters in private subnets. The EC2 instance profile is what every job on the cluster can reach — scope it to the input/output buckets, and use runtime roles (per-job IAM) where teams share a cluster so one job cannot read another''s data. Security configurations own encryption in transit and at rest; auto-terminate transient clusters (an idle cluster is idle attack surface plus idle spend), and treat bootstrap actions as root-on-every-node code review.", "configurationTemplate": "aws emr create-cluster --name etl --release-label emr-7.5.0 \\\n  --applications Name=Spark \\\n  --service-role EMR_ServiceRole --ec2-attributes \\\n  InstanceProfile=EMR_EC2_InstanceProfile,SubnetId=subnet-private1 \\\n  --instance-groups InstanceGroupType=MASTER,InstanceCount=1,InstanceType=m6g.xlarge \\\n    InstanceGroupType=CORE,InstanceCount=2,InstanceType=m6g.xlarge \\\n  --security-configuration emr-encrypted --auto-terminate"}', '[{"kind": "config", "path": "terraform/emr.tf", "priority": "recommended", "description": "EMR cluster or serverless application definition"}, {"kind": "source", "path": "spark/main.py", "priority": "required", "description": "Primary Spark application entrypoint"}, {"kind": "config", "path": "spark/config.json", "priority": "recommended", "description": "Spark submit configuration"}]', '{"serverless": {"type": "boolean", "label": "Serverless Mode", "default": false}, "releaseLabel": {"type": "string", "label": "EMR Release", "default": "emr-7.0.0"}, "coreInstanceCount": {"type": "number", "label": "Core Instance Count", "default": 2}, "primaryInstanceType": {"type": "string", "label": "Primary Instance Type", "default": "m5.xlarge"}}', '["object-storage", "database", "event-stream", "monitoring"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''access'':65C ''action'':148C ''analyt'':49B ''anoth'':118C ''apach'':11B ''attack'':140C ''auto'':31B,131C ''auto-scal'':30B ''auto-termin'':130C ''aw'':1A,3A ''best'':36B ''big'':6B ''block'':63C ''bootstrap'':147C ''bucket'':99C ''cannot'':116C ''cluster'':25B,34B,77C,91C,112C,134C,137C ''code'':155C ''configur'':122C ''data'':7B,41B,120C ''ec2'':24B,82C ''ek'':27B ''emr'':2A,4A,28B,62C ''encrypt'':124C ''everi'':87C,153C ''flexibl'':59B ''framework'':21B,58B ''genom'':51B ''hbase'':15B ''hive'':13B ''iam'':107C ''idl'':136C,139C,143C ''input/output'':98C ''instanc'':83C ''job'':88C,106C,115C ''keep'':76C ''larg'':39B ''large-scal'':38B ''learn'':44B ''machin'':43B ''manag'':5B,35B ''master'':68C ''node'':69C,154C ''one'':114C ''open'':19B,56B ''open-sourc'':18B,55B ''per'':105C ''per-job'':104C ''platform'':8B ''plus'':142C ''presto'':14B ''privat'':79C ''process'':42B ''profil'':84C ''public'':64C,67C,72C ''reach'':93C ''read'':117C ''real'':47B ''real-tim'':46B ''requir'':54B ''rest'':129C ''review'':156C ''role'':103C ''root'':151C ''root-on-every-nod'':150C ''run'':10B ''runtim'':102C ''scalabl'':23B ''scale'':32B,40B ''scope'':94C ''secur'':121C ''serverless'':29B ''share'':110C ''shell'':74C ''sourc'':20B,57B ''spark'':12B,73C ''spend'':144C ''subnet'':80C ''surfac'':141C ''team'':109C ''termin'':132C ''time'':48B ''train'':45B ''transient'':133C ''transit'':126C ''treat'':146C ''turn'':60C ''use'':101C ''without'':33B ''workload'':52B');
INSERT INTO public.technology_catalog VALUES ('react-native', 'React Native', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/react.png', '#61DAFB', '["mobile-app"]', '{"purpose": "JavaScript/TypeScript framework for building native mobile applications using React paradigms. React Native renders actual native UI components (not WebView), giving near-native performance while sharing business logic across iOS and Android. Use when your team has strong React/JavaScript expertise and wants to share code between mobile and web platforms. React Native is ideal when you want native performance with web development velocity, when your app uses standard platform UI components, and when you want access to the enormous npm ecosystem. Don''t use when you need pixel-perfect custom rendering or heavy animations -- Flutter''s Skia engine has an edge there. Don''t use for performance-critical apps like games or video editors where native is mandatory. Avoid if your app is heavily platform-specific with little shared business logic between iOS and Android.", "configMode": "code", "provenance": {"notes": "New Architecture is MANDATORY since RN 0.82 (legacy frozen June 2025, config option removed in Expo SDK 55) — deliberately NO architecture field, the decision no longer exists. Expo is the recommended toolchain.", "method": "live-docs", "sources": ["https://reactnative.dev/blog/2025/10/08/react-native-0.82", "https://docs.expo.dev/guides/new-architecture/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["React Native", "Expo", "React Navigation", "TypeScript", "Hermes", "FlashList", "Reanimated", "React Native Testing Library"], "antiPatterns": ["Using FlatList for large lists without virtualization optimization", "Passing inline functions and objects as props causing unnecessary re-renders", "Overusing bridge calls (old architecture) causing performance bottlenecks", "Not handling keyboard interactions and safe areas properly across platforms", "Using WebView for screens that should be native components", "Ignoring native module linking and Hermes engine configuration"], "apiReference": {"docsUrl": "https://reactnative.dev/docs/getting-started"}, "bestPractices": ["Use TypeScript for type safety across the entire codebase", "Use React Navigation for routing with native navigation gestures", "Implement state management with Zustand, Jotai, or TanStack Query", "Use the New Architecture (Fabric + TurboModules) for better native interop", "Test with Detox for end-to-end and React Native Testing Library for components", "Use Expo for managed workflow when possible to simplify build and deploy", "Optimize lists with FlashList instead of FlatList for large datasets"], "sdkInitPattern": "npx create-expo-app my-app --template blank-typescript && cd my-app && npx expo start\\n// App.tsx\\nimport { Text, View } from \"react-native\";\\nexport default function App() {\\n  return <View style={{ flex: 1, justifyContent: \"center\", alignItems: \"center\" }}><Text>Hello React Native</Text></View>;\\n}", "securityGuidance": "Never embed API keys or secrets in JavaScript bundles -- they are extractable. Use expo-secure-store or react-native-keychain for secure token storage. Enable Hermes engine for improved security (bytecode rather than plain JS). Implement certificate pinning for sensitive API connections. Use App Transport Security (iOS) and Network Security Config (Android) to enforce HTTPS.", "commonApiPatterns": [{"name": "Screen Component", "description": "Screen with route params and TanStack Query data fetching", "codeTemplate": "function UserScreen({ route }: { route: RouteProp<RootStack, \"User\"> }) {\\n  const { id } = route.params;\\n  const { data: user, isLoading } = useQuery({ queryKey: [\"user\", id], queryFn: () => fetchUser(id) });\\n  if (isLoading) return <ActivityIndicator />;\\n  return <View><Text style={styles.name}>{user?.name}</Text></View>;\\n}"}, {"name": "Navigation Stack", "description": "Native stack navigator with typed routes", "codeTemplate": "const Stack = createNativeStackNavigator<RootStack>();\\nfunction AppNavigator() {\\n  return (\\n    <Stack.Navigator>\\n      <Stack.Screen name=\"Home\" component={HomeScreen} />\\n      <Stack.Screen name=\"User\" component={UserScreen} />\\n    </Stack.Navigator>\\n  );\\n}"}, {"name": "Animated Component", "description": "Reanimated 3 animation running on the UI thread", "codeTemplate": "import Animated, { useSharedValue, useAnimatedStyle, withSpring } from \"react-native-reanimated\";\\nfunction AnimatedBox() {\\n  const offset = useSharedValue(0);\\n  const style = useAnimatedStyle(() => ({ transform: [{ translateX: withSpring(offset.value) }] }));\\n  return <Animated.View style={[styles.box, style]} onTouchStart={() => { offset.value = offset.value === 0 ? 200 : 0; }} />;\\n}"}], "setupInstructions": [{"url": "https://reactnative.dev/docs/environment-setup", "type": "toolchain_install", "title": "Install Development Environment", "commands": ["npm install -g react-native-cli", "brew install watchman"], "required": true, "instructions": "Install Node.js, Watchman (macOS), and the React Native CLI or use Expo."}, {"type": "toolchain_install", "title": "Configure Android Environment", "commands": ["export ANDROID_HOME=$HOME/Android/Sdk", "export PATH=$PATH:$ANDROID_HOME/emulator:$ANDROID_HOME/platform-tools"], "required": true, "instructions": "Install Android Studio, configure ANDROID_HOME, and set up an emulator or connect a physical device."}, {"type": "toolchain_install", "title": "Configure iOS Environment (macOS only)", "commands": ["sudo gem install cocoapods", "cd ios && pod install"], "required": false, "instructions": "Install Xcode and CocoaPods for iOS development."}], "integrationPatterns": ["Expo for simplified build, OTA updates, and managed native module configuration", "Firebase or Supabase for backend services (auth, database, push notifications)", "EAS Build + EAS Submit for CI/CD pipeline to App Store and Google Play"], "configurationTemplate": "// app.json (Expo)\\n{\\n  \"expo\": {\\n    \"name\": \"my-app\",\\n    \"slug\": \"my-app\",\\n    \"version\": \"1.0.0\",\\n    \"platforms\": [\"ios\", \"android\"],\\n    \"newArchEnabled\": true,\\n    \"plugins\": [\\n      \"expo-router\",\\n      \"expo-secure-store\"\\n    ]\\n  }\\n}"}', '[{"kind": "config", "path": "app.json", "language": "json", "description": "Expo/React Native app configuration"}, {"kind": "source", "path": "App.tsx", "language": "typescript", "description": "Root application component"}, {"kind": "source", "path": "src/navigation/index.tsx", "language": "typescript", "description": "Navigation configuration"}, {"kind": "config", "path": "package.json", "language": "json", "description": "NPM dependencies and scripts"}, {"kind": "config", "path": "metro.config.js", "language": "javascript", "description": "Metro bundler configuration"}, {"kind": "source", "path": "src/screens/HomeScreen.tsx", "language": "typescript", "description": "Home screen component"}]', '{"targets": {"type": "multiselect", "label": "Targets", "options": ["ios", "android", "web"], "description": "One codebase, one node — targets are configuration, not extra nodes"}, "toolchain": {"type": "enum", "label": "Toolchain", "default": "expo", "options": ["expo", "bare-react-native"], "description": "Expo is the recommended framework (EAS builds, expo-router, OTA updates); bare RN only when a native requirement rules Expo out — and check that it actually does, most no longer do"}, "navigation": {"type": "enum", "label": "Navigation", "default": "expo-router", "options": ["expo-router", "react-navigation"]}, "otaUpdates": {"type": "boolean", "label": "OTA updates (EAS Update)", "default": true, "description": "Ship JS-level fixes without a store review — within store policy limits"}, "stateManagement": {"type": "enum", "label": "State", "default": "zustand", "options": ["zustand", "redux-toolkit", "tanstack-query-plus-store", "context-only"]}}', '["web.rest-api", "auth.supabase-auth", "backend.nodejs"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-31 20:06:52.233344+00', NULL, '#4DC0E8', '''1'':193C ''access'':80B ''across'':33B ''actual'':18B ''alignitem'':196C ''android'':36B,142B,255C ''anim'':99B ''api'':204C,244C ''app'':70B,115B,128B,160C,163C,171C,187C,247C ''app.tsx'':176C ''applic'':11B ''avoid'':125B ''blank'':166C ''blank-typescript'':165C ''build'':8B ''bundl'':210C ''busi'':31B,137B ''bytecod'':234C ''cd'':168C ''center'':195C,197C ''certif'':240C ''code'':49B ''compon'':21B,75B ''config'':254C ''connect'':245C ''creat'':158C ''create-expo-app'':157C ''critic'':114B ''custom'':95B ''default'':185C ''develop'':66B ''ecosystem'':85B ''edg'':106B ''editor'':120B ''emb'':203C ''enabl'':228C ''enforc'':257C ''engin'':103B,230C ''enorm'':83B ''expertis'':44B ''expo'':145C,159C,173C,216C ''expo-secure-stor'':215C ''extract'':213C ''flashlist'':150C ''flex'':192C ''flutter'':100B ''framework'':6B ''function'':186C ''game'':117B ''give'':24B ''heavi'':98B ''heavili'':130B ''hello'':198C ''herm'':149C,229C ''https'':258C ''ideal'':58B ''implement'':239C ''improv'':232C ''io'':34B,140B,250C ''javascript'':209C ''javascript/typescript'':5B ''js'':238C ''justifycont'':194C ''key'':205C ''keychain'':223C ''librari'':155C ''like'':116B ''littl'':135B ''logic'':32B,138B ''mandatori'':124B ''mobil'':10B,51B ''my-app'':161C,169C ''n'':175C,188C,201C ''nativ'':2A,4A,9B,16B,19B,27B,56B,62B,122B,144C,153C,183C,200C,222C ''navig'':147C ''near'':26B ''near-nat'':25B ''need'':91B ''network'':252C ''never'':202C ''nexport'':184C ''nimport'':177C ''npm'':84B ''npx'':156C,172C ''paradigm'':14B ''perfect'':94B ''perform'':28B,63B,113B ''performance-crit'':112B ''pin'':241C ''pixel'':93B ''pixel-perfect'':92B ''plain'':237C ''platform'':54B,73B,132B ''platform-specif'':131B ''rather'':235C ''react'':1A,3A,13B,15B,55B,143C,146C,152C,182C,199C,221C ''react-nat'':181C ''react-nativ