INSERT INTO public.technology_catalog VALUES ('angular', 'Angular', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/angular.png', '#dd0031', '["frontend-app"]', '{"purpose": "Full-featured TypeScript framework for building enterprise-scale web applications with dependency injection and RxJS", "configMode": "code", "provenance": {"notes": "Zoneless change detection is the DEFAULT since v21 and Zone.js is no longer included by default; signals fundamentals stable since v20. Model knowledge would have shipped zoneless as experimental.", "method": "live-docs", "sources": ["https://angular.dev/guide/zoneless", "https://blog.angular.dev/announcing-angular-v21-57946c34f14b"], "verifiedAt": "2026-07-27"}, "typicalTech": ["Angular 17+", "TypeScript", "RxJS", "NgRx", "Angular CLI", "Angular Material"], "antiPatterns": ["Using NgModules for new components when standalone components are preferred", "Not unsubscribing from Observables causing memory leaks (use takeUntilDestroyed or async pipe)", "Putting logic in component templates instead of the component class", "Not using OnPush change detection for performance-critical components", "Creating barrel files that re-export everything causing larger bundles"], "apiReference": {"docsUrl": "https://angular.dev/overview"}, "bestPractices": ["Use standalone components", "Follow the Angular style guide", "Use OnPush change detection strategy", "Implement lazy loading for feature modules", "Use NgRx for complex state management", "Use Angular signals for reactive state", "Implement proper error handling with interceptors", "Use trackBy with ngFor"], "sdkInitPattern": "npx @angular/cli new my-app --routing --style=scss --ssr=false && cd my-app\\n// src/app/app.component.ts\\n@Component({\\n  selector: \"app-root\",\\n  standalone: true,\\n  template: `<h1>Hello Angular</h1>`,\\n})\\nexport class AppComponent {}", "securityGuidance": "Angular sanitizes template bindings by default. Never bypass sanitization with bypassSecurityTrust* unless absolutely necessary and input is verified. Use HttpInterceptors for centralized auth token injection. Enable strict CSP. Use Angular built-in XSRF protection with HttpClient. Avoid using ElementRef.nativeElement for direct DOM manipulation.", "commonApiPatterns": [{"name": "Standalone Component", "description": "Standalone component with signal-based input and control flow", "codeTemplate": "@Component({\\n  selector: \"app-user-list\",\\n  standalone: true,\\n  imports: [CommonModule, RouterLink],\\n  template: `\\n    @for (user of users(); track user.id) {\\n      <div><a [routerLink]=\"[''/user'', user.id]\">{{ user.name }}</a></div>\\n    }\\n  `,\\n})\\nexport class UserListComponent {\\n  users = input.required<User[]>();\\n}"}, {"name": "Injectable Service", "description": "Root-provided service with HttpClient for API calls", "codeTemplate": "@Injectable({ providedIn: \"root\" })\\nexport class UserService {\\n  private http = inject(HttpClient);\\n  getUsers() {\\n    return this.http.get<User[]>(\"/api/users\");\\n  }\\n  getUser(id: string) {\\n    return this.http.get<User>(`/api/users/${id}`);\\n  }\\n}"}, {"name": "Route Guard", "description": "Functional route guard with redirect to login", "codeTemplate": "export const authGuard: CanActivateFn = (route, state) => {\\n  const auth = inject(AuthService);\\n  const router = inject(Router);\\n  if (auth.isAuthenticated()) return true;\\n  return router.createUrlTree([\"/login\"], { queryParams: { returnUrl: state.url } });\\n};"}], "integrationPatterns": ["Angular Router for routing with lazy-loaded feature modules", "RxJS for reactive data streams and state management", "NgRx or Angular Signals for complex state management", "Angular Material or PrimeNG for UI component libraries", "Karma/Jasmine or Jest with Angular Testing Library for testing"], "configurationTemplate": "// angular.json (key sections)\\n{\\n  \"projects\": {\\n    \"my-app\": {\\n      \"architect\": {\\n        \"build\": {\\n          \"options\": {\\n            \"outputPath\": \"dist/my-app\",\\n            \"budgets\": [\\n              { \"type\": \"initial\", \"maximumWarning\": \"500kB\", \"maximumError\": \"1MB\" }\\n            ]\\n          }\\n        }\\n      }\\n    }\\n  }\\n}"}', '[{"kind": "source", "path": "src/app/app.component.ts", "language": "typescript", "description": "Root component"}, {"kind": "source", "path": "src/main.ts", "language": "typescript", "description": "Application bootstrap"}, {"kind": "config", "path": "angular.json", "language": "json", "description": "Angular workspace configuration"}]', '{"ssr": {"type": "boolean", "label": "SSR / hydration", "default": false}, "reactivity": {"type": "enum", "label": "Reactivity", "default": "signals-first", "options": ["signals-first", "rxjs-heavy", "mixed"], "description": "signal/effect/linkedSignal are stable — new state should be signals; RxJS stays for genuine streams"}, "componentModel": {"type": "enum", "label": "Component model", "default": "standalone-default", "options": ["standalone-default", "ngmodules-legacy"]}, "changeDetection": {"type": "enum", "label": "Change detection", "default": "zoneless-default", "options": ["zoneless-default", "zone-based-legacy"], "description": "Zoneless is the default since v21 (Zone.js is no longer included); zone-based only for apps that have not migrated"}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#B00028', '''17'':21C ''absolut'':76C ''angular'':1A,2A,20C,25C,27C,59C,64C,93C ''angular/cli'':30C ''app'':34C,43C,51C ''app-root'':50C ''appcompon'':63C ''applic'':14B ''auth'':86C ''avoid'':101C ''bind'':67C ''build'':9B ''built'':95C ''built-in'':94C ''bypass'':71C ''bypasssecuritytrust'':74C ''cd'':40C ''central'':85C ''class'':62C ''cli'':26C ''compon'':47C ''csp'':91C ''default'':69C ''depend'':16B ''direct'':105C ''dom'':106C ''elementref.nativeelement'':103C ''enabl'':89C ''enterpris'':11B ''enterprise-scal'':10B ''fals'':39C ''featur'':5B ''framework'':7B ''full'':4B ''full-featur'':3B ''hello'':58C ''httpclient'':100C ''httpinterceptor'':83C ''inject'':17B,88C ''input'':79C ''manipul'':107C ''materi'':28C ''my-app'':32C,41C ''n'':44C,46C,48C,53C,56C,60C ''necessari'':77C ''never'':70C ''new'':31C ''nexport'':61C ''ngrx'':24C ''npx'':29C ''protect'':98C ''root'':52C ''rout'':35C ''rxjs'':19B,23C ''sanit'':65C,72C ''scale'':12B ''scss'':37C ''selector'':49C ''src/app/app.component.ts'':45C ''ssr'':38C ''standalon'':54C ''strict'':90C ''style'':36C ''templat'':57C,66C ''token'':87C ''true'':55C ''typescript'':6B,22C ''unless'':75C ''use'':82C,92C,102C ''verifi'':81C ''web'':13B ''xsrf'':97C');
INSERT INTO public.technology_catalog VALUES ('blazor', 'Blazor', NULL, '#512bd4', '["frontend-app"]', '{"purpose": "Microsoft framework for building interactive web UIs with C# instead of JavaScript, running on WebAssembly or server-side", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Blazor", "C#", ".NET 8+", "Razor", "Entity Framework Core"], "antiPatterns": ["Using Blazor Server for high-latency scenarios where WASM is more appropriate", "Performing heavy synchronous work in component lifecycle methods blocking the UI thread", "Not disposing event handlers and JS interop references causing memory leaks", "Embedding secrets in Blazor WebAssembly client code", "Overusing CascadingParameters when DI services are more appropriate"], "apiReference": {"docsUrl": "https://learn.microsoft.com/aspnet/core/blazor/"}, "bestPractices": ["Use Blazor Server for internal apps needing real-time updates", "Use Blazor WebAssembly for offline-capable apps", "Implement proper component lifecycle management", "Use cascading parameters sparingly", "Implement proper error boundaries", "Use dependency injection for services"], "sdkInitPattern": "dotnet new blazor -n MyApp --framework net8.0 --interactivity Auto\\n@* Pages/Home.razor *@\\n@page \"/\"\\n<h1>Hello Blazor</h1>", "securityGuidance": "Blazor Server keeps component state on the server -- connection loss drops state. Use InputSelect and EditForm with DataAnnotations for input validation. Sanitize content before using MarkupString. In Blazor WebAssembly, all client-side code is visible to the user -- never embed secrets. Use ASP.NET Core Identity or external OIDC for authentication. Apply authorization attributes on pages and components.", "commonApiPatterns": [{"name": "Component with State", "description": "Razor component with event handling and state", "codeTemplate": "@page \"/counter\"\\n<h1>Counter</h1>\\n<p>Count: @count</p>\\n<button @onclick=\"Increment\">Click me</button>\\n@code {\\n    private int count = 0;\\n    private void Increment() => count++;\\n}"}, {"name": "Data-Bound Component", "description": "Component with lifecycle data loading and null-state handling", "codeTemplate": "@page \"/users\"\\n@inject HttpClient Http\\n@if (users is null) {\\n  <p>Loading...</p>\\n} else {\\n  @foreach (var user in users) {\\n    <div>@user.Name</div>\\n  }\\n}\\n@code {\\n    private User[]? users;\\n    protected override async Task OnInitializedAsync() {\\n        users = await Http.GetFromJsonAsync<User[]>(\"/api/users\");\\n    }\\n}"}, {"name": "Cascading Parameter", "description": "Cascading value for theme or auth state propagation", "codeTemplate": "<CascadingValue Value=\"@theme\">\\n  <Router AppAssembly=\"typeof(App).Assembly\" />\\n</CascadingValue>\\n@* In child component: *@\\n[CascadingParameter] private Theme Theme { get; set; } = default!;"}], "integrationPatterns": ["ASP.NET Core hosting for server-side rendering with SignalR interactivity", "Entity Framework Core for database access in server components", "MudBlazor or Radzen for UI component libraries", "Microsoft.AspNetCore.Components.Authorization for auth state", "bUnit for Blazor component unit testing"], "configurationTemplate": "<!-- MyApp.csproj -->\\n<Project Sdk=\"Microsoft.NET.Sdk.Web\">\\n  <PropertyGroup>\\n    <TargetFramework>net8.0</TargetFramework>\\n    <Nullable>enable</Nullable>\\n    <ImplicitUsings>enable</ImplicitUsings>\\n  </PropertyGroup>\\n</Project>\\n\\n// Program.cs\\nbuilder.Services.AddRazorComponents()\\n    .AddInteractiveServerComponents()\\n    .AddInteractiveWebAssemblyComponents();"}', '[{"kind": "source", "path": "Program.cs", "language": "csharp", "description": "Application entry point"}, {"kind": "source", "path": "App.razor", "language": "razor", "description": "Root component"}]', '{"aot": {"type": "boolean", "label": "AOT compilation", "default": false, "description": "Faster runtime, much larger download — measure before enabling"}, "hosting": {"type": "enum", "label": "Hosting", "default": "aspnet-core", "options": ["aspnet-core", "standalone-wasm-static"], "description": "Standalone WASM deploys as static files with no .NET server — the hosting answer changes the architecture"}, "renderMode": {"type": "enum", "label": "Render mode", "default": "interactive-auto", "options": ["interactive-auto", "interactive-server", "interactive-wasm", "static-ssr"], "description": "The .NET 8+ render modes. Interactive Auto starts on the server and swaps to WASM once cached — the usual default; Static SSR for content pages with no interactivity"}}', '["rest-api", "database", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#4023A8', '''8'':25C ''appli'':97C ''asp.net'':89C ''attribut'':99C ''authent'':96C ''author'':98C ''auto'':38C ''blazor'':1A,2A,22C,32C,45C,46C,73C ''build'':6B ''c'':11B,23C ''client'':77C ''client-sid'':76C ''code'':79C ''compon'':49C,103C ''connect'':54C ''content'':68C ''core'':29C,90C ''dataannot'':63C ''dotnet'':30C ''drop'':56C ''editform'':61C ''emb'':86C ''entiti'':27C ''extern'':93C ''framework'':4B,28C,35C ''hello'':44C ''ident'':91C ''input'':65C ''inputselect'':59C ''instead'':12B ''interact'':7B,37C ''javascript'':14B ''keep'':48C ''loss'':55C ''markupstr'':71C ''microsoft'':3B ''myapp'':34C ''n'':33C,39C,41C,43C ''net'':24C ''net8.0'':36C ''never'':85C ''new'':31C ''oidc'':94C ''page'':42C,101C ''pages/home.razor'':40C ''razor'':26C ''run'':15B ''sanit'':67C ''secret'':87C ''server'':20B,47C,53C ''server-sid'':19B ''side'':21B,78C ''state'':50C,57C ''ui'':9B ''use'':58C,70C,88C ''user'':84C ''valid'':66C ''visibl'':81C ''web'':8B ''webassembl'':17B,74C');
INSERT INTO public.technology_catalog VALUES ('vue', 'Vue', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/vue.png', '#42b883', '["frontend-app"]', '{"purpose": "Progressive JavaScript framework for building user interfaces with an approachable, performant, and versatile design", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Vue 3", "TypeScript", "Vite", "Vue Router", "Pinia", "VueUse"], "antiPatterns": ["Using Options API in new projects when Composition API offers better TypeScript support", "Mutating props directly instead of emitting events to parent", "Deeply nested v-if/v-else chains instead of computed properties or component composition", "Using Vuex in new projects instead of Pinia", "Not using script setup syntax which provides better type inference and less boilerplate"], "apiReference": {"docsUrl": "https://vuejs.org/guide/"}, "bestPractices": ["Use Composition API with script setup", "Use Pinia for state management", "Implement proper prop validation", "Use computed properties instead of methods for derived state", "Leverage Vue devtools for debugging", "Use provide/inject sparingly", "Implement lazy loading for routes"], "sdkInitPattern": "npm create vite@latest my-app -- --template vue-ts && cd my-app && npm install\\n<!-- src/App.vue -->\\n<script setup lang=\"ts\">\\nimport { ref } from \"vue\";\\nconst msg = ref(\"Hello Vue\");\\n</script>\\n<template><h1>{{ msg }}</h1></template>", "securityGuidance": "Vue auto-escapes template interpolation preventing XSS. Never use v-html with unsanitized content. Validate dynamic :href and :src bindings to block javascript: URIs. Use CSP headers in production. Avoid storing auth tokens in reactive state exposed to devtools -- use httpOnly cookies. Sanitize input before passing to third-party DOM manipulation libraries.", "commonApiPatterns": [{"name": "Composition API Component", "description": "Component with reactive state, computed properties, and lifecycle hooks", "codeTemplate": "<script setup lang=\"ts\">\\nimport { ref, computed, onMounted } from \"vue\";\\nconst count = ref(0);\\nconst doubled = computed(() => count.value * 2);\\nconst increment = () => count.value++;\\nonMounted(() => console.log(\"mounted\"));\\n</script>\\n<template>\\n  <button @click=\"increment\">{{ count }} ({{ doubled }})</button>\\n</template>"}, {"name": "Composable", "description": "Reusable composable function for data fetching", "codeTemplate": "export function useUsers() {\\n  const users = ref<User[]>([]);\\n  const loading = ref(true);\\n  onMounted(async () => {\\n    users.value = await fetch(\"/api/users\").then(r => r.json());\\n    loading.value = false;\\n  });\\n  return { users, loading };\\n}"}, {"name": "Pinia Store", "description": "Pinia store with Composition API setup syntax", "codeTemplate": "export const useAuthStore = defineStore(\"auth\", () => {\\n  const user = ref<User | null>(null);\\n  const isAuthenticated = computed(() => !!user.value);\\n  async function login(credentials: Credentials) {\\n    user.value = await authApi.login(credentials);\\n  }\\n  return { user, isAuthenticated, login };\\n});"}], "integrationPatterns": ["Vue Router for SPA routing with navigation guards", "Pinia for type-safe state management with devtools support", "VueUse for collection of essential composition utilities", "Tailwind CSS or UnoCSS for utility-first styling", "Vitest + Vue Test Utils for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport vue from \"@vitejs/plugin-vue\";\\nexport default defineConfig({\\n  plugins: [vue()],\\n  server: { port: 3000 },\\n  resolve: {\\n    alias: { \"@\": \"/src\" }\\n  }\\n});\\n\\n// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2020\",\\n    \"module\": \"ESNext\",\\n    \"jsx\": \"preserve\",\\n    \"strict\": true,\\n    \"moduleResolution\": \"bundler\",\\n    \"paths\": { \"@/*\": [\"./src/*\"] }\\n  }\\n}"}', '[{"kind": "source", "path": "src/App.vue", "language": "vue", "description": "Root Vue component"}, {"kind": "source", "path": "src/main.ts", "language": "typescript", "description": "Application entry point"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite configuration"}]', '{"state": {"type": "enum", "label": "State", "default": "pinia", "options": ["pinia", "composables-only", "none"]}, "styling": {"type": "enum", "label": "Styling", "default": "scoped-sfc-css", "options": ["tailwind", "scoped-sfc-css", "css-modules"]}, "apiStyle": {"type": "enum", "label": "API style", "default": "composition-script-setup", "options": ["composition-script-setup", "options-legacy"], "description": "Composition API with <script setup> is the standing default; Options API is maintained for existing code"}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#35946D', '''3'':18C ''app'':31C,39C ''approach'':12B ''auth'':79C ''auto'':48C ''auto-escap'':47C ''avoid'':77C ''bind'':67C ''block'':69C ''build'':7B ''cd'':36C ''content'':61C ''cooki'':89C ''creat'':26C ''csp'':73C ''design'':16B ''devtool'':86C ''dom'':98C ''dynam'':63C ''escap'':49C ''expos'':84C ''framework'':5B ''header'':74C ''href'':64C ''html'':58C ''httpon'':88C ''input'':91C ''instal'':41C ''interfac'':9B ''interpol'':51C ''javascript'':4B,70C ''latest'':28C ''librari'':100C ''manipul'':99C ''msg'':45C ''my-app'':29C,37C ''n'':42C,43C,44C ''never'':54C ''npm'':25C,40C ''parti'':97C ''pass'':93C ''perform'':13B ''pinia'':23C ''prevent'':52C ''product'':76C ''progress'':3B ''reactiv'':82C ''router'':22C ''sanit'':90C ''src'':66C ''state'':83C ''store'':78C ''templat'':32C,50C ''third'':96C ''third-parti'':95C ''token'':80C ''ts'':35C ''typescript'':19C ''unsanit'':60C ''uri'':71C ''use'':55C,72C,87C ''user'':8B ''v'':57C ''v-html'':56C ''valid'':62C ''versatil'':15B ''vite'':20C,27C ''vue'':1A,2A,17C,21C,34C,46C ''vue-t'':33C ''vueus'':24C ''xss'':53C');
INSERT INTO public.technology_catalog VALUES ('wpf', 'WPF', NULL, '#512BD4', '["desktop-app"]', '{"purpose": "Windows Presentation Foundation - .NET framework for building rich Windows desktop applications with XAML-based UI and data binding", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["WPF", "C#", ".NET 8+", "XAML", "CommunityToolkit.Mvvm", "Prism", "MaterialDesignInXaml", "Entity Framework Core"], "antiPatterns": ["Putting logic in code-behind instead of ViewModels", "Blocking the UI thread with synchronous operations", "Not using data templates for dynamic content", "Hardcoding styles instead of using resource dictionaries", "Not implementing IDisposable for resource cleanup"], "apiReference": {"docsUrl": "https://learn.microsoft.com/dotnet/desktop/wpf/"}, "bestPractices": ["Use MVVM pattern with CommunityToolkit.Mvvm or Prism", "Leverage data binding and INotifyPropertyChanged for reactive UI", "Use resource dictionaries for consistent theming", "Implement ICommand for button and interaction handling", "Use dependency injection via Microsoft.Extensions.DependencyInjection", "Implement proper async patterns for UI-thread safety", "Use UserControls and CustomControls for reusable components"], "sdkInitPattern": "// MVVM: view binds to an observable view model — no code-behind business logic\npublic sealed class OrdersViewModel : ObservableObject\n{\n    private readonly IOrderService _orders;\n    public ObservableCollection<OrderDto> Orders { get; } = new();\n\n    public OrdersViewModel(IOrderService orders) => _orders = orders;\n\n    public async Task LoadAsync()\n    {\n        Orders.Clear();\n        foreach (var o in await _orders.ListForCurrentUserAsync())\n            Orders.Add(o);\n    }\n}", "securityGuidance": "A desktop app runs on a machine you do not control — credentials cached locally go through DPAPI/Windows credential manager, never plaintext config files, and API access uses per-user OAuth tokens (authorization-code + PKCE via the system browser), not an embedded client secret every install shares. Validate and least-privilege everything the app reads from disk or IPC (other local processes are not friends), keep XAML free of BAML-injection by never loading untrusted XAML (XamlReader.Load executes object graphs), sign the binaries and the installer, and ship updates through a signed channel."}', '[{"kind": "source", "path": "App.xaml.cs", "language": "csharp", "description": "Application entry point and startup"}, {"kind": "source", "path": "MainWindow.xaml", "language": "xaml", "description": "Main window layout"}, {"kind": "source", "path": "ViewModels/MainViewModel.cs", "language": "csharp", "description": "Main view model"}, {"kind": "config", "path": "App.csproj", "language": "xml", "description": ".NET project file"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "dotnet-current", "options": ["dotnet-current", "dotnet-framework-legacy"], "description": "Modern .NET unless the app is chained to Framework-only dependencies — the single biggest WPF modernization decision"}, "packaging": {"type": "enum", "label": "Packaging", "default": "msix", "options": ["msix", "clickonce-legacy", "plain-exe-installer"]}, "uiPattern": {"type": "enum", "label": "UI pattern", "default": "mvvm", "options": ["mvvm", "code-behind-legacy"]}}', '["rest-api", "database", "auth-provider"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-31 20:06:52.233344+00', 'WPF', NULL, '''8'':25C ''access'':105C ''api'':104C ''app'':82C,135C ''applic'':13B ''async'':68C ''author'':113C ''authorization-cod'':112C ''await'':76C ''baml'':152C ''baml-inject'':151C ''base'':17B ''behind'':44C ''binari'':165C ''bind'':21B,35C ''browser'':119C ''build'':9B ''busi'':45C ''c'':23C ''cach'':92C ''channel'':175C ''class'':49C ''client'':123C ''code'':43C,114C ''code-behind'':42C ''communitytoolkit.mvvm'':27C ''config'':101C ''control'':90C ''core'':32C ''credenti'':91C,97C ''data'':20B ''desktop'':12B,81C ''disk'':138C ''dpapi/windows'':96C ''embed'':122C ''entiti'':30C ''everi'':125C ''everyth'':133C ''execut'':160C ''file'':102C ''foreach'':72C ''foundat'':5B ''framework'':7B,31C ''free'':149C ''friend'':146C ''get'':59C ''go'':94C ''graph'':162C ''inject'':153C ''instal'':126C,168C ''iorderservic'':54C,63C ''ipc'':140C ''keep'':147C ''least'':131C ''least-privileg'':130C ''load'':156C ''loadasync'':70C ''local'':93C,142C ''logic'':46C ''machin'':86C ''manag'':98C ''materialdesigninxaml'':29C ''model'':40C ''mvvm'':33C ''net'':6B,24C ''never'':99C,155C ''new'':60C ''o'':74C,79C ''oauth'':110C ''object'':161C ''observ'':38C ''observablecollect'':57C ''observableobject'':51C ''order'':55C,58C,64C,65C,66C ''orders.add'':78C ''orders.clear'':71C ''orders.listforcurrentuserasync'':77C ''ordersviewmodel'':50C,62C ''per'':108C ''per-us'':107C ''pkce'':115C ''plaintext'':100C ''present'':4B ''prism'':28C ''privat'':52C ''privileg'':132C ''process'':143C ''public'':47C,56C,61C,67C ''read'':136C ''readon'':53C ''rich'':10B ''run'':83C ''seal'':48C ''secret'':124C ''share'':127C ''ship'':170C ''sign'':163C,174C ''system'':118C ''task'':69C ''token'':111C ''ui'':18B ''untrust'':157C ''updat'':171C ''use'':106C ''user'':109C ''valid'':128C ''var'':73C ''via'':116C ''view'':34C,39C ''window'':3B,11B ''wpf'':1A,2A,22C ''xaml'':16B,26C,148C,158C ''xaml-bas'':15B ''xamlreader.load'':159C');
INSERT INTO public.technology_catalog VALUES ('dotnet-maui', '.NET MAUI', NULL, '#512BD4', '["desktop-app"]', '{"purpose": "Microsoft framework for building native cross-platform desktop and mobile applications with C# and XAML, targeting Windows, macOS (via Catalyst), iOS, and Android from a single codebase", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": [".NET MAUI", "C#", "XAML", ".NET 8", "CommunityToolkit.Mvvm", "CommunityToolkit.Maui", "SQLite-net", "Microsoft.Extensions.DependencyInjection"], "antiPatterns": ["Putting platform-specific code in shared projects without abstraction", "Not using dependency injection causing tight coupling", "Ignoring macOS Catalyst differences from iOS behavior", "Using code-behind instead of data binding for UI logic", "Not testing on all target platforms before release"], "apiReference": {"docsUrl": "https://learn.microsoft.com/dotnet/maui/"}, "bestPractices": ["Use MVVM pattern with CommunityToolkit.Mvvm for clean separation of concerns", "Register services and view models in MauiProgram.cs via dependency injection", "Use platform-specific code via partial classes in Platforms/ folders", "Implement proper lifecycle handling (OnStart, OnSleep, OnResume)", "Use Shell for navigation with URI-based routing", "Leverage Handlers for custom native control rendering", "Publish as MSIX for Windows and .app bundle for macOS", "Use semantic versioning in the csproj ApplicationVersion property"], "sdkInitPattern": "// MauiProgram.cs\npublic static class MauiProgram\n{\n    public static MauiApp CreateMauiApp()\n    {\n        var builder = MauiApp.CreateBuilder();\n        builder.UseMauiApp<App>();\n        builder.Services.AddSingleton<IApiClient>(_ =>\n            new ApiClient(new Uri(AppConfig.ApiBaseUrl)));  // tokens via SecureStorage\n        builder.Services.AddTransient<OrdersViewModel>();\n        return builder.Build();\n    }\n}", "securityGuidance": "Tokens and credentials go in SecureStorage (Keychain/Keystore-backed), never Preferences or bundled config — the app package is extractable on every platform it ships to. Authenticate with authorization-code + PKCE through the system browser (WebAuthenticator), pin your API''s TLS expectations, and treat platform permissions as user trust: request the minimum, explain why. Anything secret-dependent (API keys for third-party services, signing operations) belongs on your backend — a MAUI binary shared by thousands of installs cannot hold a secret, and deep links/app links are untrusted input like any URL."}', '[{"kind": "config", "path": "App.csproj", "language": "xml", "description": ".NET MAUI project file with target frameworks and NuGet dependencies"}, {"kind": "source", "path": "MauiProgram.cs", "language": "csharp", "description": "MAUI application builder and service registration"}, {"kind": "source", "path": "App.xaml.cs", "language": "csharp", "description": "Application lifecycle and shell configuration"}, {"kind": "config", "path": "Platforms/Windows/Package.appxmanifest", "language": "xml", "description": "Windows MSIX packaging manifest"}, {"kind": "config", "path": "Platforms/MacCatalyst/Info.plist", "language": "xml", "description": "macOS Catalyst bundle configuration"}, {"kind": "config", "path": "Platforms/MacCatalyst/Entitlements.plist", "language": "xml", "description": "macOS entitlements for sandbox and system access"}, {"kind": "config", "path": "Properties/launchSettings.json", "language": "json", "description": "Debug launch profiles for each target platform"}]', '{"mvvm": {"type": "enum", "label": "MVVM tooling", "default": "community-toolkit-mvvm", "options": ["community-toolkit-mvvm", "manual-inotify"]}, "targets": {"type": "multiselect", "label": "Targets", "options": ["ios", "android", "windows", "macos"], "description": "One codebase, one node — targets are configuration"}, "uiModel": {"type": "enum", "label": "UI model", "default": "xaml-maui", "options": ["xaml-maui", "blazor-hybrid"], "description": "Blazor Hybrid renders Blazor components in a native WebView — the way a Blazor team ships desktop/mobile without rewriting UI (the 4d-1 blazor row covers the web side)"}}', '["frontend-app", "rest-api", "database"]', false, NULL, NULL, '2026-03-16 02:23:33.717373+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''8'':38C ''android'':28B ''anyth'':122C ''api'':106C,126C ''apicli'':60C ''app'':83C ''appconfig.apibaseurl'':63C ''applic'':16B ''authent'':93C ''author'':96C ''authorization-cod'':95C ''backend'':138C ''belong'':135C ''binari'':141C ''browser'':102C ''build'':8B ''builder'':55C ''builder.build'':69C ''builder.services.addsingleton'':58C ''builder.services.addtransient'':67C ''builder.usemauiapp'':57C ''bundl'':80C ''c'':18B,35C ''cannot'':147C ''catalyst'':25B ''class'':48C ''code'':97C ''codebas'':32B ''communitytoolkit.maui'':40C ''communitytoolkit.mvvm'':39C ''config'':81C ''createmauiapp'':53C ''credenti'':72C ''cross'':11B ''cross-platform'':10B ''deep'':152C ''depend'':125C ''desktop'':13B ''dotnet'':3A ''everi'':88C ''expect'':109C ''explain'':120C ''extract'':86C ''framework'':6B ''go'':73C ''hold'':148C ''input'':157C ''instal'':146C ''io'':26B ''key'':127C ''keychain/keystore-backed'':76C ''like'':158C ''link'':154C ''links/app'':153C ''maco'':23B ''maui'':2A,4A,34C,140C ''mauiapp'':52C ''mauiapp.createbuilder'':56C ''mauiprogram'':49C ''mauiprogram.cs'':45C ''microsoft'':5B ''microsoft.extensions.dependencyinjection'':44C ''minimum'':119C ''mobil'':15B ''nativ'':9B ''net'':1A,33C,37C,43C ''never'':77C ''new'':59C,61C ''oper'':134C ''packag'':84C ''parti'':131C ''permiss'':113C ''pin'':104C ''pkce'':98C ''platform'':12B,89C,112C ''prefer'':78C ''public'':46C,50C ''request'':117C ''return'':68C ''secret'':124C,150C ''secret-depend'':123C ''securestorag'':66C,75C ''servic'':132C ''share'':142C ''ship'':91C ''sign'':133C ''singl'':31B ''sqlite'':42C ''sqlite-net'':41C ''static'':47C,51C ''system'':101C ''target'':21B ''third'':130C ''third-parti'':129C ''thousand'':144C ''tls'':108C ''token'':64C,70C ''treat'':111C ''trust'':116C ''untrust'':156C ''uri'':62C ''url'':160C ''user'':115C ''var'':54C ''via'':24B,65C ''webauthent'':103C ''window'':22B ''xaml'':20B,36C');
INSERT INTO public.technology_catalog VALUES ('c-systems', 'C', NULL, '#A8B9CC', '["shared-library", "cli-tool"]', '{"purpose": "Systems language for native libraries, CLI tools and the FFI boundary other languages bind to (Python extensions, Node addons, language runtimes). In THIS catalog its scope is native/shared libraries and system tooling — embedded/microcontroller C becomes modelable when the Hardware & IoT roles are populated. For new application-level services, Rust or Go are usually the honest recommendation; C is the right node when the deliverable IS a C library/tool or binds to one.", "configMode": "code", "provenance": {"notes": "Phase B8d additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["CMake", "clang/gcc", "ASan/UBSan", "libFuzzer", "pkg-config", "cmocka/Unity tests"], "antiPatterns": ["Hand-rolled string/buffer handling where a vetted library exists — strcpy-era code is the top vulnerability source", "Global mutable state in library code — makes the library unusable from threaded hosts", "Choosing C for a new network service where memory safety matters and Rust/Go would do — justify the choice, do not default to it"], "apiReference": {"docsUrl": "https://en.cppreference.com/w/c"}, "bestPractices": ["CMake as the build default (broadest toolchain/IDE support); commit a preset file so builds are reproducible", "Treat warnings as errors (-Wall -Wextra -Werror) and run sanitizers (ASan/UBSan) in CI — memory bugs are the defect class", "Export a minimal, versioned public header; everything else static — the API surface IS the maintenance contract", "Fuzz any parser/decoder surface (libFuzzer/AFL) — C parsing code without fuzzing is unshipped CVEs"], "securityGuidance": "Every buffer has a length and every read of external bytes must honor it — the CWE top of the charts (overflow, use-after-free, off-by-one) lives in hand-rolled parsers, so fuzz them and run ASan/UBSan/Valgrind in CI. Use the bounded string functions (snprintf, strlcpy where available), check every allocation and every return, drop privileges early in privileged daemons, and ship with the hardening flags on (stack protector, FORTIFY, RELRO, PIE). Integer arithmetic on sizes gets explicit overflow checks before it reaches malloc or memcpy.", "configurationTemplate": "# Makefile\nCC := gcc\nCFLAGS := -std=c17 -Wall -Wextra -Werror -O2 \\\n  -fstack-protector-strong -D_FORTIFY_SOURCE=2 -fPIE\nLDFLAGS := -pie -Wl,-z,relro,-z,now\n\napp: src/main.o src/parser.o\n\t$(CC) $(LDFLAGS) -o $@ $^\n\n%.o: %.c\n\t$(CC) $(CFLAGS) -c -o $@ $<"}', '[{"kind": "config", "path": "CMakeLists.txt"}, {"kind": "source", "path": "include/"}, {"kind": "source", "path": "src/"}]', '{"linkage": {"type": "enum", "label": "Artifact", "default": "static-library", "options": ["static-library", "shared-library", "cli-binary"], "description": "What the build produces — drives packaging and the consumer''s link story"}, "sanitizers": {"type": "boolean", "label": "Sanitizers in CI", "default": true, "description": "ASan/UBSan runs are the memory-safety net — a manual CI decision, not a code change"}, "buildSystem": {"type": "enum", "label": "Build system", "default": "cmake", "options": ["cmake", "make", "meson"]}}', '[]', false, NULL, NULL, '2026-08-31 20:06:50.522268+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''addon'':22B ''alloc'':140C ''applic'':50B ''application-level'':49B ''arithmet'':163C ''asan/ubsan'':79C ''asan/ubsan/valgrind'':126C ''avail'':137C ''becom'':38B ''bind'':17B,74B ''bound'':131C ''boundari'':14B ''buffer'':87C ''byte'':96C ''c'':1A,2A,37B,61B,71B ''catalog'':27B ''chart'':105C ''check'':138C,169C ''ci'':128C ''clang/gcc'':78C ''cli'':9B ''cmake'':77C ''cmocka/unity'':84C ''config'':83C ''cwe'':101C ''daemon'':149C ''deliver'':68B ''drop'':144C ''earli'':146C ''embedded/microcontroller'':36B ''everi'':86C,92C,139C,142C ''explicit'':167C ''extens'':20B ''extern'':95C ''ffi'':13B ''flag'':155C ''fortifi'':159C ''free'':110C ''function'':133C ''fuzz'':122C ''get'':166C ''go'':55B ''hand'':118C ''hand-rol'':117C ''harden'':154C ''hardwar'':42B ''honest'':59B ''honor'':98C ''integ'':162C ''iot'':43B ''languag'':5B,16B,23B ''length'':90C ''level'':51B ''libfuzz'':80C ''librari'':8B,32B ''library/tool'':72B ''live'':115C ''malloc'':173C ''memcpi'':175C ''model'':39B ''must'':97C ''nativ'':7B ''native/shared'':31B ''new'':48B ''node'':21B,65B ''off-by-on'':111C ''one'':76B,114C ''overflow'':106C,168C ''parser'':120C ''pie'':161C ''pkg'':82C ''pkg-config'':81C ''popul'':46B ''privileg'':145C,148C ''protector'':158C ''python'':19B ''reach'':172C ''read'':93C ''recommend'':60B ''relro'':160C ''return'':143C ''right'':64B ''role'':44B ''roll'':119C ''run'':125C ''runtim'':24B ''rust'':53B ''scope'':29B ''servic'':52B ''ship'':151C ''size'':165C ''snprintf'':134C ''stack'':157C ''string'':132C ''strlcpi'':135C ''system'':3A,4B,34B ''test'':85C ''tool'':10B,35B ''top'':102C ''use'':108C,129C ''use-after-fre'':107C ''usual'':57B');
INSERT INTO public.technology_catalog VALUES ('colyseus', 'Colyseus', NULL, '#6b7280', '["game-server"]', '{"purpose": "Node.js/TypeScript multiplayer game server with automatic authoritative state sync (Schema) and a simple room system over WebSockets. The indie/web-game lane: one language across client and server. Not for massive CCU or physics-heavy simulation — that is Nakama/Photon territory.", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-28. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Colyseus Schema", "room lifecycle", "WebSocket transport", "Redis presence (scale-out)"], "antiPatterns": ["Trusting client-reported positions/scores — the authority model exists to prevent it", "One mega-room as the whole game world", "Blocking the event loop with game logic — same Node.js rule as any service"], "apiReference": {"docsUrl": "https://docs.colyseus.io/"}, "bestPractices": ["Authoritative server state via Schema — clients send intents, never state", "Patch rate + state size discipline: sync what players SEE, not the whole world", "Rooms small and disposable; matchmaking via the built-in lobby patterns", "Load-test CCU per node early — the scaling story (Redis presence) is a step change, plan it"], "sdkInitPattern": "import { Room, Client } from ''colyseus'';\nimport { MyRoomState, Player } from ''./schema/MyRoomState'';\n\nexport class GameRoom extends Room<MyRoomState> {\n  maxClients = 4;\n  state = new MyRoomState();\n\n  static async onAuth(token: string) {\n    return await verifyJwt(token);  // reject before the room ever sees the client\n  }\n\n  onJoin(client: Client, options: unknown, user: AuthUser) {\n    this.state.players.set(client.sessionId, new Player(user.id));\n  }\n\n  onCreate() {\n    this.onMessage(''move'', (client, input: unknown) => {\n      const move = MoveSchema.parse(input);        // validate every payload\n      this.simulateMove(client.sessionId, move);   // server owns the simulation\n    });\n    this.setSimulationInterval((dt) => this.update(dt));\n  }\n}", "securityGuidance": "The room IS the authoritative server — state lives in the schema and clients receive patches, so never mutate state from client messages without validation: parse every onMessage payload against a schema, bound rates per client, and let onAuth verify a real token before join (an open room is an open game server). Match players by server-side matchmaking rather than client-chosen room ids for anything ranked, keep the monitor panel authenticated (it is a full room inspector), and scale with the presence/driver layer secured like any Redis deployment."}', '[{"kind": "code", "path": "src/rooms/GameRoom.ts", "language": "typescript", "description": "Authoritative room: onAuth JWT check, schema state, validated onMessage"}, {"kind": "code", "path": "src/schema/GameState.ts", "language": "typescript", "description": "Replicated state schema"}]', '{"scale": {"type": "enum", "label": "Scale", "default": "single-node", "options": ["single-node", "scaled-redis-presence"], "description": "Rooms pin to a process; scaling out needs the Redis presence + proxy setup"}, "stateModel": {"type": "enum", "label": "State sync", "default": "schema-authoritative", "options": ["schema-authoritative", "custom-messages"]}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/schema/myroomstate'':63C ''/typescript'':5B ''4'':70C ''across'':27B ''anyth'':194C ''async'':75C ''authent'':200C ''authorit'':11B,131C ''authus'':97C ''automat'':10B ''await'':80C ''bound'':158C ''ccu'':34B ''chosen'':190C ''class'':65C ''client'':28B,56C,90C,92C,93C,106C,139C,147C,161C,189C ''client-chosen'':188C ''client.sessionid'':99C,117C ''colyseus'':1A,2A,44C,58C ''const'':109C ''deploy'':217C ''dt'':124C,126C ''ever'':87C ''everi'':114C,152C ''export'':64C ''extend'':67C ''full'':204C ''game'':7B,177C ''gameroom'':66C ''heavi'':38B ''id'':192C ''import'':54C,59C ''indie/web-game'':23B ''input'':107C,112C ''inspector'':206C ''join'':170C ''keep'':196C ''lane'':24B ''languag'':26B ''layer'':212C ''let'':163C ''lifecycl'':47C ''like'':214C ''live'':134C ''massiv'':33B ''match'':179C ''matchmak'':185C ''maxclient'':69C ''messag'':148C ''monitor'':198C ''move'':105C,110C,118C ''moveschema.parse'':111C ''multiplay'':6B ''mutat'':144C ''myroomst'':60C,73C ''nakama/photon'':42B ''never'':143C ''new'':72C,100C ''node.js'':4B ''node.js/typescript'':3B ''onauth'':76C,164C ''oncreat'':103C ''one'':25B ''onjoin'':91C ''onmessag'':153C ''open'':172C,176C ''option'':94C ''own'':120C ''panel'':199C ''pars'':151C ''patch'':141C ''payload'':115C,154C ''per'':160C ''physic'':37B ''physics-heavi'':36B ''player'':61C,101C,180C ''presenc'':51C ''presence/driver'':211C ''rank'':195C ''rate'':159C ''rather'':186C ''real'':167C ''receiv'':140C ''redi'':50C,216C ''reject'':83C ''return'':79C ''room'':18B,46C,55C,68C,86C,128C,173C,191C,205C ''scale'':53C,208C ''scale-out'':52C ''schema'':14B,45C,137C,157C ''secur'':213C ''see'':88C ''server'':8B,30B,119C,132C,178C,183C ''server-sid'':182C ''side'':184C ''simpl'':17B ''simul'':39B,122C ''state'':12B,71C,133C,145C ''static'':74C ''string'':78C ''sync'':13B ''system'':19B ''territori'':43B ''this.onmessage'':104C ''this.setsimulationinterval'':123C ''this.simulatemove'':116C ''this.state.players.set'':98C ''this.update'':125C ''token'':77C,82C,168C ''transport'':49C ''unknown'':95C,108C ''user'':96C ''user.id'':102C ''valid'':113C,150C ''verifi'':165C ''verifyjwt'':81C ''websocket'':21B,48C ''without'':149C');
INSERT INTO public.technology_catalog VALUES ('python-backend', 'Python', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/python-backend.png', '#3776ab', '["backend-service", "worker", "ml-pipeline", "inference-service", "webhook-handler", "cli-tool", "shared-library"]', '{"purpose": "The default language for data/ML-adjacent backends and a first-class choice for typed API services (FastAPI + Pydantic). Spans API services, workers, ML pipelines, inference services, webhook handlers and CLIs — when the component touches the data/ML ecosystem, Python is usually the honest pick.", "configMode": "code", "provenance": {"notes": "Stable stack facts (uv consolidation, FastAPI/Pydantic defaults); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["FastAPI + Pydantic", "uv", "ruff", "pyright", "pytest", "SQLAlchemy/SQLModel", "Celery/arq", "httpx"], "antiPatterns": ["Blocking I/O inside async routes (sync DB drivers, requests) — kills the event loop invisibly", "requirements.txt without pins in a production service", "Django for a pure JSON API where FastAPI is lighter — Django earns its weight only when the admin/ORM/auth batteries are used", "Global mutable module state as a cache — breaks under multiple workers"], "apiReference": {"docsUrl": "https://docs.python.org/3/"}, "bestPractices": ["Type hints everywhere + Pydantic models at every boundary — FastAPI turns them into validation and OpenAPI for free", "uv for env + deps (committed lockfile, pinned python version); one venv per service", "Async where the framework is async — mixing blocking calls (requests, raw psycopg) into async handlers is the classic FastAPI foot-gun; use httpx/asyncpg", "Workers: Celery or arq with explicit idempotency — Python queue consumers WILL be redelivered", "ruff for lint+format (one tool), pytest with fixtures over unittest classes"], "sdkInitPattern": "pip install fastapi uvicorn sqlalchemy pydantic-settings\\n# main.py\\nfrom fastapi import FastAPI\\napp = FastAPI()\\n\\n@app.get(\"/health\")\\ndef health(): return {\"status\": \"ok\"}\\n\\n# uvicorn main:app --reload", "securityGuidance": "Use Pydantic models for automatic input validation on all endpoints. Use parameterized queries via SQLAlchemy ORM, never raw string interpolation. Set CORS middleware with explicit allowed origins. Use python-jose or PyJWT for JWT validation. Pin dependencies and use pip-audit for vulnerability scanning. Never run uvicorn with --reload in production.", "commonApiPatterns": [{"name": "REST Endpoint", "description": "FastAPI endpoint with dependency injection and response model", "codeTemplate": "@app.get(\"/api/users/{user_id}\", response_model=UserResponse)\\nasync def get_user(user_id: int, db: AsyncSession = Depends(get_db)):\\n    user = await db.get(User, user_id)\\n    if not user:\\n        raise HTTPException(status_code=404, detail=\"User not found\")\\n    return user"}, {"name": "Dependency Injection", "description": "Composable dependency chain for DB sessions and auth", "codeTemplate": "async def get_db() -> AsyncGenerator[AsyncSession, None]:\\n    async with async_session() as session:\\n        yield session\\n\\nasync def get_current_user(token: str = Depends(oauth2_scheme), db: AsyncSession = Depends(get_db)) -> User:\\n    payload = verify_token(token)\\n    return await db.get(User, payload[\"sub\"])"}, {"name": "Background Task", "description": "Celery task for async background processing", "codeTemplate": "from celery import Celery\\ncelery_app = Celery(\"tasks\", broker=\"redis://localhost:6379\")\\n\\n@celery_app.task\\ndef send_email(to: str, subject: str, body: str):\\n    smtp_client.send(to=to, subject=subject, body=body)"}], "integrationPatterns": ["FastAPI or Flask for HTTP framework with automatic OpenAPI docs", "SQLAlchemy 2.0 with asyncio for async database access", "Celery or ARQ for distributed task queues", "Pydantic for data validation and settings management", "pytest with httpx.AsyncClient for async API testing"], "configurationTemplate": "# pyproject.toml\\n[project]\\nname = \"myapp\"\\nversion = \"1.0.0\"\\nrequires-python = \">=3.11\"\\ndependencies = [\\n    \"fastapi>=0.110.0\",\\n    \"uvicorn[standard]>=0.27.0\",\\n    \"sqlalchemy[asyncio]>=2.0.0\",\\n    \"pydantic-settings>=2.0.0\",\\n]\\n\\n[tool.ruff]\\ntarget-version = \"py311\"\\nselect = [\"E\", \"F\", \"I\", \"UP\"]\\n\\n[tool.mypy]\\nstrict = true\\nplugins = [\"pydantic.mypy\"]"}', '[{"kind": "source", "path": "src/main.py", "language": "python", "description": "Application entry point"}, {"kind": "source", "path": "src/routes/__init__.py", "language": "python", "description": "Route definitions"}, {"kind": "config", "path": "pyproject.toml", "language": "toml", "description": "Python project manifest"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "fastapi", "options": ["fastapi", "django", "flask", "none-script"], "description": "FastAPI = typed async APIs (the default for services); Django = batteries-included product apps with admin; Flask = small and legacy codebases"}, "packaging": {"type": "enum", "label": "Packaging / env", "default": "uv", "options": ["uv", "poetry", "pip-requirements"], "description": "uv is the 2026 default (fast, lockfile, python-version management in one tool); poetry legacy-fine; bare requirements.txt only for throwaway scripts"}, "typeChecking": {"type": "enum", "label": "Type checking", "default": "pyright", "options": ["pyright", "mypy", "none"]}}', '["database", "cache", "message-broker", "ai-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', 'Python', '#2D5F89', '''/health'':74C ''allow'':111C ''api'':18B,23B ''app'':84C ''audit'':128C ''automat'':90C ''backend'':3A,9B ''celery/arq'':54C ''choic'':15B ''class'':14B ''clis'':33B ''compon'':36B ''cor'':107C ''data/ml'':39B ''data/ml-adjacent'':8B ''default'':5B ''depend'':123C ''ecosystem'':40B ''endpoint'':95C ''explicit'':110C ''fastapi'':20B,47C,58C,67C,69C,71C ''first'':13B ''first-class'':12B ''handler'':31B ''health'':76C ''honest'':45B ''httpx'':55C ''import'':68C ''infer'':28B ''input'':91C ''instal'':57C ''interpol'':105C ''jose'':116C ''jwt'':120C ''languag'':6B ''main'':83C ''main.py'':65C ''middlewar'':108C ''ml'':26B ''model'':88C ''n'':64C,72C,80C,81C ''n@app.get'':73C ''napp'':70C ''ndef'':75C ''never'':102C,132C ''nfrom'':66C ''ok'':79C ''origin'':112C ''orm'':101C ''parameter'':97C ''pick'':46B ''pin'':122C ''pip'':56C,127C ''pip-audit'':126C ''pipelin'':27B ''product'':138C ''pydant'':21B,48C,62C,87C ''pydantic-set'':61C ''pyjwt'':118C ''pyright'':51C ''pytest'':52C ''python'':1A,2A,41B,115C ''python-jos'':114C ''queri'':98C ''raw'':103C ''reload'':85C,136C ''return'':77C ''ruff'':50C ''run'':133C ''scan'':131C ''servic'':19B,24B,29B ''set'':63C,106C ''span'':22B ''sqlalchemi'':60C,100C ''sqlalchemy/sqlmodel'':53C ''status'':78C ''string'':104C ''touch'':37B ''type'':17B ''use'':86C,96C,113C,125C ''usual'':43B ''uv'':49C ''uvicorn'':59C,82C,134C ''valid'':92C,121C ''via'':99C ''vulner'':130C ''webhook'':30B ''worker'':25B');
INSERT INTO public.technology_catalog VALUES ('godot', 'Godot', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/godot.png', '#478CBF', '["desktop-app", "mobile-app", "game-client"]', '{"purpose": "Open-source game engine for 2D and 3D games with its own GDScript language, C# support, and a scene-tree architecture", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Godot 4+", "GDScript", "C#", "GDExtension", "Godot Shading Language", "GUT (testing framework)"], "antiPatterns": ["Overusing get_node() with hardcoded paths instead of exported NodePaths", "Not using signals, creating tight coupling between nodes", "Putting all logic in _process without delta time consideration", "Creating deep node hierarchies instead of flat compositions", "Not using typed GDScript (static typing) for better performance and safety", "Ignoring the scene instancing system and duplicating node trees"], "apiReference": {"docsUrl": "https://docs.godotengine.org/en/stable/"}, "bestPractices": ["Use the scene tree and node composition for game architecture", "Leverage signals for decoupled communication between nodes", "Use resources (tres/res) for shared data and configuration", "Implement autoloads (singletons) sparingly for global state", "Use GDScript for gameplay logic and C# for complex systems", "Leverage AnimationPlayer and AnimationTree for state machines", "Use TileMaps and TileSets for 2D level design", "Export custom properties with @export for editor-configurable values"], "sdkInitPattern": "# player.gd — client input, server authority via MultiplayerAPI\nextends CharacterBody3D\n\nfunc _physics_process(delta: float) -> void:\n    if not is_multiplayer_authority():\n        return\n    var input := Input.get_vector(\"left\", \"right\", \"forward\", \"back\")\n    move_intent.rpc_id(1, input)  # send intent to server (peer 1), never position\n\n@rpc(\"any_peer\", \"call_remote\", \"unreliable_ordered\")\nfunc move_intent(input: Vector2) -> void:\n    if multiplayer.get_remote_sender_id() != get_multiplayer_authority():\n        return  # reject spoofed intents\n    velocity = _simulate(input)  # server simulates; clients receive replicated state", "securityGuidance": "The shipped game is fully inspectable — GDScript decompiles trivially and PCK files unpack, so no API keys, no server credentials, and no authoritative logic in the client: purchases, scores, and inventory mutations happen on a backend the player cannot edit. In multiplayer, clients send INTENT (input) and the server simulates — validate every RPC server-side (sender identity, argument bounds, rate) because @rpc(\"any_peer\") means exactly that. Savegames are user-editable files: sign or checksum what matters competitively, and never load untrusted .tscn/.gd content — instancing a scene executes its scripts."}', '[{"kind": "source", "path": "scripts/main.gd", "language": "gdscript", "description": "Main game script"}, {"kind": "source", "path": "scenes/main.tscn", "language": "tscn", "description": "Main scene"}, {"kind": "config", "path": "project.godot", "language": "ini", "description": "Godot project configuration"}, {"kind": "config", "path": "export_presets.cfg", "language": "ini", "description": "Export target presets"}]', '{"targets": {"type": "multiselect", "label": "Targets", "options": ["desktop", "mobile", "web"], "description": "One project, one node — export targets are configuration (the 4d platform-targets rule)"}, "language": {"type": "enum", "label": "Language", "default": "gdscript", "options": ["gdscript", "csharp"]}}', '["rest-api", "database"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-31 20:06:52.233344+00', 'Godot', NULL, '''1'':68C,75C ''2d'':9B ''3d'':11B ''4'':27C ''api'':127C ''architectur'':25B ''argument'':170C ''author'':41C,56C,98C ''authorit'':134C ''back'':65C ''backend'':147C ''bound'':171C ''c'':18B,29C ''call'':81C ''cannot'':150C ''characterbody3d'':45C ''checksum'':188C ''client'':38C,108C,138C,154C ''competit'':191C ''content'':197C ''credenti'':131C ''decompil'':119C ''delta'':49C ''edit'':151C,184C ''engin'':7B ''everi'':163C ''exact'':178C ''execut'':201C ''extend'':44C ''file'':123C,185C ''float'':50C ''forward'':64C ''framework'':36C ''fulli'':116C ''func'':46C,85C ''game'':6B,12B,114C ''gdextens'':30C ''gdscript'':16B,28C,118C ''get'':96C ''godot'':1A,2A,26C,31C ''gut'':34C ''happen'':144C ''id'':67C,95C ''ident'':169C ''input'':39C,59C,69C,88C,105C,157C ''input.get'':60C ''inspect'':117C ''instanc'':198C ''intent'':71C,87C,102C,156C ''inventori'':142C ''key'':128C ''languag'':17B,33C ''left'':62C ''load'':194C ''logic'':135C ''matter'':190C ''mean'':177C ''move'':86C ''move_intent.rpc'':66C ''multiplay'':55C,97C,153C ''multiplayer.get'':92C ''multiplayerapi'':43C ''mutat'':143C ''never'':76C,193C ''open'':4B ''open-sourc'':3B ''order'':84C ''pck'':122C ''peer'':74C,80C,176C ''physic'':47C ''player'':149C ''player.gd'':37C ''posit'':77C ''process'':48C ''purchas'':139C ''rate'':172C ''receiv'':109C ''reject'':100C ''remot'':82C,93C ''replic'':110C ''return'':57C,99C ''right'':63C ''rpc'':78C,164C,174C ''savegam'':180C ''scene'':23B,200C ''scene-tre'':22B ''score'':140C ''script'':203C ''send'':70C,155C ''sender'':94C,168C ''server'':40C,73C,106C,130C,160C,166C ''server-sid'':165C ''shade'':32C ''ship'':113C ''side'':167C ''sign'':186C ''simul'':104C,107C,161C ''sourc'':5B ''spoof'':101C ''state'':111C ''support'':19B ''test'':35C ''tree'':24B ''trivial'':120C ''tscn/.gd'':196C ''unpack'':124C ''unreli'':83C ''untrust'':195C ''user'':183C ''user-edit'':182C ''valid'':162C ''var'':58C ''vector'':61C ''vector2'':89C ''veloc'':103C ''via'':42C ''void'':51C,90C');
INSERT INTO public.technology_catalog VALUES ('kotlin-android', 'Kotlin (Android)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/kotlin-android.png', '#7F52FF', '["mobile-app"]', '{"purpose": "JetBrains'' modern language for native Android development, now Google''s preferred language for Android. Kotlin with Jetpack Compose provides a declarative, type-safe UI framework for building Android applications. Use when building Android-specific apps that need deep platform integration -- Google Play services, Android widgets, Wear OS, Android Auto, or advanced camera and sensor APIs. Native Kotlin apps deliver the best performance and most complete access to Android platform capabilities. Don''t use when you need cross-platform iOS support from the same codebase -- use Flutter, React Native, or Kotlin Multiplatform instead. Don''t use for simple content apps where a cross-platform solution reduces development cost. Consider Kotlin Multiplatform for sharing business logic with iOS while keeping native UI on each platform.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Kotlin", "Jetpack Compose", "Android Studio", "Hilt", "Room", "Retrofit/Ktor", "Kotlin Coroutines", "Gradle Version Catalog"], "antiPatterns": ["Using Java patterns in Kotlin (verbose builders instead of DSLs, nullable types everywhere)", "Not using coroutines and falling back to callbacks or RxJava for simple async", "Putting business logic in Activities/Fragments instead of ViewModels", "Using GlobalScope for coroutines instead of lifecycle-aware scopes", "Not handling configuration changes (rotation) causing state loss", "Ignoring ProGuard/R8 configuration causing runtime crashes in release builds"], "apiReference": {"docsUrl": "https://developer.android.com/docs"}, "bestPractices": ["Use Jetpack Compose for new UI development instead of XML layouts", "Follow MVVM with ViewModel and StateFlow for reactive state management", "Use Kotlin coroutines and Flow for asynchronous operations", "Implement Hilt for dependency injection", "Use Room or SQLDelight for local database persistence", "Write unit tests with JUnit5 and UI tests with Compose Testing", "Use Version Catalog (libs.versions.toml) for centralized dependency management"], "sdkInitPattern": "// Android Studio: New Project > Empty Activity (Compose)\\n// MainActivity.kt\\nclass MainActivity : ComponentActivity() {\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContent {\\n            MyAppTheme {\\n                Text(\"Hello Kotlin\")\\n            }\\n        }\\n    }\\n}", "securityGuidance": "Use EncryptedSharedPreferences or Android Keystore for storing credentials. Enable network security config to enforce HTTPS. Use certificate pinning for sensitive API connections. Enable ProGuard/R8 for release builds to obfuscate code. Never embed API keys in Java/Kotlin source -- use BuildConfig fields from local.properties or CI secrets. Use biometric authentication via BiometricPrompt for sensitive operations.", "commonApiPatterns": [{"name": "Compose UI with State", "description": "Composable function with remember state", "codeTemplate": "@Composable\\nfun Counter() {\\n    var count by remember { mutableIntStateOf(0) }\\n    Column(horizontalAlignment = Alignment.CenterHorizontally) {\\n        Text(\"Count: $count\", style = MaterialTheme.typography.headlineMedium)\\n        Button(onClick = { count++ }) { Text(\"Increment\") }\\n    }\\n}"}, {"name": "ViewModel with StateFlow", "description": "Hilt-injected ViewModel with sealed UiState and coroutines", "codeTemplate": "@HiltViewModel\\nclass UserViewModel @Inject constructor(private val repo: UserRepository) : ViewModel() {\\n    private val _uiState = MutableStateFlow<UiState>(UiState.Loading)\\n    val uiState = _uiState.asStateFlow()\\n    init {\\n        viewModelScope.launch {\\n            _uiState.value = try { UiState.Success(repo.getUsers()) } catch (e: Exception) { UiState.Error(e.message ?: \"Unknown error\") }\\n        }\\n    }\\n}"}, {"name": "Navigation", "description": "Jetpack Navigation Compose with arguments", "codeTemplate": "NavHost(navController = navController, startDestination = \"home\") {\\n    composable(\"home\") { HomeScreen(onUserClick = { navController.navigate(\"user/$it\") }) }\\n    composable(\"user/{id}\") { backStackEntry ->\\n        UserScreen(userId = backStackEntry.arguments?.getString(\"id\")!!)\\n    }\\n}"}], "setupInstructions": [{"url": "https://play.google.com/console", "type": "console", "title": "Create the Play Console developer account", "required": true, "instructions": "One-time $25 registration; identity verification can take days. Organization accounts need a D-U-N-S number."}, {"type": "console", "title": "Create the app + store listing", "required": true, "instructions": "Application ID (package name) is permanent once published. Listing needs the data-safety form, content rating questionnaire and privacy policy URL before ANY track can publish."}, {"type": "console", "title": "Signing: upload key + Play App Signing", "required": true, "instructions": "Generate an upload keystore and enroll in Play App Signing (Google holds the release key, you hold the upload key). Losing a legacy self-managed release key is unrecoverable — always enroll."}, {"type": "console", "title": "Internal testing track first", "required": false, "instructions": "Internal track publishes in minutes with no review — wire CI to it before touching production. New personal accounts also need a closed-testing period before production access."}, {"type": "manual", "title": "Production release + review", "required": true, "instructions": "Staged rollout by percentage is the default safety net — start at a low percentage and watch vitals before 100%."}], "integrationPatterns": ["Firebase or Supabase Kotlin SDK for backend services (auth, database, messaging)", "Retrofit or Ktor Client for type-safe HTTP API communication", "GitHub Actions or Gradle Play Publisher for CI/CD to Google Play"], "configurationTemplate": "// build.gradle.kts (app module)\\nplugins {\\n    alias(libs.plugins.android.application)\\n    alias(libs.plugins.kotlin.android)\\n    alias(libs.plugins.kotlin.compose)\\n    alias(libs.plugins.hilt.android)\\n    alias(libs.plugins.ksp)\\n}\\nandroid {\\n    namespace = \"com.example.myapp\"\\n    compileSdk = 34\\n    defaultConfig {\\n        minSdk = 26\\n        targetSdk = 34\\n    }\\n    buildFeatures { compose = true }\\n}"}', '[{"kind": "config", "path": "build.gradle.kts", "language": "kotlin", "description": "Gradle build configuration"}, {"kind": "source", "path": "app/src/main/java/MainActivity.kt", "language": "kotlin", "description": "Main Activity with Compose UI"}, {"kind": "config", "path": "app/src/main/AndroidManifest.xml", "language": "xml", "description": "Android application manifest"}, {"kind": "source", "path": "app/src/main/java/ui/theme/Theme.kt", "language": "kotlin", "description": "Compose theme configuration"}, {"kind": "source", "path": "app/src/test/ExampleUnitTest.kt", "language": "kotlin", "description": "Unit test suite"}]', '{"di": {"type": "enum", "label": "Dependency injection", "default": "hilt", "options": ["hilt", "koin", "manual"]}, "ui": {"type": "enum", "label": "UI", "default": "jetpack-compose", "options": ["jetpack-compose", "xml-views-legacy", "mixed"], "description": "Compose is the standing default for new apps"}, "async": {"type": "enum", "label": "Async model", "default": "coroutines-flow", "options": ["coroutines-flow", "rxjava-legacy"]}, "persistence": {"type": "enum", "label": "Persistence", "default": "room", "options": ["room", "datastore-only", "none-api-only"]}, "distribution": {"type": "enum", "label": "Distribution", "default": "play-store", "options": ["play-store", "internal-testing", "enterprise-sideload"], "description": "Play Console setup, signing keys and review are MANUAL steps, not code"}}', '["web.rest-api", "auth.supabase-auth", "database.firebase"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-31 20:06:52.233344+00', NULL, '#6B3FE6', '''access'':72B ''activ'':150C ''advanc'':57B ''android'':2A,4A,10B,18B,33B,39B,50B,54B,74B,135C,145C,181C ''android-specif'':38B ''api'':61B,198C,210C ''app'':41B,64B,106B ''applic'':34B ''authent'':225C ''auto'':55B ''best'':67B ''biometr'':224C ''biometricprompt'':227C ''build'':32B,37B,204C ''buildconfig'':216C ''bundl'':162C ''busi'':121B ''camera'':58B ''capabl'':76B ''catalog'':144C ''certif'':194C ''ci'':221C ''code'':207C ''codebas'':91B ''complet'':71B ''componentact'':156C ''compos'':22B,134C,151C ''config'':189C ''connect'':199C ''consid'':116B ''content'':105B ''coroutin'':141C ''cost'':115B ''credenti'':185C ''cross'':84B,110B ''cross-platform'':83B,109B ''declar'':25B ''deep'':44B ''deliv'':65B ''develop'':11B,114B ''emb'':209C ''empti'':149C ''enabl'':186C,200C ''encryptedsharedprefer'':179C ''enforc'':191C ''field'':217C ''flutter'':93B ''framework'':30B ''fun'':159C ''googl'':13B,47B ''gradl'':142C ''hello'':172C ''hilt'':137C ''https'':192C ''instead'':99B ''integr'':46B ''io'':86B,124B ''java/kotlin'':213C ''jetbrain'':5B ''jetpack'':21B,133C ''keep'':126B ''key'':211C ''keystor'':182C ''kotlin'':1A,3A,19B,63B,97B,117B,132C,140C,173C ''languag'':7B,16B ''local.properties'':219C ''logic'':122B ''mainact'':155C ''mainactivity.kt'':153C ''modern'':6B ''multiplatform'':98B,118B ''myappthem'':169C ''n'':152C,157C,163C,166C,168C,170C,174C,175C,176C,177C ''nativ'':9B,62B,95B,127B ''nclass'':154C ''need'':43B,82B ''network'':187C ''never'':208C ''new'':147C ''obfusc'':206C ''oncreat'':160C ''oper'':230C ''os'':53B ''overrid'':158C ''perform'':68B ''pin'':195C ''platform'':45B,75B,85B,111B,131B ''play'':48B ''prefer'':15B ''proguard/r8'':201C ''project'':148C ''provid'':23B ''react'':94B ''reduc'':113B ''releas'':203C ''retrofit/ktor'':139C ''room'':138C ''safe'':28B ''savedinstancest'':161C,165C ''secret'':222C ''secur'':188C ''sensit'':197C,229C ''sensor'':60B ''servic'':49B ''setcont'':167C ''share'':120B ''simpl'':104B ''solut'':112B ''sourc'':214C ''specif'':40B ''store'':184C ''studio'':136C,146C ''super.oncreate'':164C ''support'':87B ''text'':171C ''type'':27B ''type-saf'':26B ''ui'':29B,128B ''use'':35B,79B,92B,102B,178C,193C,215C,223C ''version'':143C ''via'':226C ''wear'':52B ''widget'':51B');
INSERT INTO public.technology_catalog VALUES ('php-backend', 'PHP', NULL, '#777BB4', '["backend-service", "webhook-handler", "cli-tool"]', '{"purpose": "Server-side language powering a huge share of the production web. Modern PHP (8.4/8.5 era) is typed, fast and framework-driven: Laravel (current major: 13, 2026-02) is the default choice for product work — full-stack conventions, Eloquent ORM, queues, scheduling; Symfony for component-driven architectures. Serve via php-fpm (the boring default) or FrankenPHP + Octane where high concurrency pays.", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Laravel 13", "Composer", "Eloquent ORM", "PHPStan", "Pest/PHPUnit", "php-fpm", "FrankenPHP + Octane", "Horizon queues"], "antiPatterns": ["Writing 2010-era PHP (no types, raw superglobals, include-based routing) — an AI generating legacy-style PHP is producing liability", "Composer dependencies without a committed lock file", "Long-running state in Octane/FrankenPHP workers without resetting per-request state — the classic share-nothing assumption no longer holds there", "Hand-rolled auth/password handling when the framework ships hardened primitives"], "apiReference": {"docsUrl": "https://www.php.net/docs.php"}, "bestPractices": ["Laravel unless there is a reason not to — conventions, first-party packages (queues, auth, billing) and the largest hiring pool", "composer.lock committed; declare the PHP version in composer.json require.php and pin the runtime image to it", "Static analysis from day one (PHPStan or Psalm at a meaningful level) — modern PHP is typed, use it", "Queues for anything slow (Laravel queues + Horizon); HTTP requests do not send emails or call slow third parties inline", "FrankenPHP + Octane for high-concurrency deployments — but the octane:install static binary is PHP-8.4-locked; match the binary to the app''s PHP version deliberately"], "sdkInitPattern": "<?php\ndeclare(strict_types=1);\n\n$pdo = new PDO($_ENV[''DATABASE_DSN''], $_ENV[''DB_USER''], $_ENV[''DB_PASS''], [\n    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\n    PDO::ATTR_EMULATE_PREPARES => false,\n]);\n\n$stmt = $pdo->prepare(''SELECT * FROM orders WHERE owner_id = :owner'');\n$stmt->execute([''owner'' => $userId]);\n$orders = $stmt->fetchAll(PDO::FETCH_ASSOC);", "securityGuidance": "PDO prepared statements with emulation off — string-built SQL is the canonical PHP breach. Never unserialize() untrusted input (object injection is RCE; use JSON), never pass user input to include/require paths or shell functions (escapeshellarg if unavoidable), and htmlspecialchars on output unless a template engine escapes by default. password_hash/password_verify for credentials, session cookies HttpOnly+Secure+SameSite with session_regenerate_id on login, uploads validated by content and stored outside the web root, and display_errors off in production."}', '[{"kind": "config", "path": "composer.json"}, {"kind": "source", "path": "app/Http/Controllers/"}, {"kind": "source", "path": "routes/web.php"}, {"kind": "config", "path": "phpstan.neon"}]', '{"serving": {"type": "enum", "label": "Serving model", "default": "php-fpm", "options": ["php-fpm", "frankenphp-octane"], "description": "php-fpm = the boring share-nothing default; FrankenPHP+Octane = persistent workers for high concurrency (state-reset discipline required)"}, "framework": {"type": "enum", "label": "Framework", "default": "laravel", "options": ["laravel", "symfony", "plain-php"], "description": "Laravel is the product-work default; Symfony for component-driven builds; plain PHP only for tiny scripts"}, "staticAnalysis": {"type": "enum", "label": "Static analysis", "default": "phpstan", "options": ["phpstan", "psalm", "none"]}}', '[{"id": "postgresql", "reason": "Primary relational store via Eloquent/Doctrine"}, {"id": "redis", "reason": "Queues, cache and session store"}, {"id": "stripe", "reason": "Laravel Cashier is the standing billing integration"}]', false, NULL, NULL, '2026-08-31 20:06:50.522268+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''-02'':33B ''/8.5'':19B ''1'':88C ''13'':31B,71C ''2026'':32B ''8.4'':18B ''architectur'':54B ''assoc'':131C ''attr'':102C,108C ''backend'':3A ''bore'':61B ''breach'':146C ''built'':140C ''canon'':144C ''choic'':37B ''compon'':52B ''component-driven'':51B ''compos'':72C ''concurr'':68B ''content'':199C ''convent'':44B ''cooki'':186C ''credenti'':184C ''current'':29B ''databas'':93C ''db'':96C,99C ''declar'':85C ''default'':36B,62B,180C ''display'':207C ''driven'':27B,53B ''dsn'':94C ''eloqu'':45B,73C ''emul'':109C,136C ''engin'':177C ''env'':92C,95C,98C ''era'':20B ''errmod'':103C,105C ''error'':208C ''escap'':178C ''escapeshellarg'':167C ''except'':106C ''execut'':123C ''fals'':111C ''fast'':23B ''fetch'':130C ''fetchal'':128C ''fpm'':59B,79C ''framework'':26B ''framework-driven'':25B ''frankenphp'':64B,80C ''full'':42B ''full-stack'':41B ''function'':166C ''hash/password_verify'':182C ''high'':67B ''horizon'':82C ''htmlspecialchar'':171C ''httpon'':187C ''huge'':10B ''id'':120C,193C ''include/require'':162C ''inject'':152C ''input'':150C,160C ''json'':156C ''languag'':7B ''laravel'':28B,70C ''login'':195C ''major'':30B ''modern'':16B ''never'':147C,157C ''new'':90C ''object'':151C ''octan'':65B,81C ''order'':117C,126C ''orm'':46B,74C ''output'':173C ''outsid'':202C ''owner'':119C,121C,124C ''pass'':100C,158C ''password'':181C ''path'':163C ''pay'':69B ''pdo'':89C,91C,101C,104C,107C,113C,129C,132C ''pest/phpunit'':76C ''php'':1A,2A,17B,58B,78C,84C,145C ''php-fpm'':57B,77C ''phpstan'':75C ''power'':8B ''prepar'':110C,114C,133C ''product'':14B,39B,211C ''queue'':47B,83C ''rce'':154C ''regener'':192C ''root'':205C ''samesit'':189C ''schedul'':48B ''secur'':188C ''select'':115C ''serv'':55B ''server'':5B ''server-sid'':4B ''session'':185C,191C ''share'':11B ''shell'':165C ''side'':6B ''sql'':141C ''stack'':43B ''statement'':134C ''stmt'':112C,122C,127C ''store'':201C ''strict'':86C ''string'':139C ''string-built'':138C ''symfoni'':49B ''templat'':176C ''type'':22B,87C ''unavoid'':169C ''unless'':174C ''unseri'':148C ''untrust'':149C ''upload'':196C ''use'':155C ''user'':97C,159C ''userid'':125C ''valid'':197C ''via'':56B ''web'':15B,204C ''work'':40B');
INSERT INTO public.technology_catalog VALUES ('tauri', 'Tauri', NULL, '#FFC131', '["desktop-app"]', '{"purpose": "Framework for building lightweight cross-platform desktop applications with a Rust backend and any web frontend, using the OS native webview instead of bundled Chromium", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Tauri", "Rust", "WebView2", "WKWebView", "tauri-bundler", "tauri-plugin-updater", "serde", "tokio"], "antiPatterns": ["Using allowlist: all instead of scoping permissions per capability", "Blocking the main thread with synchronous Rust commands", "Not validating IPC payloads from the frontend in command handlers", "Skipping code signing which prevents auto-update and triggers OS warnings", "Bundling native Node.js modules (Tauri does not ship Node.js)"], "apiReference": {"docsUrl": "https://tauri.app/start/"}, "bestPractices": ["Use Tauri commands (invoke) for frontend-to-Rust IPC instead of raw events", "Define granular capability permissions in src-tauri/capabilities/", "Keep the Rust backend thin; delegate heavy logic to async tasks with tokio", "Use tauri-plugin-store for persistent key-value storage", "Enable the updater plugin with code signing for automatic updates", "Build universal binaries for macOS (aarch64 + x86_64)", "Use the Tauri CLI (cargo tauri build) for reproducible cross-platform builds", "Leverage sidecar binaries for shipping CLI tools alongside the app"], "securityGuidance": "The capability system is the security model — grant the webview only the specific commands and scoped paths/urls it needs (a broad fs or shell scope hands web content the machine), and keep the CSP strict: the webview renders your UI but any injected script speaks to your Rust commands with the app''s privileges. Validate every command''s arguments in Rust as untrusted input, never build shell invocations from webview strings, ship updates only through the signed updater (the signing key lives in CI secrets, not the repo), and pin remote content out — loading arbitrary remote pages into a privileged webview recreates Electron''s classic mistake.", "setupInstructions": [{"url": "https://www.rust-lang.org/tools/install", "type": "toolchain_install", "title": "Install Rust Toolchain", "commands": ["curl --proto =https --tlsv1.2 -sSf https://sh.rustup.rs | sh", "rustup update stable"], "required": true, "instructions": "Install Rust via rustup. Tauri requires a stable Rust compiler."}, {"type": "toolchain_install", "title": "Install OS Dependencies", "commands": ["# Linux (Debian/Ubuntu):", "sudo apt-get install libwebkit2gtk-4.1-dev build-essential curl wget file libxdo-dev libssl-dev libayatana-appindicator3-dev librsvg2-dev", "# macOS:", "xcode-select --install"], "required": true, "instructions": "Install platform-specific webview and build dependencies: Windows needs WebView2 (pre-installed on Win11), Linux needs webkit2gtk and related libs, macOS needs Xcode Command Line Tools."}, {"type": "dashboard_config", "title": "Configure tauri.conf.json", "required": true, "instructions": "Edit src-tauri/tauri.conf.json to set your app identifier (reverse domain), window title, size, and permissions. The identifier cannot change after distribution."}, {"type": "certificate", "title": "Set Up Code Signing", "commands": ["# macOS env vars:", "export APPLE_CERTIFICATE=<base64-p12>", "export APPLE_CERTIFICATE_PASSWORD=<password>", "export APPLE_ID=<apple-id>", "export APPLE_PASSWORD=<app-specific-password>"], "required": false, "instructions": "For macOS: configure Apple Developer certificate and notarization credentials. For Windows: set up Authenticode certificate. Tauri CLI handles signing during build if credentials are provided via env vars."}], "configurationTemplate": "// src-tauri/tauri.conf.json\n{\n  \"productName\": \"app\",\n  \"identifier\": \"com.example.app\",\n  \"app\": {\n    \"security\": {\n      \"csp\": \"default-src ''self''; connect-src ''self'' https://api.example.com\"\n    }\n  },\n  \"bundle\": { \"targets\": \"all\" }\n}\n// capabilities/main.json grants the webview ONLY the commands + scopes it needs"}', '[{"kind": "config", "path": "src-tauri/tauri.conf.json", "language": "json", "description": "Tauri application configuration (windows, security, bundler)"}, {"kind": "source", "path": "src-tauri/src/main.rs", "language": "rust", "description": "Tauri Rust backend entry point"}, {"kind": "source", "path": "src-tauri/src/commands.rs", "language": "rust", "description": "Tauri command handlers invoked from frontend"}, {"kind": "config", "path": "src-tauri/Cargo.toml", "language": "toml", "description": "Rust dependencies for the Tauri sidecar"}, {"kind": "config", "path": "src-tauri/capabilities/default.json", "language": "json", "description": "Tauri v2 capability permissions for IPC and system access"}, {"kind": "config", "path": "src-tauri/build.rs", "language": "rust", "description": "Tauri build script for compile-time setup"}, {"kind": "config", "path": "src-tauri/icons/icon.png", "description": "Application icon source for all platform targets"}]', '{"targets": {"type": "multiselect", "label": "Build targets", "options": ["windows", "macos", "linux"], "description": "Signing/notarization are per-OS manual setup"}, "updater": {"type": "boolean", "label": "Built-in updater", "default": true}, "ipcSurface": {"type": "enum", "label": "Backend surface", "default": "commands-rust", "options": ["commands-rust", "sidecar-binary", "minimal-shell"], "description": "Tauri commands are Rust functions the UI invokes — the real app logic boundary"}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "react", "options": ["react", "vue", "svelte", "solid", "vanilla"], "description": "The web framework rendering inside Tauri — this node IS the desktop app; the backend is Rust commands"}, "capabilities": {"type": "boolean", "label": "Capability-scoped permissions", "default": true, "description": "Tauri v2 permissions: each window gets only the APIs its capability file grants"}}', '["frontend-app", "rest-api", "database"]', false, NULL, NULL, '2026-03-16 02:23:33.717373+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''app'':93C ''applic'':11B ''arbitrari'':136C ''argument'':100C ''backend'':15B ''broad'':62C ''build'':5B,107C ''bundl'':27B ''bundler'':35C ''capabl'':43C ''chromium'':28B ''ci'':125C ''classic'':146C ''command'':55C,90C,98C ''content'':69C,133C ''cross'':8B ''cross-platform'':7B ''csp'':75C ''desktop'':10B ''electron'':144C ''everi'':97C ''framework'':3B ''frontend'':19B ''fs'':63C ''grant'':49C ''hand'':67C ''inject'':84C ''input'':105C ''instead'':25B ''invoc'':109C ''keep'':73C ''key'':122C ''lightweight'':6B ''live'':123C ''load'':135C ''machin'':71C ''mistak'':147C ''model'':48C ''nativ'':23B ''need'':60C ''never'':106C ''os'':22B ''page'':138C ''paths/urls'':58C ''pin'':131C ''platform'':9B ''plugin'':38C ''privileg'':95C,141C ''recreat'':143C ''remot'':132C,137C ''render'':79C ''repo'':129C ''rust'':14B,30C,89C,102C ''scope'':57C,66C ''script'':85C ''secret'':126C ''secur'':47C ''serd'':40C ''shell'':65C,108C ''ship'':113C ''sign'':118C,121C ''speak'':86C ''specif'':54C ''strict'':76C ''string'':112C ''system'':44C ''tauri'':1A,2A,29C,34C,37C ''tauri-bundl'':33C ''tauri-plugin-updat'':36C ''tokio'':41C ''ui'':81C ''untrust'':104C ''updat'':39C,114C,119C ''use'':20B ''valid'':96C ''web'':18B,68C ''webview'':24B,51C,78C,111C,142C ''webview2'':31C ''wkwebview'':32C');
INSERT INTO public.technology_catalog VALUES ('go-backend', 'Go', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/go-backend.png', '#00add8', '["backend-service", "worker", "webhook-handler", "cli-tool", "shared-library"]', '{"purpose": "The infrastructure-and-services language: single static binary, first-class concurrency, boring deployments. Default choice for network services, CLIs and anything that ships as one binary into a container. Its standard library carries more of the app than in any other mainstream stack.", "configMode": "code", "provenance": {"notes": "Stable idioms (stdlib-first, sqlc, race detector); live-docs upgrade rides N10(b). Row previously had EMPTY ai_context.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["net/http (1.22+ routing)", "sqlc", "pgx", "golangci-lint", "go test -race", "single-binary Docker images"], "antiPatterns": ["Goroutine leaks — every `go` needs an exit story (context cancellation or channel close)", "interface{} / any where a concrete type or small interface would do", "Framework-first architectures imported from other ecosystems (heavy DI containers, fat middleware stacks)", "Ignoring the error return — the linter catches it, wire the linter (golangci-lint)"], "apiReference": {"docsUrl": "https://go.dev/doc/"}, "bestPractices": ["Start with the stdlib (net/http with 1.22+ routing, database/sql) — add frameworks only when a concrete need appears", "Errors are values: wrap with %w, check with errors.Is/As; no panic in library/service code", "Context on every request path — cancellation and deadlines through every layer", "sqlc for data access: write SQL, generate typed Go — reviewable queries beat ORM magic", "Table-driven tests + the race detector in CI (go test -race)"], "sdkInitPattern": "go mod init myapp\\n// main.go\\npackage main\\n\\nimport (\\n  \"log\"\\n  \"net/http\"\\n)\\n\\nfunc main() {\\n  mux := http.NewServeMux()\\n  mux.HandleFunc(\"GET /health\", healthHandler)\\n  log.Fatal(http.ListenAndServe(\":8080\", mux))\\n}", "securityGuidance": "Use context.Context for request-scoped values and cancellation propagation. Use parameterized SQL queries via database/sql to prevent injection. Validate input with a struct validation library. Set timeouts on HTTP server, client, and database connections. Use crypto/rand for random values, never math/rand. Run go vet and staticcheck in CI. Use Go modules with go.sum for dependency integrity.", "commonApiPatterns": [{"name": "HTTP Handler", "description": "Handler function with DB query and error handling using closures for dependency injection", "codeTemplate": "func getUserHandler(db *sql.DB) http.HandlerFunc {\\n  return func(w http.ResponseWriter, r *http.Request) {\\n    id := r.PathValue(\"id\")\\n    var user User\\n    err := db.QueryRowContext(r.Context(), \"SELECT id, name FROM users WHERE id = $1\", id).Scan(&user.ID, &user.Name)\\n    if err == sql.ErrNoRows {\\n      http.Error(w, \"not found\", http.StatusNotFound)\\n      return\\n    }\\n    json.NewEncoder(w).Encode(user)\\n  }\\n}"}, {"name": "Middleware", "description": "Middleware pattern using handler wrapping and context for auth propagation", "codeTemplate": "func authMiddleware(next http.Handler) http.Handler {\\n  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\\n    token := r.Header.Get(\"Authorization\")\\n    claims, err := validateToken(strings.TrimPrefix(token, \"Bearer \"))\\n    if err != nil {\\n      http.Error(w, \"unauthorized\", http.StatusUnauthorized)\\n      return\\n    }\\n    ctx := context.WithValue(r.Context(), userKey, claims)\\n    next.ServeHTTP(w, r.WithContext(ctx))\\n  })\\n}"}, {"name": "Graceful Shutdown", "description": "Graceful shutdown with signal handling and context timeout", "codeTemplate": "srv := &http.Server{Addr: \":8080\", Handler: mux}\\ngo func() { log.Fatal(srv.ListenAndServe()) }()\\nquit := make(chan os.Signal, 1)\\nsignal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)\\n<-quit\\nctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)\\ndefer cancel()\\nsrv.Shutdown(ctx)"}], "integrationPatterns": ["net/http (stdlib) or Chi/Echo for HTTP routing", "database/sql with pgx or sqlc for type-safe database access", "gRPC with protobuf for service-to-service communication", "slog (stdlib) for structured logging", "testing package with testcontainers for integration tests"], "configurationTemplate": "// go.mod\\nmodule myapp\\ngo 1.22\\n\\n// Makefile\\n.PHONY: build run test\\nbuild:\\n\\tCGO_ENABLED=0 go build -ldflags=\"-s -w\" -o bin/server ./cmd/server\\nrun:\\n\\tgo run ./cmd/server\\ntest:\\n\\tgo test -race -cover ./..."}', '[{"kind": "source", "path": "cmd/server/main.go", "language": "go", "description": "Server entry point"}, {"kind": "source", "path": "internal/handlers/handlers.go", "language": "go", "description": "HTTP handlers"}, {"kind": "config", "path": "go.mod", "language": "go", "description": "Go module definition"}]', '{"config": {"type": "enum", "label": "Config style", "default": "env-only", "options": ["env-only", "env-plus-flags"]}, "httpStack": {"type": "enum", "label": "HTTP stack", "default": "stdlib-net-http", "options": ["stdlib-net-http", "gin", "echo", "fiber"], "description": "Since Go 1.22 the stdlib router handles methods + path params — the honest default; frameworks earn their place only for middleware ecosystems"}, "dataAccess": {"type": "enum", "label": "Data access", "default": "sqlc", "options": ["sqlc", "gorm", "database-sql"], "description": "sqlc = SQL-first codegen (the Go-idiomatic pick); gorm = ORM convenience with its own cost"}}', '["database", "cache", "message-broker", "grpc-service"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', 'Go', '#00889B', '''/health'':89C ''1.22'':50C ''8080'':94C ''anyth'':26B ''app'':42B ''backend'':3A ''binari'':12B,31B,62C ''bore'':17B ''cancel'':105C ''carri'':38B ''choic'':20B ''ci'':145C ''class'':15B ''client'':128C ''clis'':24B ''concurr'':16B ''connect'':131C ''contain'':34B ''context.context'':98C ''crypto/rand'':133C ''databas'':130C ''database/sql'':112C ''default'':19B ''depend'':152C ''deploy'':18B ''docker'':63C ''first'':14B ''first-class'':13B ''get'':88C ''go'':1A,2A,57C,65C,140C,147C ''go.sum'':150C ''golangci'':55C ''golangci-lint'':54C ''healthhandl'':90C ''http'':126C ''http.listenandserve'':93C ''http.newservemux'':85C ''imag'':64C ''infrastructur'':6B ''infrastructure-and-servic'':5B ''init'':67C ''inject'':115C ''input'':117C ''integr'':153C ''languag'':9B ''librari'':37B,122C ''lint'':56C ''log'':76C ''log.fatal'':92C ''main'':72C,82C ''main.go'':70C ''mainstream'':47B ''math/rand'':138C ''mod'':66C ''modul'':148C ''mux'':84C,95C ''mux.handlefunc'':87C ''myapp'':68C ''n'':69C,73C,75C,77C,79C,80C,83C,86C,91C,96C ''net/http'':49C,78C ''network'':22B ''never'':137C ''nfunc'':81C ''nimport'':74C ''npackag'':71C ''one'':30B ''parameter'':108C ''pgx'':53C ''prevent'':114C ''propag'':106C ''queri'':110C ''race'':59C ''random'':135C ''request'':101C ''request-scop'':100C ''rout'':51C ''run'':139C ''scope'':102C ''server'':127C ''servic'':8B,23B ''set'':123C ''ship'':28B ''singl'':10B,61C ''single-binari'':60C ''sql'':109C ''sqlc'':52C ''stack'':48B ''standard'':36B ''static'':11B ''staticcheck'':143C ''struct'':120C ''test'':58C ''timeout'':124C ''use'':97C,107C,132C,146C ''valid'':116C,121C ''valu'':103C,136C ''vet'':141C ''via'':111C');
INSERT INTO public.technology_catalog VALUES ('deno-edge', 'Deno (Supabase Edge)', NULL, '#6b7280', '["serverless-function"]', '{"purpose": "Deno-based edge runtime for Supabase Edge Functions — TypeScript-first, web-standard APIs, sub-50ms cold starts, Supabase client built in. Constraints are the design: limited execution time and no persistent connections — long work belongs on a worker node, and database access goes through the pooler or PostgREST, not held connections.", "configMode": "code", "provenance": {"notes": "Phase B8c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Deno runtime", "supabase-js", "npm: specifiers", "Web Crypto", "supabase functions deploy"], "antiPatterns": ["Holding database connections open — use the connection pooler or supabase-js, connections do not survive the isolate", "Long-running work against the execution-time limit — queue it instead", "Porting Node-specific APIs (fs, net) into edge code"], "apiReference": {"docsUrl": "https://docs.deno.com/deploy/"}, "bestPractices": ["Web-standard APIs (fetch, Request/Response, crypto) — code written this way ports across edge runtimes", "npm: specifiers for npm packages (no bare npm by default); jsr for Deno-native", "Secrets via supabase secrets set, read from Deno.env — never bundled", "Verify webhooks/JWTs IN the function — the edge is the trust boundary", "Keep functions single-purpose and fast; anything long-running is a worker node, not an edge function"], "sdkInitPattern": "Deno.serve(async (req: Request) => {\n  const url = new URL(req.url);\n  if (url.pathname === ''/api/orders'') {\n    const user = await verifyJwt(req.headers.get(''authorization''));\n    if (!user) return new Response(''unauthorized'', { status: 401 });\n    return Response.json(await listOrders(user.id));\n  }\n  return new Response(''not found'', { status: 404 });\n});", "securityGuidance": "Secrets come from the deployment''s environment variables (Deno.env), never module constants — edge source ships to many isolates and bundles are inspectable in CI logs. Verify JWTs on every request (issuer, audience, expiry) rather than trusting forwarded headers, remember each isolate is stateless and globals are per-isolate (no in-memory session state), and outbound fetch from the edge runs with your credentials: allow-list the hosts your function calls rather than proxying arbitrary user-supplied URLs."}', '[{"kind": "code", "path": "main.ts", "language": "typescript", "description": "Deno.serve entrypoint with per-request JWT verification"}, {"kind": "config", "path": "deno.json", "language": "json", "description": "Tasks, imports map, compiler options"}]', '{"imports": {"type": "multiselect", "label": "Import sources", "options": ["npm-specifiers", "jsr", "https-urls"], "description": "How dependencies enter the function — npm: specifiers cover most needs; jsr for Deno-native packages"}, "boundResources": {"type": "multiselect", "label": "Talks to", "options": ["supabase-db", "supabase-storage", "external-apis"], "description": "What the function reaches — drives the env/secret checklist in the packet"}}', '[]', false, NULL, NULL, '2026-05-11 15:06:54.3445+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''/api/orders'':84C ''401'':98C ''404'':110C ''50ms'':24B ''access'':51B ''allow'':177C ''allow-list'':176C ''api'':21B ''arbitrari'':187C ''async'':74C ''audienc'':142C ''author'':90C ''await'':87C,101C ''base'':8B ''belong'':44B ''built'':29B ''bundl'':130C ''call'':183C ''ci'':134C ''client'':28B ''cold'':25B ''come'':112C ''connect'':41B,60B ''const'':77C,85C ''constant'':122C ''constraint'':31B ''credenti'':175C ''crypto'':69C ''databas'':50B ''deno'':1A,4A,7B,61C ''deno-bas'':6B ''deno.env'':119C ''deno.serve'':73C ''deploy'':72C,115C ''design'':34B ''edg'':3A,5A,9B,13B,123C,171C ''environ'':117C ''everi'':139C ''execut'':36B ''expiri'':143C ''fetch'':168C ''first'':17B ''forward'':147C ''found'':108C ''function'':14B,71C,182C ''global'':155C ''goe'':52B ''header'':148C ''held'':59B ''host'':180C ''in-memori'':161C ''inspect'':132C ''isol'':128C,151C,159C ''issuer'':141C ''js'':65C ''jwts'':137C ''limit'':35B ''list'':178C ''listord'':102C ''log'':135C ''long'':42B ''mani'':127C ''memori'':163C ''modul'':121C ''never'':120C ''new'':79C,94C,105C ''node'':48B ''npm'':66C ''outbound'':167C ''per'':158C ''per-isol'':157C ''persist'':40B ''pooler'':55B ''postgrest'':57B ''proxi'':186C ''rather'':144C,184C ''rememb'':149C ''req'':75C ''req.headers.get'':89C ''req.url'':81C ''request'':76C,140C ''respons'':95C,106C ''response.json'':100C ''return'':93C,99C,104C ''run'':172C ''runtim'':10B,62C ''secret'':111C ''session'':164C ''ship'':125C ''sourc'':124C ''specifi'':67C ''standard'':20B ''start'':26B ''state'':165C ''stateless'':153C ''status'':97C,109C ''sub'':23B ''sub-50ms'':22B ''supabas'':2A,12B,27B,64C,70C ''supabase-j'':63C ''suppli'':190C ''time'':37B ''trust'':146C ''typescript'':16B ''typescript-first'':15B ''unauthor'':96C ''url'':78C,80C,191C ''url.pathname'':83C ''user'':86C,92C,189C ''user-suppli'':188C ''user.id'':103C ''variabl'':118C ''verifi'':136C ''verifyjwt'':88C ''web'':19B,68C ''web-standard'':18B ''work'':43B ''worker'':47B');
INSERT INTO public.technology_catalog VALUES ('astro', 'Astro', NULL, '#ff5d01', '["frontend-app"]', '{"purpose": "Content-focused web framework that ships zero JavaScript by default, with island architecture for interactive components", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Astro 4+", "TypeScript", "MDX", "React/Vue/Svelte islands"], "antiPatterns": ["Using client:load on every component negating Astro zero-JS advantage", "Building a heavily interactive SPA in Astro instead of using React/Vue/Svelte directly", "Not using content collections for blog/docs content", "Importing heavy JS libraries in Astro component frontmatter when they should be in islands", "Using set:html with user-provided content without sanitization"], "apiReference": {"docsUrl": "https://docs.astro.build"}, "bestPractices": ["Use content collections for structured content", "Implement islands architecture for interactive components", "Leverage zero-JS by default", "Use proper image optimization with astro:assets", "Implement view transitions for smooth navigation"], "sdkInitPattern": "npm create astro@latest my-app && cd my-app && npm install\\n---\\n// src/pages/index.astro\\nconst title = \"Hello Astro\";\\n---\\n<html>\\n  <body><h1>{title}</h1></body>\\n</html>", "securityGuidance": "Astro components render static HTML by default with no client-side JS -- minimal attack surface. Use set:html only with sanitized content. Validate input in API endpoints and server-side logic. Use environment variables via import.meta.env with PUBLIC_ prefix only for client-safe values. Set security headers via middleware or hosting configuration.", "commonApiPatterns": [{"name": "Astro Component with Data", "description": "Dynamic route with content collection data loading", "codeTemplate": "---\\n// src/pages/blog/[slug].astro\\nimport { getEntry } from \"astro:content\";\\nconst { slug } = Astro.params;\\nconst post = await getEntry(\"blog\", slug!);\\nif (!post) return Astro.redirect(\"/404\");\\nconst { Content } = await post.render();\\n---\\n<article>\\n  <h1>{post.data.title}</h1>\\n  <Content />\\n</article>"}, {"name": "Interactive Island", "description": "Partial hydration with client directives for interactive islands", "codeTemplate": "---\\nimport Counter from \"../components/Counter.tsx\";\\n---\\n<Counter client:visible />\\n<!-- Also: client:load, client:idle, client:media -->"}, {"name": "API Endpoint", "description": "Server endpoint for API routes in SSR mode", "codeTemplate": "// src/pages/api/users.ts\\nimport type { APIRoute } from \"astro\";\\nexport const GET: APIRoute = async () => {\\n  const users = await db.user.findMany();\\n  return new Response(JSON.stringify(users), {\\n    headers: { \"Content-Type\": \"application/json\" },\\n  });\\n};"}], "integrationPatterns": ["Content Collections for type-safe Markdown/MDX content management", "React, Vue, Svelte, or Solid components as interactive islands", "Tailwind CSS integration for utility-first styling", "Adapters for Vercel, Netlify, Cloudflare, or Node.js deployment", "View Transitions API for SPA-like page transitions"], "configurationTemplate": "// astro.config.mjs\\nimport { defineConfig } from \"astro/config\";\\nimport react from \"@astrojs/react\";\\nimport tailwind from \"@astrojs/tailwind\";\\nimport node from \"@astrojs/node\";\\nexport default defineConfig({\\n  output: \"hybrid\",\\n  adapter: node({ mode: \"standalone\" }),\\n  integrations: [react(), tailwind()],\\n});"}', '[{"kind": "source", "path": "src/pages/index.astro", "language": "astro", "description": "Home page"}, {"kind": "config", "path": "astro.config.mjs", "language": "javascript", "description": "Astro configuration"}]', '{"output": {"type": "enum", "label": "Output", "default": "static", "options": ["static", "server", "hybrid-prerender"], "description": "Astro is static-first; server output only when real request-time work exists"}, "islandFrameworks": {"type": "multiselect", "label": "Island frameworks", "options": ["react", "vue", "svelte", "solid", "none-zero-js"], "description": "Which frameworks hydrate islands — none is a legitimate and fast answer"}, "contentCollections": {"type": "boolean", "label": "Content collections", "default": true}}', '["rest-api", "cdn"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#D64E01', '''4'':21C ''api'':77C ''app'':32C,36C ''architectur'':16B ''astro'':1A,2A,20C,28C,45C,51C ''attack'':65C ''cd'':33C ''client'':61C,95C ''client-saf'':94C ''client-sid'':60C ''compon'':19B,52C ''configur'':105C ''content'':4B,73C ''content-focus'':3B ''creat'':27C ''default'':13B,57C ''endpoint'':78C ''environ'':85C ''focus'':5B ''framework'':7B ''header'':100C ''hello'':44C ''host'':104C ''html'':55C,69C ''import.meta.env'':88C ''input'':75C ''instal'':38C ''interact'':18B ''island'':15B,25C ''javascript'':11B ''js'':63C ''latest'':29C ''logic'':83C ''mdx'':23C ''middlewar'':102C ''minim'':64C ''my-app'':30C,34C ''n'':39C,40C,46C,47C,48C,50C ''nconst'':42C ''npm'':26C,37C ''prefix'':91C ''public'':90C ''react/vue/svelte'':24C ''render'':53C ''safe'':96C ''sanit'':72C ''secur'':99C ''server'':81C ''server-sid'':80C ''set'':68C,98C ''ship'':9B ''side'':62C,82C ''src/pages/index.astro'':41C ''static'':54C ''surfac'':66C ''titl'':43C,49C ''typescript'':22C ''use'':67C,84C ''valid'':74C ''valu'':97C ''variabl'':86C ''via'':87C,101C ''web'':6B ''zero'':10B');
INSERT INTO public.technology_catalog VALUES ('aws', 'Amazon Web Services', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws.png', '#FF9900', '["aws"]', '{"purpose": "AWS cloud provider identifier for infrastructure container nodes. Use this as the technology for cloud-project, vpc, and subnet roles when the deployment target is AWS. Individual AWS managed services (Aurora, SQS, Lambda, EC2, etc.) have their own technology entries and should be assigned to their respective leaf-role nodes, NOT to infrastructure containers.", "lifecycle": "platform-umbrella", "provenance": {"notes": "B10 lifecycle stamp; body content predates provenance tracking. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS CloudFormation", "AWS CDK", "Terraform", "AWS Organizations", "AWS Control Tower"], "antiPatterns": ["Using a single AWS account for all environments", "Assigning IAM policies directly to users instead of roles/groups", "Running workloads in default VPCs with public IPs", "Ignoring resource tagging making cost attribution impossible", "Using long-lived access keys instead of IAM roles and temporary credentials"], "bestPractices": ["Use VPCs with private subnets for workloads", "Enable CloudTrail for audit logging", "Use AWS Organizations for multi-account strategy", "Tag all resources for cost allocation"], "sdkInitPattern": "aws configure --profile my-project && export AWS_PROFILE=my-project && aws sts get-caller-identity", "securityGuidance": "Enable AWS CloudTrail in all regions for audit logging. Use AWS Organizations with SCPs to enforce guardrails. Never use root account credentials for day-to-day operations. Enable GuardDuty for threat detection. Use AWS Config rules for compliance monitoring. Enforce MFA on all IAM users. Use AWS SSO for centralized access management.", "commonApiPatterns": [{"name": "Create Organization", "description": "Set up AWS Organizations for multi-account strategy", "codeTemplate": "aws organizations create-organization --feature-set ALL && aws organizations create-account --email prod@company.com --account-name production"}, {"name": "CloudFormation Stack", "description": "Deploy infrastructure via CloudFormation", "codeTemplate": "aws cloudformation deploy --template-file infra.yml --stack-name my-stack --capabilities CAPABILITY_NAMED_IAM --parameter-overrides Env=prod"}, {"name": "Cost Explorer", "description": "Query cost and usage data grouped by tag", "codeTemplate": "aws ce get-cost-and-usage --time-period Start=2024-01-01,End=2024-02-01 --granularity MONTHLY --metrics BlendedCost --group-by Type=TAG,Key=Environment"}], "integrationPatterns": ["AWS Organizations + Control Tower for multi-account governance", "CloudTrail + CloudWatch for centralized logging and monitoring", "IAM Identity Center (SSO) for federated access across accounts", "AWS Config for continuous compliance evaluation", "AWS Cost Explorer + Budgets for cost governance"], "configurationTemplate": "# AWS Landing Zone pattern (Terraform)\\nprovider \"aws\" {\\n  region = var.primary_region\\n  default_tags {\\n    tags = {\\n      Environment = var.environment\\n      ManagedBy   = \"terraform\"\\n    }\\n  }\\n}\\nresource \"aws_organizations_organization\" \"root\" {\\n  feature_set = \"ALL\"\\n  enabled_policy_types = [\"SERVICE_CONTROL_POLICY\"]\\n}"}', '[]', '{}', '[]', false, NULL, NULL, '2026-02-20 14:25:20.585755+00', '2026-08-31 20:06:52.233344+00', NULL, '#EC7211', '''access'':140C ''account'':109C ''amazon'':1A ''assign'':49B ''audit'':96C ''aurora'':36B ''aw'':4A,5B,31B,33B,61C,63C,66C,68C,71C,78C,83C,90C,99C,123C,136C ''caller'':87C ''cdk'':64C ''central'':139C ''cloud'':6B,20B ''cloud-project'':19B ''cloudform'':62C ''cloudtrail'':91C ''complianc'':127C ''config'':124C ''configur'':72C ''contain'':11B,60B ''control'':69C ''credenti'':110C ''day'':113C,115C ''day-to-day'':112C ''deploy'':28B ''detect'':121C ''ec2'':39B ''enabl'':89C,117C ''enforc'':104C,129C ''entri'':45B ''etc'':40B ''export'':77C ''get'':86C ''get-caller-ident'':85C ''guardduti'':118C ''guardrail'':105C ''iam'':133C ''ident'':88C ''identifi'':8B ''individu'':32B ''infrastructur'':10B,59B ''lambda'':38B ''leaf'':54B ''leaf-rol'':53B ''log'':97C ''manag'':34B,141C ''mfa'':130C ''monitor'':128C ''my-project'':74C,80C ''never'':106C ''node'':12B,56B ''oper'':116C ''organ'':67C,100C ''profil'':73C,79C ''project'':21B,76C,82C ''provid'':7B ''region'':94C ''respect'':52B ''role'':25B,55B ''root'':108C ''rule'':125C ''scps'':102C ''servic'':3A,35B ''sqs'':37B ''sso'':137C ''sts'':84C ''subnet'':24B ''target'':29B ''technolog'':17B,44B ''terraform'':65C ''threat'':120C ''tower'':70C ''use'':13B,98C,107C,122C,135C ''user'':134C ''vpc'':22B ''web'':2A');
INSERT INTO public.technology_catalog VALUES ('aws-api-gateway', 'AWS API Gateway', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-api-gateway.png', '#ff9900', '["api-gateway"]', '{"purpose": "Fully managed AWS service for creating, publishing, and managing APIs at any scale with built-in authorization and throttling", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS API Gateway", "REST API/HTTP API", "Lambda Proxy", "Cognito Authorizer", "AWS SAM/CDK"], "antiPatterns": ["Not implementing rate limiting", "Using REST API when HTTP API suffices", "Not validating request models", "Ignoring CORS configuration", "Not monitoring 4xx/5xx error rates"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/apigateway/"}, "bestPractices": ["Use HTTP API for simple proxying (cheaper, faster)", "Use REST API when you need request/response transformation", "Implement proper throttling and usage plans", "Use Lambda authorizers for custom auth", "Enable CloudWatch logging", "Use stages for deployment management"], "securityGuidance": "Every production route gets an authorizer — IAM, JWT, or Lambda; authorization NONE is for public content decisions, not a default. Enable throttling and usage plans so one client cannot exhaust the backend, validate request models at the gateway so garbage never reaches your functions, and attach WAF on internet-facing REST APIs. Access logs should capture caller identity, not request bodies.", "configurationTemplate": "# HTTP API with a JWT authorizer\r\naws apigatewayv2 create-api --name my-api --protocol-type HTTP\r\naws apigatewayv2 create-authorizer --api-id API_ID --authorizer-type JWT \\\r\n  --identity-source ''$request.header.Authorization'' --name jwt-auth \\\r\n  --jwt-configuration Audience=my-audience,Issuer=https://issuer.example.com"}', '[{"kind": "config", "path": "infra/aws/api-gateway.tf"}]', '{"cors": {"type": "boolean", "label": "CORS", "default": true, "description": "Enable cross-origin access for browser clients"}, "apiType": {"type": "enum", "label": "API type", "default": "HTTP", "options": ["HTTP", "REST", "WebSocket"], "description": "HTTP: cheapest/simplest for Lambda+HTTP backends (~71% cheaper); REST: adds management features (usage plans, API keys, per-client throttling); WebSocket: bidirectional real-time"}, "customDomain": {"type": "boolean", "label": "Custom domain", "default": false, "description": "Attach an ACM-certified custom domain"}, "authorization": {"type": "enum", "label": "Authorization", "default": "jwt-cognito", "options": ["none", "iam", "jwt-cognito", "lambda-authorizer"], "description": "How callers authenticate at the gateway"}, "throttleRateRps": {"type": "number", "label": "Throttle rate (req/s)", "default": 100, "description": "Steady-state request rate limit"}}', '["serverless-function", "backend-service", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:49:13.558998+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''access'':92C ''api'':2A,5A,16B,28C,32C,91C ''api/http'':31C ''attach'':84C ''author'':24B,36C,44C,49C ''aw'':1A,4A,9B,27C,37C ''backend'':70C ''bodi'':100C ''built'':22B ''built-in'':21B ''caller'':96C ''cannot'':67C ''captur'':95C ''client'':66C ''cognito'':35C ''content'':54C ''creat'':12B ''decis'':55C ''default'':58C ''enabl'':59C ''everi'':39C ''exhaust'':68C ''face'':89C ''fulli'':7B ''function'':82C ''garbag'':78C ''gateway'':3A,6A,29C,76C ''get'':42C ''iam'':45C ''ident'':97C ''internet'':88C ''internet-fac'':87C ''jwt'':46C ''lambda'':33C,48C ''log'':93C ''manag'':8B,15B ''model'':73C ''never'':79C ''none'':50C ''one'':65C ''plan'':63C ''product'':40C ''proxi'':34C ''public'':53C ''publish'':13B ''reach'':80C ''request'':72C,99C ''rest'':30C,90C ''rout'':41C ''sam/cdk'':38C ''scale'':19B ''servic'':10B ''throttl'':26B,60C ''usag'':62C ''valid'':71C ''waf'':85C');
INSERT INTO public.technology_catalog VALUES ('aws-app-runner', 'AWS App Runner', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-app-runner.png', '#FF9900', '["docker-container", "backend-service"]', '{"purpose": "AWS App Runner is AWS''s fully managed service for deploying web applications and APIs directly from source code or container images to a scalable and secure runtime. Use it for containerized web backends, APIs, and application services when you want automatic build and deployment, managed scaling, and simplified operations without deep container platform management. Choose App Runner over AWS Fargate when the workload is primarily an internet-facing web service and you prefer a more opinionated developer experience, and over Elastic Beanstalk or EC2 when you do not need host management. Do not use it for complex microservice platforms, deep Kubernetes integration, or workloads requiring low-level networking and orchestration control.", "configMode": "code", "provenance": {"notes": "Phase B11 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS App Runner", "Amazon ECR", "AWS CodePipeline", "Amazon CloudWatch", "AWS Secrets Manager", "Amazon VPC", "Application Load Balancer"], "antiPatterns": ["Using App Runner as a substitute for Kubernetes when service mesh, operators, or cluster-level control are required", "Treating local container state as durable storage for application data", "Bundling many unrelated web services into one App Runner service for convenience", "Embedding secrets in container images or checked-in source code", "Choosing App Runner for non-web workloads that fit asynchronous workers or batch systems better", "Ignoring service boundaries and private connectivity requirements for dependent backends"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/apprunner/"}, "bestPractices": ["Use App Runner for bounded web services and APIs rather than stretching it into a full platform layer", "Store secrets and connection settings in managed configuration instead of baking them into images or source repositories", "Separate services by domain boundary and environment for clearer ownership and safer releases", "Use private VPC connectivity intentionally when services need secure access to internal data stores or APIs", "Monitor request latency, autoscaling behavior, deployment health, and cost continuously", "Pin source images and deployment configurations so production releases are reproducible", "Choose App Runner when its managed build and deploy path improves delivery speed more than custom platform control"], "securityGuidance": "Two roles again: the access role pulls from ECR, the instance role is what YOUR CODE can do — scope it per service. Inject secrets via the secrets block (Secrets Manager/SSM references), never plaintext env in apprunner.yaml (it lives in the repo). Use a VPC connector for private-resource egress instead of exposing databases publicly, keep the service private (or behind WAF via CloudFront) when it is not a public API, and pin the deployed image by digest for auditable rollbacks.", "configurationTemplate": "# apprunner.yaml\nversion: 1.0\nruntime: nodejs18\nbuild:\n  commands:\n    build:\n      - npm ci && npm run build\nrun:\n  command: node dist/server.js\n  network:\n    port: 3000\n  secrets:\n    - name: DATABASE_URL\n      value-from: arn:aws:secretsmanager:us-east-1:123:secret:db-url"}', '[{"kind": "source", "path": "src/apprunner/server.ts", "priority": "essential", "description": "Primary application entrypoint for the AWS App Runner service"}, {"kind": "config", "path": "apprunner/apprunner.yaml", "priority": "essential", "description": "App Runner service configuration for source, runtime, and deployment settings"}, {"kind": "config", "path": "infra/app-runner.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for AWS App Runner services and connectivity"}]', '{"vpcConnector": {"type": "boolean", "label": "VPC Connector", "default": false, "description": "Connect the App Runner service to private resources in an Amazon VPC"}, "publicService": {"type": "boolean", "label": "Public Service", "default": true, "description": "Expose the App Runner service publicly over HTTPS"}, "deploymentSource": {"type": "string", "label": "Deployment Source", "default": "container-image", "options": ["container-image", "source-code"], "description": "Primary source type for App Runner deployments"}}', '["api-gateway", "object-storage", "monitoring", "auth-provider", "database"]', false, NULL, NULL, '2026-03-14 21:45:27.163157+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''access'':142C ''amazon'':124C,128C,133C ''api'':21B,41B,208C ''app'':2A,5A,8B,63B,122C ''applic'':19B,43B,135C ''apprunner.yaml'':173C ''audit'':217C ''automat'':48B ''aw'':1A,4A,7B,11B,66B,121C,126C,130C ''backend'':40B ''balanc'':137C ''beanstalk'':90B ''behind'':198C ''block'':165C ''build'':49B ''choos'':62B ''cloudfront'':201C ''cloudwatch'':129C ''code'':25B,153C ''codepipelin'':127C ''complex'':105B ''connector'':182C ''contain'':27B,59B ''container'':38B ''control'':120B ''databas'':191C ''deep'':58B,108B ''deploy'':17B,51B,212C ''develop'':85B ''digest'':215C ''direct'':22B ''ec2'':92B ''ecr'':125C,146C ''egress'':187C ''elast'':89B ''env'':171C ''experi'':86B ''expos'':190C ''face'':76B ''fargat'':67B ''fulli'':13B ''host'':98B ''imag'':28B,213C ''inject'':160C ''instanc'':148C ''instead'':188C ''integr'':110B ''internet'':75B ''internet-fac'':74B ''keep'':193C ''kubernet'':109B ''level'':116B ''live'':175C ''load'':136C ''low'':115B ''low-level'':114B ''manag'':14B,52B,61B,99B,132C ''manager/ssm'':167C ''microservic'':106B ''need'':97B ''network'':117B ''never'':169C ''oper'':56B ''opinion'':84B ''orchestr'':119B ''per'':158C ''pin'':210C ''plaintext'':170C ''platform'':60B,107B ''prefer'':81B ''primarili'':72B ''privat'':185C,196C ''private-resourc'':184C ''public'':192C,207C ''pull'':144C ''refer'':168C ''repo'':178C ''requir'':113B ''resourc'':186C ''role'':139C,143C,149C ''rollback'':218C ''runner'':3A,6A,9B,64B,123C ''runtim'':34B ''scalabl'':31B ''scale'':53B ''scope'':156C ''secret'':131C,161C,164C,166C ''secur'':33B ''servic'':15B,44B,78B,159C,195C ''simplifi'':55B ''sourc'':24B ''two'':138C ''use'':35B,102B,179C ''via'':162C,200C ''vpc'':134C,181C ''waf'':199C ''want'':47B ''web'':18B,39B,77B ''without'':57B ''workload'':70B,112B');
INSERT INTO public.technology_catalog VALUES ('aws-cloudfront', 'AWS CloudFront', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-cloudfront.png', '#8C4FFF', '["cdn"]', '{"purpose": "AWS''s global content delivery network (CDN) that caches and delivers content from edge locations worldwide. Use when you need low-latency delivery of static assets (images, CSS, JS), dynamic API acceleration, or DDoS protection at the edge. CloudFront integrates natively with S3, ALB, API Gateway, and Lambda@Edge/CloudFront Functions for edge compute. Ideal for web applications needing global performance, video streaming, and any workload where proximity to end users matters. CloudFront also provides SSL/TLS termination at the edge with AWS Certificate Manager. Don''t use when your users are all in a single region and latency is already acceptable -- a simple ALB or S3 with Transfer Acceleration may suffice. Don''t use for real-time bidirectional communication (WebSockets) unless you specifically configure it. Avoid when cost sensitivity is extreme and CloudFlare or a simpler CDN would meet your needs at lower cost.", "configMode": "declarative", "provenance": {"notes": "Schema kept to stable API surface (queue/topic types, price classes, managed cache policies, record/routing basics); full live fetch upgrades this in the 4a-3 verification pass.", "method": "model-knowledge", "sources": ["https://docs.aws.amazon.com/"], "verifiedAt": "2026-07-27"}, "typicalTech": ["AWS CloudFront", "CloudFront Functions", "Lambda@Edge", "AWS Certificate Manager", "S3 Origin", "ALB Origin", "AWS WAF", "Terraform aws_cloudfront_distribution"], "antiPatterns": ["Using CloudFront without Origin Access Control allowing direct S3 access", "Setting excessively long TTLs for dynamic content causing stale data", "Not invalidating cache after deployments leaving users on old versions", "Forwarding unnecessary headers/cookies to origin defeating cache effectiveness", "Using a single behavior for all content instead of separating static and dynamic paths", "Not enabling compression wasting bandwidth on text assets"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cloudfront/"}, "bestPractices": ["Use Origin Access Control (OAC) to restrict S3 access exclusively through CloudFront", "Set appropriate Cache-Control headers on origins to control edge caching behavior", "Use cache policies and origin request policies instead of legacy cache behavior settings", "Enable compression (gzip, brotli) for text-based content", "Use Lambda@Edge or CloudFront Functions for URL rewriting, auth, and A/B testing", "Configure custom error pages for 4xx/5xx responses", "Use CloudFront access logs in S3 for traffic analysis and debugging"], "sdkInitPattern": "# AWS CLI create distribution\\naws cloudfront create-distribution --distribution-config file://dist-config.json\\n# Terraform is preferred for CloudFront configuration (see configurationTemplate)", "securityGuidance": "Use Origin Access Control (OAC) to prevent direct access to S3 origins. Attach AWS WAF to CloudFront for bot protection, rate limiting, and IP filtering. Enforce HTTPS with redirect-to-https viewer protocol policy. Use TLS 1.2+ minimum protocol version. Use signed URLs or signed cookies for private content. Set appropriate security headers via response headers policy (CSP, HSTS, X-Frame-Options).", "commonApiPatterns": [{"name": "Create Invalidation", "description": "Invalidate all cached content after a deployment", "codeTemplate": "aws cloudfront create-invalidation --distribution-id E1234567890 --paths \"/*\""}, {"name": "CloudFront Function", "description": "CloudFront Function for SPA URL rewriting", "codeTemplate": "function handler(event) {\\n  var request = event.request;\\n  var uri = request.uri;\\n  // SPA routing: rewrite paths without extensions to /index.html\\n  if (!uri.includes(''.'')) {\\n    request.uri = ''/index.html'';\\n  }\\n  return request;\\n}"}, {"name": "Signed URL", "description": "Generate signed URL for private content access", "codeTemplate": "import { getSignedUrl } from \"@aws-sdk/cloudfront-signer\";\\nconst signedUrl = getSignedUrl({\\n  url: `https://d123.cloudfront.net/private/file.pdf`,\\n  keyPairId: process.env.CF_KEY_PAIR_ID!,\\n  privateKey: process.env.CF_PRIVATE_KEY!,\\n  dateLessThan: new Date(Date.now() + 3600000).toISOString()\\n});"}], "integrationPatterns": ["S3 + CloudFront for static website hosting with global edge delivery", "ALB + CloudFront for dynamic API acceleration with edge caching", "AWS WAF for web application firewall protection at the CDN edge"], "configurationTemplate": "resource \"aws_cloudfront_distribution\" \"main\" {\\n  enabled             = true\\n  default_root_object = \"index.html\"\\n  aliases             = [\"app.example.com\"]\\n  origin {\\n    domain_name              = aws_s3_bucket.assets.bucket_regional_domain_name\\n    origin_id                = \"s3-assets\"\\n    origin_access_control_id = aws_cloudfront_origin_access_control.main.id\\n  }\\n  default_cache_behavior {\\n    allowed_methods        = [\"GET\", \"HEAD\"]\\n    cached_methods         = [\"GET\", \"HEAD\"]\\n    target_origin_id       = \"s3-assets\"\\n    cache_policy_id        = \"658327ea-f89d-4fab-a63d-7e88639e58f6\" # CachingOptimized\\n    viewer_protocol_policy = \"redirect-to-https\"\\n    compress               = true\\n  }\\n  viewer_certificate {\\n    acm_certificate_arn      = aws_acm_certificate.main.arn\\n    ssl_support_method       = \"sni-only\"\\n    minimum_protocol_version = \"TLSv1.2_2021\"\\n  }\\n  restrictions {\\n    geo_restriction { restriction_type = \"none\" }\\n  }\\n}"}', '[{"kind": "config", "path": "infra/aws/cloudfront.tf"}]', '{"originType": {"type": "enum", "label": "Origin", "default": "s3", "options": ["s3", "alb", "api-gateway", "custom"], "description": "What CloudFront fronts"}, "priceClass": {"type": "enum", "label": "Price class", "default": "PriceClass_100", "options": ["PriceClass_100", "PriceClass_200", "PriceClass_All"], "description": "Edge-location coverage vs cost (100 = NA+EU)"}, "cachePolicy": {"type": "enum", "label": "Cache policy", "default": "CachingOptimized", "options": ["CachingOptimized", "CachingDisabled", "custom"], "description": "Managed policy; disable for dynamic APIs"}, "edgeCompute": {"type": "enum", "label": "Edge compute", "default": "none", "options": ["none", "cloudfront-functions", "lambda-edge"], "description": "Lightweight request rewrites (Functions) vs full logic (Lambda@Edge)"}, "httpsPolicy": {"type": "enum", "label": "Viewer HTTPS", "default": "redirect-to-https", "options": ["redirect-to-https", "https-only"]}}', '["frontend-app", "backend-service", "rest-api", "storage"]', false, NULL, NULL, '2026-02-16 19:35:14.881443+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''1.2'':228C ''acceler'':37B,113B ''accept'':105B ''access'':193C,199C ''alb'':49B,108B,161C ''alreadi'':104B ''also'':78B ''api'':36B,50B ''applic'':62B ''appropri'':242C ''asset'':31B ''attach'':203C ''avoid'':131B ''aw'':1A,3A,5B,86B,150C,156C,163C,166C,169C,204C ''bidirect'':123B ''bot'':209C ''cach'':13B ''cdn'':11B,142B ''certif'':87B,157C ''cli'':170C ''cloudflar'':138B ''cloudfront'':2A,4A,44B,77B,151C,152C,167C,174C,187C,207C ''communic'':124B ''comput'':58B ''config'':180C ''configur'':129B,188C ''configurationtempl'':190C ''content'':8B,16B,240C ''control'':194C ''cooki'':237C ''cost'':133B,149B ''creat'':171C,176C ''create-distribut'':175C ''csp'':249C ''css'':33B ''ddos'':39B ''deliv'':15B ''deliveri'':9B,28B ''direct'':198C ''dist-config.json'':181C ''distribut'':168C,172C,177C,179C ''distribution-config'':178C ''dynam'':35B ''edg'':18B,43B,57B,84B,155C ''edge/cloudfront'':54B ''end'':74B ''enforc'':216C ''extrem'':136B ''filter'':215C ''frame'':253C ''function'':55B,153C ''gateway'':51B ''global'':7B,64B ''header'':244C,247C ''hsts'':250C ''https'':217C,222C ''ideal'':59B ''imag'':32B ''integr'':45B ''ip'':214C ''js'':34B ''lambda'':53B,154C ''latenc'':27B,102B ''limit'':212C ''locat'':19B ''low'':26B ''low-lat'':25B ''lower'':148B ''manag'':88B,158C ''matter'':76B ''may'':114B ''meet'':144B ''minimum'':229C ''n'':182C ''nativ'':46B ''naw'':173C ''need'':24B,63B,146B ''network'':10B ''oac'':195C ''option'':254C ''origin'':160C,162C,192C,202C ''perform'':65B ''polici'':225C,248C ''prefer'':185C ''prevent'':197C ''privat'':239C ''protect'':40B,210C ''protocol'':224C,230C ''provid'':79B ''proxim'':72B ''rate'':211C ''real'':121B ''real-tim'':120B ''redirect'':220C ''redirect-to-http'':219C ''region'':100B ''respons'':246C ''s3'':48B,110B,159C,201C ''secur'':243C ''see'':189C ''sensit'':134B ''set'':241C ''sign'':233C,236C ''simpl'':107B ''simpler'':141B ''singl'':99B ''specif'':128B ''ssl/tls'':80B ''static'':30B ''stream'':67B ''suffic'':115B ''termin'':81B ''terraform'':165C,183C ''time'':122B ''tls'':227C ''transfer'':112B ''unless'':126B ''url'':234C ''use'':21B,91B,118B,191C,226C,232C ''user'':75B,94B ''version'':231C ''via'':245C ''video'':66B ''viewer'':223C ''waf'':164C,205C ''web'':61B ''websocket'':125B ''workload'':70B ''worldwid'':20B ''would'':143B ''x'':252C ''x-frame-opt'':251C');
INSERT INTO public.technology_catalog VALUES ('aws-cloudwatch', 'AWS CloudWatch', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-cloudwatch.png', '#FF4F8B', '["monitoring", "logging"]', '{"purpose": "AWS-native monitoring and observability service providing metrics, logs, alarms, dashboards, and traces. CloudWatch Logs aggregates application and infrastructure logs; CloudWatch Metrics collects time-series data from 70+ AWS services; CloudWatch Alarms triggers notifications and auto-scaling actions. Best for AWS-native monitoring when you want deep integration with all AWS services without managing Prometheus/Grafana infrastructure. Use Datadog or Grafana Cloud for multi-cloud observability.", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Logging at DEBUG level in production causing excessive costs", "Not setting log retention policies (default is indefinite)", "Creating too many high-resolution custom metrics unnecessarily", "Using CloudWatch alone for complex multi-cloud observability", "Not using structured JSON logging format"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cloudwatch/"}, "bestPractices": ["Use CloudWatch Logs Insights for structured log querying", "Create composite alarms for multi-metric health checks", "Use metric filters to extract custom metrics from log data", "Enable Container Insights for ECS/EKS monitoring", "Use CloudWatch Synthetics for endpoint monitoring", "Set up cross-account observability for multi-account architectures"], "securityGuidance": "Logs are a leak surface: never log credentials, tokens, or full request bodies — scrub before emit. Set retention policies on every log group (the default is forever) and KMS-encrypt groups holding sensitive application logs. Scope IAM to specific log groups and metric namespaces rather than cloudwatch:*, and alarm on security-relevant events (auth failures, throttles) so the monitoring plane is itself a detector.", "configurationTemplate": "# Log group with retention + a metric alarm\r\naws logs create-log-group --log-group-name /app/api\r\naws logs put-retention-policy --log-group-name /app/api --retention-in-days 30\r\naws cloudwatch put-metric-alarm --alarm-name api-5xx --namespace AWS/ApplicationELB \\\r\n  --metric-name HTTPCode_Target_5XX_Count --statistic Sum --period 300 \\\r\n  --threshold 10 --comparison-operator GreaterThanThreshold --evaluation-periods 1"}', '[{"kind": "config", "path": "monitoring/cloudwatch-dashboard.json", "priority": "recommended", "description": "CloudWatch dashboard definition"}, {"kind": "config", "path": "monitoring/alarms.ts", "priority": "recommended", "description": "CloudWatch alarm definitions"}, {"kind": "config", "path": "terraform/cloudwatch.tf", "priority": "recommended", "description": "CloudWatch infrastructure definition"}]', '{"logRetentionDays": {"type": "number", "label": "Log Retention (days)", "default": 30}, "containerInsights": {"type": "boolean", "label": "Container Insights", "default": true}, "detailedMonitoring": {"type": "boolean", "label": "Detailed Monitoring", "default": false}}', '["rest-api", "worker", "serverless-function"]', false, NULL, NULL, '2026-03-02 03:15:03.625255+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''70'':34B ''action'':45B ''aggreg'':21B ''alarm'':15B,38B,124C ''applic'':22B,109C ''auth'':130C ''auto'':43B ''auto-sc'':42B ''aw'':1A,3A,6B,35B,49B,59B ''aws-nat'':5B,48B ''best'':46B ''bodi'':87C ''cloud'':69B,73B ''cloudwatch'':2A,4A,19B,26B,37B,122C ''collect'':28B ''credenti'':82C ''dashboard'':16B ''data'':32B ''datadog'':66B ''deep'':55B ''default'':99C ''detector'':140C ''emit'':90C ''encrypt'':105C ''event'':129C ''everi'':95C ''failur'':131C ''forev'':101C ''full'':85C ''grafana'':68B ''group'':97C,106C,116C ''hold'':107C ''iam'':112C ''infrastructur'':24B,64B ''integr'':56B ''kms'':104C ''kms-encrypt'':103C ''leak'':78C ''log'':14B,20B,25B,75C,81C,96C,110C,115C ''manag'':62B ''metric'':13B,27B,118C ''monitor'':8B,51B,135C ''multi'':72B ''multi-cloud'':71B ''namespac'':119C ''nativ'':7B,50B ''never'':80C ''notif'':40B ''observ'':10B,74B ''plane'':136C ''polici'':93C ''prometheus/grafana'':63B ''provid'':12B ''rather'':120C ''relev'':128C ''request'':86C ''retent'':92C ''scale'':44B ''scope'':111C ''scrub'':88C ''secur'':127C ''security-relev'':126C ''sensit'':108C ''seri'':31B ''servic'':11B,36B,60B ''set'':91C ''specif'':114C ''surfac'':79C ''throttl'':132C ''time'':30B ''time-seri'':29B ''token'':83C ''trace'':18B ''trigger'':39B ''use'':65B ''want'':54B ''without'':61B');
INSERT INTO public.technology_catalog VALUES ('aws-codepipeline', 'AWS CodePipeline', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-codepipeline.png', '#FF4F8B', '["ci-cd-pipeline"]', '{"purpose": "AWS CodePipeline is AWS''s managed continuous delivery service for orchestrating source, build, test, approval, and deployment stages across software delivery workflows. Use it for automated release pipelines, artifact promotion, environment progression, and governed deployment flows where multiple tools and stages must run in sequence. Choose CodePipeline over simple cron-style schedulers when the workflow is tied to source changes, delivery stages, approvals, and deployment automation, and over ad hoc scripts when repeatable CI/CD orchestration matters. Do not use it as an application runtime, low-latency task queue, or replacement for in-process business job scheduling.", "configMode": "definition-as-code", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS CodePipeline", "AWS CodeBuild", "AWS CodeDeploy", "Amazon ECR", "AWS CloudFormation", "AWS Lambda", "Amazon S3"], "antiPatterns": ["Using CodePipeline as a general-purpose application scheduler for operational business workloads", "Embedding secrets or long-lived credentials directly in pipeline configuration", "Combining many unrelated product releases into one oversized pipeline with weak ownership boundaries", "Deploying mutable artifacts without version tracking or provenance controls", "Triggering every pipeline run from noisy repositories without branch, path, or promotion discipline", "Treating pipeline failures as normal noise instead of improving stage quality and observability"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/codepipeline/"}, "bestPractices": ["Define pipelines as versioned delivery workflows with clear stage boundaries and promotion criteria", "Separate build, test, approval, and deployment concerns into explicit stages instead of collapsing everything into one action", "Use artifact versioning and immutable deployment inputs so releases are reproducible across environments", "Integrate approval gates and rollback-aware deployment stages for production-bound changes", "Store secrets and environment-specific configuration in managed services rather than embedding them in pipeline definitions", "Monitor stage duration, failure rates, and retry patterns to continuously improve delivery performance", "Use reusable templates and shared actions where many teams follow common platform delivery paths"], "securityGuidance": "The pipeline role and each action role are deployment power — scope per stage so the build action cannot deploy and the staging deployer cannot touch prod. Manual approval gates before production, artifact buckets encrypted and closed to non-pipeline principals (artifact tampering IS supply-chain compromise), and secrets reach builds via Secrets Manager/SSM references, never pipeline variables in plaintext.", "configurationTemplate": "# pipeline.json (skeleton)\n{\n  \"pipeline\": {\n    \"name\": \"api-pipeline\",\n    \"roleArn\": \"arn:aws:iam::123:role/pipelineRole\",\n    \"stages\": [\n      { \"name\": \"Source\", \"actions\": [{ \"actionTypeId\": { \"category\": \"Source\", \"provider\": \"CodeStarSourceConnection\" } }] },\n      { \"name\": \"Build\",  \"actions\": [{ \"actionTypeId\": { \"category\": \"Build\", \"provider\": \"CodeBuild\" } }] },\n      { \"name\": \"ApproveProd\", \"actions\": [{ \"actionTypeId\": { \"category\": \"Approval\", \"provider\": \"Manual\" } }] },\n      { \"name\": \"Deploy\", \"actions\": [{ \"actionTypeId\": { \"category\": \"Deploy\", \"provider\": \"CloudFormation\" } }] }\n    ]\n  }\n}"}', '[{"kind": "config", "path": "pipeline/codepipeline.json", "priority": "essential", "description": "Primary AWS CodePipeline stage, action, and artifact flow definition"}, {"kind": "config", "path": "pipeline/buildspec.yml", "priority": "recommended", "description": "Build and test instructions used by integrated pipeline stages"}, {"kind": "config", "path": "infra/codepipeline.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for AWS CodePipeline and connected delivery resources"}]', '{"triggerMode": {"type": "string", "label": "Trigger Mode", "default": "commit", "options": ["commit", "manual", "scheduled", "multi-trigger"], "description": "Primary way the pipeline is started"}, "artifactStore": {"type": "string", "label": "Artifact Store", "default": "s3", "options": ["s3", "custom"], "description": "Primary storage backend for pipeline artifacts"}, "manualApproval": {"type": "boolean", "label": "Manual Approval", "default": false, "description": "Require human approval before progressing critical stages"}, "supplyChainSecurity": {"type": "multiselect", "label": "Supply-chain security steps", "options": ["vulnerability-scan-trivy-grype", "sbom-generation-syft", "artifact-signing-cosign", "iac-scanning", "none-yet"], "description": "Security steps IN this pipeline (owner IaC ruling: scanners/signers are pipeline configuration, not canvas nodes) — each selected step is a concrete pipeline stage the packet will direct"}}', '["object-storage", "docker-container", "backend-service", "monitoring", "auth-provider"]', false, NULL, NULL, '2026-03-14 22:32:41.504306+00', '2026-08-31 20:06:52.233344+00', NULL, '#C0125F', '''across'':23B ''action'':123C,134C ''ad'':74B ''amazon'':110C,116C ''applic'':88B ''approv'':19B,68B,145C ''artifact'':33B,149C,159C ''autom'':30B,71B ''aw'':1A,3A,5B,8B,104C,106C,108C,112C,114C ''bucket'':150C ''build'':17B,133C,169C ''busi'':101B ''cannot'':135C,141C ''chain'':164C ''chang'':65B ''choos'':50B ''ci/cd'':79B ''close'':153C ''cloudform'':113C ''codebuild'':107C ''codedeploy'':109C ''codepipelin'':2A,4A,6B,51B,105C ''compromis'':165C ''continu'':11B ''cron'':55B ''cron-styl'':54B ''deliveri'':12B,25B,66B ''deploy'':21B,39B,70B,126C,136C,140C ''ecr'':111C ''encrypt'':151C ''environ'':35B ''flow'':40B ''gate'':146C ''govern'':38B ''hoc'':75B ''in-process'':98B ''job'':102B ''lambda'':115C ''latenc'':92B ''low'':91B ''low-lat'':90B ''manag'':10B ''manager/ssm'':172C ''manual'':144C ''matter'':81B ''multipl'':42B ''must'':46B ''never'':174C ''non'':156C ''non-pipelin'':155C ''orchestr'':15B,80B ''per'':129C ''pipelin'':32B,119C,157C,175C ''plaintext'':178C ''power'':127C ''princip'':158C ''process'':100B ''prod'':143C ''product'':148C ''progress'':36B ''promot'':34B ''queue'':94B ''reach'':168C ''refer'':173C ''releas'':31B ''repeat'':78B ''replac'':96B ''role'':120C,124C ''run'':47B ''runtim'':89B ''s3'':117C ''schedul'':57B,103B ''scope'':128C ''script'':76B ''secret'':167C,171C ''sequenc'':49B ''servic'':13B ''simpl'':53B ''softwar'':24B ''sourc'':16B,64B ''stage'':22B,45B,67B,130C,139C ''style'':56B ''suppli'':163C ''supply-chain'':162C ''tamper'':160C ''task'':93B ''test'':18B ''tie'':62B ''tool'':43B ''touch'':142C ''use'':27B,84B ''variabl'':176C ''via'':170C ''workflow'':26B,60B');
INSERT INTO public.technology_catalog VALUES ('aws-efs', 'AWS EFS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws.png', '#FF9900', '["file-share"]', '{"purpose": "Fully managed, elastic NFS file system for Linux workloads. Provides shared file storage accessible from multiple EC2 instances, ECS tasks, EKS pods, and Lambda functions simultaneously. Supports automatic scaling from gigabytes to petabytes and offers Standard and Infrequent Access storage classes for cost optimization.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using EFS for high-IOPS random-access workloads (use EBS or FSx instead)", "Not enabling lifecycle policies causing all data to remain in Standard tier", "Using General Purpose mode for throughput-heavy batch processing", "Mounting EFS across regions instead of using replication"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/efs/"}, "bestPractices": ["Use EFS Infrequent Access for files not accessed frequently to reduce costs by up to 92%", "Enable lifecycle management to automatically move files between storage classes", "Use Provisioned Throughput mode for latency-sensitive workloads with known I/O patterns", "Mount using EFS mount helper for automatic encryption in transit", "Use access points to manage application-specific entry points with POSIX permissions", "Enable backup with AWS Backup for disaster recovery"], "securityGuidance": "One access point per application, enforcing its POSIX identity and rooting it in its own directory — shared raw mounts are how one workload reads another''s files. Back it with a file-system policy requiring elasticfilesystem:AccessedViaMountTarget and TLS in transit, keep mount targets'' security groups scoped to the client tier, and enable encryption at rest at creation (it cannot be added later).", "configurationTemplate": "# Access point per app — enforced POSIX identity + rooted path\naws efs create-access-point --file-system-id fs-0123 \\\n  --posix-user Uid=1001,Gid=1001 \\\n  --root-directory ''Path=/app-data,CreationInfo={OwnerUid=1001,OwnerGid=1001,Permissions=750}''\n# Mount via the access point with TLS: mount -t efs -o tls,accesspoint=fsap-0456 fs-0123 /data"}', '[{"kind": "config", "path": "terraform/efs.tf", "priority": "recommended", "description": "EFS file system and mount target definitions"}, {"kind": "config", "path": "k8s/efs-storage-class.yaml", "priority": "optional", "description": "EKS persistent volume claim for EFS"}]', '{"encrypted": {"type": "boolean", "label": "Encryption at Rest", "default": true}, "throughputMode": {"type": "string", "label": "Throughput Mode", "default": "bursting"}, "lifecyclePolicy": {"type": "boolean", "label": "Lifecycle Policy", "default": true}, "performanceMode": {"type": "string", "label": "Performance Mode", "default": "generalPurpose"}}', '["ecs-cluster", "k8s-cluster", "serverless-function", "backend-service"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''access'':18B,43B,50C ''accessedviamounttarget'':86C ''ad'':111C ''anoth'':73C ''applic'':53C ''automat'':32B ''aw'':1A,3A ''back'':76C ''cannot'':109C ''class'':45B ''client'':99C ''cost'':47B ''creation'':107C ''directori'':64C ''ec'':23B ''ec2'':21B ''ef'':2A,4A ''ek'':25B ''elast'':7B ''elasticfilesystem'':85C ''enabl'':102C ''encrypt'':103C ''enforc'':54C ''file'':9B,16B,75C,81C ''file-system'':80C ''fulli'':5B ''function'':29B ''gigabyt'':35B ''group'':95C ''ident'':57C ''infrequ'':42B ''instanc'':22B ''keep'':91C ''lambda'':28B ''later'':112C ''linux'':12B ''manag'':6B ''mount'':67C,92C ''multipl'':20B ''nfs'':8B ''offer'':39B ''one'':49C,70C ''optim'':48B ''per'':52C ''petabyt'':37B ''pod'':26B ''point'':51C ''polici'':83C ''posix'':56C ''provid'':14B ''raw'':66C ''read'':72C ''requir'':84C ''rest'':105C ''root'':59C ''scale'':33B ''scope'':96C ''secur'':94C ''share'':15B,65C ''simultan'':30B ''standard'':40B ''storag'':17B,44B ''support'':31B ''system'':10B,82C ''target'':93C ''task'':24B ''tier'':100C ''tls'':88C ''transit'':90C ''workload'':13B,71C');
INSERT INTO public.technology_catalog VALUES ('aws-elastic-beanstalk', 'AWS Elastic Beanstalk', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-elastic-beanstalk.png', '#FF9900', '["backend-service"]', '{"purpose": "AWS Elastic Beanstalk is AWS''s managed application platform for deploying and operating web applications and backend services on supported runtimes with reduced infrastructure management. Use it for traditional web apps, APIs, and application services when you want managed provisioning, deployment, scaling, and health monitoring on top of familiar compute environments. Choose Elastic Beanstalk over raw EC2 when you want a more opinionated application deployment experience, and over App Runner when you need broader platform customization around underlying AWS resources. Do not use it for deep Kubernetes orchestration, highly custom container platforms, or workloads that require serverless-first event execution patterns where ECS, EKS, Lambda, or App Runner are better fits.", "configMode": "code", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["AWS Elastic Beanstalk", "Amazon EC2", "Application Load Balancer", "Amazon RDS", "Amazon S3", "Amazon CloudWatch", "AWS Auto Scaling"], "antiPatterns": ["Treating Elastic Beanstalk instances as manually managed pets outside the platform lifecycle", "Storing critical application state on local instance filesystems", "Over-customizing environments until the platform abstraction no longer provides operational value", "Bundling unrelated services into one environment with conflicting scaling and release needs", "Embedding secrets directly in source bundles or unmanaged environment configuration", "Choosing Elastic Beanstalk when container-native or serverless platforms better match the workload model"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/elasticbeanstalk/"}, "bestPractices": ["Use environment-specific configurations and separate applications or environments by lifecycle stage and ownership", "Externalize durable state to managed databases, caches, and storage services instead of relying on instance-local data", "Treat Elastic Beanstalk configuration and platform hooks as versioned delivery assets rather than console-only settings", "Use rolling, immutable, or blue-green deployment strategies based on workload criticality and rollback requirements", "Monitor environment health, instance behavior, deployment events, and autoscaling outcomes continuously", "Customize the platform only where necessary and document deviations from default environment behavior clearly", "Choose Elastic Beanstalk for bounded application hosting rather than as a catch-all platform for unrelated services"], "securityGuidance": "Environment properties are plaintext in configuration — resolve secrets from Secrets Manager/SSM at boot instead. The instance profile is what your app can do: scope it per environment, never a shared admin profile. Terminate TLS at the load balancer with modern policies, run instances in private subnets, and treat .ebextensions/.platform hooks as code review surface — they execute as root on every deploy.", "configurationTemplate": "# .ebextensions/app.config\noption_settings:\n  aws:autoscaling:launchconfiguration:\n    IamInstanceProfile: app-instance-profile\n  aws:elasticbeanstalk:environment:\n    ServiceRole: aws-elasticbeanstalk-service-role\n  aws:elasticbeanstalk:application:environment:\n    NODE_ENV: production\n# secrets resolve from SSM/Secrets Manager at boot, not here"}', '[{"kind": "source", "path": "src/beanstalk/app.ts", "priority": "essential", "description": "Primary application entrypoint for the Elastic Beanstalk web or backend service"}, {"kind": "config", "path": ".ebextensions/options.config", "priority": "recommended", "description": "Elastic Beanstalk environment configuration, scaling, and platform customization"}, {"kind": "config", "path": "infra/elastic-beanstalk.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for AWS Elastic Beanstalk applications and environments"}]', '{"platform": {"type": "string", "label": "Platform", "default": "nodejs", "options": ["nodejs", "python", "java", "docker", "dotnet"], "description": "Primary application platform used by Elastic Beanstalk"}, "publicEnvironment": {"type": "boolean", "label": "Public Environment", "default": true, "description": "Expose the application publicly through a load balancer or internet-facing environment"}, "deploymentStrategy": {"type": "string", "label": "Deployment Strategy", "default": "rolling", "options": ["all-at-once", "rolling", "rolling-with-batch", "immutable", "blue-green"], "description": "Primary release strategy for environment updates"}}', '["database", "object-storage", "load-balancer", "monitoring", "auth-provider"]', false, NULL, NULL, '2026-03-14 22:32:41.504306+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''admin'':166C ''amazon'':122C,127C,129C,131C ''api'':38B ''app'':37B,75B,114B,156C ''applic'':14B,21B,40B,70B,124C ''around'':83B ''auto'':134C ''aw'':1A,4A,7B,11B,85B,119C,133C ''backend'':23B ''balanc'':126C,173C ''beanstalk'':3A,6A,9B,60B,121C ''better'':117B ''boot'':148C ''broader'':80B ''choos'':58B ''cloudwatch'':132C ''code'':187C ''comput'':56B ''configur'':141C ''contain'':97B ''custom'':82B,96B ''deep'':92B ''deploy'':17B,47B,71B,196C ''ebextensions/.platform'':184C ''ec'':110B ''ec2'':63B,123C ''ek'':111B ''elast'':2A,5A,8B,59B,120C ''environ'':57B,136C,162C ''event'':106B ''everi'':195C ''execut'':107B,191C ''experi'':72B ''familiar'':55B ''first'':105B ''fit'':118B ''health'':50B ''high'':95B ''hook'':185C ''infrastructur'':30B ''instanc'':151C,178C ''instead'':149C ''kubernet'':93B ''lambda'':112B ''load'':125C,172C ''manag'':13B,31B,45B ''manager/ssm'':146C ''modern'':175C ''monitor'':51B ''need'':79B ''never'':163C ''oper'':19B ''opinion'':69B ''orchestr'':94B ''pattern'':108B ''per'':161C ''plaintext'':139C ''platform'':15B,81B,98B ''polici'':176C ''privat'':180C ''profil'':152C,167C ''properti'':137C ''provis'':46B ''raw'':62B ''rds'':128C ''reduc'':29B ''requir'':102B ''resolv'':142C ''resourc'':86B ''review'':188C ''root'':193C ''run'':177C ''runner'':76B,115B ''runtim'':27B ''s3'':130C ''scale'':48B,135C ''scope'':159C ''secret'':143C,145C ''serverless'':104B ''serverless-first'':103B ''servic'':24B,41B ''share'':165C ''subnet'':181C ''support'':26B ''surfac'':189C ''termin'':168C ''tls'':169C ''top'':53B ''tradit'':35B ''treat'':183C ''under'':84B ''use'':32B,89B ''want'':44B,66B ''web'':20B,36B ''workload'':100B');
INSERT INTO public.technology_catalog VALUES ('aws-elb', 'AWS Elastic Load Balancing', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-elb.png', '#6b7280', '["load-balancer"]', '{"purpose": "Automatically distributes incoming application traffic across multiple targets such as EC2 instances, containers, and IP addresses in one or more Availability Zones.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: live-docs 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Application Load Balancer", "Network Load Balancer", "Gateway Load Balancer", "Target Groups", "Listener Rules", "Health Checks"], "antiPatterns": ["Not configuring health checks", "Using a single AZ for targets", "Not enabling access logging", "Overly permissive security groups", "Not using sticky sessions when needed for stateful apps"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/elasticloadbalancing/"}, "bestPractices": ["Use Application Load Balancer for HTTP/HTTPS traffic with path-based routing", "Use Network Load Balancer for TCP/UDP with ultra-low latency", "Configure health checks with appropriate thresholds", "Enable cross-zone load balancing", "Use target groups to route to different services", "Enable access logging for monitoring and debugging", "Configure SSL/TLS termination at the load balancer", "Integrate with AWS WAF for Application Load Balancer"], "securityGuidance": "HTTPS listeners with a current TLS policy and an HTTP→HTTPS redirect — no plaintext production listeners. Targets live in private subnets accepting traffic only from the LB''s security group (direct-to-origin bypasses your WAF and auth layers). Enable access logs to a locked bucket, drop invalid header fields on ALBs, and let ACM own certificate rotation.", "configurationTemplate": "# ALB + HTTPS listener + redirect\naws elbv2 create-load-balancer --name app-alb --subnets subnet-a subnet-b --security-groups sg-0123\naws elbv2 create-listener --load-balancer-arn $ALB --protocol HTTPS --port 443 \\\n  --certificates CertificateArn=$ACM_CERT --ssl-policy ELBSecurityPolicy-TLS13-1-2-2021-06 \\\n  --default-actions Type=forward,TargetGroupArn=$TG"}', '[{"kind": "config", "path": "infra/aws/load-balancer.tf"}]', '{"type": {"type": "enum", "label": "Load balancer type", "default": "application", "options": ["application", "network", "gateway"], "description": "ALB: HTTP/L7 + path routing; NLB: TCP-UDP/L4; Gateway: appliance fleets. (Classic is legacy — migrate.)"}, "scheme": {"type": "enum", "label": "Scheme", "default": "internet-facing", "options": ["internet-facing", "internal"]}, "httpsOnly": {"type": "boolean", "label": "HTTPS listeners only", "default": true, "description": "Redirect/terminate TLS at the LB (ACM cert)"}, "stickySessions": {"type": "boolean", "label": "Sticky sessions", "default": false, "description": "Prefer stateless targets; enable only when session affinity is unavoidable"}, "healthCheckPath": {"type": "string", "label": "Health check path", "default": "/health"}}', '["backend-service", "frontend-app", "worker"]', false, NULL, NULL, '2026-02-21 04:24:52.574678+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''accept'':65C ''access'':85C ''acm'':99C ''across'':12B ''address'':22B ''alb'':96C ''applic'':10B,29C ''auth'':82C ''automat'':7B ''avail'':27B ''aw'':1A,5A ''balanc'':4A,31C,34C,37C ''bucket'':90C ''bypass'':78C ''certif'':101C ''check'':43C ''contain'':19B ''current'':48C ''direct'':75C ''direct-to-origin'':74C ''distribut'':8B ''drop'':91C ''ec2'':17B ''elast'':2A ''elb'':6A ''enabl'':84C ''field'':94C ''gateway'':35C ''group'':39C,73C ''header'':93C ''health'':42C ''http'':53C ''https'':44C,54C ''incom'':9B ''instanc'':18B ''invalid'':92C ''ip'':21B ''layer'':83C ''lb'':70C ''let'':98C ''listen'':40C,45C,59C ''live'':61C ''load'':3A,30C,33C,36C ''lock'':89C ''log'':86C ''multipl'':13B ''network'':32C ''one'':24B ''origin'':77C ''plaintext'':57C ''polici'':50C ''privat'':63C ''product'':58C ''redirect'':55C ''rotat'':102C ''rule'':41C ''secur'':72C ''subnet'':64C ''target'':14B,38C,60C ''tls'':49C ''traffic'':11B,66C ''waf'':80C ''zone'':28B');
INSERT INTO public.technology_catalog VALUES ('aws-kinesis', 'AWS Kinesis', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-kinesis.png', '#8C4FFF', '["event-stream"]', '{"purpose": "AWS-native real-time data streaming for ingesting and processing high-volume event data. Kinesis Data Streams provides ordered, replayable event logs; Kinesis Data Firehose delivers data to S3, Redshift, or Elasticsearch without consumer management. Best for real-time analytics, log aggregation, clickstream capture, and IoT telemetry on AWS. Use Kinesis over Kafka when you want fully managed AWS-native streaming without broker management.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using Kinesis for simple point-to-point queuing (use SQS)", "Choosing too few shards causing WriteProvisionedThroughputExceeded errors", "Not monitoring IteratorAge causing undetected consumer lag", "Using Kinesis Data Streams when Firehose delivery is sufficient", "Hardcoding shard counts without auto-scaling strategy"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/kinesis/"}, "bestPractices": ["Use enhanced fan-out for dedicated throughput per consumer", "Design partition keys to distribute load evenly across shards", "Use Kinesis Data Firehose for simple S3/Redshift delivery without custom consumers", "Enable server-side encryption for data at rest", "Monitor IteratorAge metric to detect consumer lag", "Use on-demand capacity mode for unpredictable workloads"], "sdkInitPattern": "import { KinesisClient, PutRecordCommand } from ''@aws-sdk/client-kinesis'';\n\nconst kinesis = new KinesisClient({});\nawait kinesis.send(new PutRecordCommand({\n  StreamName: ''events'',\n  PartitionKey: tenantId,\n  Data: Buffer.from(JSON.stringify(event)),\n}));", "securityGuidance": "Scope producers to PutRecord on their stream and consumers to their consumer ARN — enhanced fan-out consumers are individually addressable, use that for isolation. Enable KMS encryption on the stream, choose partition keys that spread load without embedding sensitive identifiers (they appear in metrics and errors), and remember retention is replay: anyone with read access can re-read the full window."}', '[{"kind": "source", "path": "src/streaming/kinesis-producer.ts", "priority": "essential", "description": "Kinesis stream producer client"}, {"kind": "source", "path": "src/streaming/kinesis-consumer.ts", "priority": "essential", "description": "Kinesis stream consumer with checkpoint"}, {"kind": "config", "path": "terraform/kinesis.tf", "priority": "recommended", "description": "Kinesis stream infrastructure definition"}]', '{"shardCount": {"type": "number", "label": "Shard Count", "default": 1}, "streamMode": {"enum": ["on-demand", "provisioned"], "type": "string", "label": "Capacity Mode", "default": "on-demand"}, "enhancedFanout": {"type": "boolean", "label": "Enhanced Fan-Out", "default": false}, "retentionHours": {"type": "number", "label": "Retention Hours", "default": 24}}', '["serverless-function", "worker", "database", "object-storage"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''/client-kinesis'':81C ''access'':153C ''address'':118C ''aggreg'':50B ''analyt'':48B ''anyon'':150C ''appear'':140C ''arn'':110C ''aw'':1A,3A,6B,57B,68B,79C ''await'':86C ''aws-nat'':5B,67B ''aws-sdk'':78C ''best'':43B ''broker'':72B ''buffer.from'':95C ''captur'':52B ''choos'':129C ''clickstream'':51B ''const'':82C ''consum'':41B,106C,109C,115C ''data'':11B,21B,23B,31B,34B,94C ''deliv'':33B ''elasticsearch'':39B ''embed'':136C ''enabl'':123C ''encrypt'':125C ''enhanc'':111C ''error'':144C ''event'':20B,28B,91C,97C ''fan'':113C ''fan-out'':112C ''firehos'':32B ''full'':159C ''fulli'':65B ''high'':18B ''high-volum'':17B ''identifi'':138C ''import'':74C ''individu'':117C ''ingest'':14B ''iot'':54B ''isol'':122C ''json.stringify'':96C ''kafka'':61B ''key'':131C ''kinesi'':2A,4A,22B,30B,59B,83C ''kinesis.send'':87C ''kinesiscli'':75C,85C ''kms'':124C ''load'':134C ''log'':29B,49B ''manag'':42B,66B,73B ''metric'':142C ''nativ'':7B,69B ''new'':84C,88C ''order'':26B ''partit'':130C ''partitionkey'':92C ''process'':16B ''produc'':99C ''provid'':25B ''putrecord'':101C ''putrecordcommand'':76C,89C ''re'':156C ''re-read'':155C ''read'':152C,157C ''real'':9B,46B ''real-tim'':8B,45B ''redshift'':37B ''rememb'':146C ''replay'':27B,149C ''retent'':147C ''s3'':36B ''scope'':98C ''sdk'':80C ''sensit'':137C ''spread'':133C ''stream'':12B,24B,70B,104C,128C ''streamnam'':90C ''telemetri'':55B ''tenantid'':93C ''time'':10B,47B ''use'':58B,119C ''volum'':19B ''want'':64B ''window'':160C ''without'':40B,71B,135C');
INSERT INTO public.technology_catalog VALUES ('aws-opensearch', 'AWS OpenSearch Service', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-opensearch.png', '#FF9900', '["search-engine"]', '{"purpose": "Amazon OpenSearch Service is AWS''s managed search and analytics service built around OpenSearch for full-text search, log analytics, observability, and real-time analytical querying. Use it for application search, operational analytics, security telemetry, and vector or hybrid search patterns where indexed search and aggregations are central requirements. Choose Amazon OpenSearch Service over relational databases when search relevance, inverted indexes, and analytical querying matter more than transactional integrity, and over self-managed clusters when you want managed operations. Do not use it as the primary system of record for transactional data or as a generic replacement for OLTP databases.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon OpenSearch Service", "Amazon OpenSearch Ingestion", "Amazon S3", "Amazon CloudWatch", "AWS Lambda", "Amazon Bedrock", "Kinesis Data Firehose"], "antiPatterns": ["Using OpenSearch as the only system of record for business transactions", "Designing indexes without considering shard count, mapping evolution, or retention strategy", "Mixing unrelated domains and workloads into one cluster without tenant or ownership boundaries", "Sending unbounded high-cardinality logs without lifecycle or cost controls", "Assuming search engines can replace relational joins, constraints, and transactional consistency", "Opening domains broadly without fine-grained access control or private network protections"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/opensearch-service/"}, "bestPractices": ["Define index mappings, shard strategy, and lifecycle policies based on query patterns and data retention goals", "Use separate domains, collections, or index namespaces by environment and ownership boundary", "Keep source-of-truth transactional data in durable systems and project searchable views into OpenSearch", "Enable fine-grained access control, encryption, and network restrictions for production domains", "Use ingestion pipelines and backpressure-aware producers instead of writing directly from many unmanaged clients", "Monitor query latency, shard health, indexing pressure, and storage growth continuously", "Choose specialized search features such as vector search or observability integrations deliberately for the workload"], "sdkInitPattern": "import { Client } from ''@opensearch-project/opensearch'';\nimport { AwsSigv4Signer } from ''@opensearch-project/opensearch/aws'';\nimport { defaultProvider } from ''@aws-sdk/credential-provider-node'';\n\nconst client = new Client({\n  ...AwsSigv4Signer({ region: ''us-east-1'', service: ''es'', getCredentials: defaultProvider() }),\n  node: process.env.OPENSEARCH_ENDPOINT,\n});\nawait client.search({ index: ''orders'', body: { query: { term: { ownerId: userId } } } });", "securityGuidance": "VPC-only domains with fine-grained access control on — the public-domain-plus-open-policy combination is the classic leaked-cluster story. Map IAM roles to OpenSearch roles scoped per index pattern, sign requests with SigV4 (no basic-auth master user in app code), and remember the index inherits source sensitivity: per-user document access needs security filters at query time or the search API leaks what the source APIs protect."}', '[{"kind": "config", "path": "search/index-mappings.json", "priority": "essential", "description": "Index templates, mappings, and lifecycle settings for Amazon OpenSearch"}, {"kind": "source", "path": "src/search/opensearch-client.ts", "priority": "recommended", "description": "Application client for indexing, querying, and managing OpenSearch requests"}, {"kind": "config", "path": "infra/opensearch.yaml", "priority": "recommended", "description": "Infrastructure-as-code definition for Amazon OpenSearch Service domains and access controls"}]', '{"workloadType": {"type": "string", "label": "Workload Type", "default": "search", "options": ["search", "log-analytics", "vector-search", "observability"], "description": "Primary OpenSearch usage pattern"}, "lifecyclePolicy": {"type": "boolean", "label": "Lifecycle Policy", "default": true, "description": "Apply index lifecycle management for retention and cost control"}, "fineGrainedAccess": {"type": "boolean", "label": "Fine-Grained Access", "default": true, "description": "Enable role-based and index-level access controls"}}', '["backend-service", "ai-service", "monitoring", "object-storage", "worker"]', false, NULL, NULL, '2026-03-14 21:45:27.163157+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC7A00', '''/credential-provider-node'':146C ''/opensearch'':132C ''/opensearch/aws'':139C ''1'':156C ''access'':181C,233C ''aggreg'':53B ''amazon'':6B,58B,109C,112C,115C,117C,121C ''analyt'':15B,26B,32B,40B,70B ''api'':243C,248C ''app'':220C ''applic'':37B ''around'':18B ''auth'':216C ''aw'':1A,4A,10B,119C,144C ''await'':164C ''aws-sdk'':143C ''awssigv4signer'':134C,151C ''basic'':215C ''basic-auth'':214C ''bedrock'':122C ''bodi'':168C ''built'':17B ''central'':55B ''choos'':57B ''classic'':194C ''client'':127C,148C,150C ''client.search'':165C ''cloudwatch'':118C ''cluster'':82B,197C ''code'':221C ''combin'':191C ''const'':147C ''control'':182C ''data'':100B,124C ''databas'':63B,108B ''defaultprovid'':141C,160C ''document'':232C ''domain'':176C,187C ''east'':155C ''endpoint'':163C ''es'':158C ''filter'':236C ''fine'':179C ''fine-grain'':178C ''firehos'':125C ''full'':22B ''full-text'':21B ''generic'':104B ''getcredenti'':159C ''grain'':180C ''hybrid'':46B ''iam'':200C ''import'':126C,133C,140C ''index'':50B,68B,166C,207C,225C 