INSERT INTO public.technology_catalog VALUES ('aws-redshift', 'AWS Redshift', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-redshift.png', '#8C4FFF', '["database", "data-warehouse"]', '{"purpose": "Petabyte-scale cloud data warehouse using columnar storage and massively parallel processing (MPP). Optimized for analytical queries (OLAP) across large datasets. Redshift Serverless eliminates capacity planning; Redshift Spectrum queries data directly in S3 without loading. Best for BI dashboards, reporting, and complex analytical workloads.", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using Redshift for OLTP workloads with frequent small inserts/updates", "Not defining sort keys and distribution keys for large tables", "Loading data row-by-row instead of using bulk COPY", "Running cross-cluster queries without considering data distribution"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/redshift/"}, "bestPractices": ["Choose appropriate sort keys based on query patterns (compound vs interleaved)", "Use distribution keys to minimize data shuffling across nodes", "Use COPY command for bulk data loading instead of individual INSERTs", "Enable Redshift Spectrum for querying cold data in S3 without loading", "Use workload management (WLM) to allocate resources across query types", "Schedule VACUUM and ANALYZE regularly to maintain query performance"], "securityGuidance": "No public accessibility — private subnets and security groups only. Authenticate with IAM (temporary credentials via GetCredentials/GetClusterCredentials) instead of long-lived database passwords. Encrypt the namespace with KMS, enable audit logging, and grant schema/table privileges per role — BI tools get read-only roles, never the admin user. Parameterize every query built from user input.", "configurationTemplate": "# Serverless workgroup in private subnets\r\naws redshift-serverless create-namespace --namespace-name analytics\r\naws redshift-serverless create-workgroup --workgroup-name analytics \\\r\n  --namespace-name analytics --no-publicly-accessible \\\r\n  --subnet-ids subnet-aaa subnet-bbb --security-group-ids sg-ccc"}', '[{"kind": "config", "path": "terraform/redshift.tf", "priority": "recommended", "description": "Redshift cluster or serverless configuration"}, {"kind": "schema", "path": "sql/redshift-schema.sql", "priority": "recommended", "description": "Redshift table definitions with sort/dist keys"}, {"kind": "source", "path": "etl/redshift-loader.ts", "priority": "recommended", "description": "Data loading pipeline into Redshift"}]', '{"nodeType": {"type": "string", "label": "Node Type", "default": "ra3.xlplus"}, "encrypted": {"type": "boolean", "label": "Encryption", "default": true}, "serverless": {"type": "boolean", "label": "Serverless Mode", "default": false}, "numberOfNodes": {"type": "number", "label": "Number of Nodes", "default": 2}}', '["object-storage", "worker", "backend-service", "ml-pipeline"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''access'':52C ''across'':24B ''admin'':96C ''analyt'':21B,48B ''audit'':79C ''authent'':59C ''aw'':1A,3A ''best'':41B ''bi'':43B,87C ''built'':101C ''capac'':30B ''cloud'':8B ''columnar'':12B ''complex'':47B ''credenti'':63C ''dashboard'':44B ''data'':9B,35B ''databas'':71C ''dataset'':26B ''direct'':36B ''elimin'':29B ''enabl'':78C ''encrypt'':73C ''everi'':99C ''get'':89C ''getcredentials/getclustercredentials'':65C ''grant'':82C ''group'':57C ''iam'':61C ''input'':104C ''instead'':66C ''kms'':77C ''larg'':25B ''live'':70C ''load'':40B ''log'':80C ''long'':69C ''long-liv'':68C ''massiv'':15B ''mpp'':18B ''namespac'':75C ''never'':94C ''olap'':23B ''optim'':19B ''parallel'':16B ''parameter'':98C ''password'':72C ''per'':85C ''petabyt'':6B ''petabyte-scal'':5B ''plan'':31B ''privat'':53C ''privileg'':84C ''process'':17B ''public'':51C ''queri'':22B,34B,100C ''read'':91C ''read-on'':90C ''redshift'':2A,4A,27B,32B ''report'':45B ''role'':86C,93C ''s3'':38B ''scale'':7B ''schema/table'':83C ''secur'':56C ''serverless'':28B ''spectrum'':33B ''storag'':13B ''subnet'':54C ''temporari'':62C ''tool'':88C ''use'':11B ''user'':97C,103C ''via'':64C ''warehous'':10B ''without'':39B ''workload'':49B');
INSERT INTO public.technology_catalog VALUES ('aws-route53', 'AWS Route 53', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-route53.png', '#8C4FFF', '["dns"]', '{"purpose": "Highly available and scalable DNS web service providing domain registration, DNS routing, and health checking. Supports routing policies including simple, weighted, latency-based, failover, geolocation, geoproximity, and multi-value. Commonly the entry point for all traffic into AWS architectures, routing to CloudFront, ALB, API Gateway, or S3 static sites.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Using CNAME records for zone apex domains instead of alias records", "Setting excessively low TTLs causing high DNS query volumes and costs", "Not configuring health checks for failover routing policies", "Managing DNS records manually instead of through IaC"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/route53/"}, "bestPractices": ["Use alias records for AWS resources to avoid DNS charges and get faster resolution", "Configure health checks with failover routing for high availability", "Use latency-based routing for multi-region deployments", "Enable DNSSEC signing for domain authenticity", "Use private hosted zones for internal service discovery within VPCs", "Set appropriate TTL values balancing freshness with DNS query costs"], "securityGuidance": "Zone write access is traffic control — scope route53:ChangeResourceRecordSets with change-rrset conditions (by record name/type where possible) and audit every change. Delete records when their targets are deprovisioned: dangling aliases and CNAMEs to released resources are the subdomain-takeover class. Enable DNSSEC signing where clients validate it, and treat registrar/transfer-lock settings as part of the security posture.", "configurationTemplate": "aws route53 change-resource-record-sets --hosted-zone-id Z0123 --change-batch ''{\n  \"Changes\": [{ \"Action\": \"UPSERT\", \"ResourceRecordSet\": {\n    \"Name\": \"api.example.com\", \"Type\": \"A\",\n    \"AliasTarget\": { \"HostedZoneId\": \"Z35SXDOTRQ7X7K\", \"DNSName\": \"app-alb-123.us-east-1.elb.amazonaws.com\", \"EvaluateTargetHealth\": true }\n  }}]\n}''"}', '[{"kind": "config", "path": "terraform/route53.tf", "priority": "recommended", "description": "DNS hosted zones and record definitions"}, {"kind": "config", "path": "terraform/health-checks.tf", "priority": "recommended", "description": "Route 53 health check configurations"}]', '{"routingPolicy": {"type": "string", "label": "Routing Policy", "default": "simple"}, "healthCheckEnabled": {"type": "boolean", "label": "Health Check", "default": false}}', '["cdn", "load-balancer", "api-gateway", "frontend-app"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#7340D6', '''53'':3A ''access'':59C ''alb'':50B ''alias'':88C ''api'':51B ''architectur'':46B ''audit'':77C ''avail'':7B ''aw'':1A,4A,45B ''base'':29B ''chang'':68C,79C ''change-rrset'':67C ''changeresourcerecordset'':65C ''check'':20B ''class'':99C ''client'':104C ''cloudfront'':49B ''cname'':90C ''common'':37B ''condit'':70C ''control'':62C ''dangl'':87C ''delet'':80C ''deprovis'':86C ''dns'':10B,16B ''dnssec'':101C ''domain'':14B ''enabl'':100C ''entri'':39B ''everi'':78C ''failov'':30B ''gateway'':52B ''geoloc'':31B ''geoproxim'':32B ''health'':19B ''high'':6B ''includ'':24B ''latenc'':28B ''latency-bas'':27B ''multi'':35B ''multi-valu'':34B ''name/type'':73C ''part'':112C ''point'':40B ''polici'':23B ''possibl'':75C ''postur'':116C ''provid'':13B ''record'':72C,81C ''registr'':15B ''registrar/transfer-lock'':109C ''releas'':92C ''resourc'':93C ''rout'':2A,17B,22B,47B ''route53'':5A,64C ''rrset'':69C ''s3'':54B ''scalabl'':9B ''scope'':63C ''secur'':