INSERT INTO public.technology_catalog VALUES ('aws-secrets-manager', 'AWS Secrets Manager', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-secrets-manager.png', '#DD344C', '["secret-manager"]', '{"purpose": "Centralized secrets management service for rotating, managing, and retrieving database credentials, API keys, and other secrets. Supports automatic rotation with Lambda functions, fine-grained IAM access policies, and cross-account secret sharing. Integrates natively with RDS, Redshift, and DocumentDB for automatic credential rotation.", "configMode": "declarative", "provenance": {"notes": "Phase B5 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Storing secrets in environment variables, config files, or source code instead", "Not enabling automatic rotation for database credentials", "Granting overly broad IAM permissions to retrieve all secrets", "Not using VPC endpoints when accessing from private subnets"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/secretsmanager/"}, "bestPractices": ["Enable automatic rotation for database credentials", "Use resource-based policies for cross-account access", "Reference secrets by ARN in application config rather than embedding values", "Use VPC endpoints to access Secrets Manager without traversing the internet", "Tag secrets for cost allocation and access control", "Use staging labels to manage secret versions during rotation"], "sdkInitPattern": "import { SecretsManagerClient, GetSecretValueCommand } from ''@aws-sdk/client-secrets-manager'';\r\n\r\nconst sm = new SecretsManagerClient({});\r\nconst { SecretString } = await sm.send(\r\n  new GetSecretValueCommand({ SecretId: ''prod/app/db-password'' }),\r\n);", "securityGuidance": "Grant secretsmanager:GetSecretValue per secret per identity — never a wildcard over the account''s secrets. Enable rotation for credentials that support it (RDS-managed rotation where available), fetch at runtime and hold in memory — never write secret values to disk, env files, or logs. Use resource policies for the rare cross-account share, and alarm on GetSecretValue from unexpected principals."}', '[{"kind": "config", "path": "terraform/secrets-manager.tf", "priority": "recommended", "description": "Secret definitions and rotation configuration"}, {"kind": "source", "path": "src/config/secrets.ts", "priority": "recommended", "description": "Secrets retrieval client wrapper"}]', '{"rotationDays": {"type": "number", "label": "Rotation Interval (days)", "default": 30}, "automaticRotation": {"type": "boolean", "label": "Auto-Rotation", "default": true}}', '["database", "backend-service", "serverless-function", "worker"]', false, NULL, NULL, '2026-03-04 02:00:18.012811+00', '2026-08-31 20:06:52.233344+00', NULL, '#B82A3E', '''/client-secrets-manager'':59C ''access'':33B ''account'':38B,84C,125C ''alarm'':128C ''api'':18B ''automat'':24B,49B ''avail'':99C ''aw'':1A,4A,57C ''await'':66C ''aws-sdk'':56C ''central'':7B ''const'':60C,64C ''credenti'':17B,50B,90C ''cross'':37B,124C ''cross-account'':36B,123C ''databas'':16B ''disk'':112C ''documentdb'':47B ''enabl'':87C ''env'':113C ''fetch'':100C ''file'':114C ''fine'':30B ''fine-grain'':29B ''function'':28B ''getsecretvalu'':74C,130C ''getsecretvaluecommand'':54C,69C ''grain'':31B ''grant'':72C ''hold'':104C ''iam'':32B ''ident'':78C ''import'':52C ''integr'':41B ''key'':19B ''lambda'':27B ''log'':116C ''manag'':3A,6A,9B,13B,96C ''memori'':106C ''nativ'':42B ''never'':79C,107C ''new'':62C,68C ''per'':75C,77C ''polici'':34B,119C ''princip'':133C ''prod/app/db-password'':71C ''rare'':122C ''rds'':44B,95C ''rds-manag'':94C ''redshift'':45B ''resourc'':118C ''retriev'':15B ''rotat'':12B,25B,51B,88C,97C ''runtim'':102C ''sdk'':58C ''secret'':2A,5A,8B,22B,39B,76C,86C,109C ''secretid'':70C ''secretsmanag'':73C ''secretsmanagercli'':53C,63C ''secretstr'':65C ''servic'':10B ''share'':40B,126C ''sm'':61C ''sm.send'':67C ''support'':23B,92C ''unexpect'':132C ''use'':117C ''valu'':110C ''wildcard'':81C ''write'':108C');
INSERT INTO public.technology_catalog VALUES ('aws-x-ray', 'AWS X-Ray', NULL, '#FF4F8B', '["monitoring"]', '{"purpose": "Distributed tracing service mapping request paths across microservices and AWS resources", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["OpenTelemetry", "ADOT Collector", "Lambda active tracing", "Service map", "CloudWatch integration"], "antiPatterns": ["Tracing 100 percent of requests on high-volume production services", "Dropping trace context at async boundaries like SQS", "Relying on logs alone to debug cross-service latency"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/xray/"}, "bestPractices": ["Instrument services with OpenTelemetry and the ADOT collector", "Enable active tracing on Lambda and API Gateway stages", "Propagate trace context across queue and event boundaries", "Use sampling rules to keep high-volume tracing affordable", "Annotate segments with business keys for trace filtering"], "sdkInitPattern": "import { NodeSDK } from \"@opentelemetry/sdk-node\";\nimport { OTLPTraceExporter } from \"@opentelemetry/exporter-trace-otlp-grpc\";\nnew NodeSDK({ traceExporter: new OTLPTraceExporter() }).start();", "securityGuidance": "Traces are a data store: annotations and metadata must never carry credentials, tokens, or raw PII — scrub before adding. Scope PutTraceSegments to the emitting services and console read access by role; a full trace map is an architecture disclosure. Tune sampling rules so sensitive high-volume paths are not over-collected."}', '[{"kind": "config", "path": "infra/aws/xray.tf"}]', '{"tracingMode": {"type": "enum", "label": "Tracing mode", "default": "active", "options": ["active", "passthrough"], "description": "Active samples and instruments; passthrough only forwards upstream trace headers"}, "samplingRatePercent": {"type": "number", "label": "Sampling rate (%)", "default": 5, "description": "Keep low in production; raise per-route for debugging"}}', '[{"id": "aws-lambda", "reason": "Active tracing target"}, {"id": "aws-api-gateway", "reason": "Trace initiation point"}, {"id": "aws-cloudwatch", "reason": "Correlated metrics and logs"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.233344+00', NULL, NULL, '''access'':71C ''across'':14B ''activ'':23C ''ad'':61C ''adot'':20C ''annot'':48C ''architectur'':80C ''aw'':1A,5A,17B ''carri'':53C ''cloudwatch'':27C ''collect'':95C ''collector'':21C ''consol'':69C ''credenti'':54C ''data'':46C ''disclosur'':81C ''distribut'':8B ''emit'':66C ''full'':75C ''high'':88C ''high-volum'':87C ''import'':29C,33C ''integr'':28C ''lambda'':22C ''map'':11B,26C,77C ''metadata'':50C ''microservic'':15B ''must'':51C ''never'':52C ''new'':37C,40C ''nodesdk'':30C,38C ''opentelemetri'':19C ''opentelemetry/exporter-trace-otlp-grpc'':36C ''opentelemetry/sdk-node'':32C ''otlptraceexport'':34C,41C ''over-collect'':93C ''path'':13B,90C ''pii'':58C ''puttraceseg'':63C ''raw'':57C ''ray'':4A,7A ''read'':70C ''request'':12B ''resourc'':18B ''role'':73C ''rule'':84C ''sampl'':83C ''scope'':62C ''scrub'':59C ''sensit'':86C ''servic'':10B,25C,67C ''start'':42C ''store'':47C ''token'':55C ''trace'':9B,24C,43C,76C ''traceexport'':39C ''tune'':82C ''volum'':89C ''x'':3A,6A ''x-ray'':2A');
INSERT INTO public.technology_catalog VALUES ('html-css', 'HTML/CSS/JS', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/html-css.png', '#e34c26', '["frontend-app"]', '{"purpose": "Basic static website with no framework dependencies", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["HTML5", "CSS3", "Vanilla JavaScript", "ES6+"], "antiPatterns": ["Using innerHTML with unsanitized user input creating XSS vulnerabilities", "Inline event handlers (onclick) instead of addEventListener", "Loading render-blocking scripts in the head without defer/async", "Using !important extensively instead of managing CSS specificity", "Not using semantic HTML elements affecting accessibility"], "apiReference": {"docsUrl": "https://developer.mozilla.org/en-US/docs/Web"}, "bestPractices": ["Use semantic HTML elements", "Follow CSS naming conventions (BEM)", "Implement responsive design with CSS Grid/Flexbox", "Add meta tags for SEO", "Optimize images and assets", "Use local storage for state if needed"], "sdkInitPattern": "<!DOCTYPE html>\\n<html lang=\"en\">\\n<head>\\n  <meta charset=\"UTF-8\">\\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\\n  <title>My App</title>\\n  <link rel=\"stylesheet\" href=\"styles.css\">\\n</head>\\n<body>\\n  <div id=\"app\"></div>\\n  <script type=\"module\" src=\"main.js\"></script>\\n</body>\\n</html>", "securityGuidance": "Sanitize all user-generated content before DOM insertion to prevent XSS. Use textContent instead of innerHTML for dynamic text. Set Content Security Policy headers to restrict script sources. Use SameSite cookie attributes and CSRF tokens for forms. Validate and sanitize URL parameters before use. Use Subresource Integrity (SRI) for external scripts and stylesheets.", "commonApiPatterns": [{"name": "Fetch API Call", "description": "Fetch API with auth header and error handling", "codeTemplate": "async function fetchUsers() {\\n  const res = await fetch(\"/api/users\", {\\n    headers: { \"Authorization\": `Bearer ${token}` }\\n  });\\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);\\n  return res.json();\\n}"}, {"name": "Responsive Layout", "description": "CSS Grid responsive layout with auto-fit and media query fallback", "codeTemplate": ".container {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\\n  gap: 1.5rem;\\n  padding: 1rem;\\n}\\n@media (max-width: 768px) {\\n  .container { grid-template-columns: 1fr; }\\n}"}, {"name": "Custom Element", "description": "Web Component with Shadow DOM encapsulation", "codeTemplate": "class MyComponent extends HTMLElement {\\n  connectedCallback() {\\n    this.attachShadow({ mode: \"open\" });\\n    this.shadowRoot.innerHTML = `<style>:host { display: block; }</style><slot></slot>`;\\n  }\\n}\\ncustomElements.define(\"my-component\", MyComponent);"}], "integrationPatterns": ["Vite for build tooling with HMR and optimized production builds", "Fetch API for HTTP communication with REST backends", "Web Components for framework-agnostic reusable UI components", "Service Workers for offline support and caching strategies", "CSS custom properties for theming and design tokens"], "configurationTemplate": "// vite.config.js (for vanilla HTML/CSS/JS)\\nimport { defineConfig } from \"vite\";\\nexport default defineConfig({\\n  root: \"src\",\\n  build: {\\n    outDir: \"../dist\",\\n    emptyOutDir: true,\\n    rollupOptions: {\\n      input: { main: \"src/index.html\" }\\n    }\\n  }\\n});"}', '[{"kind": "source", "path": "index.html", "language": "html", "description": "Main HTML entry point"}, {"kind": "source", "path": "styles/main.css", "language": "css", "description": "Main stylesheet"}, {"kind": "source", "path": "scripts/app.js", "language": "javascript", "description": "Main JavaScript"}]', '{"bundling": {"type": "enum", "label": "Bundling", "default": "none-plain-files", "options": ["none-plain-files", "vite"]}, "jsPosture": {"type": "enum", "label": "JavaScript posture", "default": "progressive-enhancement", "options": ["progressive-enhancement", "vanilla-spa", "minimal-none"]}, "cssApproach": {"type": "enum", "label": "CSS approach", "default": "vanilla-css", "options": ["vanilla-css", "tailwind", "sass", "bootstrap"]}}', '["rest-api", "cdn"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', 'HTML/CSS', '#C94020', '''app'':22C ''attribut'':62C ''basic'':4B ''content'':35C,51C ''cooki'':61C ''csrf'':64C ''css'':3A ''css3'':12C ''depend'':10B ''dom'':37C ''dynam'':48C ''es6'':15C ''extern'':80C ''form'':67C ''framework'':9B ''generat'':34C ''header'':54C ''html'':2A ''html/css/js'':1A ''html5'':11C ''innerhtml'':46C ''insert'':38C ''instead'':44C ''integr'':77C ''javascript'':14C ''n'':16C,17C,18C,19C,20C,23C,24C,25C,26C,27C,28C,29C ''paramet'':72C ''polici'':53C ''prevent'':40C ''restrict'':56C ''samesit'':60C ''sanit'':30C,70C ''script'':57C,81C ''secur'':52C ''set'':50C ''sourc'':58C ''sri'':78C ''static'':5B ''stylesheet'':83C ''subresourc'':76C ''text'':49C ''textcont'':43C ''token'':65C ''url'':71C ''use'':42C,59C,74C,75C ''user'':33C ''user-gener'':32C ''valid'':68C ''vanilla'':13C ''websit'':6B ''xss'':41C');
INSERT INTO public.technology_catalog VALUES ('react', 'React', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/react.png', '#61dafb', '["frontend-app"]', '{"purpose": "Component-based UI library for building interactive single-page applications", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["React 18+", "TypeScript", "Vite", "React Router", "TanStack Query", "Zustand/Jotai"], "antiPatterns": ["Prop drilling through many levels instead of using Context or state management", "Using useEffect for derived state that should be computed during render", "Creating new object/function references in render causing unnecessary re-renders", "Using index as key in lists with dynamic ordering or mutations", "Putting business logic directly in components instead of custom hooks"], "apiReference": {"docsUrl": "https://react.dev/reference/react"}, "bestPractices": ["Use functional components with hooks", "Implement proper state management (lift state up, use context sparingly)", "Memoize expensive computations with useMemo/useCallback", "Use React.lazy for code splitting", "Follow the single responsibility principle per component", "Use TypeScript for type safety", "Implement error boundaries", "Use Suspense for async data loading"], "sdkInitPattern": "npm create vite@latest my-app -- --template react-ts && cd my-app && npm install\\n// src/App.tsx\\nexport default function App() {\\n  return <div>Hello React</div>;\\n}", "securityGuidance": "React auto-escapes JSX output preventing most XSS. Never use dangerouslySetInnerHTML with unsanitized input. Validate and sanitize URL-based props (href, src) to prevent javascript: injection. Use Content Security Policy headers. Avoid storing sensitive tokens in localStorage -- use httpOnly cookies. Sanitize user input before passing to third-party libraries that manipulate DOM directly.", "commonApiPatterns": [{"name": "Component with State", "description": "Functional component with useState hook", "codeTemplate": "function Counter() {\\n  const [count, setCount] = useState(0);\\n  return (\\n    <button onClick={() => setCount(c => c + 1)}>\\n      Count: {count}\\n    </button>\\n  );\\n}"}, {"name": "Data Fetching", "description": "Custom hook for data fetching with loading state", "codeTemplate": "function useUsers() {\\n  const [users, setUsers] = useState<User[]>([]);\\n  const [loading, setLoading] = useState(true);\\n  useEffect(() => {\\n    fetch(\"/api/users\").then(r => r.json()).then(setUsers).finally(() => setLoading(false));\\n  }, []);\\n  return { users, loading };\\n}"}, {"name": "Context Provider", "description": "Context API for global state with typed custom hook", "codeTemplate": "const AuthContext = createContext<AuthState | null>(null);\\nexport function AuthProvider({ children }: { children: ReactNode }) {\\n  const [user, setUser] = useState<User | null>(null);\\n  return (\\n    <AuthContext.Provider value={{ user, setUser }}>\\n      {children}\\n    </AuthContext.Provider>\\n  );\\n}\\nexport const useAuth = () => useContext(AuthContext)!;"}], "integrationPatterns": ["React Router for client-side routing with lazy-loaded routes", "TanStack Query (React Query) for server state management and caching", "Zustand or Jotai for lightweight client state management", "Tailwind CSS or CSS Modules for scoped styling", "Vitest + React Testing Library for component testing"], "configurationTemplate": "// vite.config.ts\\nimport { defineConfig } from \"vite\";\\nimport react from \"@vitejs/plugin-react\";\\nexport default defineConfig({\\n  plugins: [react()],\\n  server: { port: 3000 },\\n  build: { sourcemap: true }\\n});\\n\\n// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2020\",\\n    \"module\": \"ESNext\",\\n    \"jsx\": \"react-jsx\",\\n    \"strict\": true,\\n    \"moduleResolution\": \"bundler\"\\n  }\\n}"}', '[{"kind": "source", "path": "src/App.tsx", "language": "typescript", "description": "Root application component"}, {"kind": "source", "path": "src/main.tsx", "language": "typescript", "description": "Application entry point"}, {"kind": "config", "path": "vite.config.ts", "language": "typescript", "description": "Vite build configuration"}, {"kind": "config", "path": "tsconfig.json", "language": "json", "description": "TypeScript configuration"}]', '{"routing": {"type": "enum", "label": "Routing", "default": "react-router", "options": ["react-router", "tanstack-router", "none-single-view"]}, "styling": {"type": "enum", "label": "Styling", "default": "tailwind", "options": ["tailwind", "css-modules", "styled-components", "vanilla-css"]}, "buildTool": {"type": "enum", "label": "Build tool", "default": "vite", "options": ["vite", "custom-webpack", "cra-legacy"], "description": "Vite is the standing default for React-without-a-metaframework; CRA is legacy. If the answer is Next.js, use the Next.js node instead"}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}, "stateManagement": {"type": "multiselect", "label": "State management", "options": ["zustand", "redux-toolkit", "tanstack-query", "jotai", "mobx", "context-only"], "description": "TanStack Query owns SERVER state; pick at most one CLIENT store beside it"}}', '["rest-api", "graphql-api", "auth-provider", "websocket-server"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#4DC0E8', '''18'':16C ''app'':30C,38C,46C ''applic'':14B ''auto'':54C ''auto-escap'':53C ''avoid'':85C ''base'':5B,72C ''build'':9B ''cd'':35C ''compon'':4B ''component-bas'':3B ''content'':81C ''cooki'':93C ''creat'':25C ''dangerouslysetinnerhtml'':63C ''default'':44C ''direct'':107C ''dom'':106C ''escap'':55C ''function'':45C ''header'':84C ''hello'':49C '