INSERT INTO public.technology_catalog VALUES ('nodejs', 'Node.js', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/nodejs.svg', '#339933', '["backend-service", "worker", "webhook-handler", "cli-tool", "shared-library", "realtime-service"]', '{"purpose": "JavaScript/TypeScript on the server — the default backend for product teams already writing TS on the frontend (one language, shared types end-to-end). Spans API services, workers, webhook handlers, CLIs and realtime services. TypeScript is the default; plain JS needs a reason.", "configMode": "code", "provenance": {"notes": "Runtime landscape verified via web search 2026-07-27 (Node LTS incumbent; Bun/Deno 2 production-real, npm-compatible) — carried as the runtime field. Row previously had EMPTY ai_context.", "method": "live-docs", "sources": ["https://nodejs.org/en/about/previous-releases"], "verifiedAt": "2026-07-27"}, "typicalTech": ["TypeScript", "Hono/Fastify", "zod", "pino", "pnpm workspaces", "vitest", "Prisma/Drizzle"], "antiPatterns": ["Blocking the event loop with sync CPU work — move it to a worker node or a queue", "Floating dependency ranges in production services", "Express-era callback patterns in new code — async/await everywhere", "Reading process.env at call sites instead of one validated config module"], "apiReference": {"docsUrl": "https://nodejs.org/docs/latest/api/"}, "bestPractices": ["TypeScript strict mode + a schema validator (zod) at every boundary — request bodies, env vars, queue payloads", "Share types with the frontend through a workspace package — the reason this stack wins is losing it is the anti-pattern", "Structured logging (pino) + graceful shutdown (SIGTERM drains in-flight work) — the two ops basics AIs skip", "Pin the runtime version in package.json engines + the lockfile committed", "Worker-role nodes: one queue consumer per process, scale horizontally — do not thread inside Node"], "sdkInitPattern": "npm init -y && npm install express typescript @types/express tsx && npx tsc --init\\n// src/server.ts\\nimport express from \"express\";\\nconst app = express();\\napp.use(express.json());\\napp.listen(3000);", "securityGuidance": "Use helmet middleware for secure HTTP headers. Validate all input with a schema library (zod, joi). Use parameterized queries to prevent SQL injection. Set rate limiting on public endpoints. Never expose stack traces in production error responses. Use environment variables for secrets, never hardcode. Enable CORS with explicit origin allowlists.", "commonApiPatterns": [{"name": "REST Endpoint", "description": "Express route handler with async DB query and error handling", "codeTemplate": "app.get(\"/api/users/:id\", async (req, res) => {\\n  const user = await db.users.findById(req.params.id);\\n  if (!user) return res.status(404).json({ error: \"Not found\" });\\n  res.json(user);\\n});"}, {"name": "Middleware", "description": "Authentication middleware pattern", "codeTemplate": "function authenticate(req, res, next) {\\n  const token = req.headers.authorization?.split(\" \")[1];\\n  if (!token) return res.status(401).json({ error: \"Unauthorized\" });\\n  try { req.user = verifyToken(token); next(); }\\n  catch { res.status(401).json({ error: \"Invalid token\" }); }\\n}"}, {"name": "Error Handler", "description": "Global error handling middleware", "codeTemplate": "app.use((err, req, res, _next) => {\\n  console.error(err.stack);\\n  res.status(err.status || 500).json({ error: err.message || \"Internal server error\" });\\n});"}], "integrationPatterns": ["Express or Fastify for HTTP server framework", "Prisma, Drizzle, or Knex for type-safe database access", "Bull/BullMQ for background job processing with Redis", "Pino or Winston for structured logging", "Jest or Vitest for testing with supertest for HTTP assertions"], "configurationTemplate": "// tsconfig.json\\n{\\n  \"compilerOptions\": {\\n    \"target\": \"ES2022\",\\n    \"module\": \"NodeNext\",\\n    \"moduleResolution\": \"NodeNext\",\\n    \"outDir\": \"./dist\",\\n    \"rootDir\": \"./src\",\\n    \"strict\": true,\\n    \"esModuleInterop\": true,\\n    \"skipLibCheck\": true\\n  },\\n  \"include\": [\"src/**/*\"]\\n}"}', '[{"kind": "source", "path": "src/index.ts", "language": "typescript", "description": "Server entry point"}, {"kind": "source", "path": "src/routes/index.ts", "language": "typescript", "description": "Route definitions"}, {"kind": "config", "path": "package.json", "language": "json", "description": "Node.js project manifest"}, {"kind": "config", "path": "tsconfig.json", "language": "json", "description": "TypeScript configuration"}]', '{"runtime": {"type": "enum", "label": "Runtime", "default": "node", "options": ["node", "bun", "deno"], "description": "Node LTS is the ecosystem incumbent; Bun (speed, all-in-one toolchain) and Deno 2 (security-by-default, npm-compatible) are real 2026 production alternatives — one node, runtime as configuration"}, "language": {"type": "enum", "label": "Language", "default": "typescript", "options": ["typescript", "javascript"]}, "framework": {"type": "enum", "label": "HTTP framework", "default": "hono", "options": ["hono", "fastify", "express", "nestjs", "plain-node-http"], "description": "Hono = modern, runtime-portable default; Fastify = Node-native performance; Express = the legacy-ecosystem choice; NestJS = batteries-included DI architecture for large teams"}, "packageManager": {"type": "enum", "label": "Package manager", "default": "pnpm", "options": ["pnpm", "npm", "bun", "yarn"]}}', '["database", "cache", "message-broker", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:36:03.876304+00', '2026-08-31 20:06:52.233344+00', NULL, '#3c873a', '''3000'':78C ''allowlist'':128C ''alreadi'':13B ''api'':28B ''app'':73C ''backend'':9B ''clis'':33B ''cor'':124C ''default'':8B,40B ''enabl'':123C ''end'':24B,26B ''end-to-end'':23B ''endpoint'':107C ''environ'':117C ''error'':114C ''explicit'':126C ''expos'':109C ''express'':59C,69C,71C,74C ''express.json'':76C ''frontend'':18B ''handler'':32B ''hardcod'':122C ''header'':85C ''helmet'':80C ''hono/fastify'':47C ''http'':84C ''init'':55C,65C ''inject'':101C ''input'':88C ''instal'':58C ''javascript/typescript'':3B ''joi'':94C ''js'':42B ''languag'':20B ''librari'':92C ''limit'':104C ''middlewar'':81C ''n'':66C ''napp.listen'':77C ''napp.use'':75C ''nconst'':72C ''need'':43B ''never'':108C,121C ''nimport'':68C ''node.js'':1A ''nodej'':2A ''npm'':54C,57C ''npx'':63C ''one'':19B ''origin'':127C ''parameter'':96C ''pino'':49C ''plain'':41B ''pnpm'':50C ''prevent'':99C ''prisma/drizzle'':53C ''product'':11B,113C ''public'':106C ''queri'':97C ''rate'':103C ''realtim'':35B ''reason'':45B ''respons'':115C ''schema'':91C ''secret'':120C ''secur'':83C ''server'':6B ''servic'':29B,36B ''set'':102C ''share'':21B ''span'':27B ''sql'':100C ''src/server.ts'':67C ''stack'':110C ''team'':12B ''trace'':111C ''ts'':15B ''tsc'':64C ''tsx'':62C ''type'':22B ''types/express'':61C ''typescript'':37B,46C,60C ''use'':79C,95C,116C ''valid'':86C ''variabl'':118C ''vitest'':52C ''webhook'':31B ''worker'':30B ''workspac'':51C ''write'':14B ''y'':56C ''zod'':48C,93C');
INSERT INTO public.technology_catalog VALUES ('nuxt', 'Nuxt', NULL, '#00dc82', '["frontend-app", "backend-service"]', '{"purpose": "Full-stack Vue framework with hybrid rendering, auto-imports, and file-based routing", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Nuxt 3", "Vue 3", "TypeScript", "Nitro", "UnJS"], "antiPatterns": ["Using axios instead of built-in useFetch breaking SSR hydration", "Putting secrets in public runtimeConfig exposing them to the client", "Not using auto-imports and manually importing Vue APIs and composables", "Creating API proxies when Nitro server routes handle it natively", "Using Options API instead of Composition API with script setup"], "apiReference": {"docsUrl": "https://nuxt.com/docs"}, "bestPractices": ["Use auto-imports for composables and components", "Leverage server routes for API endpoints", "Use useFetch/useAsyncData for data fetching", "Implement proper error handling with error.vue", "Use Nuxt modules for common functionality", "Configure proper SEO with useHead"], "sdkInitPattern": "npx nuxi@latest init my-app && cd my-app && npm install\\n<!-- app.vue -->\\n<template>\\n  <NuxtPage />\\n</template>\\n<!-- pages/index.vue -->\\n<template><h1>Hello Nuxt</h1></template>", "securityGuidance": "Use runtimeConfig for secrets (not public prefix) to keep them server-only. Validate all server route inputs with zod or similar. Use nuxt-security module for automatic security headers. Never expose database credentials in public runtime config. Use server middleware for authentication on API routes. Set CORS policies on Nitro server routes.", "commonApiPatterns": [{"name": "Data Fetching", "description": "useFetch composable for SSR-compatible data loading", "codeTemplate": "<script setup lang=\"ts\">\\nconst { data: users, pending } = await useFetch<User[]>(\"/api/users\");\\n</script>\\n<template>\\n  <div v-if=\"pending\">Loading...</div>\\n  <ul v-else>\\n    <li v-for=\"user in users\" :key=\"user.id\">{{ user.name }}</li>\\n  </ul>\\n</template>"}, {"name": "Server Route", "description": "File-based server API routes with Nitro", "codeTemplate": "// server/api/users.get.ts\\nexport default defineEventHandler(async (event) => {\\n  const users = await db.user.findMany();\\n  return users;\\n});\\n// server/api/users.post.ts\\nexport default defineEventHandler(async (event) => {\\n  const body = await readBody(event);\\n  return db.user.create({ data: body });\\n});"}, {"name": "Middleware", "description": "Route middleware for authentication guard", "codeTemplate": "// middleware/auth.ts\\nexport default defineNuxtRouteMiddleware((to, from) => {\\n  const { loggedIn } = useUserSession();\\n  if (!loggedIn.value) {\\n    return navigateTo(\"/login\", { query: { redirect: to.fullPath } });\\n  }\\n});"}], "integrationPatterns": ["Nitro server engine for API routes and server middleware", "Pinia for state management with SSR hydration support", "Nuxt Modules ecosystem for rapid feature integration", "useFetch/useAsyncData for SSR-safe data fetching", "Vitest + Nuxt Test Utils for component and integration testing"], "configurationTemplate": "// nuxt.config.ts\\nexport default defineNuxtConfig({\\n  devtools: { enabled: true },\\n  modules: [\\n    \"@nuxtjs/tailwindcss\",\\n    \"@pinia/nuxt\",\\n  ],\\n  runtimeConfig: {\\n    dbUrl: \"\",\\n    public: {\\n      apiBase: \"/api\",\\n    },\\n  },\\n});"}', '[{"kind": "source", "path": "app.vue", "language": "vue", "description": "Root component"}, {"kind": "source", "path": "nuxt.config.ts", "language": "typescript", "description": "Nuxt configuration"}]', '{"apiSurface": {"type": "boolean", "label": "server/api routes", "default": true}, "deployment": {"type": "enum", "label": "Deployment (Nitro preset)", "default": "node-server", "options": ["node-server", "static-hosting", "edge", "docker"], "description": "Nitro presets make the same app deployable to any of these — say which one is real"}, "renderingMode": {"type": "enum", "label": "Rendering", "default": "universal-ssr", "options": ["universal-ssr", "spa", "static"]}}', '["database", "cache", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#00B36B', '''3'':20C,22C ''api'':92C ''app'':32C,36C ''authent'':90C ''auto'':12B ''auto-import'':11B ''automat'':75C ''base'':17B ''cd'':33C ''config'':85C ''cor'':95C ''credenti'':81C ''databas'':80C ''expos'':79C ''file'':16B ''file-bas'':15B ''framework'':7B ''full'':4B ''full-stack'':3B ''header'':77C ''hello'':45C ''hybrid'':9B ''import'':13B ''init'':29C ''input'':64C ''instal'':38C ''keep'':55C ''latest'':28C ''middlewar'':88C ''modul'':73C ''my-app'':30C,34C ''n'':39C,40C,41C,42C,43C,44C ''never'':78C ''nitro'':24C,98C ''npm'':37C ''npx'':26C ''nuxi'':27C ''nuxt'':1A,2A,19C,46C,71C ''nuxt-secur'':70C ''polici'':96C ''prefix'':53C ''public'':52C,83C ''render'':10B ''rout'':18B,63C,93C,100C ''runtim'':84C ''runtimeconfig'':48C ''secret'':50C ''secur'':72C,76C ''server'':58C,62C,87C,99C ''server-on'':57C ''set'':94C ''similar'':68C ''stack'':5B ''typescript'':23C ''unj'':25C ''use'':47C,69C,86C ''valid'':60C ''vue'':6B,21C ''zod'':66C');
INSERT INTO public.technology_catalog VALUES ('svelte', 'Svelte', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/svelte.png', '#ff3e00', '["frontend-app"]', '{"purpose": "Compiler-based framework that shifts work from runtime to build time, producing minimal vanilla JavaScript", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Svelte 5", "SvelteKit", "TypeScript", "Vite"], "antiPatterns": ["Using onMount for data that should load via SvelteKit load functions", "Overusing stores when component-local $state is sufficient", "Using {@html} with user-provided content without sanitization", "Not using TypeScript with lang=\"ts\" losing type safety benefits", "Creating deeply nested component hierarchies instead of using slots and composition"], "apiReference": {"docsUrl": "https://svelte.dev/docs"}, "bestPractices": ["Use runes ($state, $derived, $effect) in Svelte 5", "Leverage SvelteKit for routing and SSR", "Use stores for shared state", "Keep components small and focused", "Use TypeScript for type safety", "Implement proper loading states with SvelteKit"], "sdkInitPattern": "npx sv create my-app && cd my-app && npm install\\n<!-- src/routes/+page.svelte -->\\n<script lang=\"ts\">\\n  let count = $state(0);\\n</script>\\n<button onclick={() => count++}>Count: {count}</button>", "securityGuidance": "Svelte auto-escapes template expressions. Never use {@html ...} with unsanitized user content. Validate form inputs server-side in SvelteKit form actions. Use SvelteKit hooks for centralized authentication checks. Set CSP headers via SvelteKit hooks.server.ts. Use environment variables via $env/static/private for server-only secrets.", "commonApiPatterns": [{"name": "Reactive Component", "description": "Component with Svelte 5 runes: $props, $state, $derived", "codeTemplate": "<script lang=\"ts\">\\n  let { data }: { data: PageData } = $props();\\n  let search = $state(\"\");\\n  let filtered = $derived(data.items.filter(i => i.name.includes(search)));\\n</script>\\n<input bind:value={search} placeholder=\"Search...\" />\\n{#each filtered as item (item.id)}\\n  <div>{item.name}</div>\\n{/each}"}, {"name": "SvelteKit Load Function", "description": "Server-side data loading with SvelteKit", "codeTemplate": "// src/routes/users/+page.server.ts\\nexport async function load({ fetch }) {\\n  const res = await fetch(\"/api/users\");\\n  if (!res.ok) throw error(res.status, \"Failed to load users\");\\n  const users: User[] = await res.json();\\n  return { users };\\n}"}, {"name": "Store Pattern", "description": "Writable store with derived computed value", "codeTemplate": "import { writable, derived } from \"svelte/store\";\\nexport const cart = writable<CartItem[]>([]);\\nexport const total = derived(cart, $cart =>\\n  $cart.reduce((sum, item) => sum + item.price * item.qty, 0)\\n);"}], "integrationPatterns": ["SvelteKit for full-stack framework with SSR and file-based routing", "Svelte stores for reactive state management", "Tailwind CSS or vanilla CSS scoped by default in Svelte components", "Superforms for type-safe form handling with validation", "Vitest + Svelte Testing Library for component testing"], "configurationTemplate": "// svelte.config.js\\nimport adapter from \"@sveltejs/adapter-auto\";\\nimport { vitePreprocess } from \"@sveltejs/vite-plugin-svelte\";\\nexport default {\\n  preprocess: vitePreprocess(),\\n  kit: {\\n    adapter: adapter(),\\n    alias: { \"$components\": \"src/lib/components\" }\\n  }\\n};"}', '[{"kind": "source", "path": "src/routes/+page.svelte", "language": "svelte", "description": "Home page"}, {"kind": "source", "path": "src/routes/+layout.svelte", "language": "svelte", "description": "Root layout"}, {"kind": "config", "path": "svelte.config.js", "language": "javascript", "description": "Svelte configuration"}]', '{"framework": {"type": "enum", "label": "Framework", "default": "sveltekit", "options": ["sveltekit", "svelte-standalone"], "description": "SvelteKit is the standing answer for apps; standalone Svelte for embedding components elsewhere"}, "deployment": {"type": "enum", "label": "Deployment (adapter)", "default": "node-server", "options": ["node-server", "static", "edge", "vercel"]}, "typescript": {"type": "boolean", "label": "TypeScript", "default": true}, "reactivityModel": {"type": "enum", "label": "Reactivity model", "default": "runes", "options": ["runes", "legacy-stores"], "description": "Runes ($state/$derived/$effect) are the Svelte 5+ model — pick before writing components, the authoring style differs"}}', '["rest-api", "graphql-api", "auth-provider"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#CC3200', '''5'':20C ''action'':66C ''app'':29C,33C ''authent'':72C ''auto'':46C ''auto-escap'':45C ''base'':5B ''build'':13B ''button'':39C ''cd'':30C ''central'':71C ''check'':73C ''compil'':4B ''compiler-bas'':3B ''content'':56C ''count'':41C,42C,43C ''creat'':26C ''csp'':75C ''env/static/private'':84C ''environ'':81C ''escap'':47C ''express'':49C ''form'':58C,65C ''framework'':6B ''header'':76C ''hook'':69C ''hooks.server.ts'':79C ''html'':52C ''input'':59C ''instal'':35C ''javascript'':18B ''minim'':16B ''my-app'':27C,31C ''n'':36C,37C,38C ''never'':50C ''npm'':34C ''npx'':24C ''onclick'':40C ''produc'':15B ''runtim'':11B ''secret'':89C ''server'':61C,87C ''server-on'':86C ''server-sid'':60C ''set'':74C ''shift'':8B ''side'':62C ''sv'':25C ''svelt'':1A,2A,19C,44C ''sveltekit'':21C,64C,68C,78C ''templat'':48C ''time'':14B ''typescript'':22C ''unsanit'':54C ''use'':51C,67C,80C ''user'':55C ''valid'':57C ''vanilla'':17B ''variabl'':82C ''via'':77C,83C ''vite'':23C ''work'':9B');
INSERT INTO public.technology_catalog VALUES ('swift-ios', 'Swift (iOS)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/swift-ios.png', '#F05138', '["mobile-app"]', '{"purpose": "Apple''s native programming language for iOS, iPadOS, macOS, watchOS, and tvOS application development. Use when building apps that need the deepest integration with Apple platform features -- ARKit, HealthKit, CarPlay, Widgets, App Clips, and advanced camera/CoreML capabilities. SwiftUI provides a declarative UI framework for building modern Apple apps. Native Swift apps deliver the best performance, smallest memory footprint, and most polished user experience on Apple devices. Don''t use when you need cross-platform Android support from the same codebase -- use Flutter or React Native instead. Don''t use for simple content-only apps where a cross-platform solution would be more cost-effective. Avoid Swift for backend services unless the team specifically wants server-side Swift (Vapor) -- Node.js, Go, or Python are more common choices.", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (UI model, concurrency model, persistence, distribution); live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Swift 5.9+", "SwiftUI", "Xcode", "UIKit", "Combine", "Swift Package Manager", "CoreData/SwiftData", "XCTest"], "antiPatterns": ["Massive view controllers (or massive views in SwiftUI) without proper decomposition", "Using singletons everywhere instead of dependency injection", "Force-unwrapping optionals (!) without safety checks", "Not using structured concurrency causing data races and thread-safety issues", "Ignoring memory management (retain cycles) with closures and delegates", "Blocking the main thread with synchronous network or file operations"], "apiReference": {"docsUrl": "https://developer.apple.com/documentation/"}, "bestPractices": ["Use SwiftUI with MVVM pattern for new projects targeting iOS 16+", "Use Swift concurrency (async/await, actors) instead of completion handlers", "Follow Human Interface Guidelines for navigation and layout patterns", "Use Swift Package Manager for dependency management", "Implement proper error handling with typed throws and Result types", "Write unit tests with XCTest and UI tests with XCUITest", "Use Instruments for performance profiling (Time Profiler, Memory Graph)"], "sdkInitPattern": "// Xcode: File > New > Project > App (SwiftUI)\\n// ContentView.swift\\nimport SwiftUI\\nstruct ContentView: View {\\n    var body: some View {\\n        NavigationStack {\\n            Text(\"Hello Swift\")\\n                .navigationTitle(\"Home\")\\n        }\\n    }\\n}\\n#Preview { ContentView() }", "securityGuidance": "Use Keychain Services for storing credentials and tokens. Enable App Transport Security (ATS) to enforce HTTPS. Use certificate pinning for sensitive API communications. Never store secrets in UserDefaults or plain files. Use biometric authentication (FaceID/TouchID) via LocalAuthentication framework for sensitive operations. Code-sign all releases and enable Hardened Runtime.", "commonApiPatterns": [{"name": "SwiftUI View with State", "description": "SwiftUI view with @State for local reactive state", "codeTemplate": "struct CounterView: View {\\n    @State private var count = 0\\n    var body: some View {\\n        VStack {\\n            Text(\"Count: \\\\(count)\").font(.title)\\n            Button(\"Increment\") { count += 1 }\\n        }\\n    }\\n}"}, {"name": "Async Data Loading", "description": "Observable view model with async data fetching", "codeTemplate": "@Observable class UserViewModel {\\n    var users: [User] = []\\n    var isLoading = false\\n    func loadUsers() async throws {\\n        isLoading = true\\n        defer { isLoading = false }\\n        let (data, _) = try await URLSession.shared.data(from: URL(string: \"https://api.example.com/users\")!)\\n        users = try JSONDecoder().decode([User].self, from: data)\\n    }\\n}"}, {"name": "Navigation", "description": "Type-safe navigation with NavigationStack", "codeTemplate": "NavigationStack {\\n    List(users) { user in\\n        NavigationLink(value: user) {\\n            Text(user.name)\\n        }\\n    }\\n    .navigationDestination(for: User.self) { user in\\n        UserDetailView(user: user)\\n    }\\n}"}], "setupInstructions": [{"url": "https://developer.apple.com/programs/enroll/", "type": "console", "title": "Enroll in the Apple Developer Program", "required": true, "instructions": "Required before any device install or store upload ($99/yr, org verification can take days — start early). Individual vs Organization changes the seller name on the listing."}, {"url": "https://appstoreconnect.apple.com", "type": "console", "title": "Create the App Store Connect app record", "required": true, "instructions": "Reserve the bundle ID and app name in App Store Connect. The bundle ID is permanent once shipped — decide it deliberately."}, {"type": "console", "title": "Signing: certificates + provisioning profiles", "required": true, "instructions": "Distribution certificate + provisioning profile per bundle ID. Prefer automation (Xcode managed signing, or fastlane match with an encrypted certs repo) over hand-managed .p12 files — hand-managed signing is the top cause of broken mobile CI."}, {"type": "console", "title": "TestFlight before review", "required": false, "instructions": "Internal testers are instant; external testing needs a lightweight beta review. Ship the first build to TestFlight days before the store submission, not the same day."}, {"type": "manual", "title": "App Review submission", "required": true, "instructions": "Privacy nutrition labels, export-compliance question, screenshots per device class, review notes with a demo account. First reviews commonly take 1-3 days and REJECTIONS ARE NORMAL — budget an iteration."}], "integrationPatterns": ["Supabase Swift SDK or Firebase iOS SDK for backend services", "Swift concurrency (async/await) for clean networking with URLSession", "TestFlight for beta distribution and App Store Connect for release"], "configurationTemplate": "// Package.swift (for SPM dependencies)\\n// swift-tools-version: 5.9\\nimport PackageDescription\\nlet package = Package(\\n    name: \"MyApp\",\\n    platforms: [.iOS(.v17)],\\n    dependencies: [\\n        .package(url: \"https://github.com/supabase/supabase-swift\", from: \"2.0.0\"),\\n    ]\\n)"}', '[{"kind": "config", "path": "Package.swift", "language": "swift", "description": "Swift Package Manager manifest"}, {"kind": "source", "path": "Sources/App/App.swift", "language": "swift", "description": "Application entry point"}, {"kind": "source", "path": "Sources/App/ContentView.swift", "language": "swift", "description": "Main content view"}, {"kind": "config", "path": "Info.plist", "language": "xml", "description": "Application configuration plist"}, {"kind": "source", "path": "Tests/AppTests.swift", "language": "swift", "description": "Unit test suite"}]', '{"concurrency": {"type": "enum", "label": "Concurrency", "default": "swift-concurrency", "options": ["swift-concurrency", "combine-legacy", "mixed"], "description": "async/await + actors is the current model; Combine survives in older code"}, "persistence": {"type": "enum", "label": "Persistence", "default": "swiftdata", "options": ["swiftdata", "coredata-legacy", "grdb-sqlite", "none-api-only"]}, "uiFramework": {"type": "enum", "label": "UI framework", "default": "swiftui", "options": ["swiftui", "uikit-legacy", "mixed"], "description": "SwiftUI is the standing default for new apps; UIKit interop where a control genuinely needs it"}, "distribution": {"type": "enum", "label": "Distribution", "default": "app-store", "options": ["app-store", "testflight-only", "enterprise"], "description": "Signing, provisioning profiles and App Store review are MANUAL console/Xcode steps, not code"}}', '["web.rest-api", "auth.supabase-auth", "database.firebase"]', false, NULL, NULL, '2026-02-16 02:23:50.361867+00', '2026-08-31 20:06:52.233344+00', NULL, '#D63B25', '''5.9'':137C ''advanc'':39B ''android'':80B ''api'':201C ''app'':22B,36B,52B,55B,100B,151C,189C ''appl'':5B,29B,51B,69B ''applic'':17B ''arkit'':32B ''at'':192C ''authent'':213C ''avoid'':113B ''backend'':116B ''best'':58B ''biometr'':212C ''bodi'':162C ''build'':21B,49B ''camera/coreml'':40B ''capabl'':41B ''carplay'':34B ''certif'':197C ''choic'':135B ''clip'':37B ''code'':222C ''code-sign'':221C ''codebas'':85B ''combin'':141C ''common'':134B ''communic'':202C ''content'':98B ''content-on'':97B ''contentview'':158C,179C ''contentview.swift'':154C ''coredata/swiftdata'':145C ''cost'':111B ''cost-effect'':110B ''credenti'':185C ''cross'':78B,104B ''cross-platform'':77B,103B ''declar'':45B ''deepest'':26B ''deliv'':56B ''develop'':18B ''devic'':70B ''effect'':112B ''enabl'':188C,227C ''enforc'':194C ''experi'':67B ''faceid/touchid'':214C ''featur'':31B ''file'':148C,210C ''flutter'':87B ''footprint'':62B ''framework'':47B,217C ''go'':129B ''harden'':228C ''healthkit'':33B ''hello'':169C ''home'':173C ''https'':195C ''instead'':91B ''integr'':27B ''io'':2A,4A,11B ''ipado'':12B ''keychain'':181C ''languag'':9B ''localauthent'':216C ''maco'':13B ''manag'':144C ''memori'':61B ''modern'':50B ''n'':153C,160C,165C,167C,171C,174C,175C,176C,177C ''nativ'':7B,53B,90B ''navigationstack'':166C ''navigationtitl'':172C ''need'':24B,76B ''never'':203C ''new'':149C ''nimport'':155C ''node.js'':128B ''nstruct'':157C ''oper'':220C ''packag'':143C ''perform'':59B ''pin'':198C ''plain'':209C ''platform'':30B,79B,105B ''polish'':65B ''preview'':178C ''program'':8B ''project'':150C ''provid'':43B ''python'':131B ''react'':89B ''releas'':225C ''runtim'':229C ''secret'':205C ''secur'':191C ''sensit'':200C,219C ''server'':124B ''server-sid'':123B ''servic'':117B,182C ''side'':125B ''sign'':223C ''simpl'':96B ''smallest'':60B ''solut'':106B ''specif'':121B ''store'':184C,204C ''support'':81B ''swift'':1A,3A,54B,114B,126B,136C,142C,170C ''swiftui'':42B,138C,152C,156C ''team'':120B ''text'':168C ''token'':187C ''transport'':190C ''tvos'':16B ''ui'':46B ''uikit'':140C ''unless'':118B ''use'':19B,73B,86B,94B,180C,196C,211C ''user'':66B ''userdefault'':207C ''vapor'':127B ''var'':161C ''via'':215C ''view'':159C,164C ''want'':122B ''watcho'':14B ''widget'':35B ''would'':107B ''xcode'':139C,147C ''xctest'':146C');
INSERT INTO public.technology_catalog VALUES ('unity', 'Unity', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/unity.png', '#000000', '["mobile-app", "desktop-app", "game-client"]', '{"purpose": "Cross-platform game engine for 2D/3D games, simulations, and interactive experiences using C# scripting", "configMode": "code", "provenance": {"notes": "Phase B8e additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Unity 6+", "C#", "Unity Editor", "Unity Package Manager", "Addressables", "Unity Test Framework", "DOTS/ECS", "Burst Compiler"], "antiPatterns": ["Using Find() methods in Update loops", "Not using object pooling for bullets, particles, and effects", "Allocating memory in Update/FixedUpdate causing GC spikes", "Putting all logic in massive MonoBehaviour classes", "Using string-based references for tags, layers, or animations", "Not profiling with Unity Profiler before optimizing", "Ignoring the difference between Update and FixedUpdate for physics"], "apiReference": {"docsUrl": "https://docs.unity3d.com/"}, "bestPractices": ["Use ScriptableObjects for shared data and configuration", "Implement object pooling for frequently instantiated objects", "Use assembly definitions for code organization and compile time optimization", "Leverage the new Input System for cross-platform input handling", "Use async/await with UniTask for asynchronous operations", "Implement proper scene management with additive loading", "Use Addressables for asset management and memory optimization", "Follow component-based architecture, keep MonoBehaviours small"], "sdkInitPattern": "// PlayerController.cs — intent to server, authority stays server-side\npublic class PlayerController : NetworkBehaviour\n{\n    void Update()\n    {\n        if (!IsOwner) return;\n        var input = new Vector2(Input.GetAxis(\"Horizontal\"), Input.GetAxis(\"Vertical\"));\n        SubmitInputServerRpc(input);\n    }\n\n    [ServerRpc]\n    void SubmitInputServerRpc(Vector2 input, ServerRpcParams p = default)\n    {\n        var clamped = Vector2.ClampMagnitude(input, 1f); // never trust magnitudes\n        Simulate(clamped);   // server simulates; NetworkTransform replicates down\n    }\n}", "securityGuidance": "IL2CPP obfuscates but does not protect — C# assemblies and asset bundles are extractable, so keys, drop tables, and price lists do not ship in the client; server-authoritative simulation with ServerRpc argument validation (bounds, rate, sender ownership) is the anti-cheat floor, and client-reported positions/scores are cosmetic until the server confirms them. Route IAP through receipt validation on your backend (client-side purchase callbacks are trivially forged), keep Unity Services keys server-side (Cloud Code for privileged operations), and treat mod/UGC content as untrusted — AssetBundles can carry scripts via serialized callbacks."}', '[{"kind": "source", "path": "Assets/Scripts/GameManager.cs", "language": "csharp", "description": "Core game manager"}, {"kind": "source", "path": "Assets/Scripts/Player/", "language": "csharp", "description": "Player controller scripts"}, {"kind": "config", "path": "ProjectSettings/ProjectSettings.asset", "language": "yaml", "description": "Unity project settings"}, {"kind": "config", "path": "Packages/manifest.json", "language": "json", "description": "Unity Package Manager manifest"}]', '{"targets": {"type": "multiselect", "label": "Targets", "options": ["pc-console", "mobile", "webgl"], "description": "One project, one node — build targets are configuration"}, "multiplayer": {"type": "enum", "label": "Multiplayer", "default": "none-single-player", "options": ["none-single-player", "netcode-for-gameobjects", "photon-fusion", "custom"], "description": "If multiplayer, model the game server as its own node (photon/nakama/colyseus)"}, "renderPipeline": {"type": "enum", "label": "Render pipeline", "default": "urp", "options": ["urp", "hdrp", "built-in-legacy"], "description": "URP is the default for most projects; HDRP for high-end fidelity; built-in is the legacy lane"}}', '["rest-api", "database", "ai-service"]', false, NULL, NULL, '2026-03-31 14:00:38.405595+00', '2026-08-31 20:06:52.233344+00', 'Unity', NULL, '''1f'':73C ''2d/3d'':9B ''6'':19C ''address'':26C ''anti'':124C ''anti-cheat'':123C ''argument'':115C ''assembl'':90C ''asset'':92C ''assetbundl'':173C ''author'':37C ''authorit'':111C ''backend'':146C ''bound'':117C ''bundl'':93C ''burst'':31C ''c'':16B,20C,89C ''callback'':151C,179C ''carri'':175C ''cheat'':125C ''clamp'':70C,78C ''class'':43C ''client'':108C,129C,148C ''client-report'':128C ''client-sid'':147C ''cloud'':162C ''code'':163C ''compil'':32C ''confirm'':137C ''content'':170C ''cosmet'':133C ''cross'':4B ''cross-platform'':3B ''default'':68C ''dots/ecs'':30C ''drop'':98C ''editor'':22C ''engin'':7B ''experi'':14B ''extract'':95C ''floor'':126C ''forg'':154C ''framework'':29C ''game'':6B,10B ''horizont'':56C ''iap'':140C ''il2cpp'':83C ''input'':52C,60C,65C,72C ''input.getaxis'':55C,57C ''intent'':34C ''interact'':13B ''isown'':49C ''keep'':155C ''key'':97C,158C ''list'':102C ''magnitud'':76C ''manag'':25C ''mod/ugc'':169C ''networkbehaviour'':45C ''networktransform'':81C ''never'':74C ''new'':53C ''obfusc'':84C ''oper'':166C ''ownership'':120C ''p'':67C ''packag'':24C ''platform'':5B ''playercontrol'':44C ''playercontroller.cs'':33C ''positions/scores'':131C ''price'':101C ''privileg'':165C ''protect'':88C ''public'':42C ''purchas'':150C ''rate'':118C ''receipt'':142C ''replic'':82C ''report'':130C ''return'':50C ''rout'':139C ''script'':17B,176C ''sender'':119C ''serial'':178C ''server'':36C,40C,79C,110C,136C,160C ''server-authorit'':109C ''server-sid'':39C,159C ''serverrpc'':61C,114C ''serverrpcparam'':66C ''servic'':157C ''ship'':105C ''side'':41C,149C,161C ''simul'':11B,77C,80C,112C ''stay'':38C ''submitinputserverrpc'':59C,