INSERT INTO public.technology_catalog VALUES ('yew', 'Yew', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Yew.svg', '#009a5b', '["frontend-app"]', '{"purpose": "Rust framework for creating reliable and efficient web applications compiled to WebAssembly", "configMode": "code", "provenance": {"notes": "Version-free authoring choices (router model, reactivity model, render mode) — deliberately stable against point releases; live-docs upgrade rides N10(b) freshness.", "method": "model-knowledge", "verifiedAt": "2026-07-27"}, "typicalTech": ["Yew", "Rust", "WebAssembly", "Trunk", "wasm-bindgen"], "antiPatterns": ["Excessive .clone() on state handles instead of using callbacks properly", "Not deriving PartialEq on props causing unnecessary re-renders", "Using web-sys directly when gloo provides higher-level safe abstractions", "Creating large monolithic components instead of composing smaller ones", "Ignoring WASM bundle size by including heavy dependencies"], "apiReference": {"docsUrl": "https://yew.rs/"}, "bestPractices": ["Use functional components with hooks", "Leverage Rust type system for compile-time safety", "Minimize JavaScript interop", "Use proper message-passing patterns", "Implement proper error handling with Result types"], "sdkInitPattern": "cargo install trunk && cargo init my-app && cd my-app\\ncargo add yew --features csr\\n// src/main.rs\\nuse yew::prelude::*;\\n#[function_component]\\nfn App() -> Html {\\n    html! { <h1>{\"Hello Yew\"}</h1> }\\n}\\nfn main() { yew::Renderer::<App>::new().render(); }", "securityGuidance": "Yew html! macro auto-escapes text content preventing XSS. Never use VNode::from_html with unsanitized input. All application code compiles to WASM visible to users -- never embed secrets. Validate all inputs before sending to backend APIs. Use gloo-net with proper error handling for HTTP requests. Audit dependencies with cargo-audit.", "commonApiPatterns": [{"name": "Function Component", "description": "Function component with use_state hook and callback", "codeTemplate": "#[function_component]\\nfn Counter() -> Html {\\n    let count = use_state(|| 0);\\n    let onclick = {\\n        let count = count.clone();\\n        Callback::from(move |_| count.set(*count + 1))\\n    };\\n    html! { <button {onclick}>{ format!(\"Count: {}\", *count) }</button> }\\n}"}, {"name": "Data Fetching", "description": "Data fetching with use_effect_with and spawn_local", "codeTemplate": "#[function_component]\\nfn UserList() -> Html {\\n    let users = use_state(|| Vec::<User>::new());\\n    {\\n        let users = users.clone();\\n        use_effect_with((), move |_| {\\n            wasm_bindgen_futures::spawn_local(async move {\\n                let fetched = Request::get(\"/api/users\").send().await.unwrap()\\n                    .json::<Vec<User>>().await.unwrap();\\n                users.set(fetched);\\n            });\\n        });\\n    }\\n    html! { for users.iter().map(|u| html! { <div>{&u.name}</div> }) }\\n}"}, {"name": "Props and Children", "description": "Component with typed props and children slot", "codeTemplate": "#[derive(Properties, PartialEq)]\\nstruct CardProps {\\n    title: String,\\n    children: Html,\\n}\\n#[function_component]\\nfn Card(props: &CardProps) -> Html {\\n    html! {\\n        <div class=\"card\">\\n            <h2>{ &props.title }</h2>\\n            { props.children.clone() }\\n        </div>\\n    }\\n}"}], "integrationPatterns": ["Trunk for build tooling, asset pipeline, and dev server", "yew-router for client-side routing with type-safe routes", "gloo crate family for browser API bindings (net, storage, timers)", "Tailwind CSS via Trunk CSS pipeline", "wasm-bindgen for JavaScript interop when needed"], "configurationTemplate": "# Cargo.toml\\n[package]\\nname = \"my-app\"\\nversion = \"0.1.0\"\\nedition = \"2021\"\\n\\n[dependencies]\\nyew = { version = \"0.21\", features = [\"csr\"] }\\nwasm-bindgen = \"0.2\"\\nwasm-bindgen-futures = \"0.4\"\\ngloo-net = \"0.5\"\\nserde = { version = \"1\", features = [\"derive\"] }\\n\\n# index.html (for Trunk)\\n<!DOCTYPE html>\\n<html>\\n<head><link data-trunk rel=\"css\" href=\"styles.css\" /></head>\\n<body></body>\\n</html>"}', '[{"kind": "source", "path": "src/main.rs", "language": "rust", "description": "Application entry point"}, {"kind": "config", "path": "Cargo.toml", "language": "toml", "description": "Rust project configuration"}]', '{"buildTool": {"type": "enum", "label": "Build tool", "default": "trunk", "options": ["trunk", "wasm-pack"]}, "jsInterop": {"type": "boolean", "label": "JS interop (wasm-bindgen)", "default": true, "description": "Most real Yew apps end up needing some browser-API interop — plan the boundary"}, "rendering": {"type": "enum", "label": "Rendering", "default": "csr", "options": ["csr", "ssr-hydration"]}}', '["rest-api", "grpc-service"]', false, NULL, NULL, '2026-02-06 23:30:50.186076+00', '2026-08-31 20:06:52.233344+00', NULL, '#007A4D', '''add'':35C ''api'':98C ''app'':29C,33C,48C ''applic'':11B,80C ''audit'':110C,115C ''auto'':65C ''auto-escap'':64C ''backend'':97C ''bindgen'':21C ''cargo'':22C,25C,114C ''cargo-audit'':113C ''cd'':30C ''code'':81C ''compil'':12B,82C ''compon'':46C ''content'':68C ''creat'':6B ''csr'':38C ''depend'':111C ''effici'':9B ''emb'':89C ''error'':105C ''escap'':66C ''featur'':37C ''framework'':4B ''function'':45C ''gloo'':101C ''gloo-net'':100C ''handl'':106C ''hello'':52C ''html'':49C,51C,62C,75C ''http'':108C ''init'':26C ''input'':78C,93C ''instal'':23C ''macro'':63C ''main'':56C ''my-app'':27C,31C ''n'':39C,44C,50C,54C ''ncargo'':34C ''net'':102C ''never'':71C,88C ''new'':59C ''nfn'':47C,55C ''nuse'':41C ''prelud'':43C ''prevent'':69C ''proper'':104C ''reliabl'':7B ''render'':58C,60C ''request'':109C ''rust'':3B,16C ''secret'':90C ''send'':95C ''src/main.rs'':40C ''text'':67C ''trunk'':18C,24C ''unsanit'':77C ''use'':72C,99C ''user'':87C ''valid'':91C ''visibl'':85C ''vnode'':73C ''wasm'':20C,84C ''