INSERT INTO public.technology_catalog VALUES ('aws-transit-gateway', 'AWS Transit Gateway', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Transit-Gateway_64@5x.png', '#8C4FFF', '["vpc"]', '{"purpose": "Regional hub-and-spoke router for VPC estates: attach VPCs, VPN tunnels and Direct Connect gateways to one hub and manage reachability in transit gateway route tables instead of a mesh of peering links. The scaling answer once VPC peering stops being a pair and starts being a matrix — and the segmentation point where prod, dev and shared-services routing domains are kept apart.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed under vpc per the GCP connectivity precedent - no hybrid-connectivity sub-role exists.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["TGW attachments (VPC/VPN/DX gateway)", "TGW route tables + associations/propagations", "Resource Access Manager sharing", "Inter-region TGW peering", "Terraform"], "antiPatterns": ["Keeping a growing full mesh of VPC peering links a TGW exists to replace", "One default route table every attachment shares, silently making every VPC reachable from every other", "Ignoring the per-attachment + per-GB data processing cost when a single peering link would do for two VPCs", "Inter-region peering left unencrypted assumptions — TGW peering is regional pairs, model it explicitly"], "bestPractices": ["Use separate TGW route tables as routing domains (prod / non-prod / shared-services) — segmentation is the point, not mere connectivity", "Centralize egress and inspection: one egress VPC with NAT + Network Firewall behind the TGW beats per-VPC exits", "Share the TGW across accounts with Resource Access Manager rather than building per-account networks", "Plan non-overlapping CIDRs before attaching — the TGW routes, it does not NAT overlapping ranges away"]}', '[{"kind": "config", "path": "infra/aws/transit-gateway.tf"}]', '{"crossAccount": {"type": "boolean", "label": "RAM-shared across accounts", "default": true}, "centralEgress": {"type": "boolean", "label": "Centralized egress VPC", "default": true, "description": "One inspected exit instead of per-VPC NAT"}, "routingDomains": {"type": "string", "label": "Routing domains", "default": "prod,nonprod,shared", "description": "Each becomes a TGW route table; attachments associate to exactly one"}}', '[{"id": "aws-vpc", "reason": "The spokes it interconnects"}, {"id": "aws-direct-connect", "reason": "Hybrid circuits attach via DX gateway"}, {"id": "aws-site-to-site-vpn", "reason": "VPN attachments for encrypted hybrid links"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':82C ''answer'':44B ''apart'':72B ''associations/propagations'':80C ''attach'':16B,74C ''aw'':1A,4A ''connect'':22B ''dev'':63B ''direct'':21B ''domain'':69B ''estat'':15B ''gateway'':3A,6A,23B,32B,76C ''hub'':9B,26B ''hub-and-spok'':8B ''instead'':35B ''inter'':86C ''inter-region'':85C ''kept'':71B ''link'':41B ''manag'':28B,83C ''matrix'':56B ''mesh'':38B ''one'':25B ''pair'':51B ''peer'':40B,47B,89C ''point'':60B ''prod'':62B ''reachabl'':29B ''region'':7B,87C ''resourc'':81C ''rout'':33B,68B,78C ''router'':12B ''scale'':43B ''segment'':59B ''servic'':67B ''share'':66B,84C ''shared-servic'':65B ''spoke'':11B ''start'':53B ''stop'':48B ''tabl'':34B,79C ''terraform'':90C ''tgw'':73C,77C,88C ''transit'':2A,5A,31B ''tunnel'':19B ''vpc'':14B,46B ''vpc/vpn/dx'':75C ''vpcs'':17B ''vpn'':18B');
INSERT INTO public.technology_catalog VALUES ('aws-direct-connect', 'AWS Direct Connect', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Direct-Connect_64@5x.png', '#8C4FFF', '["vpc"]', '{"purpose": "Private physical connectivity into AWS: a dedicated port (1-400 Gbps) or a hosted connection through a partner, carrying private VIFs to VPCs (via DX gateway) and public VIFs to AWS services, with BGP route exchange. Traffic bypasses the public internet — the choice for sustained bandwidth, predictable latency, and egress economics at volume. The GCP Interconnect twin.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed under vpc per the GCP interconnect precedent.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Dedicated or hosted connections", "Private/public/transit VIFs", "DX gateway + BGP", "Resiliency models (dual-site)", "Terraform"], "antiPatterns": ["A single unprotected circuit carrying production hybrid traffic under an assumed SLA", "MACsec/encryption assumptions - DX is private, not encrypted by default; encrypt at the layer that needs it", "One VIF per VPC sprawl when a DX gateway would fan out", "Choosing dedicated ports when a hosted connection matches the actual bandwidth"], "bestPractices": ["Provision two circuits in separate DX locations for any SLA that matters — the resiliency models are published, pick one deliberately", "Keep a Site-to-Site VPN as warm standby so a circuit event is a routing failover, not an incident", "Terminate private VIFs on a DX gateway + Transit Gateway so new VPCs inherit the circuit instead of new VIFs each", "Size for the sustained transfer profile - DX egress pricing vs internet egress is usually the business case"]}', '[{"kind": "config", "path": "infra/aws/direct-connect.tf"}]', '{"resiliency": {"type": "enum", "label": "Resiliency model", "default": "dual-site", "options": ["dual-site", "single-site-dual-device", "single-connection"]}, "vpnFallback": {"type": "boolean", "label": "Site-to-Site VPN fallback", "default": true}, "connectionType": {"type": "enum", "label": "Connection type", "default": "hosted-connection", "options": ["dedicated-port", "hosted-connection"]}}', '[{"id": "aws-transit-gateway", "reason": "Private VIFs land on the TGW via DX gateway"}, {"id": "aws-site-to-site-vpn", "reason": "Warm-standby fallback path"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''-400'':16B ''1'':15B ''aw'':1A,4A,11B,37B ''bandwidth'':52B ''bgp'':40B,72C ''bypass'':44B ''carri'':25B ''choic'':49B ''connect'':3A,6A,9B,21B,67C ''dedic'':13B,64C ''direct'':2A,5A ''dual'':76C ''dual-sit'':75C ''dx'':31B,70C ''econom'':57B ''egress'':56B ''exchang'':42B ''gateway'':32B,71C ''gbps'':17B ''gcp'':61B ''host'':20B,66C ''interconnect'':62B ''internet'':47B ''latenc'':54B ''model'':74C ''partner'':24B ''physic'':8B ''port'':14B ''predict'':53B ''privat'':7B,26B ''private/public/transit'':68C ''public'':34B,46B ''resili'':73C ''rout'':41B ''servic'':38B ''site'':77C ''sustain'':51B ''terraform'':78C ''traffic'':43B ''twin'':63B ''via'':30B ''vif'':27B,35B,69C ''volum'':59B ''vpcs'':29B');
INSERT INTO public.technology_catalog VALUES ('aws-site-to-site-vpn', 'AWS Site-to-Site VPN', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Site-to-Site-VPN_64@5x.png', '#8C4FFF', '["vpc"]', '{"purpose": "IPsec site-to-site connectivity between AWS and on-premises or another cloud: each connection is two tunnels to distinct AWS endpoints with BGP (or static) routing, terminating on a virtual private gateway or - preferably - a Transit Gateway. The hybrid entry point when Direct Connect bandwidth is not warranted, and the standard warm standby beside it when it is.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed under vpc per the GCP cloud-vpn precedent.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Two IPsec tunnels per connection", "BGP over IKEv2", "Customer gateway + TGW attachment", "Accelerated VPN option", "Terraform"], "antiPatterns": ["Static routes on a connection that will ever change - BGP exists for a reason", "Treating VPN as the permanent answer at sustained multi-Gbps (per-tunnel throughput caps are real) - that is Direct Connect territory", "A single customer gateway device terminating both tunnels - the AWS side is redundant, the on-prem side must match", "Per-VPC VPN sprawl that a TGW attachment would collapse"], "bestPractices": ["Keep BOTH tunnels up with BGP and monitor them - a silently-down second tunnel is the classic voided SLA", "Terminate on the Transit Gateway (not per-VPC virtual private gateways) so every spoke inherits the hybrid route", "Use accelerated VPN (Global Accelerator paths) when the peer is far from the region and jitter matters", "Plan non-overlapping CIDRs; NAT tricks inside tunnels are a permanent tax"]}', '[{"kind": "config", "path": "infra/aws/site-to-site-vpn.tf"}]', '{"routing": {"type": "enum", "label": "Routing", "default": "bgp-dynamic", "options": ["bgp-dynamic", "static"]}, "accelerated": {"type": "boolean", "label": "Accelerated VPN", "default": false}, "termination": {"type": "enum", "label": "AWS termination", "default": "transit-gateway", "options": ["transit-gateway", "virtual-private-gateway"]}}', '[{"id": "aws-transit-gateway", "reason": "Preferred termination so spokes inherit routes"}, {"id": "aws-direct-connect", "reason": "The upgrade path at sustained bandwidth"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''acceler'':81C ''anoth'':25B ''attach'':80C ''aw'':1A,7A,19B,34B ''bandwidth'':59B ''besid'':68B ''bgp'':37B,74C ''cloud'':26B ''connect'':17B,28B,58B,73C ''custom'':77C ''direct'':57B ''distinct'':33B ''endpoint'':35B ''entri'':54B ''gateway'':46B,51B,78C ''hybrid'':53B ''ikev2'':76C ''ipsec'':12B,70C ''on-premis'':21B ''option'':83C ''per'':72C ''point'':55B ''prefer'':48B ''premis'':23B ''privat'':45B ''rout'':40B ''site'':3A,5A,8A,10A,14B,16B ''site-to-sit'':2A,13B ''standard'':65B ''standbi'':67B ''static'':39B ''termin'':41B ''terraform'':84C ''tgw'':79C ''transit'':50B ''tunnel'':31B,71C ''two'':30B,69C ''virtual'':44B ''vpn'':6A,11A,82C ''warm'':66B ''warrant'':62B');
INSERT INTO public.technology_catalog VALUES ('aws-privatelink', 'AWS PrivateLink', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-PrivateLink_64@5x.png', '#8C4FFF', '["vpc", "subnet"]', '{"purpose": "Private consumer-side endpoints for services in other VPCs: reach AWS APIs, SaaS providers, or your own endpoint services through interface endpoints (ENIs with private IPs in YOUR subnets) - no peering, no public exposure, no transitive-network blast radius. Producers publish behind an NLB as an endpoint service with an allow-list; consumers mint endpoints against it. The GCP Private Service Connect twin, and the standard shape for multi-tenant SaaS ingestion on AWS.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed vpc+subnet per the GCP PSC precedent - endpoint ENIs are subnet-planned.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Interface endpoints (ENI-based)", "Endpoint services behind NLB", "Private DNS integration", "Gateway endpoints for S3/DynamoDB", "Terraform"], "antiPatterns": ["VPC peering to consume one service, inheriting the producer network as attack surface", "Auto-accepting every connection request on a production endpoint service", "Split-brain DNS where some clients quietly resolve the public endpoint", "Forgetting the per-AZ + per-GB endpoint pricing on chatty high-volume paths where a gateway endpoint or peering is cheaper"], "bestPractices": ["Prefer interface endpoints over VPC peering for service consumption - peering shares route tables, PrivateLink shares exactly one service", "Producers: front the service with an NLB endpoint service and keep acceptance manual or principal-allow-listed", "Enable private DNS on endpoints so SDK default hostnames resolve privately and traffic cannot fall back to public paths", "Use gateway endpoints (free) for S3/DynamoDB and reserve interface endpoints for everything else - the cost profiles differ"]}', '[{"kind": "config", "path": "infra/aws/privatelink.tf"}]', '{"direction": {"type": "enum", "label": "Role in the pattern", "default": "consumer-endpoint", "options": ["consumer-endpoint", "producer-endpoint-service", "both"]}, "acceptance": {"type": "enum", "label": "Producer acceptance", "default": "allow-listed-principals", "options": ["allow-listed-principals", "manual-accept", "auto-accept"]}, "privateDns": {"type": "boolean", "label": "Private DNS on endpoints", "default": true}}', '[{"id": "aws-vpc", "reason": "Endpoints live in its subnets"}, {"id": "aws-elb", "reason": "Producer side publishes behind an NLB"}, {"id": "aws-s3", "reason": "Gateway-endpoint consumption pattern"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''allow'':58B ''allow-list'':57B ''api'':17B ''aw'':1A,3A,16B,82B ''base'':87C ''behind'':48B,90C ''blast'':44B ''connect'':69B ''consum'':7B,60B ''consumer-sid'':6B ''dns'':93C ''endpoint'':9B,23B,27B,53B,62B,84C,88C,96C ''eni'':28B,86C ''eni-bas'':85C ''exposur'':39B ''gateway'':95C ''gcp'':66B ''ingest'':80B ''integr'':94C ''interfac'':26B,83C ''ip'':31B ''list'':59B ''mint'':61B ''multi'':77B ''multi-ten'':76B ''network'':43B ''nlb'':50B,91C ''peer'':36B ''privat'':5B,30B,67B,92C ''privatelink'':2A,4A ''produc'':46B ''provid'':19B ''public'':38B ''publish'':47B ''radius'':45B ''reach'':15B ''s3/dynamodb'':98C ''saa'':18B,79B ''servic'':11B,24B,54B,68B,89C ''shape'':74B ''side'':8B ''standard'':73B ''subnet'':34B ''tenant'':78B ''terraform'':99C ''transit'':42B ''transitive-network'':41B ''twin'':70B ''vpcs'':14B');
INSERT INTO public.technology_catalog VALUES ('aws-vpc-lattice', 'AWS VPC Lattice', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-VPC-Lattice_64@5x.png', '#8C4FFF', '["service-mesh"]', '{"purpose": "Application-layer service network across VPCs and accounts: register services (on ECS, EKS, EC2 or Lambda), group them in a service network, and get service-to-service connectivity with IAM auth policies, HTTP routing and weighted targets - without sidecars, peering or self-managed proxies. The successor lane to App Mesh (end of support Sept 2026) and AWS''s answer where GCP reaches for Cloud Service Mesh.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed service-mesh beside gcp-cloud-service-mesh; App Mesh (EOS 2026-09) is deliberately NOT a row - Lattice is its successor.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Service networks + services", "IAM auth policies", "Target groups (ECS/EKS/EC2/Lambda)", "Weighted routing", "RAM cross-account sharing"], "antiPatterns": ["Rebuilding App Mesh sidecar patterns here - Lattice is proxyless by design", "Anonymous (no-auth) service networks in production because IAM policies felt like friction", "Using Lattice as public ingress - it is service-to-service fabric, not an edge", "Ignoring the per-GB processing cost on high-volume east-west paths that a direct NLB would serve cheaper"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/vpc-lattice/"}, "bestPractices": ["Authorize service-to-service with IAM auth policies on the service network - identity-based, not IP-based", "Put each environment in its own service network; share across accounts with RAM instead of flattening", "Use weighted target groups for canary shifts between service versions", "Model Lattice as the INTERNAL service plane and keep public ingress on ALB/API Gateway - they answer different doors"], "securityGuidance": "Auth policies on the service network are the east-west security boundary - require authenticated principals (no anonymous access) and scope by source service identity. Lattice traffic stays on the AWS network, but private does not mean authorized: treat every service-network policy like an IAM review."}', '[{"kind": "config", "path": "infra/aws/vpc-lattice.tf"}]', '{"authMode": {"type": "enum", "label": "Service network auth", "default": "iam-auth-policies", "options": ["iam-auth-policies", "none-dev-only"]}, "crossAccount": {"type": "boolean", "label": "RAM-shared service network", "default": false}, "targetPlatforms": {"type": "multiselect", "label": "Target platforms", "default": ["ecs"], "options": ["eks", "ecs", "ec2", "lambda"], "description": "Where registered services actually run"}}', '[{"id": "aws-eks", "reason": "Cluster workloads join the service network"}, {"id": "aws-ecs", "reason": "Service targets without sidecars"}, {"id": "aws-lambda", "reason": "Functions as first-class Lattice targets"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''2026'':64B ''access'':110C ''account'':15B,90C ''across'':12B ''anonym'':109C ''answer'':68B ''app'':58B ''applic'':8B ''application-lay'':7B ''auth'':39B,80C,92C ''authent'':106C ''author'':129C ''aw'':1A,4A,66B,122C ''boundari'':104C ''cloud'':73B ''connect'':36B ''cross'':89C ''cross-account'':88C ''east'':101C ''east-west'':100C ''ec'':19B ''ec2'':21B ''ecs/eks/ec2/lambda'':84C ''ek'':20B ''end'':60B ''everi'':131C ''gcp'':70B ''get'':31B ''group'':24B,83C ''http'':41B ''iam'':38B,79C,138C ''ident'':116C ''lambda'':23B ''lane'':56B ''lattic'':3A,6A,117C ''layer'':9B ''like'':136C ''manag'':52B ''mean'':128C ''mesh'':59B,75B ''network'':11B,29B,77C,97C,123C,134C ''peer'':48B ''polici'':40B,81C,93C,135C ''princip'':107C ''privat'':125C ''proxi'':53B ''ram'':87C ''reach'':71B ''regist'':16B ''requir'':105C ''review'':139C ''rout'':42B,86C ''scope'':112C ''secur'':103C ''self'':51B ''self-manag'':50B ''sept'':63B ''servic'':10B,17B,28B,33B,35B,74B,76C,78C,96C,115C,133C ''service-network'':132C ''service-to-servic'':32B ''share'':91C ''sidecar'':47B ''sourc'':114C ''stay'':119C ''successor'':55B ''support'':62B ''target'':45B,82C ''traffic'':118C ''treat'':130C ''vpc'':2A,5A ''vpcs'':13B ''weight'':44B,85C ''west'':102C ''without'':46B');
INSERT INTO public.technology_catalog VALUES ('aws-global-accelerator', 'AWS Global Accelerator', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Global-Accelerator_64@5x.png', '#8C4FFF', '["load-balancer"]', '{"purpose": "Anycast entry point onto the AWS backbone: two static global IPs front regional endpoints (ALB/NLB/EIP), with traffic dials for regional failover and client traffic entering the AWS network at the nearest edge. Choose it for non-HTTP protocols, static-IP allow-listing requirements, or fast cross-region failover; choose CloudFront when the workload is HTTP and cacheable.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Static anycast IP pair", "Listeners + endpoint groups per region", "Traffic dials / endpoint weights", "Client IP preservation", "Terraform"], "antiPatterns": ["Fronting a single-region HTTP app with GA when CloudFront (or nothing) is the right answer", "Treating the two static IPs as load balancers - GA routes to load balancers, it does not replace them", "Failover topology that exists only in the diagram because traffic dials were never exercised", "Ignoring per-GB + per-accelerator pricing on bulk transfer paths"], "bestPractices": ["Use it for TCP/UDP and static-IP requirements - CloudFront already covers cacheable HTTP", "Set endpoint weights + traffic dials as the failover plan and TEST the dial-down, do not just own it", "Enable client IP preservation where the backend needs real source addresses", "Health checks drive routing - align them with the endpoint targets'' own health model"]}', '[{"kind": "config", "path": "infra/aws/global-accelerator.tf"}]', '{"regions": {"type": "string", "label": "Endpoint regions", "default": "us-east-1,eu-west-1"}, "protocolClass": {"type": "enum", "label": "Traffic class", "default": "multi-region-failover", "options": ["tcp-udp-non-http", "http-static-ip-requirement", "multi-region-failover"]}, "clientIpPreservation": {"type": "boolean", "label": "Client IP preservation", "default": true}}', '[{"id": "aws-elb", "reason": "The regional endpoints behind the anycast IPs"}, {"id": "aws-cloudfront", "reason": "The HTTP/cacheable alternative at the edge"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''acceler'':3A,6A ''alb/nlb/eip'':21B ''allow'':50B ''allow-list'':49B ''anycast'':7B,69C ''aw'':1A,4A,12B,33B ''backbon'':13B ''cacheabl'':67B ''choos'':39B,59B ''client'':29B,81C ''cloudfront'':60B ''cross'':56B ''cross-region'':55B ''dial'':24B,78C ''edg'':38B ''endpoint'':20B,73C,79C ''enter'':31B ''entri'':8B ''failov'':27B,58B ''fast'':54B ''front'':18B ''global'':2A,5A,16B ''group'':74C ''http'':44B,65B ''ip'':17B,48B,70C,82C ''list'':51B ''listen'':72C ''nearest'':37B ''network'':34B ''non'':43B ''non-http'':42B ''onto'':10B ''pair'':71C ''per'':75C ''point'':9B ''preserv'':83C ''protocol'':45B ''region'':19B,26B,57B,76C ''requir'':52B ''static'':15B,47B,68C ''static-ip'':46B ''terraform'':84C ''traffic'':23B,30B,77C ''two'':14B ''weight'':80C ''workload'':63B');
INSERT INTO public.technology_catalog VALUES ('aws-network-firewall', 'AWS Network Firewall', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Network-Firewall_64@5x.png', '#DD344C', '["network-firewall"]', '{"purpose": "Managed stateful network firewall (Suricata-compatible) for VPC traffic: deploy firewall endpoints in dedicated subnets, route traffic through them with VPC route tables, and enforce stateful rule groups - domain allow-lists, IPS signatures, protocol controls - at the network layer. The inspection point in a centralized-egress architecture; WAF inspects requests at the edge, this inspects packets in the network.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Lands the network-firewall role its first technology.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Firewall endpoints + dedicated subnets", "Stateful rule groups (Suricata)", "Domain allow-lists", "TGW inspection-VPC pattern", "Terraform"], "antiPatterns": ["Confusing it with WAF - HTTP request inspection at the edge is a different product and layer", "Firewall endpoints in shared subnets with workloads - they get dedicated subnets and route-table plumbing", "Alert-only rule groups in production that everyone assumes are blocking", "Per-VPC firewalls when the traffic already transits a TGW hub where one inspection VPC would do"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/network-firewall/"}, "bestPractices": ["Deploy centrally behind the Transit Gateway (inspection VPC) rather than per-VPC firewall sprawl", "Start with egress domain allow-listing - it is the highest-value stateful rule class for most estates", "Manage Suricata rules as code and version rule groups like application releases", "Route symmetrically - asymmetric paths around a stateful firewall drop legitimate return traffic"], "securityGuidance": "Route-table plumbing IS the enforcement: any subnet whose routes bypass the firewall endpoints is uninspected regardless of policy, so review route tables as part of the firewall change process. Log both alert and flow streams to CloudWatch/S3 and treat rule-group edits with change control - a permissive stateful rule silently opens the whole estate behind it."}', '[{"kind": "config", "path": "infra/aws/network-firewall.tf"}, {"kind": "config", "path": "infra/aws/firewall-rules/"}]', '{"logging": {"type": "boolean", "label": "Alert + flow logging", "default": true}, "deployment": {"type": "enum", "label": "Deployment model", "default": "central-inspection-vpc", "options": ["central-inspection-vpc", "per-vpc"]}, "ruleClasses": {"type": "multiselect", "label": "Rule classes", "default": ["egress-domain-allowlist"], "options": ["egress-domain-allowlist", "ips-signatures", "protocol-controls", "geo-controls"]}}', '[{"id": "aws-transit-gateway", "reason": "The hub that routes traffic through the inspection VPC"}, {"id": "aws-vpc", "reason": "Endpoints live in dedicated subnets"}, {"id": "aws-waf", "reason": "The request-layer complement at the edge"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''alert'':120C ''allow'':38B,79C ''allow-list'':37B,78C ''architectur'':56B ''aw'':1A,4A ''behind'':144C ''bypass'':98C ''central'':54B ''centralized-egress'':53B ''chang'':116C,133C ''cloudwatch/s3'':125C ''compat'':13B ''control'':43B,134C ''dedic'':21B,71C ''deploy'':17B ''domain'':36B,77C ''edg'':62B ''edit'':131C ''egress'':55B ''endpoint'':19B,70C,101C ''enforc'':32B,93C ''estat'':143C ''firewal'':3A,6A,10B,18B,69C,100C,115C ''flow'':122C ''group'':35B,75C,130C ''inspect'':49B,58B,64B,83C ''inspection-vpc'':82C ''ip'':40B ''layer'':47B ''list'':39B,80C ''log'':118C ''manag'':7B ''network'':2A,5A,9B,46B,68B ''open'':140C ''packet'':65B ''part'':112C ''pattern'':85C ''permiss'':136C ''plumb'':90C ''point'':50B ''polici'':106C ''process'':117C ''protocol'':42B ''regardless'':104C ''request'':59B ''review'':108C ''rout'':23B,29B,88C,97C,109C ''route-t'':87C ''rule'':34B,74C,129C,138C ''rule-group'':128C ''signatur'':41B ''silent'':139C ''state'':8B,33B,73C,137C ''stream'':123C ''subnet'':22B,72C,95C ''suricata'':12B,76C ''suricata-compat'':11B ''tabl'':30B,89C,110C ''terraform'':86C ''tgw'':81C ''traffic'':16B,24B ''treat'':127C ''uninspect'':103C ''vpc'':15B,28B,84C ''waf'':57B ''whole'':142C ''whose'':96C');
INSERT INTO public.technology_catalog VALUES ('aws-verified-access', 'AWS Verified Access', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Verified-Access_64@5x.png', '#DD344C', '["auth-provider"]', '{"purpose": "Zero-trust access to internal applications without a VPN: Verified Access endpoints front private apps and evaluate each request against identity (IAM Identity Center or OIDC) and device trust (integrated device-posture providers) using Cedar policies. The BeyondCorp pattern on AWS - the GCP Identity-Aware Proxy twin - so internal tools get identity-gated instead of network-gated.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The IAP parity row; beyondcorp-class umbrella branding skipped in the GCP round applies here to Client VPN instead.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Verified Access instances/groups/endpoints", "Cedar policies", "IAM Identity Center / OIDC trust providers", "Device-posture integrations", "Terraform"], "antiPatterns": ["Backends still directly reachable beside the endpoint - the gate must be the only path", "Identity-only policies when device posture integration is available for admin surfaces", "Treating it as a VPN replacement for non-HTTP protocols it does not carry - that remains network-layer", "Per-user policy sprawl that group-based Cedar policies would collapse"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/verified-access/"}, "bestPractices": ["Write Cedar policies against group claims and device-trust context, not individual users", "Put EVERY internal web tool behind it before standing up another client VPN", "Verify the signed Verified Access JWT in the application - defense in depth if anything bypasses the endpoint", "Log access decisions and review denials - they are your zero-trust telemetry"], "securityGuidance": "Enforce at the endpoint AND verify the signed identity header in the app; lock backend security groups to the Verified Access ENIs so the proxy is unavoidable. Policies are the boundary - review Cedar changes like IAM changes."}', '[{"kind": "config", "path": "infra/aws/verified-access.tf"}]', '{"devicePosture": {"type": "boolean", "label": "Device-trust provider", "default": false}, "identitySource": {"type": "enum", "label": "Identity source", "default": "iam-identity-center", "options": ["iam-identity-center", "oidc-provider"]}, "appJwtVerification": {"type": "boolean", "label": "Backend JWT verification", "default": true}}', '[{"id": "aws-iam-identity-center", "reason": "The workforce identity source"}, {"id": "aws-elb", "reason": "Fronts the private application load balancers"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':3A,6A,10B,18B,70C,105C ''app'':22B,97C ''applic'':13B ''aw'':1A,4A,49B ''awar'':54B ''backend'':99C ''beyondcorp'':46B ''boundari'':115C ''cedar'':43B,72C,117C ''center'':31B,76C ''chang'':118C,121C ''devic'':35B,39B,81C ''device-postur'':38B,80C ''endpoint'':19B,88C ''enforc'':85C ''eni'':106C ''evalu'':24B ''front'':20B ''gate'':63B,68B ''gcp'':51B ''get'':60B ''group'':101C ''header'':94C ''iam'':29B,74C,120C ''ident'':28B,30B,53B,62B,75C,93C ''identity-awar'':52B ''identity-g'':61B ''instances/groups/endpoints'':71C ''instead'':64B ''integr'':37B,83C ''intern'':12B,58B ''like'':119C ''lock'':98C ''network'':67B ''network-g'':66B ''oidc'':33B,77C ''pattern'':47B ''polici'':44B,73C,112C ''postur'':40B,82C ''privat'':21B ''provid'':41B,79C ''proxi'':55B,109C ''request'':26B ''review'':116C ''secur'':100C ''sign'':92C ''terraform'':84C ''tool'':59B ''trust'':9B,36B,78C ''twin'':56B ''unavoid'':111C ''use'':42B ''verifi'':2A,5A,17B,69C,90C,104C ''vpn'':16B ''without'':14B ''zero'':8B ''zero-trust'':7B');
INSERT INTO public.technology_catalog VALUES ('aws-iam-identity-center', 'AWS IAM Identity Center', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-IAM-Identity-Center_64@5x.png', '#DD344C', '["auth-provider"]', '{"purpose": "Workforce single sign-on for an AWS estate: one identity source (its own directory, or federated Entra ID/Okta/any SAML+SCIM IdP) mapped through permission sets onto accounts across the organization, plus SSO into SAML applications. It is the HUMAN access plane - short-lived credentials via the access portal and CLI - where IAM itself remains the workload authorization plane. (Formerly AWS SSO.)", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Complements the existing aws-iam row: Identity Center is the workforce plane, IAM the workload plane.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Permission sets", "SAML + SCIM federation", "Multi-account assignments (Organizations)", "SSO access portal + CLI", "Terraform"], "antiPatterns": ["IAM users with static access keys for humans surviving beside a working SSO deployment", "Per-user account assignments that turn offboarding into archaeology", "One almighty AdministratorAccess permission set as the everyday grant", "Skipping SCIM so departed users linger in the Identity Center store"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/singlesignon/"}, "bestPractices": ["Federate the existing IdP with SCIM provisioning - Identity Center maps identities, it should not become a second directory to reconcile", "Model permission sets as the reviewable vocabulary (ReadOnly, Developer, Ops, BreakGlass) assigned to GROUPS on accounts", "Make CLI/SDK access go through SSO short-lived credentials - long-lived IAM user keys for humans end here", "Alert on break-glass permission-set use and review assignments quarterly"], "securityGuidance": "This is the human keys-to-the-kingdom plane: protect the IdP federation trust and the management account, require MFA at the IdP, and keep permission-set changes under review - a quiet edit to a broad permission set is an estate-wide grant. Workload identities stay on IAM roles; do not route service auth through Identity Center."}', '[{"kind": "config", "path": "infra/aws/identity-center.tf"}]', '{"cliSso": {"type": "boolean", "label": "CLI via SSO credentials", "default": true}, "identitySource": {"type": "enum", "label": "Identity source", "default": "external-idp-scim", "options": ["external-idp-scim", "identity-center-directory", "active-directory"]}, "permissionSetModel": {"type": "string", "label": "Permission sets", "default": "readonly,developer,ops,breakglass"}}', '[{"id": "aws-iam", "reason": "Permission sets materialize as IAM roles per account"}, {"id": "aws-verified-access", "reason": "Serves as its workforce identity source"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':49B,57B,83C ''account'':36B,79C,105C ''across'':37B ''applic'':44B ''assign'':80C ''auth'':143C ''author'':67B ''aw'':1A,5A,16B,70B ''broad'':124C ''center'':4A,8A,146C ''chang'':116C ''cli'':60B,85C ''credenti'':54B ''directori'':23B ''edit'':121C ''entra'':26B ''estat'':17B,130C ''estate-wid'':129C ''feder'':25B,76C,100C ''former'':69B ''grant'':132C ''human'':48B,90C ''iam'':2A,6A,62B,137C ''id/okta/any'':27B ''ident'':3A,7A,19B,134C,145C ''idp'':30B,99C,110C ''keep'':112C ''key'':92C ''keys-to-the-kingdom'':91C ''kingdom'':95C ''live'':53B ''manag'':104C ''map'':31B ''mfa'':107C ''multi'':78C ''multi-account'':77C ''one'':18B ''onto'':35B ''organ'':39B,81C ''permiss'':33B,72C,114C,125C ''permission-set'':113C ''plane'':50B,68B,96C ''plus'':40B ''portal'':58B,84C ''protect'':97C ''quiet'':120C ''remain'':64B ''requir'':106C ''review'':118C ''role'':138C ''rout'':141C ''saml'':28B,43B,74C ''scim'':29B,75C ''servic'':142C ''set'':34B,73C,115C,126C ''short'':52B ''short-liv'':51B ''sign'':12B ''sign-on'':11B ''singl'':10B ''sourc'':20B ''sso'':41B,71B,82C ''stay'':135C ''terraform'':86C ''trust'':101C ''via'':55B ''wide'':131C ''workforc'':9B ''workload'':66B,133C');
INSERT INTO public.technology_catalog VALUES ('aws-certificate-manager', 'AWS Certificate Manager', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Certificate-Manager_64@5x.png', '#DD344C', '["certificate-manager"]', '{"purpose": "Managed public TLS certificates issued, validated (DNS via Route 53) and AUTO-RENEWED, bound directly to CloudFront, ALB/NLB, API Gateway and other integrated services - the certificate lifecycle disappears as an operational concern for anything terminating TLS on managed AWS surfaces. Private certificates come from the separate Private CA product; certs for your own hosts are exportable only in specific shapes - ACM is for AWS-terminated TLS.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-certificate-manager parity row on the certificate-manager role.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["DNS-validated public certs", "Auto-renewal", "CloudFront/ALB/API Gateway bindings", "Route 53 validation records", "Terraform"], "antiPatterns": ["Manual certificate uploads for surfaces ACM integrates with natively", "Expecting to export ACM public certs onto arbitrary servers - terminate on managed surfaces or use Private CA", "Forgetting the us-east-1 requirement for CloudFront and debugging a phantom", "Letting validation CNAMEs be deleted after issuance, breaking silent renewal later"], "bestPractices": ["Validate via DNS with Route 53 so renewal stays hands-off forever - email validation is a recurring chore", "Request certs in the region of the consumer (us-east-1 for CloudFront; the ALB region otherwise)", "Use wildcard + SAN deliberately per zone rather than one mega-cert every service shares", "Alert on RENEWAL_FAILED - auto-renewal fails exactly when DNS validation records were cleaned up"]}', '[{"kind": "config", "path": "infra/aws/acm.tf"}]', '{"consumers": {"type": "multiselect", "label": "Bound to", "default": ["alb-nlb"], "options": ["cloudfront", "alb-nlb", "api-gateway"]}, "validation": {"type": "enum", "label": "Validation", "default": "dns-route53", "options": ["dns-route53", "dns-external", "email-legacy"]}, "renewalAlarm": {"type": "boolean", "label": "Renewal-failure alarm", "default": true}}', '[{"id": "aws-route53", "reason": "DNS validation and the zones the certs cover"}, {"id": "aws-cloudfront", "reason": "Edge TLS termination (us-east-1 certs)"}, {"id": "aws-elb", "reason": "Regional TLS termination"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''53'':16B,87C ''acm'':68B ''alb/nlb'':25B ''anyth'':41B ''api'':26B ''auto'':19B,81C ''auto-renew'':18B,80C ''aw'':1A,4A,46B,72B ''aws-termin'':71B ''bind'':85C ''bound'':21B ''ca'':55B ''cert'':57B,79C ''certif'':2A,5A,10B,33B,49B ''cloudfront'':24B ''cloudfront/alb/api'':83C ''come'':50B ''concern'':39B ''direct'':22B ''disappear'':35B ''dns'':13B,76C ''dns-valid'':75C ''export'':63B ''gateway'':27B,84C ''host'':61B ''integr'':30B ''issu'':11B ''lifecycl'':34B ''manag'':3A,6A,7B,45B ''oper'':38B ''privat'':48B,54B ''product'':56B ''public'':8B,78C ''record'':89C ''renew'':20B,82C ''rout'':15B,86C ''separ'':53B ''servic'':31B ''shape'':67B ''specif'':66B ''surfac'':47B ''termin'':42B,73B ''terraform'':90C ''tls'':9B,43B,74B ''valid'':12B,77C,88C ''via'':14B');
INSERT INTO public.technology_catalog VALUES ('aws-guardduty', 'AWS GuardDuty', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-GuardDuty_64@5x.png', '#DD344C', '["monitoring"]', '{"purpose": "Managed threat detection over the telemetry AWS already has - CloudTrail events, VPC flow logs, DNS logs, plus protection planes for S3, EKS runtime, RDS logins, Lambda and malware scanning. Zero agents to deploy for the core planes; findings name the threat, the resource and the evidence. The detection half of the estate''s security posture - Security Hub aggregates and prioritizes what GuardDuty and friends find.", "configMode": "external", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). SCC-parity class: GuardDuty is the threat-detection plane, Security Hub (separate row) the posture aggregation plane - separate paid products practitioners wire separately, unlike GCP where SCC carries both.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Org-level enablement + delegated admin", "Protection planes (S3/EKS/RDS/Lambda/Malware)", "EventBridge findings routing", "Suppression rules", "Terraform"], "antiPatterns": ["Treating enablement as the outcome - detection without a drain path is compliance theater", "Running trusted-IP lists so broad that exfiltration paths are pre-forgiven", "Per-account manual enablement drift across a growing organization", "Disabling a whole protection plane to silence one noisy finding class"], "bestPractices": ["Enable at the ORGANIZATION level with a delegated security account - per-account enablement leaves shadow accounts dark", "Route findings to EventBridge into the triage flow (ticketing/SIEM/pager) - an unread findings console is decoration", "Turn on the protection planes that match the estate (EKS runtime, S3, RDS) deliberately - each is a separate cost lever", "Suppress known-benign findings with named suppression rules, with rationale, not by ignoring the console"]}', '[{"kind": "config", "path": "infra/aws/guardduty.tf"}]', '{"scope": {"type": "enum", "label": "Enablement scope", "default": "organization-delegated-admin", "options": ["organization-delegated-admin", "single-account"]}, "findingsRouting": {"type": "enum", "label": "Findings routing", "default": "eventbridge-to-triage", "options": ["eventbridge-to-triage", "siem-export", "console-only"]}, "protectionPlanes": {"type": "multiselect", "label": "Protection planes", "default": ["s3"], "options": ["s3", "eks-runtime", "rds-login", "lambda", "malware"]}}', '[{"id": "aws-security-hub", "reason": "Aggregates and prioritizes its findings"}, {"id": "aws-eventbridge", "reason": "The findings-to-triage transport"}, {"id": "aws-cloudtrail", "reason": "A primary telemetry source it analyzes"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''admin'':75C ''agent'':35B ''aggreg'':62B ''alreadi'':12B ''aw'':1A,3A,11B ''cloudtrail'':14B ''core'':40B ''deleg'':74C ''deploy'':37B ''detect'':7B,52B ''dns'':19B ''ek'':26B ''enabl'':73C ''estat'':56B ''event'':15B ''eventbridg'':79C ''evid'':50B ''find'':42B,69B,80C ''flow'':17B ''friend'':68B ''guardduti'':2A,4A,66B ''half'':53B ''hub'':61B ''lambda'':30B ''level'':72C ''log'':18B,20B ''login'':29B ''malwar'':32B ''manag'':5B ''name'':43B ''org'':71C ''org-level'':70C ''plane'':23B,41B,77C ''plus'':21B ''postur'':59B ''priorit'':64B ''protect'':22B,76C ''rds'':28B ''resourc'':47B ''rout'':81C ''rule'':83C ''runtim'':27B ''s3'':25B ''s3/eks/rds/lambda/malware'':78C ''scan'':33B ''secur'':58B,60B ''suppress'':82C ''telemetri'':10B ''terraform'':84C ''threat'':6B,45B ''vpc'':16B ''zero'':34B');
INSERT INTO public.technology_catalog VALUES ('aws-security-hub', 'AWS Security Hub', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Security-Hub_64@5x.png', '#DD344C', '["monitoring"]', '{"purpose": "Security posture aggregation for the whole estate: continuously evaluates accounts against standards (AWS Foundational Security Best Practices, CIS, PCI), ingests findings from GuardDuty, Inspector, Macie and partners into one normalized queue (ASFF), and scores posture per account and control. The single pane the drain process works from - detection tools feed it; humans and automations drain it.", "configMode": "external", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The posture half beside aws-guardduty - together they cover what gcp-security-command-center carries in one row.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Security standards (FSBP/CIS/PCI)", "ASFF normalized findings", "Cross-account aggregation", "EventBridge automation rules", "Terraform"], "antiPatterns": ["Enabling every standard on day one and drowning the queue into learned helplessness", "Treating the score as the deliverable while criticals age for quarters", "Suppressing control failures estate-wide to green a dashboard before an audit", "Running it single-account while the organization grows around it"], "bestPractices": ["Enable org-wide with central configuration so new accounts inherit standards automatically", "Pick the standards you will actually remediate and disable controls with WRITTEN rationale - a red dashboard nobody drains teaches people to ignore red", "Automate the repetitive fixes with EventBridge automation rules; save humans for judgment findings", "Track the drain rate per severity as the real posture metric, not the score alone"]}', '[{"kind": "config", "path": "infra/aws/security-hub.tf"}]', '{"scope": {"type": "enum", "label": "Scope", "default": "organization-central-config", "options": ["organization-central-config", "single-account"]}, "standards": {"type": "multiselect", "label": "Standards", "default": ["aws-fsbp"], "options": ["aws-fsbp", "cis", "pci-dss", "nist-800-53"]}, "automationRules": {"type": "boolean", "label": "Automated remediation rules", "default": false}}', '[{"id": "aws-guardduty", "reason": "Primary findings source"}, {"id": "aws-eventbridge", "reason": "Automation and escalation transport"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''account'':16B,43B,70C ''aggreg'':9B,71C ''asff'':38B,65C ''autom'':60B,73C ''aw'':1A,4A,19B ''best'':22B ''cis'':24B ''continu'':14B ''control'':45B ''cross'':69C ''cross-account'':68C ''detect'':54B ''drain'':50B,61B ''estat'':13B ''evalu'':15B ''eventbridg'':72C ''feed'':56B ''find'':27B,67C ''foundat'':20B ''fsbp/cis/pci'':64C ''guardduti'':29B ''hub'':3A,6A ''human'':58B ''ingest'':26B ''inspector'':30B ''maci'':31B ''normal'':36B,66C ''one'':35B ''pane'':48B ''partner'':33B ''pci'':25B ''per'':42B ''postur'':8B,41B ''practic'':23B ''process'':51B ''queue'':37B ''rule'':74C ''score'':40B ''secur'':2A,5A,7B,21B,62C ''singl'':47B ''standard'':18B,63C ''terraform'':75C ''tool'':55B ''whole'':12B ''work'':52B');
INSERT INTO public.technology_catalog VALUES ('aws-macie', 'AWS Macie', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Macie_64@5x.png', '#DD344C', '["external-service"]', '{"purpose": "Sensitive-data discovery for S3: managed and custom data identifiers scan buckets for PII, credentials and financial data, map which buckets are public/unencrypted/shared, and emit findings per object class. The answer to WHERE regulated data actually lives versus where policy says it lives. Discovery-focused - the de-identification/transform half that GCP''s Sensitive Data Protection carries inline lives in your pipelines on AWS (Glue/DataBrew jobs, Comprehend PII via Bedrock-era tooling).", "configMode": "external", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-cloud-dlp parity row; filed external-service with the same role-gap note (no security-tooling/inspection role - refile when one lands).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Automated sensitive data discovery", "Managed + custom data identifiers", "Bucket posture map", "EventBridge findings routing", "Terraform"], "antiPatterns": ["Scanning everything once for an audit and never again - data distribution drifts monthly", "Findings routed to a security alias while the bucket-owning teams never see them", "Assuming Macie transforms or masks - it discovers; remediation is your pipeline''s job", "Ignoring the bucket-posture map (public/unencrypted) because the PII scan is the shiny part"], "bestPractices": ["Run automated discovery org-wide with a delegated admin account rather than ad-hoc scans after incidents", "Add custom data identifiers for the org''s own sensitive shapes (internal IDs, contract numbers) - the managed set does not know your business", "Wire findings to EventBridge with bucket owners on the hook, and treat NEW sensitive-data-in-new-location findings as regressions", "Sample and scope jobs by bucket criticality - full-estate full-depth scans are a billing event, not a policy"]}', '[{"kind": "config", "path": "infra/aws/macie.tf"}]', '{"scope": {"type": "enum", "label": "Scope", "default": "organization-delegated-admin", "options": ["organization-delegated-admin", "single-account"]}, "discoveryCadence": {"type": "enum", "label": "Discovery cadence", "default": "automated-continuous", "options": ["automated-continuous", "scheduled-jobs", "on-demand"]}, "customIdentifiers": {"type": "boolean", "label": "Custom data identifiers", "default": true}}', '[{"id": "aws-s3", "reason": "The surface it discovers sensitive data across"}, {"id": "aws-security-hub", "reason": "Findings aggregate into the posture queue"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''/transform'':56B ''actual'':41B ''answer'':36B ''autom'':81C ''aw'':1A,3A,71B ''bedrock'':78B ''bedrock-era'':77B ''bucket'':17B,26B,89C ''carri'':64B ''class'':34B ''comprehend'':74B ''credenti'':20B ''custom'':13B,86C ''data'':7B,14B,23B,40B,62B,83C,87C ''de'':54B ''de-identif'':53B ''discoveri'':8B,50B,84C ''discovery-focus'':49B ''emit'':30B ''era'':79B ''eventbridg'':92C ''financi'':22B ''find'':31B,93C ''focus'':51B ''gcp'':59B ''glue/databrew'':72B ''half'':57B ''identif'':55B ''identifi'':15B,88C ''inlin'':65B ''job'':73B ''live'':42B,48B,66B ''maci'':2A,4A ''manag'':11B,85C ''map'':24B,91C ''object'':33B ''per'':32B ''pii'':19B,75B ''pipelin'':69B ''polici'':45B ''postur'':90C ''protect'':63B ''public/unencrypted/shared'':28B ''regul'':39B ''rout'':94C ''s3'':10B ''say'':46B ''scan'':16B ''sensit'':6B,61B,82C ''sensitive-data'':5B ''terraform'':95C ''tool'':80B ''versus'':43B ''via'':76B');
INSERT INTO public.technology_catalog VALUES ('aws-cloudtrail', 'AWS CloudTrail', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-CloudTrail_64@5x.png', '#DD344C', '["logging"]', '{"purpose": "The audit log of the AWS control plane: every management API call - who, what, when, from where - recorded estate-wide, with optional data events (S3 object-level, Lambda invoke) and CloudTrail Lake for SQL over the archive. Distinct from CloudWatch by subject: CloudWatch watches your WORKLOADS, CloudTrail records what principals DID TO the platform. Every incident reconstruction and most compliance regimes start here.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). ADD despite the GCP audit-log skip: on GCP audit logs ride the Cloud Logging product (already a row); on AWS CloudTrail is its own service, own storage, own controls.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Organization trail", "Log file validation digests", "Data events (S3/Lambda)", "CloudTrail Lake queries", "Terraform"], "antiPatterns": ["The audit bucket writable by the accounts being audited", "Assuming the default 90-day event history is your compliance archive - it is not; the trail to S3 is", "Blanket S3 data events on high-traffic buckets discovered via the bill", "Nobody alerting on a stopped trail - the first move of a competent intruder"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/cloudtrail/"}, "bestPractices": ["One organization trail to a dedicated, locked-down S3 bucket in a security account - per-account trail drift is how gaps happen", "Enable log file validation (digest chains) so tampering is detectable", "Turn on data events selectively for the buckets/functions that matter - blanket data events are a cost surprise", "Feed GuardDuty/SIEM from the trail and alert on the classics: root usage, CloudTrail stops, IAM policy changes"], "securityGuidance": "The trail is evidence: deliver to a bucket in a separate security account with deny-delete policies and MFA-delete-class controls, enable validation digests, and alert on StopLogging/PutEventSelectors calls. Treat trail configuration changes as security incidents until proven routine."}', '[{"kind": "config", "path": "infra/aws/cloudtrail.tf"}]', '{"scope": {"type": "enum", "label": "Trail scope", "default": "organization-trail", "options": ["organization-trail", "account-trail"]}, "dataEvents": {"type": "multiselect", "label": "Data events", "default": ["none"], "options": ["s3-selected-buckets", "lambda-selected-functions", "none"]}, "logValidation": {"type": "boolean", "label": "Log file validation", "default": true}}', '[{"id": "aws-s3", "reason": "The locked-down delivery bucket"}, {"id": "aws-guardduty", "reason": "Analyzes the trail for threats"}, {"id": "aws-cloudwatch", "reason": "The workload-telemetry complement"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''account'':94C ''alert'':110C ''api'':15B ''archiv'':43B ''audit'':6B ''aw'':1A,3A,10B ''bucket'':89C ''call'':16B,113C ''chang'':117C ''class'':104C ''cloudtrail'':2A,4A,37B,53B,78C ''cloudwatch'':46B,49B ''complianc'':66B ''configur'':116C ''control'':11B,105C ''data'':28B,75C ''delet'':98C,103C ''deliv'':86C ''deni'':97C ''deny-delet'':96C ''digest'':74C,108C ''distinct'':44B ''enabl'':106C ''estat'':24B ''estate-wid'':23B ''event'':29B,76C ''everi'':13B,61B ''evid'':85C ''file'':72C ''incid'':62B,120C ''invok'':35B ''lake'':38B,79C ''lambda'':34B ''level'':33B ''log'':7B,71C ''manag'':14B ''mfa'':102C ''mfa-delete-class'':101C ''object'':32B ''object-level'':31B ''option'':27B ''organ'':69C ''plane'':12B ''platform'':60B ''polici'':99C ''princip'':56B ''proven'':122C ''queri'':80C ''reconstruct'':63B ''record'':22B,54B ''regim'':67B ''routin'':123C ''s3'':30B ''s3/lambda'':77C ''secur'':93C,119C ''separ'':92C ''sql'':40B ''start'':68B ''stoplogging/puteventselectors'':112C ''subject'':48B ''terraform'':81C ''trail'':70C,83C,115C ''treat'':114C ''valid'':73C,107C ''watch'':50B ''wide'':25B ''workload'':52B');
INSERT INTO public.technology_catalog VALUES ('aws-data-firehose', 'AWS Data Firehose', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Data-Firehose_64@5x.png', '#FF4F8B', '["event-stream"]', '{"purpose": "Fully managed delivery streams: ingest records (direct PUT, Kinesis Data Streams, MSK) and land them in S3, Redshift, OpenSearch or HTTP endpoints with buffering, dynamic partitioning, format conversion (JSON to Parquet) and optional Lambda transforms - zero consumers to operate. The delivery half of the streaming story: Kinesis/MSK are the durable streams applications read; Firehose is how streams become datasets.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Renamed from Kinesis Data Firehose to Amazon Data Firehose - the aws-kinesis row remains the durable-stream side.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Delivery streams (S3/Redshift/OpenSearch/HTTP)", "Dynamic partitioning", "Parquet format conversion", "Transform Lambda", "Terraform"], "antiPatterns": ["Using Firehose as an application message bus - consumers cannot subscribe to a delivery stream; that is Kinesis/MSK/SNS", "JSON-at-rest lakes because format conversion felt like configuration", "One stream for unrelated data families, forcing one partitioning scheme onto all of them", "Ignoring the small-file problem until Athena queries crawl"], "bestPractices": ["Convert to Parquet at delivery and dynamically partition - downstream Athena/Redshift cost and speed are decided HERE", "Tune buffer size/interval per destination - small buffers make many small files, the classic S3 lake pathology", "Use the transform Lambda for light normalization only; heavy enrichment belongs in Flink or Glue", "Monitor delivery failures and the error prefix - silent dead-lettering into the error path is a data-loss illusion"]}', '[{"kind": "config", "path": "infra/aws/firehose.tf"}]', '{"destination": {"type": "enum", "label": "Destination", "default": "s3-parquet", "options": ["s3-parquet", "redshift", "opensearch", "http-endpoint"]}, "transformLambda": {"type": "boolean", "label": "Transform Lambda", "default": false}, "dynamicPartitioning": {"type": "boolean", "label": "Dynamic partitioning", "default": true}}', '[{"id": "aws-kinesis", "reason": "The durable stream it drains"}, {"id": "aws-s3", "reason": "The usual landing zone"}, {"id": "aws-redshift", "reason": "Warehouse delivery target"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''applic'':58B ''aw'':1A,4A ''becom'':64B ''buffer'':30B ''consum'':43B ''convers'':34B,73C ''data'':2A,5A,16B ''dataset'':65B ''deliveri'':9B,47B,66C ''direct'':13B ''durabl'':56B ''dynam'':31B,69C ''endpoint'':28B ''firehos'':3A,6A,60B ''format'':33B,72C ''fulli'':7B ''half'':48B ''http'':27B ''ingest'':11B ''json'':35B ''kinesi'':15B ''kinesis/msk'':53B ''lambda'':40B,75C ''land'':20B ''manag'':8B ''msk'':18B ''opensearch'':25B ''oper'':45B ''option'':39B ''parquet'':37B,71C ''partit'':32B,70C ''put'':14B ''read'':59B ''record'':12B ''redshift'':24B ''s3'':23B ''s3/redshift/opensearch/http'':68C ''stori'':52B ''stream'':10B,17B,51B,57B,63B,67C ''terraform'':76C ''transform'':41B,74C ''zero'':42B');
INSERT INTO public.technology_catalog VALUES ('aws-managed-flink', 'AWS Managed Service for Apache Flink', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Managed-Service-for-Apache-Flink_64@5x.png', '#8C4FFF', '["ml-pipeline"]', '{"purpose": "Managed Apache Flink for stateful stream processing: windowed aggregations, joins across streams, event-time processing with exactly-once state, reading from Kinesis/MSK and writing to the warehouse, lakes or streams. The step up from Firehose-class delivery when the computation itself is the point - sessionization, fraud windows, real-time features. Flink applications are CODE (Java/Python/SQL) you own; AWS runs the cluster, checkpoints and scaling.", "configMode": "code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Formerly Kinesis Data Analytics. No generic flink row exists - this row is the catalog carrier for the stream-processing-with-state capability on AWS (contrast Managed Grafana/Prometheus, skipped because generic rows exist).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Flink DataStream / Table API", "Event time + watermarks", "Checkpoints + snapshots", "Kinesis/MSK sources", "Parquet/S3 + stream sinks"], "antiPatterns": ["Using Flink where Firehose delivery or an SQS consumer would do - operational weight without computational need", "Unbounded state (keyed state with no TTL) discovered as ever-growing checkpoints", "Ignoring watermark strategy until late events silently vanish from windows", "Upgrading application code without a snapshot-restore path rehearsed"], "bestPractices": ["Design around event time + watermarks from day one - processing-time jobs quietly lie under replay and lag", "Size state and checkpoint intervals deliberately; snapshots are your recovery AND upgrade mechanism - test restoring from them", "Keep one job per application - multiplexing unrelated topologies into one Flink app couples their failure and scaling", "Use Flink SQL / Table API where it fits before hand-rolling operators"]}', '[{"kind": "source", "path": "streaming/flink-app/"}, {"kind": "config", "path": "infra/aws/managed-flink.tf"}]', '{"source": {"type": "enum", "label": "Primary source", "default": "kinesis", "options": ["kinesis", "msk"]}, "apiLevel": {"type": "enum", "label": "API level", "default": "flink-sql", "options": ["flink-sql", "table-api", "datastream-api"]}, "checkpointInterval": {"type": "number", "label": "Checkpoint interval (s)", "default": 60}}', '[{"id": "aws-kinesis", "reason": "Primary stream source"}, {"id": "aws-msk", "reason": "Kafka source alternative"}, {"id": "aws-s3", "reason": "Lake sink for processed output"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''across'':20B ''aggreg'':18B ''apach'':5A,11B ''api'':81C ''applic'':65B ''aw'':1A,7A,71B ''checkpoint'':75B,85C ''class'':48B ''cluster'':74B ''code'':67B ''comput'':52B ''datastream'':79C ''deliveri'':49B ''event'':23B,82C ''event-tim'':22B ''exact'':28B ''exactly-onc'':27B ''featur'':63B ''firehos'':47B ''firehose-class'':46B ''flink'':6A,9A,12B,64B,78C ''fraud'':58B ''java/python/sql'':68B ''join'':19B ''kinesis/msk'':33B,87C ''lake'':39B ''manag'':2A,8A,10B ''parquet/s3'':89C ''point'':56B ''process'':16B,25B ''read'':31B ''real'':61B ''real-tim'':60B ''run'':72B ''scale'':77B ''servic'':3A ''session'':57B ''sink'':91C ''snapshot'':86C ''sourc'':88C ''state'':14B,30B ''step'':43B ''stream'':15B,21B,41B,90C ''tabl'':80C ''time'':24B,62B,83C ''warehous'':38B ''watermark'':84C ''window'':17B,59B ''write'':35B');
INSERT INTO public.technology_catalog VALUES ('aws-mwaa', 'AWS Managed Workflows for Apache Airflow', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Managed-Workflows-for-Apache-Airflow_64@5x.png', '#8C4FFF', '["ml-pipeline"]', '{"purpose": "Managed Apache Airflow: DAGs deployed via S3, workers scaled by AWS, IAM-integrated connections - batch orchestration for data and ML pipelines where dependencies, backfills and retries are the actual product. The AWS twin of Cloud Composer. Choose Step Functions for event-driven service orchestration; choose Airflow when the mental model is scheduled DAGs owned by a data team.", "configMode": "definition-as-code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Cloud Composer parity; no generic airflow row exists, so this row carries the capability.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["DAGs via S3 deployment", "Airflow operators/providers", "IAM execution roles", "CloudWatch task logs", "Terraform"], "antiPatterns": ["Doing the data processing INSIDE Airflow workers - the scheduler becomes the bottleneck and the bill", "Unversioned DAGs edited straight in the bucket", "One mega-DAG entangling every pipeline''s failure domain", "Choosing MWAA for event-driven microservice flows that Step Functions models natively"], "bestPractices": ["Treat the S3 DAGs bucket as a deployment target from CI - reviewed, versioned, never hand-uploaded", "Keep DAGs thin: orchestration logic in Airflow, heavy lifting in the services it triggers (Glue/EMR/ECS tasks)", "Pin provider/package versions in requirements.txt and rehearse environment upgrades - Airflow version drift breaks operators", "Design DAGs idempotent so backfills and retries are safe by construction"]}', '[{"kind": "source", "path": "dags/"}, {"kind": "config", "path": "infra/aws/mwaa.tf"}]', '{"dagDeployment": {"type": "enum", "label": "DAG deployment", "default": "ci-to-s3", "options": ["ci-to-s3", "manual-s3-legacy"]}, "workloadTargets": {"type": "string", "label": "Orchestrated services", "default": "glue,emr,ecs"}, "environmentClass": {"type": "enum", "label": "Environment class", "default": "mw1-small", "options": ["mw1-small", "mw1-medium", "mw1-large"]}}', '[{"id": "aws-glue", "reason": "The ETL jobs it orchestrates"}, {"id": "aws-emr", "reason": "Cluster jobs under DAG control"}, {"id": "aws-s3", "reason": "DAG deployment + data staging"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''actual'':38B ''airflow'':6A,11B,56B,73C ''apach'':5A,10B ''aw'':1A,7A,19B,41B ''backfil'':33B ''batch'':24B ''choos'':46B,55B ''cloud'':44B ''cloudwatch'':78C ''compos'':45B ''connect'':23B ''dag'':12B,63B,69C ''data'':27B,67B ''depend'':32B ''deploy'':13B,72C ''driven'':52B ''event'':51B ''event-driven'':50B ''execut'':76C ''function'':48B ''iam'':21B,75C ''iam-integr'':20B ''integr'':22B ''log'':80C ''manag'':2A,9B ''mental'':59B ''ml'':29B ''model'':60B ''mwaa'':8A ''operators/providers'':74C ''orchestr'':25B,54B ''own'':64B ''pipelin'':30B ''product'':39B ''retri'':35B ''role'':77C ''s3'':15B,71C ''scale'':17B ''schedul'':62B ''servic'':53B ''step'':47B ''task'':79C ''team'':68B ''terraform'':81C ''twin'':42B ''via'':14B,70C ''worker'':16B ''workflow'':3A');
INSERT INTO public.technology_catalog VALUES ('aws-lake-formation', 'AWS Lake Formation', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Lake-Formation_64@5x.png', '#8C4FFF', '["external-service"]', '{"purpose": "Governance layer over the S3 + Glue Data Catalog lake: register lake locations once, then grant table/column/row-level permissions to principals centrally, enforced across Athena, Redshift Spectrum, Glue and EMR. The answer to WHO may read WHICH columns of the lake - replacing a thicket of bucket policies with database-style grants. The AWS twin of Dataplex''s governance half; cataloging itself lives in Glue.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-dataplex parity row; filed external-service with the same role-gap note (no data-governance role - refile when one lands).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Registered lake locations", "LF-Tags (TBAC)", "Table/column/row-level grants", "Cross-account shares", "Terraform"], "antiPatterns": ["Running S3 bucket policies AND LF grants for the same paths with nobody sure which wins", "Per-table manual grants at scale where LF-Tags were the design", "Treating it as ETL - movement/transformation is Glue''s job; LF governs", "Registering locations without revoking the direct S3 access that bypasses governance"], "bestPractices": ["Move enforcement to Lake Formation grants and retire broad S3 bucket-policy access to lake paths - two overlapping permission systems is how leaks happen", "Use LF-Tags (tag-based access control) so new tables inherit policy by classification instead of per-table grants", "Grant to roles/groups mapped from the identity plane, never to individual users", "Audit effective permissions periodically - the cross-account + tag matrix drifts"]}', '[{"kind": "config", "path": "infra/aws/lake-formation.tf"}]', '{"accessModel": {"type": "enum", "label": "Access model", "default": "lf-tags-tbac", "options": ["lf-tags-tbac", "named-resource-grants"]}, "granularity": {"type": "multiselect", "label": "Grant granularity", "default": ["table", "column"], "options": ["table", "column", "row-cell"]}, "crossAccount": {"type": "boolean", "label": "Cross-account shares", "default": false}}', '[{"id": "aws-s3", "reason": "The lake storage it governs"}, {"id": "aws-glue", "reason": "The catalog its permissions attach to"}, {"id": "aws-athena", "reason": "Queries enforce LF grants"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''account'':81C ''across'':28B ''answer'':36B ''athena'':29B ''aw'':1A,4A,58B ''bucket'':50B ''catalog'':14B,65B ''central'':26B ''column'':42B ''cross'':80C ''cross-account'':79C ''data'':13B ''databas'':54B ''database-styl'':53B ''dataplex'':61B ''emr'':34B ''enforc'':27B ''format'':3A,6A ''glue'':12B,32B,69B ''govern'':7B,63B ''grant'':21B,56B,78C ''half'':64B ''lake'':2A,5A,15B,17B,45B,71C ''layer'':8B ''lf'':74C ''lf-tag'':73C ''live'':67B ''locat'':18B,72C ''may'':39B ''permiss'':23B ''polici'':51B ''princip'':25B ''read'':40B ''redshift'':30B ''regist'':16B,70C ''replac'':46B ''s3'':11B ''share'':82C ''spectrum'':31B ''style'':55B ''table/column/row-level'':22B,77C ''tag'':75C ''tbac'':76C ''terraform'':83C ''thicket'':48B ''twin'':59B');
INSERT INTO public.technology_catalog VALUES ('aws-sagemaker', 'AWS SageMaker', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-sagemaker.png', '#55C2A2', '["inference-service", "ml-pipeline"]', '{"purpose": "AWS fully managed machine learning platform for building, training, and deploying ML models at scale. Provides Studio IDE, built-in algorithms, distributed training, real-time and batch inference endpoints, and MLOps pipelines. Best for teams building custom ML models on AWS who need end-to-end ML lifecycle management. Use SageMaker when you need model training infrastructure, experiment tracking, or managed inference endpoints. Use OpenAI/Anthropic for pre-trained LLM access without custom training.", "configMode": "declarative", "provenance": {"notes": "Phase B4 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "antiPatterns": ["Training models on notebook instances instead of using training jobs", "Not using Model Monitor in production causing silent model degradation", "Skipping SageMaker Pipelines for ad-hoc training runs", "Using SageMaker for simple LLM API calls (use Bedrock or direct API)", "Not cleaning up endpoints causing unnecessary hosting costs"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/sagemaker/"}, "bestPractices": ["Use SageMaker Pipelines for reproducible ML workflows", "Enable Model Monitor for detecting data drift and model quality degradation", "Use Spot instances for training to reduce costs up to 90%", "Store training data in S3 and reference via SageMaker Data channels", "Use SageMaker Feature Store for reusable feature engineering", "Version models in Model Registry for production deployment governance"], "sdkInitPattern": "# SageMaker Python SDK — deploy a trained model to an endpoint\r\nimport sagemaker\r\nfrom sagemaker.model import Model\r\n\r\nsession = sagemaker.Session()\r\nmodel = Model(image_uri=image_uri, model_data=model_s3_uri, role=execution_role_arn)\r\npredictor = model.deploy(initial_instance_count=1, instance_type=''ml.m5.large'')", "securityGuidance": "Scope the execution role to the specific S3 buckets and ECR repos a job needs — the examples'' broad AmazonSageMakerFullAccess is not a production posture. Run training and endpoints in VPC mode when data is sensitive, and KMS-encrypt volumes and model artifacts. Endpoints are invoked with SigV4/IAM — grant sagemaker:InvokeEndpoint per caller, and never front an endpoint with an unauthenticated proxy."}', '[{"kind": "source", "path": "ml/training/train.py", "priority": "essential", "description": "Model training script"}, {"kind": "source", "path": "ml/inference/handler.py", "priority": "essential", "description": "Inference endpoint handler"}, {"kind": "source", "path": "ml/pipelines/pipeline.py", "priority": "recommended", "description": "SageMaker Pipeline definition"}, {"kind": "config", "path": "terraform/sagemaker.tf", "priority": "recommended", "description": "SageMaker infrastructure definition"}]', '{"framework": {"enum": ["pytorch", "tensorflow", "sklearn", "xgboost", "huggingface"], "type": "string", "label": "Framework", "default": "pytorch"}, "mlLifecycle": {"type": "multiselect", "label": "ML lifecycle stages", "options": ["training", "inference-endpoints", "pipelines", "data-labeling", "feature-store"], "description": "Ground Truth (labeling) and the SageMaker sub-products are configuration of this platform node, not separate nodes"}, "endpointType": {"enum": ["real-time", "serverless", "batch"], "type": "string", "label": "Endpoint Type", "default": "real-time"}, "instanceType": {"type": "string", "label": "Instance Type", "default": "ml.m5.large"}}', '["rest-api", "object-storage", "worker", "event-stream"]', false, NULL, NULL, '2026-03-04 00:48:04.051147+00', '2026-08-31 20:06:52.578953+00', NULL, '#14500B', '''1'':120C ''access'':78B ''algorithm'':26B ''amazonsagemakerfullaccess'':142C ''arn'':114C ''artifact'':166C ''aw'':1A,3A,5B,47B ''batch'':33B ''best'':39B ''broad'':141C ''bucket'':132C ''build'':12B,42B ''built'':24B ''built-in'':23B ''caller'':176C ''count'':119C ''custom'':43B,80B ''data'':107C,156C ''deploy'':15B,85C ''distribut'':27B ''ecr'':134C ''encrypt'':162C ''end'':51B,53B ''end-to-end'':50B ''endpoint'':35B,70B,91C,151C,167C,181C ''exampl'':140C ''execut'':112C,126C ''experi'':65B ''front'':179C ''fulli'':6B ''grant'':172C ''ide'':22B ''imag'':102C,104C ''import'':92C,96C ''infer'':34B,69B ''infrastructur'':64B ''initi'':117C ''instanc'':118C,121C ''invok'':169C ''invokeendpoint'':174C ''job'':137C ''kms'':161C ''kms-encrypt'':160C ''learn'':9B ''lifecycl'':55B ''llm'':77B ''machin'':8B ''manag'':7B,56B,68B ''ml'':16B,44B,54B ''ml.m5.large'':123C ''mlop'':37B ''mode'':154C ''model'':17B,45B,62B,88C,97C,100C,101C,106C,108C,165C ''model.deploy'':116C ''need'':49B,61B,138C ''never'':178C ''openai/anthropic'':72B ''per'':175C ''pipelin'':38B ''platform'':10B ''postur'':147C ''pre'':75B ''pre-train'':74B ''predictor'':115C ''product'':146C ''provid'':20B ''proxi'':185C ''python'':83C ''real'':30B ''real-tim'':29B ''repo'':135C ''role'':111C,113C,127C ''run'':148C ''s3'':109C,131C ''sagemak'':2A,4A,58B,82C,93C,173C ''sagemaker.model'':95C ''sagemaker.session'':99C ''scale'':19B ''scope'':124C ''sdk'':84C ''sensit'':158C ''session'':98C ''sigv4/iam'':171C ''specif'':130C ''studio'':21B ''team'':41B ''time'':31B ''track'':66B ''train'':13B,28B,63B,76B,81B,87C,149C ''type'':122C ''unauthent'':184C ''uri'':103C,105C,110C ''use'':57B,71B ''volum'':163C ''vpc'':153C ''without'':79B');
INSERT INTO public.technology_catalog VALUES ('aws-quicksight', 'AWS QuickSight', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Quick_64@5x.png', '#8C4FFF', '["bi-analytics"]', '{"purpose": "Serverless BI over the AWS data stack (now marketed under the Amazon Quick Suite umbrella): dashboards and pixel-perfect reports on Athena/Redshift/RDS sources, per-session pricing, SPICE in-memory acceleration, and signed embedding for customer-facing analytics. Choose it when the data lives in AWS and embedded/per-session economics matter; the semantic-layer-as-code philosophy belongs to Looker-class tools.", "configMode": "external", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Icon file is Arch_Amazon-Quick (the Quick Suite rebrand); id keeps the universally-known quicksight handle. Joins gcp-looker on bi-analytics.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["SPICE datasets + refresh schedules", "Athena/Redshift sources", "Row-level security", "Signed embedding APIs", "Terraform"], "antiPatterns": ["Direct-querying the warehouse for every viewer of a hot dashboard SPICE exists to serve", "Embedding without row-level security and trusting the frontend to filter", "Dashboard-local calculated fields as the org''s de facto metric definitions", "Ignoring the per-session vs capacity pricing fork until the invoice decides"], "bestPractices": ["Import hot datasets into SPICE with scheduled refreshes - direct query against Athena per dashboard view is a latency and cost trap", "Use row-level security rules tied to the embedding identity for customer-facing analytics", "Model shared datasets once and build analyses on top - per-dashboard SQL drifts into metric chaos", "Embed with registered-user or anonymous session APIs deliberately - the pricing models differ materially"]}', '[{"kind": "config", "path": "infra/aws/quicksight.tf"}]', '{"embedding": {"type": "enum", "label": "Embedding", "default": "none", "options": ["none", "registered-user", "anonymous-session"]}, "queryMode": {"type": "enum", "label": "Query mode", "default": "spice-import", "options": ["spice-import", "direct-query", "mixed"]}, "rowLevelSecurity": {"type": "boolean", "label": "Row-level security", "default": true}}', '[{"id": "aws-athena", "reason": "Lake queries behind dashboards"}, {"id": "aws-redshift", "reason": "Warehouse source"}, {"id": "frontend-app", "reason": "Embedded dashboards"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''acceler'':37B ''amazon'':16B ''analyt'':45B ''api'':83C ''athena/redshift'':75C ''athena/redshift/rds'':27B ''aw'':1A,3A,9B,53B ''belong'':65B ''bi'':6B ''choos'':46B ''class'':69B ''code'':63B ''custom'':43B ''customer-fac'':42B ''dashboard'':20B ''data'':10B,50B ''dataset'':72C ''econom'':56B ''embed'':40B,82C ''embedded/per-session'':55B ''face'':44B ''in-memori'':34B ''layer'':61B ''level'':79C ''live'':51B ''looker'':68B ''looker-class'':67B ''market'':13B ''matter'':57B ''memori'':36B ''per'':30B ''per-sess'':29B ''perfect'':24B ''philosophi'':64B ''pixel'':23B ''pixel-perfect'':22B ''price'':32B ''quick'':17B ''quicksight'':2A,4A ''refresh'':73C ''report'':25B ''row'':78C ''row-level'':77C ''schedul'':74C ''secur'':80C ''semant'':60B ''semantic-layer-as-cod'':59B ''serverless'':5B ''session'':31B ''sign'':39B,81C ''sourc'':28B,76C ''spice'':33B,71C ''stack'':11B ''suit'':18B ''terraform'':84C ''tool'':70B ''umbrella'':19B');
INSERT INTO public.technology_catalog VALUES ('aws-location-service', 'AWS Location Service', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Location-Service_64@5x.png', '#FF4F8B', '["external-service"]', '{"purpose": "Maps, places, geocoding, routing, trackers and geofences as AWS-native APIs (provider data from Esri/HERE/GrabMaps): the location dependency for logistics and mobility features with IAM auth, no separate vendor contract, and data that stays in your AWS account. The Google Maps Platform parity row - choose by data quality in your geography, pricing, and whether tracker/geofence primitives (which Google lacks as managed pieces) matter.", "configMode": "code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-google-maps-platform parity row, external-service filing.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Maps + Places + Routes APIs", "Trackers + geofence collections", "Cognito-scoped access", "Provider selection (Esri/HERE/Grab)", "Terraform"], "antiPatterns": ["Hand-building geofence evaluation on raw coordinates beside a managed geofence primitive", "Scattering location calls through every service so nobody owns the spend", "Assuming provider parity across geographies - Esri/HERE/Grab coverage differs; validate in YOUR market", "Client-held credentials broader than the one map resource they render"], "bestPractices": ["Auth map/API access through Cognito or API keys scoped per surface - never a broad IAM principal in a client", "Use trackers + geofences for fleet/arrival features instead of hand-rolling position diffing over a database", "Cache geocodes against stable place IDs where terms permit - repeat geocoding is the classic runaway bill", "Route server-side calls through one owning service that holds quotas, retries and caching policy"]}', '[{"kind": "source", "path": "src/services/location-client.ts"}, {"kind": "config", "path": "infra/aws/location.tf"}]', '{"apis": {"type": "multiselect", "label": "APIs in use", "default": ["maps"], "options": ["maps", "places-geocoding", "routes", "trackers", "geofences"]}, "authMode": {"type": "enum", "label": "Client auth", "default": "cognito-scoped", "options": ["cognito-scoped", "api-keys-restricted"]}, "provider": {"type": "enum", "label": "Data provider", "default": "esri", "options": ["esri", "here", "grab"]}}', '[{"id": "frontend-app", "reason": "Map rendering in the client"}, {"id": "aws-cognito", "reason": "Scoped client credentials"}, {"id": "backend-service", "reason": "Server-side geocoding/routing owner"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':81C ''account'':45B ''api'':18B,74C ''auth'':33B ''aw'':1A,4A,16B,44B ''aws-nat'':15B ''choos'':52B ''cognito'':79C ''cognito-scop'':78C ''collect'':77C ''contract'':37B ''data'':20B,39B,54B ''depend'':25B ''esri/here/grab'':84C ''esri/here/grabmaps'':22B ''featur'':30B ''geocod'':9B ''geofenc'':13B,76C ''geographi'':58B ''googl'':47B,65B ''iam'':32B ''lack'':66B ''locat'':2A,5A,24B ''logist'':27B ''manag'':68B ''map'':7B,48B,71C ''matter'':70B ''mobil'':29B ''nativ'':17B ''pariti'':50B ''piec'':69B ''place'':8B,72C ''platform'':49B ''price'':59B ''primit'':63B ''provid'':19B,82C ''qualiti'':55B ''rout'':10B,73C ''row'':51B ''scope'':80C ''select'':83C ''separ'':35B ''servic'':3A,6A ''stay'':41B ''terraform'':85C ''tracker'':11B,75C ''tracker/geofence'':62B ''vendor'':36B ''whether'':61B');
INSERT INTO public.technology_catalog VALUES ('aws-timestream', 'AWS Timestream', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Timestream_64@5x.png', '#C925D1', '["time-series-db"]', '{"purpose": "Purpose-built time-series database in two shapes: Timestream for LiveAnalytics (serverless, SQL with time-series functions, memory-to-magnetic tiering) and Timestream for InfluxDB (managed InfluxDB for existing Flux/line-protocol workloads). For metrics, IoT telemetry and event-time analytics where general-purpose rows-and-indexes storage fights the access pattern.", "configMode": "code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Lands the starved time-series-db role its second technology.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["LiveAnalytics SQL / InfluxDB engines", "Dimensions + measures modeling", "Memory/magnetic retention tiers", "Scheduled queries/rollups", "Grafana integration"], "antiPatterns": ["Time-series bolted into DynamoDB/RDS with hand-rolled rollups a TSDB gives natively", "Unbounded high-cardinality dimensions (per-request IDs) exploding series count", "Querying magnetic-tier history at interactive latency expectations", "Using it as a general OLTP store because the ingestion was easy"], "bestPractices": ["Choose the engine deliberately: InfluxDB compatibility for existing tooling, LiveAnalytics for serverless SQL", "Model dimensions vs measures carefully - dimension cardinality drives cost and query shape", "Set memory-store retention to the hot query window and let magnetic tiering own history", "Batch writes and use common attributes - per-point writes at scale are a cost trap"]}', '[{"kind": "config", "path": "infra/aws/timestream.tf"}]', '{"engine": {"type": "enum", "label": "Engine", "default": "live-analytics", "options": ["live-analytics", "influxdb"]}, "memoryRetentionHours": {"type": "number", "label": "Memory-store retention (h)", "default": 24}, "magneticRetentionDays": {"type": "number", "label": "Magnetic retention (days)", "default": 365}}', '[{"id": "aws-iot-core", "reason": "Device telemetry ingestion path"}, {"id": "grafana", "reason": "Dashboarding over series"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':60B ''analyt'':48B ''aw'':1A,3A ''built'':7B ''databas'':11B ''dimens'':66C ''engin'':65C ''event'':46B ''event-tim'':45B ''exist'':37B ''fight'':58B ''flux/line-protocol'':38B ''function'':24B ''general'':51B ''general-purpos'':50B ''grafana'':74C ''index'':56B ''influxdb'':33B,35B,64C ''integr'':75C ''iot'':42B ''liveanalyt'':17B,62C ''magnet'':28B ''manag'':34B ''measur'':67C ''memori'':26B ''memory-to-magnet'':25B ''memory/magnetic'':69C ''metric'':41B ''model'':68C ''pattern'':61B ''purpos'':6B,52B ''purpose-built'':5B ''queries/rollups'':73C ''retent'':70C ''row'':54B ''rows-and-index'':53B ''schedul'':72C ''seri'':10B,23B ''serverless'':18B ''shape'':14B ''sql'':19B,63C ''storag'':57B ''telemetri'':43B ''tier'':29B,71C ''time'':9B,22B,47B ''time-seri'':8B,21B ''timestream'':2A,4A,15B,31B ''two'':13B ''workload'':39B');
INSERT INTO public.technology_catalog VALUES ('aws-keyspaces', 'AWS Keyspaces', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Keyspaces_64@5x.png', '#C925D1', '["database"]', '{"purpose": "Serverless Apache Cassandra-compatible database: CQL API, partition-key data modeling and Cassandra drivers, with capacity, patching and replication as AWS''s problem - and no cluster to run. For teams with Cassandra workloads or genuine wide-partition access patterns who want the operational model of DynamoDB while keeping CQL. It is API-compatible, not a Cassandra cluster: no ring to tune, but also driver/feature deltas to verify.", "configMode": "code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Complements the generic cassandra row (self-hosted ring) - this is the rent-shaped variant with a materially different operational contract.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["CQL API + Cassandra drivers", "Partition-key modeling", "On-demand / provisioned capacity", "Point-in-time recovery", "Terraform"], "antiPatterns": ["Lifting a Cassandra schema without checking feature deltas (materialized views, per-query tunables)", "Relational access patterns forced through CQL - that is RDS/Aurora''s job", "Hot partitions from low-cardinality partition keys - serverless does not repeal Cassandra physics", "Choosing it over DynamoDB with no Cassandra legacy and no CQL requirement - compare deliberately"], "bestPractices": ["Design tables from queries backward (partition key first) - Cassandra modeling discipline fully applies", "Verify driver behavior and unsupported-feature deltas against the compatibility docs before migrating", "Use on-demand capacity until access patterns stabilize, then evaluate provisioned for steady load", "Point-in-time recovery on for anything you would grieve"]}', '[{"kind": "config", "path": "infra/aws/keyspaces.tf"}]', '{"pitr": {"type": "boolean", "label": "Point-in-time recovery", "default": true}, "capacityMode": {"type": "enum", "label": "Capacity", "default": "on-demand", "options": ["on-demand", "provisioned"]}, "clientCompat": {"type": "boolean", "label": "Driver-delta verified", "default": false, "description": "Compatibility deltas checked against the migration workload"}}', '[{"id": "backend-service", "reason": "CQL client workloads"}, {"id": "cassandra", "reason": "The self-hosted sibling it replaces operationally"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''access'':45B ''also'':71B ''apach'':6B ''api'':12B,60B,77C ''api-compat'':59B ''aw'':1A,3A,27B ''capac'':22B,88C ''cassandra'':8B,19B,38B,64B,78C ''cassandra-compat'':7B ''cluster'':32B,65B ''compat'':9B,61B ''cql'':11B,56B,76C ''data'':16B ''databas'':10B ''delta'':73B ''demand'':86C ''driver'':20B,79C ''driver/feature'':72B ''dynamodb'':53B ''genuin'':41B ''keep'':55B ''key'':15B,82C ''keyspac'':2A,4A ''model'':17B,51B,83C ''on-demand'':84C ''oper'':50B ''partit'':14B,44B,81C ''partition-key'':13B,80C ''patch'':23B ''pattern'':46B ''point'':90C ''point-in-tim'':89C ''problem'':29B ''provis'':87C ''recoveri'':93C ''replic'':25B ''ring'':67B ''run'':34B ''serverless'':5B ''team'':36B ''terraform'':94C ''time'':92C ''tune'':69B ''verifi'':75B ''want'':48B ''wide'':43B ''wide-partit'':42B ''workload'':39B');
INSERT INTO public.technology_catalog VALUES ('aws-kms', 'AWS KMS', NULL, '#DD344C', '["key-management"]', '{"purpose": "Managed encryption key service for creating and controlling cryptographic keys", "configMode": "declarative", "provenance": {"notes": "Phase B6 additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Customer Managed Keys", "Envelope encryption", "S3 SSE-KMS", "RDS encryption", "CloudTrail auditing"], "antiPatterns": ["Encrypting large blobs directly instead of using envelope encryption", "Using one key for every workload and environment", "Scheduling key deletion without a recovery window plan", "Ignoring CloudTrail logs of key usage"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/kms/"}, "bestPractices": ["Use customer managed keys for auditable, revocable control over data", "Enable automatic annual key rotation on symmetric keys", "Scope key policies to specific services and principals", "Use grants for temporary, revocable access", "Use envelope encryption for payloads larger than 4 KB"], "sdkInitPattern": "import { KMSClient, GenerateDataKeyCommand } from \"@aws-sdk/client-kms\";\nconst kms = new KMSClient({ region: \"us-east-1\" });\nconst { Plaintext, CiphertextBlob } = await kms.send(new GenerateDataKeyCommand({ KeyId: \"alias/app-key\", KeySpec: \"AES_256\" }));", "securityGuidance": "Key policies are the root of trust — never grant kms:* or open a key policy to the account root casually; separate ENCRYPT and DECRYPT grants by principal. Enable automatic rotation for customer-managed keys, use grants (not policy edits) for temporary service access, and alarm on Decrypt from unexpected principals. Deleting a key is deleting the data — schedule-deletion windows exist for a reason."}', '[{"kind": "config", "path": "infra/aws/kms.tf"}]', '{"keySpec": {"type": "enum", "label": "Key spec", "default": "symmetric-default", "options": ["symmetric-default", "rsa-2048", "ecc-nist-p256"], "description": "Symmetric covers envelope encryption; asymmetric for sign/verify or external encrypt"}, "keyStore": {"type": "enum", "label": "Key store", "default": "kms-default", "options": ["kms-default", "custom-key-store-cloudhsm", "external-key-store"], "description": "Custom key stores back KMS keys with your CloudHSM cluster; external key stores (XKS) keep material outside AWS - backing-store choices of this node, not separate nodes"}, "rotation": {"type": "boolean", "label": "Automatic rotation", "default": true, "description": "Yearly rotation for symmetric CMKs"}, "aliasPrefix": {"type": "string", "label": "Alias prefix", "default": "alias/app", "description": "Reference keys by alias, never key id, in code/config"}, "multiRegion": {"type": "boolean", "label": "Multi-region key", "default": false, "description": "Replica keys for cross-region decrypt/DR"}}', '[{"id": "aws-s3", "reason": "Server-side encryption keys"}, {"id": "aws-rds", "reason": "Database encryption at rest"}, {"id": "aws-secrets-manager", "reason": "Secret encryption backing"}]', false, NULL, NULL, '2026-08-31 20:06:49.738528+00', '2026-08-31 20:06:52.578953+00', NULL, NULL, '''/client-kms'':35C ''1'':44C ''256'':56C ''access'':100C ''account'':74C ''ae'':55C ''alarm'':102C ''alias/app-key'':53C ''audit'':27C ''automat'':85C ''aw'':1A,3A,33C ''await'':48C ''aws-sdk'':32C ''casual'':76C ''ciphertextblob'':47C ''cloudtrail'':26C ''const'':36C,45C ''control'':12B ''creat'':10B ''cryptograph'':13B ''custom'':15C,89C ''customer-manag'':88C ''data'':114C ''decrypt'':80C,104C ''delet'':108C,112C,117C ''east'':43C ''edit'':96C ''enabl'':84C ''encrypt'':6B,19C,25C,78C ''envelop'':18C ''exist'':119C ''generatedatakeycommand'':30C,51C ''grant'':65C,81C,93C ''import'':28C ''key'':7B,14B,17C,57C,70C,91C,110C ''keyid'':52C ''keyspec'':54C ''kms'':2A,4A,23C,37C,66C ''kms.send'':49C ''kmsclient'':29C,39C ''manag'':5B,16C,90C ''never'':64C ''new'':38C,50C ''open'':68C ''plaintext'':46C ''polici'':58C,71C,95C ''princip'':83C,107C ''rds'':24C ''reason'':122C ''region'':40C ''root'':61C,75C ''rotat'':86C ''s3'':20C ''schedul'':116C ''schedule-delet'':115C ''sdk'':34C ''separ'':77C ''servic'':8B,99C ''sse'':22C ''sse-km'':21C ''temporari'':98C ''trust'':63C ''unexpect'':106C ''us'':42C ''us-east'':41C ''use'':92C ''window'':118C');
INSERT INTO public.technology_catalog VALUES ('aws-memorydb', 'AWS MemoryDB', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-MemoryDB_64@5x.png', '#C925D1', '["database", "cache"]', '{"purpose": "Durable Redis-compatible (Valkey-based) PRIMARY database: in-memory speed with a multi-AZ transactional log underneath, so writes survive node loss - unlike a cache. Use it when the Redis data model (structures, streams, sorted sets) IS the system of record: session truth, leaderboards, real-time state machines. ElastiCache remains the right row when Redis is a cache in front of another database.", "configMode": "code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Filed database+cache: a durable primary with cache-class latency; the cache-only sibling is aws-elasticache.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Redis/Valkey API", "Multi-AZ transaction log", "Shards + replicas", "ACL users", "Terraform"], "antiPatterns": ["Paying MemoryDB durability prices for cache workloads ElastiCache serves", "Treating it as Redis-with-persistence-toggles - the durability model (multi-AZ log) is the product", "One default ACL user shared by every service", "Unbounded streams/keys with no eviction or trimming policy - memory IS the storage"], "bestPractices": ["Decide cache vs primary FIRST: if losing the data means reload-from-source, that is ElastiCache; if it means data loss, MemoryDB", "Model with Redis structures deliberately (streams, sorted sets, hashes) - it is a data model, not a key-value dump", "Use ACL users per service with least-privilege command sets", "Size shards for the working set and rehearse failover - durability is not a substitute for capacity planning"]}', '[{"kind": "config", "path": "infra/aws/memorydb.tf"}]', '{"role": {"type": "enum", "label": "Data role", "default": "primary-system-of-record", "options": ["primary-system-of-record", "hybrid-cache-plus-state"]}, "shards": {"type": "number", "label": "Shards", "default": 1}, "aclPerService": {"type": "boolean", "label": "Per-service ACL users", "default": true}}', '[{"id": "backend-service", "reason": "Real-time state workloads"}, {"id": "aws-elasticache", "reason": "The cache-only sibling for non-durable workloads"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''acl'':82C ''anoth'':71B ''api'':74C ''aw'':1A,3A ''az'':22B,77C ''base'':11B ''cach'':33B,67B ''compat'':8B ''data'':39B ''databas'':13B,72B ''durabl'':5B ''elasticach'':58B ''front'':69B ''in-memori'':14B ''leaderboard'':52B ''log'':24B,79C ''loss'':30B ''machin'':57B ''memori'':16B ''memorydb'':2A,4A ''model'':40B ''multi'':21B,76C ''multi-az'':20B,75C ''node'':29B ''primari'':12B ''real'':54B ''real-tim'':53B ''record'':49B ''redi'':7B,38B,64B ''redis-compat'':6B ''redis/valkey'':73C ''remain'':59B ''replica'':81C ''right'':61B ''row'':62B ''session'':50B ''set'':44B ''shard'':80C ''sort'':43B ''speed'':17B ''state'':56B ''stream'':42B ''structur'':41B ''surviv'':28B ''system'':47B ''terraform'':84C ''time'':55B ''transact'':23B,78C ''truth'':51B ''underneath'':25B ''unlik'':31B ''use'':34B ''user'':83C ''valkey'':10B ''valkey-bas'':9B ''write'':27B');
INSERT INTO public.technology_catalog VALUES ('aws-fsx', 'AWS FSx', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-FSx_64@5x.png', '#7AA116', '["file-share"]', '{"purpose": "Managed file systems in four flavors chosen per workload: Windows File Server (SMB + Active Directory), NetApp ONTAP (multiprotocol NFS/SMB/iSCSI with SnapMirror), Lustre (HPC/ML scratch at throughput), and OpenZFS (NFS with snapshots/clones). One catalog node - the FLAVOR is configuration, and it is the decision that matters: each variant has different protocols, HA shapes and price physics. EFS remains the simple-elastic-NFS row.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). ONE row for the family - the four variant icon files are skipped as configuration per the census; parity partner of aws-efs on file-share.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Variant selection (Windows/ONTAP/Lustre/OpenZFS)", "Multi-AZ deployment", "SnapMirror / S3-linked repositories", "Backups + snapshots", "Terraform"], "antiPatterns": ["Defaulting to FSx when EFS''s simple elastic NFS answers the need", "Lustre as durable primary storage - it is performance scratch with S3 as the system of record", "Single-AZ file systems under production SLAs", "Ignoring AD dependency planning for the Windows variant until join errors block launch"], "bestPractices": ["Choose the variant by protocol + ecosystem (SMB/AD -> Windows FS; multiprotocol/replication -> ONTAP; HPC scratch -> Lustre; NFS+snapshots -> OpenZFS), not by familiarity", "Deploy Multi-AZ for anything production-facing; single-AZ is for scratch and dev by design", "Use the variant''s native data movers (SnapMirror, Lustre-S3 linkage) instead of hand-rolled rsync", "Benchmark with the real workload - throughput capacity is a provisioning choice with a bill attached"]}', '[{"kind": "config", "path": "infra/aws/fsx.tf"}]', '{"variant": {"type": "enum", "label": "FSx variant", "default": "netapp-ontap", "options": ["windows-file-server", "netapp-ontap", "lustre", "openzfs"], "description": "The decision that sets protocols, HA and price physics"}, "deployment": {"type": "enum", "label": "Deployment", "default": "multi-az", "options": ["multi-az", "single-az"]}, "throughputMbps": {"type": "number", "label": "Throughput capacity (MB/s)", "default": 128}}', '[{"id": "aws-ec2", "reason": "Instance fleets mounting the shares"}, {"id": "aws-efs", "reason": "The simple-elastic-NFS alternative"}, {"id": "aws-s3", "reason": "Lustre-linked repository / archive tier"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''activ'':18B ''aw'':1A,3A ''az'':73C ''backup'':80C ''catalog'':37B ''chosen'':11B ''configur'':42B ''decis'':47B ''deploy'':74C ''differ'':53B ''directori'':19B ''ef'':60B ''elast'':65B ''file'':6B,15B ''flavor'':10B,40B ''four'':9B ''fsx'':2A,4A ''ha'':55B ''hpc/ml'':27B ''link'':78C ''lustr'':26B ''manag'':5B ''matter'':49B ''multi'':72C ''multi-az'':71C ''multiprotocol'':22B ''netapp'':20B ''nfs'':33B,66B ''nfs/smb/iscsi'':23B ''node'':38B ''one'':36B ''ontap'':21B ''openzf'':32B ''per'':12B ''physic'':59B ''price'':58B ''protocol'':54B ''remain'':61B ''repositori'':79C ''row'':67B ''s3'':77C ''s3-linked'':76C ''scratch'':28B ''select'':69C ''server'':16B ''shape'':56B ''simpl'':64B ''simple-elastic-nf'':63B ''smb'':17B ''snapmirror'':25B,75C ''snapshot'':81C ''snapshots/clones'':35B ''system'':7B ''terraform'':82C ''throughput'':30B ''variant'':51B,68C ''window'':14B ''windows/ontap/lustre/openzfs'':70C ''workload'':13B');
INSERT INTO public.technology_catalog VALUES ('aws-transfer-family', 'AWS Transfer Family', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-Transfer-Family_64@5x.png', '#7AA116', '["file-share"]', '{"purpose": "Managed SFTP/FTPS/AS2 endpoints in front of S3 or EFS: partners keep their file-drop workflows and credentials while the data lands natively in your lake - no SFTP servers to patch, no EC2 file gateways to babysit. The standing answer for B2B file exchange with counterparties whose integration surface is and will remain a file drop.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Distinct from the migration/transfer-tooling skips: a STANDING architectural boundary for partner exchange, not a one-time mover.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["SFTP/FTPS/AS2 protocols", "S3/EFS backing storage", "Per-partner IAM session scoping", "S3 event-driven processing", "Terraform"], "antiPatterns": ["An EC2 SFTP server with cron sync surviving beside a managed endpoint", "One shared partner credential everyone rotates never", "Processing files by polling the bucket instead of S3 event notifications", "Treating the endpoint as internal file sharing - workloads mount EFS/FSx; this is a PARTNER boundary"], "bestPractices": ["Land transfers directly in the lake''s raw zone with per-partner prefixes and event-driven processing on arrival", "Use service-managed keys or federate against the existing identity provider per partner - one identity per counterparty", "Scope each partner''s session to their prefix with the IAM session policy - partner A must not list partner B", "Use AS2 where the counterparty''s compliance regime demands signed/MDN exchange, not as a default"]}', '[{"kind": "config", "path": "infra/aws/transfer-family.tf"}]', '{"identity": {"type": "enum", "label": "Partner identity", "default": "service-managed", "options": ["service-managed", "custom-idp-lambda", "directory"]}, "protocols": {"type": "multiselect", "label": "Protocols", "default": ["sftp"], "options": ["sftp", "ftps", "as2"]}, "backingStore": {"type": "enum", "label": "Backing store", "default": "s3", "options": ["s3", "efs"]}}', '[{"id": "aws-s3", "reason": "Transfers land in the lake raw zone"}, {"id": "aws-lambda", "reason": "On-arrival processing and custom IdP hooks"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''answer'':46B ''aw'':1A,4A ''b2b'':48B ''babysit'':43B ''back'':66C ''counterparti'':52B ''credenti'':24B ''data'':27B ''driven'':77C ''drop'':21B,62B ''ec2'':39B ''ef'':15B ''endpoint'':9B ''event'':76C ''event-driven'':75C ''exchang'':50B ''famili'':3A,6A ''file'':20B,40B,49B,61B ''file-drop'':19B ''front'':11B ''gateway'':41B ''iam'':71C ''integr'':54B ''keep'':17B ''lake'':32B ''land'':28B ''manag'':7B ''nativ'':29B ''partner'':16B,70C ''patch'':37B ''per'':69C ''per-partn'':68C ''process'':78C ''protocol'':64C ''remain'':59B ''s3'':13B,74C ''s3/efs'':65C ''scope'':73C ''server'':35B ''session'':72C ''sftp'':34B ''sftp/ftps/as2'':8B,63C ''stand'':45B ''storag'':67C ''surfac'':55B ''terraform'':79C ''transfer'':2A,5A ''whose'':53B ''workflow'':22B');
INSERT INTO public.technology_catalog VALUES ('aws-appconfig', 'AWS AppConfig', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-AppConfig_64@5x.png', '#E7157B', '["config-store"]', '{"purpose": "Feature flags and dynamic configuration deployed like code: configurations are versioned, VALIDATED (JSON Schema or Lambda) before release, rolled out gradually with CloudWatch-alarm rollback, and fetched by applications through a local agent/extension. The difference from a parameter in SSM is the DEPLOYMENT SEMANTICS - config changes become safe, observable releases instead of instant global edits.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). Lands the starved config-store role a second technology; the GCP runtime-config skip does not transfer - AppConfig is current and actively pushed.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Configuration profiles + environments", "JSON Schema / Lambda validators", "Gradual deployment strategies + alarm rollback", "AppConfig agent / Lambda extension", "Terraform"], "antiPatterns": ["Instant-global config edits to every instance at once - the failure mode AppConfig exists to remove", "Secrets in AppConfig - that is Secrets Manager''s job; AppConfig is behavior, not credentials", "Per-request GetConfiguration calls with no local cache", "Permanent \"temporary\" flags accumulating into an untestable combinatorial state space"], "bestPractices": ["Attach a validator to every configuration profile - malformed config stopped at deploy time is the product", "Roll out gradually with a CloudWatch alarm as the rollback trigger, exactly like a code canary", "Fetch through the AppConfig agent/Lambda extension with local caching - do not hammer the API per request", "Keep flag lifecycles honest: retire launched flags on a schedule or inherit a flag graveyard"]}', '[{"kind": "config", "path": "infra/aws/appconfig.tf"}, {"kind": "config", "path": "config/flags.json"}]', '{"contentType": {"type": "enum", "label": "Content", "default": "feature-flags", "options": ["feature-flags", "freeform-config", "both"]}, "alarmRollback": {"type": "boolean", "label": "CloudWatch alarm rollback", "default": true}, "deploymentStrategy": {"type": "enum", "label": "Deployment strategy", "default": "linear-gradual", "options": ["linear-gradual", "canary-percent", "all-at-once-dev-only"]}}', '[{"id": "aws-lambda", "reason": "Fetches via the AppConfig extension"}, {"id": "aws-ecs", "reason": "Agent sidecar consumption"}, {"id": "aws-cloudwatch", "reason": "Alarm-driven rollback signal"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''agent'':74C ''agent/extension'':38B ''alarm'':29B,71C ''appconfig'':2A,4A,73C ''applic'':34B ''aw'':1A,3A ''becom'':52B ''chang'':51B ''cloudwatch'':28B ''cloudwatch-alarm'':27B ''code'':12B ''config'':50B ''configur'':9B,13B,61C ''deploy'':10B,48B,69C ''differ'':40B ''dynam'':8B ''edit'':60B ''environ'':63C ''extens'':76C ''featur'':5B ''fetch'':32B ''flag'':6B ''global'':59B ''gradual'':25B,68C ''instant'':58B ''instead'':56B ''json'':17B,64C ''lambda'':20B,66C,75C ''like'':11B ''local'':37B ''observ'':54B ''paramet'':43B ''profil'':62C ''releas'':22B,55B ''roll'':23B ''rollback'':30B,72C ''safe'':53B ''schema'':18B,65C ''semant'':49B ''ssm'':45B ''strategi'':70C ''terraform'':77C ''valid'':16B,67C ''version'':15B');
INSERT INTO public.technology_catalog VALUES ('aws-codebuild', 'AWS CodeBuild', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-CodeBuild_64@5x.png', '#C925D1', '["ci-cd-pipeline"]', '{"purpose": "Managed build execution: buildspec-defined phases run in ephemeral containers (including your own build images and GPU/ARM fleets), scaling to zero between builds. In the AWS-native chain it is the BUILD stage CodePipeline orchestrates; it also serves as a self-hosted-runner backend for GitHub Actions. Choose it when builds should live inside the AWS IAM/VPC perimeter - artifact pushes to ECR, integration tests against VPC resources - rather than on an external CI vendor.", "configMode": "definition-as-code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-cloud-build parity row; completes the AWS-native chain beside the existing aws-codepipeline.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["buildspec.yml phases", "Custom build images", "S3/local caching", "VPC-attached builds", "ECR artifact pushes"], "antiPatterns": ["A god-role build project that can touch everything, making CI the softest path to production", "Uncached builds re-downloading the node_modules universe every run", "Baking secrets into build images instead of Secrets Manager references at run time", "Using CodeBuild as a cron runner for jobs that belong on Lambda/ECS scheduled tasks"], "bestPractices": ["Keep buildspec.yml in the repo and treat build images as versioned infrastructure", "Give each project the narrowest IAM role - the build is production-adjacent code execution", "Cache dependencies (S3/local cache modes) - cold dependency restores dominate naive build times", "Run integration-test builds inside the VPC against real private resources instead of mocking what exists"]}', '[{"kind": "config", "path": "buildspec.yml"}, {"kind": "config", "path": "infra/aws/codebuild.tf"}]', '{"caching": {"type": "enum", "label": "Cache mode", "default": "s3", "options": ["s3", "local", "none"]}, "computeType": {"type": "enum", "label": "Compute", "default": "standard-container", "options": ["standard-container", "arm", "gpu", "lambda-compute"]}, "vpcAttached": {"type": "boolean", "label": "VPC-attached builds", "default": false}}', '[{"id": "aws-codepipeline", "reason": "Orchestrates it as the build stage"}, {"id": "aws-ecr", "reason": "Image artifact destination"}, {"id": "aws-secrets-manager", "reason": "Run-time secret references"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''action'':54B ''also'':43B ''artifact'':66B,94C ''attach'':91C ''aw'':1A,3A,32B,63B ''aws-nat'':31B ''backend'':51B ''build'':6B,19B,28B,38B,58B,85C,92C ''buildspec'':9B ''buildspec-defin'':8B ''buildspec.yml'':82C ''cach'':88C ''chain'':34B ''choos'':55B ''ci'':80B ''codebuild'':2A,4A ''codepipelin'':40B ''contain'':15B ''custom'':84C ''defin'':10B ''ecr'':69B,93C ''ephemer'':14B ''execut'':7B ''extern'':79B ''fleet'':23B ''github'':53B ''gpu/arm'':22B ''host'':49B ''iam/vpc'':64B ''imag'':20B,86C ''includ'':16B ''insid'':61B ''integr'':70B ''live'':60B ''manag'':5B ''nativ'':33B ''orchestr'':41B ''perimet'':65B ''phase'':11B,83C ''push'':67B,95C ''rather'':75B ''resourc'':74B ''run'':12B ''runner'':50B ''s3/local'':87C ''scale'':24B ''self'':48B ''self-hosted-runn'':47B ''serv'':44B ''stage'':39B ''test'':71B ''vendor'':81B ''vpc'':73B,90C ''vpc-attach'':89C ''zero'':26B');
INSERT INTO public.technology_catalog VALUES ('aws-codedeploy', 'AWS CodeDeploy', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-CodeDeploy_64@5x.png', '#C925D1', '["ci-cd-pipeline"]', '{"purpose": "Managed deployment orchestration with rollback semantics per compute platform: blue/green and canary traffic shifting for ECS and Lambda (alias-weighted), and in-place/blue-green fleets for EC2 via appspec hooks. It owns the PROMOTION step - shift, verify, roll back on alarm - where CodeBuild owns build and CodePipeline the pipeline. The gcp-cloud-deploy parity row.", "configMode": "definition-as-code", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The gcp-cloud-deploy parity row on ci-cd-pipeline.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Deployment groups per platform", "Blue/green + canary strategies", "appspec lifecycle hooks", "Alarm-triggered rollback", "Terraform"], "antiPatterns": ["Deploying straight from the build stage to prod with no traffic-shifted promotion step", "Hooks that pass on exit-0 theater while the service returns 500s", "Blue/green everywhere including dev, doubling infra where in-place would do", "Manual console rollbacks as the documented recovery procedure"], "bestPractices": ["Wire CloudWatch alarms as automatic rollback triggers - a canary nobody measures is a slow full rollout", "Use Lambda alias traffic shifting (linear/canary) for function releases instead of all-at-once publishes", "Keep appspec + lifecycle hooks in the repo; validation hooks should run REAL smoke checks, not sleep timers", "Prefer blue/green for ECS services so rollback is a target-group swap, not a redeploy"]}', '[{"kind": "config", "path": "appspec.yml"}, {"kind": "config", "path": "infra/aws/codedeploy.tf"}]', '{"platform": {"type": "enum", "label": "Compute platform", "default": "ecs-blue-green", "options": ["ecs-blue-green", "lambda-traffic-shift", "ec2-in-place", "ec2-blue-green"]}, "strategy": {"type": "enum", "label": "Shift strategy", "default": "canary", "options": ["canary", "linear", "all-at-once-dev-only"]}, "alarmRollback": {"type": "boolean", "label": "Alarm-triggered rollback", "default": true}}', '[{"id": "aws-codepipeline", "reason": "The pipeline that invokes the promotion"}, {"id": "aws-ecs", "reason": "Blue/green service deployments"}, {"id": "aws-lambda", "reason": "Alias-weighted traffic shifting"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''/blue-green'':30B ''alarm'':47B,74C ''alarm-trigg'':73C ''alia'':24B ''alias-weight'':23B ''appspec'':35B,70C ''aw'':1A,3A ''back'':45B ''blue/green'':14B,67C ''build'':51B ''canari'':16B,68C ''cloud'':59B ''codebuild'':49B ''codedeploy'':2A,4A ''codepipelin'':53B ''comput'':12B ''deploy'':6B,60B,63C ''ec'':20B ''ec2'':33B ''fleet'':31B ''gcp'':58B ''gcp-cloud-deploy'':57B ''group'':64C ''hook'':36B,72C ''in-plac'':27B ''lambda'':22B ''lifecycl'':71C ''manag'':5B ''orchestr'':7B ''own'':38B,50B ''pariti'':61B ''per'':11B,65C ''pipelin'':55B ''place'':29B ''platform'':13B,66C ''promot'':40B ''roll'':44B ''rollback'':9B,76C ''row'':62B ''semant'':10B ''shift'':18B,42B ''step'':41B ''strategi'':69C ''terraform'':77C ''traffic'':17B ''trigger'':75C ''verifi'':43B ''via'':34B ''weight'':25B');
INSERT INTO public.technology_catalog VALUES ('aws-iot-core', 'AWS IoT Core', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_AWS-IoT-Core_64@5x.png', '#7AA116', '["message-broker"]', '{"purpose": "Managed MQTT broker plus device identity for fleets: X.509 per-device authentication, fine-grained IoT policies on topic patterns, device shadows for desired/reported state, and a rules engine routing telemetry into Kinesis/Timestream/S3/Lambda without custom bridge code. The front door of an AWS IoT architecture - and unlike its GCP counterpart (retired 2023), it is alive and central.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The GCP IoT-Core skip does not transfer - Google retired theirs; AWS''s is alive. Greengrass and the IoT verticals stay skipped (edge/on-prem role gap + vertical rule).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["MQTT + X.509 per-device identity", "IoT policies on topic patterns", "Device shadows", "Rules engine routing", "Fleet provisioning"], "antiPatterns": ["A shared MQTT credential across the fleet - one leak, whole-fleet compromise, no per-device revocation", "Fat business logic inside IoT rules SQL that belongs in Lambda/Flink", "Polling devices over HTTP where shadows and topics model the state machine", "Unbounded raw telemetry into hot storage with no tiering plan - fleets multiply data faster than dashboards need it"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/iot/"}, "bestPractices": ["One X.509 identity per device, provisioned via fleet provisioning - shared device credentials are unrevocable by design", "Scope IoT policies to per-device topic patterns (device/${iot:Connection.Thing.ThingName}/*), never wildcard-publish fleets", "Use device shadows for state reconciliation instead of hand-rolled retained-message conventions", "Do routing in the rules engine (to Kinesis/Timestream/S3) and keep business logic downstream, versioned and testable"], "securityGuidance": "Device identity is the whole game: per-device certs with rotation and revocation paths, least-privilege topic policies bound to the thing name, and TLS mutual auth everywhere. Treat the rules-engine IAM roles as production credentials - a permissive rule action is an exfiltration path from every device topic it matches."}', '[{"kind": "config", "path": "infra/aws/iot-core.tf"}]', '{"shadows": {"type": "boolean", "label": "Device shadows", "default": true}, "deviceAuth": {"type": "enum", "label": "Device auth", "default": "x509-per-device", "options": ["x509-per-device", "custom-authorizer"]}, "rulesTargets": {"type": "multiselect", "label": "Rules targets", "default": ["kinesis"], "options": ["kinesis", "timestream", "s3", "lambda"]}}', '[{"id": "aws-timestream", "reason": "Telemetry storage via rules"}, {"id": "aws-kinesis", "reason": "Stream fan-out of device events"}, {"id": "aws-lambda", "reason": "Rule-triggered processing"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''2023'':59B ''action'':126C ''aliv'':62B ''architectur'':52B ''auth'':111C ''authent'':19B ''aw'':1A,4A,50B ''bound'':103C ''bridg'':43B ''broker'':9B ''central'':64B ''cert'':92C ''code'':44B ''core'':3A,6A ''counterpart'':57B ''credenti'':122C ''custom'':42B ''desired/reported'':31B ''devic'':11B,18B,28B,69C,76C,83C,91C,133C ''door'':47B ''engin'':36B,79C,117C ''everi'':132C ''everywher'':112C ''exfiltr'':129C ''fine'':21B ''fine-grain'':20B ''fleet'':14B,81C ''front'':46B ''game'':88C ''gcp'':56B ''grain'':22B ''iam'':118C ''ident'':12B,70C,84C ''iot'':2A,5A,23B,51B,71C ''kinesis/timestream/s3/lambda'':40B ''least'':99C ''least-privileg'':98C ''manag'':7B ''match'':136C ''mqtt'':8B,65C ''mutual'':110C ''name'':107C ''path'':97C,130C ''pattern'':27B,75C ''per'':17B,68C,90C ''per-devic'':16B,67C,89C ''permiss'':124C ''plus'':10B ''polici'':24B,72C,102C ''privileg'':100C ''prod