INSERT INTO public.technology_catalog VALUES ('aws-gamelift', 'AWS GameLift', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-GameLift-Servers_64@5x.png', '#FF9900', '["game-server"]', '{"purpose": "Managed dedicated game-server hosting: upload server builds, define fleets (EC2 or containers) across regions, and let GameLift place sessions, autoscale on player demand, and run FlexMatch matchmaking - with spot-instance economics for tolerant fleets. The multiplayer session-hosting node; the game client and its backend services stay separate nodes.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The GCP game-servers skip does not transfer - Google discontinued theirs; GameLift is alive (icon: GameLift-Servers; Streams is a separate skipped product). Joins the game-server role.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Server builds + fleets (EC2/containers)", "Session placement queues", "FlexMatch matchmaking", "Spot fleet economics", "Server SDK integration"], "antiPatterns": ["Hand-rolled EC2 session servers with custom placement logic GameLift already owns", "One giant home-region fleet serving global players through 200ms", "Ignoring spot for stateless-session games and paying on-demand forever", "Coupling matchmaking logic into game-server code instead of FlexMatch rule sets"], "bestPractices": ["Integrate the server SDK health/termination callbacks properly - placement quality is only as good as the signals", "Use spot fleets with FlexMatch backfill for cost - session-tolerant games leave large EC2 savings unclaimed", "Deploy fleets multi-region and let latency-based placement do its job", "Scale on player-session metrics, not CPU - empty warm servers and full stressed ones both lie via CPU"]}', '[{"kind": "config", "path": "infra/aws/gamelift.tf"}]', '{"regions": {"type": "string", "label": "Fleet regions", "default": "us-east-1,eu-west-1"}, "fleetType": {"type": "enum", "label": "Fleet type", "default": "spot", "options": ["spot", "on-demand", "container"]}, "flexMatch": {"type": "boolean", "label": "FlexMatch matchmaking", "default": true}}', '[{"id": "game-client", "reason": "Connects into placed sessions"}, {"id": "backend-service", "reason": "Meta-game services beside session hosting"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''across'':19B ''autoscal'':26B ''aw'':1A,3A ''backend'':53B ''build'':13B,59C ''client'':50B ''contain'':18B ''dedic'':6B ''defin'':14B ''demand'':29B ''ec2'':16B ''ec2/containers'':61C ''econom'':38B,69C ''fleet'':15B,41B,60C,68C ''flexmatch'':32B,65C ''game'':8B,49B ''game-serv'':7B ''gamelift'':2A,4A,23B ''host'':10B,46B ''instanc'':37B ''integr'':72C ''let'':22B ''manag'':5B ''matchmak'':33B,66C ''multiplay'':43B ''node'':47B,57B ''place'':24B ''placement'':63C ''player'':28B ''queue'':64C ''region'':20B ''run'':31B ''sdk'':71C ''separ'':56B ''server'':9B,12B,58C,70C ''servic'':54B ''session'':25B,45B,62C ''session-host'':44B ''spot'':36B,67C ''spot-inst'':35B ''stay'':55B ''toler'':40B ''upload'':11B');
INSERT INTO public.technology_catalog VALUES ('aws-lightsail', 'AWS Lightsail', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/AWS/Arch_Amazon-Lightsail_64@5x.png', '#FF9900', '["virtual-machine"]', '{"purpose": "Fixed-price VPS bundles (instance + storage + transfer), managed databases, and simple container hosting with a deliberately small console: the right-sized answer when a project needs A SERVER, not an estate - side projects, agencies, small-business workloads. Its virtue is the ceiling: when you outgrow the bundle, the exit is EC2/ECS, and pretending otherwise costs more than migrating.", "configMode": "declarative", "provenance": {"notes": "Authored for the AWS expansion (CAT-3). The small-shop deployment target - relevant to the personal/solopreneur template slate (TPL-2).", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Fixed-price instance bundles", "Managed DB + container services", "Snapshots", "Built-in LB + DNS", "Terraform"], "antiPatterns": ["Building a multi-service estate on Lightsail and re-inventing what EC2/ECS/IAM already are", "Burst-credit CPU surprise: sustained-load workloads on burstable bundles", "Skipping snapshots because the workload felt small until the disk failed", "Bridging into the full VPC world through workarounds instead of graduating"], "bestPractices": ["Take the bundle honestly: predictable price and simplicity in exchange for narrow instrumentation and IAM surface", "Snapshot on a schedule - it is the whole disaster-recovery story at this tier", "Use Lightsail DNS/static IPs + the built-in load balancer before reaching for Route 53/ELB complexity", "Know the exit ramp: the day you need VPC peering, fine IAM, or autoscaling groups, migrate rather than fight the tier"]}', '[{"kind": "config", "path": "infra/aws/lightsail.tf"}]', '{"bundle": {"type": "enum", "label": "Bundle class", "default": "small-burstable", "options": ["small-burstable", "medium", "large"]}, "workload": {"type": "enum", "label": "Workload", "default": "instance-vps", "options": ["instance-vps", "containers", "managed-database"]}, "snapshots": {"type": "boolean", "label": "Scheduled snapshots", "default": true}}', '[{"id": "backend-service", "reason": "Small-footprint app hosting"}, {"id": "aws-ec2", "reason": "The graduation path when the bundle ceiling hits"}]', false, NULL, NULL, '2026-08-31 20:06:52.555672+00', '2026-08-31 20:06:52.555672+00', NULL, NULL, '''agenc'':40B ''answer'':28B ''aw'':1A,3A ''built'':77C ''built-in'':76C ''bundl'':9B,54B,70C ''busi'':43B ''ceil'':49B ''consol'':23B ''contain'':17B,73C ''cost'':62B ''databas'':14B ''db'':72C ''deliber'':21B ''dns'':80C ''ec2/ecs'':58B ''estat'':37B ''exit'':56B ''fix'':6B,67C ''fixed-pric'':5B,66C ''host'':18B ''instanc'':10B,69C ''lb'':79C ''lightsail'':2A,4A ''manag'':13B,71C ''migrat'':65B ''need'':32B ''otherwis'':61B ''outgrow'':52B ''pretend'':60B ''price'':7B,68C ''project'':31B,39B ''right'':26B ''right-siz'':25B ''server'':34B ''servic'':74C ''side'':38B ''simpl'':16B ''size'':27B ''small'':22B,42B ''small-busi'':41B ''snapshot'':75C ''storag'':11B ''terraform'':81C ''transfer'':12B ''virtu'':46B ''vps'':8B ''workload'':44B');
INSERT INTO public.technology_catalog VALUES ('aws-bedrock', 'AWS Bedrock', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/aws-bedrock.png', '#FF4F8B', '["inference-service"]', '{"purpose": "Amazon Bedrock is AWS''s fully managed service for building generative AI applications with foundation models from Amazon and third-party providers through managed APIs and platform tooling. Use it for chat, text generation, embeddings, multimodal inference, agentic workflows, and customization features when you want managed model access integrated with AWS security and governance. Choose Amazon Bedrock over self-managed model serving when you want rapid access to multiple model providers without operating inference infrastructure, and over SageMaker AI when the primary need is managed foundation model consumption rather than general ML training and deployment. Do not use it as a workflow engine, vector database, or transactional application backend.", "configMode": "declarative", "provenance": {"notes": "Phase B7c additions authored from model knowledge. Prior stamp: model-knowledge 2026-07-27. Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["Amazon Bedrock", "Amazon Bedrock Agents", "Amazon Bedrock Knowledge Bases", "Amazon S3", "AWS Lambda", "Amazon OpenSearch Service", "Amazon CloudWatch"], "antiPatterns": ["Treating Amazon Bedrock as a replacement for application business logic and workflow coordination", "Sending sensitive data to models without governance, minimization, and access controls", "Assuming one model or prompt configuration is optimal for every workload", "Skipping evaluation and safety checks for grounded or customer-facing AI systems", "Using Bedrock as a persistent data store instead of pairing it with databases or search systems", "Hard-coding secrets, model identifiers, and prompt logic directly into unmanaged scripts"], "apiReference": {"docsUrl": "https://docs.aws.amazon.com/bedrock/"}, "bestPractices": ["Separate model access, prompt configuration, and application orchestration into distinct layers", "Use guardrails, evaluation, and redaction strategies for customer-facing or sensitive AI workloads", "Store prompts, system instructions, and model settings as versioned assets rather than scattering them through application code", "Ground responses with retrieval or knowledge base patterns when domain accuracy matters", "Monitor token usage, latency, error rates, and model selection cost continuously in production", "Apply least-privilege IAM and private networking controls for model invocation paths where required", "Choose model families and inference patterns based on workload needs such as reasoning, embeddings, or multimodal input"], "sdkInitPattern": "import { BedrockRuntimeClient, ConverseCommand } from ''@aws-sdk/client-bedrock-runtime'';\n\nconst bedrock = new BedrockRuntimeClient({ region: ''us-east-1'' });\nconst res = await bedrock.send(new ConverseCommand({\n  modelId: ''anthropic.claude-sonnet-5'',\n  messages: [{ role: ''user'', content: [{ text: prompt }] }],\n}));", "securityGuidance": "Scope bedrock:InvokeModel by model ARN per workload — model access is a cost and capability grant, not a formality. All calls go server-side under IAM roles (no exported keys to clients), treat model output as untrusted input to downstream systems, use Guardrails where user input reaches prompts, and check the invocation-logging configuration deliberately: it can capture full prompts and completions, which is either your audit trail or your data leak depending on where it lands."}', '[{"kind": "source", "path": "src/ai/bedrock-client.ts", "priority": "essential", "description": "Client wrapper for invoking Amazon Bedrock models and runtime APIs"}, {"kind": "config", "path": "src/ai/prompt-registry.json", "priority": "recommended", "description": "Versioned prompts, model selections, and inference configuration for Bedrock workloads"}, {"kind": "config", "path": "infra/bedrock.yaml", "priority": "recommended", "description": "Infrastructure and IAM configuration for Amazon Bedrock integrations"}]', '{"workloadType": {"type": "string", "label": "Primary Workload Type", "default": "chat", "options": ["chat", "embeddings", "multimodal", "agents"], "description": "Dominant generative AI workload handled by Amazon Bedrock"}, "inferenceMode": {"type": "enum", "label": "Inference mode", "default": "on-demand", "options": ["on-demand", "provisioned-throughput", "batch"], "description": "On-demand per-token; provisioned throughput for guaranteed capacity; batch for async bulk jobs"}, "knowledgeBase": {"type": "boolean", "label": "Knowledge Base", "default": false, "description": "Use retrieval-augmented grounding with Bedrock knowledge base patterns"}, "modelProvider": {"type": "enum", "label": "Model provider", "default": "anthropic", "options": ["anthropic", "amazon", "meta", "mistral", "cohere", "ai21", "stability"], "description": "Vendor family — the implementing AI resolves CURRENT model ids at build time (model lists churn; never hardcode them here)"}, "aiCapabilities": {"type": "multiselect", "label": "AI capabilities used", "options": ["generative-foundation-models", "document-processing", "speech-to-text", "text-to-speech", "translation", "vision", "natural-language", "embeddings", "personalization", "enterprise-search"], "description": "Owner ruling 2026-08-11: Bedrock is the arbiter of task AI on AWS - which capabilities this component consumes is Bedrock configuration, not separate nodes. The legacy single-task APIs (Comprehend, Rekognition, Textract, Transcribe, Polly, Translate, Lex, Kendra, Personalize) remain callable but new work routes here"}, "guardrailsEnabled": {"type": "boolean", "label": "Guardrails Enabled", "default": true, "description": "Apply managed safety and policy controls to model interactions"}, "crossRegionInference": {"type": "boolean", "label": "Cross-region inference", "default": true, "description": "Route to capacity across regions via inference profiles"}}', '["backend-service", "api-gateway", "vector-database", "monitoring", "object-storage"]', false, NULL, NULL, '2026-03-14 21:45:27.163157+00', '2026-08-31 20:06:52.578953+00', NULL, '#C0125F', '''-5'':160C ''/client-bedrock-runtime'':141C ''1'':150C ''access'':53B,73B,176C ''agent'':43B,120C ''ai'':16B,85B ''amazon'':5B,22B,61B,116C,118C,121C,125C,129C,132C ''anthropic.claude'':158C ''api'':30B ''applic'':17B,114B ''arn'':172C ''audit'':235C ''aw'':1A,3A,8B,56B,127C,139C ''await'':153C ''aws-sdk'':138C ''backend'':115B ''base'':124C ''bedrock'':2A,4A,6B,62B,117C,119C,122C,143C,168C ''bedrock.send'':154C ''bedrockruntimecli'':135C,145C ''build'':14B ''call'':187C ''capabl'':181C ''captur'':226C ''chat'':37B ''check'':217C ''choos'':60B ''client'':199C ''cloudwatch'':133C ''complet'':230C ''configur'':222C ''const'':142C,151C ''consumpt'':94B ''content'':164C ''conversecommand'':136C,156C ''cost'':179C ''custom'':46B ''data'':239C ''databas'':111B ''deliber'':223C ''depend'':241C ''deploy'':101B ''downstream'':207C ''east'':149C ''either'':233C ''embed'':40B ''engin'':109B ''export'':196C ''featur'':47B ''formal'':185C ''foundat'':19B,92B ''full'':227C ''fulli'':10B ''general'':97B ''generat'':15B,39B ''go'':188C ''govern'':59B ''grant'':182C ''guardrail'':210C ''iam'':193C ''import'':134C ''infer'':42B,80B ''infrastructur'':81B ''input'':205C,213C ''integr'':54B ''invoc'':220C ''invocation-log'':219C ''invokemodel'':169C ''key'':197C ''knowledg'':123C ''lambda'':128C ''land'':245C ''leak'':240C ''log'':221C ''manag'':11B,29B,51B,66B,91B ''messag'':161C ''ml'':98B ''model'':20B,52B,67B,76B,93B,171C,175C,201C ''modelid'':157C ''multimod'':41B ''multipl'':75B ''need'':89B ''new'':144C,155C ''opensearch'':130C ''oper'':79B ''output'':202C ''parti'':26B ''per'':173C ''platform'':32B ''primari'':88B ''prompt'':166C,215C,228C ''provid'':27B,77B ''rapid'':72B ''rather'':95B ''reach'':214C ''region'':146C ''res'':152C ''role'':162C,194C ''s3'':126C ''sagemak'':84B ''scope'':167C ''sdk'':140C ''secur'':57B ''self'':65B ''self-manag'':64B ''serv'':68B ''server'':190C ''server-sid'':189C ''servic'':12B,131C ''side'':191C ''sonnet'':159C ''system'':208C ''text'':38B,165C ''third'':25B ''third-parti'':24B ''tool'':33B ''trail'':236C ''train'':99B ''transact'':113B ''treat'':200C ''untrust'':204C ''us'':148C ''us-east'':147C ''use'':34B,104B,209C ''user'':163C,212C ''vector'':110B ''want'':50B,71B ''without'':78B ''workflow'':44B,108B ''workload'':174C');
INSERT INTO public.technology_catalog VALUES ('supabase', 'Supabase (Managed)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["supabase"]', '{"purpose": "The managed Supabase platform as a CONTAINER: place it, then nest only the services this system actually adopts - Auth, Database, Storage, Realtime, Edge Functions are separate contained nodes because the platform sells a-la-carte and architectures should say which parts they rent. The platform node carries project-level facts (region, environment tiers, API gateway surface); each service node carries its own doctrine and configuration.", "configMode": "declarative", "provenance": {"notes": "Platform-container rewrite for the Supabase round (owner direction 2026-08-11): services are contained nodes, adopted a-la-carte. Prior thin platform context superseded.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["Project + environment tiers", "supabase-js / service clients", "CLI migrations (supabase db push)", "Row Level Security", "API gateway (PostgREST/Kong surface)"], "antiPatterns": ["One platform node standing for auth+db+storage+realtime with the adoption story invisible", "service_role key in client code or edge-exposed configuration", "Dashboard-authored schema changes that never land in migration history", "Treating Supabase as only-a-database while its Auth/Storage/Realtime go unmodeled beside a duplicate stack"], "apiReference": {"docsUrl": "https://supabase.com/docs"}, "bestPractices": ["Model each adopted service as its own contained node - a lone platform box hides the real architecture", "One Supabase project per environment (dev/staging/prod) with config promoted by migration, not console drift", "Treat the service_role key as a server-only secret and the anon key as public-by-design - RLS is the real boundary", "Keep schema in migrations under git; the dashboard SQL editor is for reading, not for production change"]}', '[]', '{"region": {"type": "string", "label": "Region", "description": "Supabase project region (e.g. us-east-1)"}, "services": {"type": "multiselect", "label": "Services Used", "options": ["database-postgres", "auth", "storage", "edge-functions", "realtime", "vector"], "required": true, "description": "Which Supabase services this architecture actually uses — using only a portion is expected; each service is its own config and cost surface"}, "environment": {"type": "string", "label": "Environment", "default": "production", "description": "production, staging, development"}}', '[]', false, NULL, NULL, '2026-08-31 20:06:50.928715+00', '2026-08-31 20:06:52.592427+00', 'Supabase (Managed)', NULL, '''a-la-cart'':36B ''actual'':20B ''adopt'':21B ''api'':59B,87C ''architectur'':41B ''auth'':22B ''carri'':51B,65B ''cart'':39B ''cli'':79C ''client'':78C ''configur'':70B ''contain'':10B,30B ''databas'':23B ''db'':82C ''doctrin'':68B ''edg'':26B ''environ'':57B,72C ''fact'':55B ''function'':27B ''gateway'':60B,88C ''js'':76C ''la'':38B ''level'':54B,85C ''manag'':2A,5B ''migrat'':80C ''nest'':14B ''node'':31B,50B,64B ''part'':45B ''place'':11B ''platform'':7B,34B,49B ''postgrest/kong'':89C ''project'':53B,71C ''project-level'':52B ''push'':83C ''realtim'':25B ''region'':56B ''rent'':47B ''row'':84C ''say'':43B ''secur'':86C ''sell'':35B ''separ'':29B ''servic'':17B,63B,77C ''storag'':24B ''supabas'':1A,3A,6B,75C,81C ''supabase-j'':74C ''surfac'':61B,90C ''system'':19B ''tier'':58B,73C');
INSERT INTO public.technology_catalog VALUES ('supabase-db', 'Supabase Database', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["database"]', '{"purpose": "Managed PostgreSQL platform with built-in auth (GoTrue), auto-generated RESTful API (PostgREST), real-time subscriptions (Realtime), Edge Functions (Deno), object storage, and vector embeddings (pgvector). Ideal when you want a full backend-as-a-service built on PostgreSQL with Row Level Security as the authorization layer.", "configMode": "declarative", "provenance": {"notes": "Phase B10 configMode ruling + additions authored from model knowledge. Prior stamp: none . Upgrade at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-10"}, "typicalTech": ["PostgreSQL 15+", "@supabase/supabase-js", "PostgREST", "GoTrue", "Supabase Realtime", "Supabase Edge Functions", "Supabase Storage", "pgvector", "pg_net", "pg_cron", "pgBouncer"], "antiPatterns": ["Using service_role key in client-side code (exposes full database access)", "Creating RLS policies with USING (true) which defeats the purpose of RLS", "Not enabling RLS on new tables (tables are public by default without RLS)", "Using the dashboard SQL editor for production schema changes instead of migrations", "Storing large files in database columns instead of Supabase Storage", "Not using connection pooling for serverless or high-concurrency deployments", "Directly querying auth.users table instead of using auth.uid() in RLS", "Skipping foreign key indexes which degrades join and RLS policy performance", "Using single() when the query might return zero rows (throws error instead of null)"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/database"}, "bestPractices": ["Use Row Level Security (RLS) policies on every table as the primary authorization mechanism", "Use auth.uid() in RLS policies to scope data to the authenticated user", "Use Supabase client library instead of raw PostgREST for type safety", "Create database functions for complex business logic to keep it close to the data", "Use Supabase Realtime subscriptions for live data updates instead of polling", "Use Edge Functions for server-side logic that needs secrets or external API calls", "Use Supabase Storage with RLS-protected buckets for file uploads", "Use pg_net for async HTTP calls from database functions", "Use pgvector for AI embedding storage and similarity search", "Configure connection pooling via Supabase dashboard for production workloads", "Use database migrations for schema changes instead of the dashboard SQL editor", "Use maybeSingle() instead of single() when a query might return zero rows"], "freshnessNote": "PLACEMENT decides the lane (owner ruling 2026-07-28): inside the Supabase (Managed) platform container this is the managed product (dashboard, branching, PITR backups); inside a Docker/self-managed container it is the open-source stack (docker-compose of Postgres + GoTrue + storage-api + edge-runtime + postgrest) with the capability deltas noted on each service row. Same client SDKs either way. There is NO managed-vs-OSS config field — the container the node lives in IS the answer.", "securityGuidance": "RLS on every exposed table with policies for each operation — a table without RLS in the public schema is world-readable through the anon key, which ships in every client bundle by design. The service-role key bypasses RLS: server-side only, never in client code or logs. Write schema as versioned migrations (the dashboard is for reading, git is for truth), use security-definer functions sparingly and audit them (each is an RLS bypass), and keep the auth.uid() calls wrapped in selects so policies stay performant at scale.", "configurationTemplate": "-- supabase/migrations/0001_orders.sql\ncreate table public.orders (\n  id uuid primary key default gen_random_uuid(),\n  owner_id uuid not null references auth.users (id),\n  total numeric not null,\n  created_at timestamptz not null default now()\n);\nalter table public.orders enable row level security;\ncreate policy \"owners read own orders\" on public.orders\n  for select using ((select auth.uid()) = owner_id);\ncreate policy \"owners insert own orders\" on public.orders\n  for insert with check ((select auth.uid()) = owner_id);"}', '[{"kind": "config", "path": "supabase/config.toml", "language": "toml", "priority": "essential", "description": "Supabase project configuration for local development and CI"}, {"kind": "schema", "path": "supabase/migrations/", "language": "sql", "priority": "essential", "description": "Database migration files with schema changes and RLS policies"}, {"kind": "config", "path": "supabase/seed.sql", "language": "sql", "priority": "recommended", "description": "Seed data for local development and testing"}, {"kind": "source", "path": "src/lib/supabase.ts", "language": "typescript", "priority": "essential", "description": "Supabase client singleton initialization with environment variables"}, {"kind": "source", "path": "src/types/database.types.ts", "language": "typescript", "priority": "essential", "description": "Auto-generated TypeScript types from database schema (supabase gen types)"}, {"kind": "source", "path": "supabase/functions/", "language": "typescript", "priority": "recommended", "description": "Edge Functions directory for server-side Deno functions"}, {"kind": "config", "path": ".env.local", "language": "text", "priority": "essential", "description": "Environment variables with SUPABASE_URL and SUPABASE_ANON_KEY"}, {"kind": "schema", "path": "supabase/migrations/rls-policies.sql", "language": "sql", "priority": "essential", "description": "Row Level Security policies using auth.uid() for data access control"}]', '{"region": {"type": "string", "label": "Region", "description": "Supabase project hosting region"}, "projectUrl": {"type": "string", "label": "Project URL", "description": "Supabase project API URL (e.g., https://xxx.supabase.co)"}, "rlsEnabled": {"type": "boolean", "label": "Row Level Security", "default": true, "description": "Enable RLS on all tables (strongly recommended)"}, "vectorEnabled": {"type": "boolean", "label": "pgvector", "default": false, "description": "Enable pgvector extension for AI embedding storage and similarity search"}, "storageEnabled": {"type": "boolean", "label": "Storage", "default": false, "description": "Use Supabase Storage for file uploads with RLS-protected buckets"}, "realtimeEnabled": {"type": "boolean", "label": "Realtime", "default": true, "description": "Enable real-time subscriptions for live data updates"}, "connectionPooling": {"type": "boolean", "label": "Connection Pooling", "default": true, "description": "Use Supavisor connection pooling for production workloads"}, "edgeFunctionsEnabled": {"type": "boolean", "label": "Edge Functions", "default": true, "description": "Use Supabase Edge Functions for server-side logic"}}', '["auth-provider", "backend-service", "frontend-app", "edge-function"]', false, NULL, NULL, '2026-02-20 20:35:26.902667+00', '2026-08-31 20:07:01.887163+00', 'Supabase', '#32A872', '''15'':57C ''anon'':98C ''api'':18B ''audit'':146C ''auth'':12B ''auth.uid'':156C ''author'':54B ''auto'':15B ''auto-gener'':14B ''backend'':41B ''backend-as-a-servic'':40B ''built'':10B,45B ''built-in'':9B ''bundl'':105C ''bypass'':113C,152C ''call'':157C ''client'':104C,121C ''code'':122C ''cron'':72C ''dashboard'':131C ''databas'':2A ''db'':4A ''defin'':142C ''deno'':27B ''design'':107C ''edg'':25B,64C ''embed'':32B ''everi'':76C,103C ''expos'':77C ''full'':39B ''function'':26B,65C,143C ''generat'':16B ''git'':135C ''gotru'':13B,60C ''ideal'':34B ''keep'':154C ''key'':99C,112C ''layer'':55B ''level'':50B ''log'':124C ''manag'':5B ''migrat'':129C ''net'':70C ''never'':119C ''object'':28B ''oper'':83C ''perform'':164C ''pg'':69C,71C ''pgbouncer'':73C ''pgvector'':33B,68C ''platform'':7B ''polici'':80C,162C ''postgresql'':6B,4