INSERT INTO public.technology_catalog VALUES ('supabase-oss-db', 'Supabase OSS Postgres', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["database"]', '{"purpose": "The Postgres container at the core of a self-hosted Supabase stack: the supabase/postgres image (Postgres + the platform extensions: pgjwt, pgsodium/supabase_vault, pg_graphql, pgvector and friends) with the auth/storage/realtime schemas provisioned by init scripts. Everything else in the stack is a satellite of this container - its volume is the system of record and its migration discipline is the deployment''s real quality bar.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase OSS round 2 (owner direction): lane-specific self-host row; the lane-neutral supabase-db row remains valid in either home per the 2026-08-05 ruling.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["supabase/postgres image (pinned)", "Init scripts + migration files", "Platform extensions (pgvector, pgjwt, vault)", "Supavisor pooling", "WAL archiving / off-host dumps"], "antiPatterns": ["psql-ing schema changes into the running container that no migration file records", "Exposing 5432 beside Kong instead of keeping database access inside the compose network", "Using a stock postgres image and wondering where the platform extensions and auth schema went", "Treating the data volume as the backup strategy", "Skipping the pooler and exhausting connection slots under modest concurrency"], "bestPractices": ["Apply schema through migration files (supabase CLI db push against the self-host, or ordered init/migration scripts in volumes/db) - never by hand inside the container", "Keep the supabase/postgres image version pinned and upgrade Postgres majors as a rehearsed event with a dump/restore path", "Route application connections through Supavisor (the stack pooler) rather than raw :5432 - Postgres connection slots are the first thing self-hosts exhaust", "Ship WAL archiving or scheduled dumps OFF the host - the compose volume is not a backup", "Write RLS policies exactly as on the managed platform - GoTrue/PostgREST enforce through the same JWT claims"]}', '[{"kind": "config", "path": "volumes/db/init/"}, {"kind": "config", "path": "supabase/migrations/"}]', '{"backups": {"type": "enum", "label": "Backups", "default": "scheduled-dumps-offhost", "options": ["wal-archiving-offhost", "scheduled-dumps-offhost", "volume-snapshots-only"]}, "pooling": {"type": "enum", "label": "Connection path", "default": "supavisor-pooler", "options": ["supavisor-pooler", "direct-5432-internal-only"]}, "imageTag": {"type": "string", "label": "Pinned image tag", "default": "supabase/postgres:15", "description": "Never latest - upgrades are rehearsed events"}, "extensions": {"type": "multiselect", "label": "Platform extensions in use", "default": ["pgjwt"], "options": ["pgvector", "pg_graphql", "pgjwt", "vault", "pg_cron", "postgis"]}}', '[{"id": "supabase-oss", "reason": "The compose boundary this container runs in"}, {"id": "supabase-oss-auth", "reason": "GoTrue reads/writes the auth schema"}, {"id": "supabase-oss-realtime", "reason": "Streams this database''s WAL"}]', false, NULL, NULL, '2026-08-31 20:06:52.606247+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''archiv'':86C ''auth/storage/realtime'':36B ''bar'':70B ''contain'':9B,52B ''core'':12B ''db'':6A ''deploy'':66B ''disciplin'':63B ''dump'':90C ''els'':43B ''everyth'':42B ''extens'':26B,79C ''file'':77C ''friend'':33B ''graphql'':30B ''host'':17B,89C ''imag'':22B,72C ''init'':40B,74C ''migrat'':62B,76C ''off-host'':87C ''oss'':2A,5A ''pg'':29B ''pgjwt'':27B,81C ''pgsodium/supabase_vault'':28B ''pgvector'':31B,80C ''pin'':73C ''platform'':25B,78C ''pool'':84C ''postgr'':3A,8B,23B ''provis'':38B ''qualiti'':69B ''real'':68B ''record'':59B ''satellit'':49B ''schema'':37B ''script'':41B,75C ''self'':16B ''self-host'':15B ''stack'':19B,46B ''supabas'':1A,4A,18B ''supabase/postgres'':21B,71C ''supavisor'':83C ''system'':57B ''vault'':82C ''volum'':54B ''wal'':85C');
INSERT INTO public.technology_catalog VALUES ('supabase-oss-auth', 'Supabase OSS Auth (GoTrue)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["auth-provider"]', '{"purpose": "The GoTrue container - the auth service of a self-hosted Supabase stack, configured entirely by environment: SITE_URL and redirect allow-lists, the shared JWT secret it mints tokens with, SMTP for email flows, and per-provider OAuth credentials. On the managed platform these are dashboard toggles; here every one is a compose .env line the deployment owns, and the JWT secret must match the whole stack.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase OSS round 2 (owner direction) - the GoTrue container as an individually-configured node.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["GoTrue container (env-configured)", "Shared stack JWT secret", "SMTP for email flows", "OAuth provider env pairs", "Kong-routed callbacks"], "antiPatterns": ["Running with the demo JWT secret or a secret that differs from the rest of the stack (tokens verify nowhere)", "Email auth enabled with no SMTP configured - signups succeed, confirmations vanish", "Wildcard redirect URLs to make an OAuth error go away", "Editing auth.users directly instead of using GoTrue''s admin API"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/self-hosting/auth/config"}, "bestPractices": ["Set GOTRUE_SITE_URL and the additional redirect allow-list exactly - open redirect config is the classic self-host auth hole", "Wire real SMTP before enabling email signup: confirmations/recovery silently fail without it and lock users out", "Configure each OAuth provider with its own env pair and callback URL pointing through Kong", "Keep token lifetimes short with refresh rotation enabled - the defaults are a starting point, not a policy", "Disable signup (autoconfirm off, invite-only) on stacks that are internal tools, not consumer products"], "securityGuidance": "GoTrue mints the tokens every other service trusts: its JWT secret is the stack''s trust anchor and its redirect configuration is an open-redirect surface. Callbacks route through Kong only; the container itself never faces a network. Admin endpoints (service-role scoped) are for server-side use exclusively."}', '[{"kind": "config", "path": ".env"}, {"kind": "config", "path": "docker-compose.yml"}]', '{"authMethods": {"type": "multiselect", "label": "Enabled methods", "default": ["email-password"], "options": ["email-password", "magic-links", "oauth-providers", "phone-otp", "anonymous"]}, "signupPolicy": {"type": "enum", "label": "Signup policy", "default": "open-signup", "options": ["open-signup", "invite-only", "disabled"]}, "smtpConfigured": {"type": "boolean", "label": "Real SMTP configured", "default": true, "description": "Email flows silently fail without it"}, "refreshRotation": {"type": "boolean", "label": "Refresh token rotation", "default": true}}', '[{"id": "supabase-oss", "reason": "The compose boundary this container runs in"}, {"id": "supabase-oss-db", "reason": "Owns the auth schema it reads/writes"}, {"id": "frontend-app", "reason": "The clients holding its tokens"}]', false, NULL, NULL, '2026-08-31 20:06:52.606247+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''admin'':138C ''allow'':30B ''allow-list'':29B ''anchor'':115C ''auth'':3A,7A,12B ''callback'':98C,126C ''compos'':63B ''configur'':21B,82C,119C ''contain'':10B,79C,132C ''credenti'':49B ''dashboard'':56B ''deploy'':67B ''email'':42B,89C ''endpoint'':139C ''entir'':22B ''env'':64B,81C,93C ''env-configur'':80C ''environ'':24B ''everi'':59B,103C ''exclus'':150C ''face'':135C ''flow'':43B,90C ''gotru'':4A,9B,78C,99C ''host'':18B ''jwt'':34B,71B,85C,108C ''kong'':96C,129C ''kong-rout'':95C ''line'':65B ''list'':31B ''manag'':52B ''match'':74B ''mint'':37B,100C ''must'':73B ''network'':137C ''never'':134C ''oauth'':48B,91C ''one'':60B ''open'':123C ''open-redirect'':122C ''oss'':2A,6A ''own'':68B ''pair'':94C ''per'':46B ''per-provid'':45B ''platform'':53B ''provid'':47B,92C ''redirect'':28B,118C,124C ''role'':142C ''rout'':97C,127C ''scope'':143C ''secret'':35B,72B,86C,109C ''self'':17B ''self-host'':16B ''server'':147C ''server-sid'':146C ''servic'':13B,105C,141C ''service-rol'':140C ''share'':33B,83C ''side'':148C ''site'':25B ''smtp'':40B,87C ''stack'':20B,77B,84C,112C ''supabas'':1A,5A,19B ''surfac'':125C ''toggl'':57B ''token'':38B,102C ''trust'':106C,114C ''url'':26B ''use'':149C ''whole'':76B');
INSERT INTO public.technology_catalog VALUES ('supabase-oss-storage', 'Supabase OSS Storage API', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["object-storage"]', '{"purpose": "The Storage API container of a self-hosted stack (plus imgproxy for on-the-fly image transforms): bucket/object storage whose authorization is RLS policies on storage.objects in the same Postgres, and whose BACKEND is the deployment decision - a mounted file volume for simple installs, or S3-compatible object storage (MinIO, real S3) when durability and scale are the requirement.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase OSS round 2 (owner direction) - the storage-api container as an individually-configured node; backend choice is THE self-host decision the managed platform never asks.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["storage-api container", "file or s3-compatible backend (MinIO)", "RLS on storage.objects", "Signed URLs", "imgproxy transforms"], "antiPatterns": ["File-backend uploads living only in a compose volume nobody backs up - the database survives, every upload is gone", "Public buckets as the default because policies felt like friction", "Serving files by proxying through your backend instead of the storage API''s signed URLs", "Skipping imgproxy and shipping full-size originals to every client"], "bestPractices": ["Choose the backend deliberately: file backend + volume for small installs, s3 backend (MinIO or cloud) when the files must outlive the host", "Authorize with RLS on storage.objects exactly as on the managed platform - bucket privacy is policy, not obscurity", "Run imgproxy beside it if the app serves image variants - transforming in app code duplicates a stack capability", "Include the storage backend in the backup story: database dumps do NOT carry the object bytes"]}', '[{"kind": "config", "path": "docker-compose.yml"}, {"kind": "config", "path": ".env"}]', '{"backend": {"type": "enum", "label": "Storage backend", "default": "file-volume", "options": ["file-volume", "s3-minio", "s3-cloud"], "description": "The decision the managed platform never asks - file for simple installs, s3-compatible when files must outlive the host"}, "backupIncluded": {"type": "boolean", "label": "Backend in backup story", "default": true, "description": "Database dumps do not carry object bytes"}, "imageTransforms": {"type": "boolean", "label": "imgproxy transforms", "default": true}}', '[{"id": "supabase-oss", "reason": "The compose boundary this container runs in"}, {"id": "supabase-oss-db", "reason": "storage.objects policies live there"}, {"id": "frontend-app", "reason": "Uploads and signed-URL consumers"}]', false, NULL, NULL, '2026-08-31 20:06:52.606247+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''api'':4A,10B,72C ''author'':30B ''backend'':42B,79C ''bucket/object'':27B ''compat'':57B,78C ''contain'':11B,73C ''decis'':46B ''deploy'':45B ''durabl'':64B ''file'':49B,74C ''fli'':24B ''host'':16B ''imag'':25B ''imgproxi'':19B,86C ''instal'':53B ''minio'':60B,80C ''mount'':48B ''object'':58B ''on-the-fli'':21B ''oss'':2A,6A ''plus'':18B ''polici'':33B ''postgr'':39B ''real'':61B ''requir'':69B ''rls'':32B,81C ''s3'':56B,62B,77C ''s3-compatible'':55B,76C ''scale'':66B ''self'':15B ''self-host'':14B ''sign'':84C ''simpl'':52B ''stack'':17B ''storag'':3A,7A,9B,28B,59B,71C ''storage-api'':70C ''storage.objects'':35B,83C ''supabas'':1A,5A ''transform'':26B,87C ''url'':85C ''volum'':50B ''whose'':29B,41B');
INSERT INTO public.technology_catalog VALUES ('supabase-oss-realtime', 'Supabase OSS Realtime', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["realtime-service"]', '{"purpose": "The Realtime container (Elixir) of a self-hosted stack: websocket fan-out for the same three primitives as the platform - Postgres Changes (WAL-driven CDC), Broadcast, Presence - with the self-host obligations the managed service hides: it consumes a replication slot on YOUR Postgres, its JWT verification uses the stack secret, and its capacity is your container''s memory and connection budget.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase OSS round 2 (owner direction) - the realtime container with the self-host obligations (replication slot, capacity) made explicit.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["realtime container (Elixir)", "Logical replication slot", "Postgres Changes / Broadcast / Presence", "RLS-authorized channels", "Stack JWT verification"], "antiPatterns": ["Ignoring the replication slot until WAL retention fills the database volume", "Broadcasting large payloads through a container whose memory YOU provision", "Public channels for user data because the stack is \"internal\"", "Treating container restarts as invisible - clients must resync from the database, which is the truth"], "bestPractices": ["Monitor the replication slot it holds - a stalled Realtime container retaining WAL is a full-disk incident on the database", "Authorize private channels with RLS exactly as on the platform; the self-host does not loosen the model", "Scope Postgres Changes subscriptions narrowly - every subscribed table is decode work on your own WAL stream", "Size websocket concurrency deliberately and put reconnect/resync in the client - delivery is not guaranteed across container restarts"]}', '[{"kind": "config", "path": "docker-compose.yml"}]', '{"primitives": {"type": "multiselect", "label": "Primitives used", "default": ["postgres-changes"], "options": ["postgres-changes", "broadcast", "presence"]}, "maxConnections": {"type": "number", "label": "Websocket connection budget", "default": 500}, "slotMonitoring": {"type": "boolean", "label": "Replication-slot monitoring", "default": true, "description": "A stalled slot retaining WAL is a full-disk incident"}}', '[{"id": "supabase-oss", "reason": "The compose boundary this container runs in"}, {"id": "supabase-oss-db", "reason": "Holds a replication slot on its WAL"}, {"id": "frontend-app", "reason": "The subscribing clients"}]', false, NULL, NULL, '2026-08-31 20:06:52.606247+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''author'':85C ''broadcast'':35B,81C ''budget'':72B ''capac'':64B ''cdc'':34B ''chang'':30B,80C ''channel'':86C ''connect'':71B ''consum'':48B ''contain'':9B,67B,74C ''driven'':33B ''elixir'':10B,75C ''fan'':19B ''fan-out'':18B ''hide'':46B ''host'':15B,41B ''jwt'':56B,88C ''logic'':76C ''manag'':44B ''memori'':69B ''oblig'':42B ''oss'':2A,5A ''platform'':28B ''postgr'':29B,54B,79C ''presenc'':36B,82C ''primit'':25B ''realtim'':3A,6A,8B,73C ''replic'':50B,77C ''rls'':84C ''rls-author'':83C ''secret'':61B ''self'':14B,40B ''self-host'':13B,39B ''servic'':45B ''slot'':51B,78C ''stack'':16B,60B,87C ''supabas'':1A,4A ''three'':24B ''use'':58B ''verif'':57B,89C ''wal'':32B ''wal-driven'':31B ''websocket'':17B');
INSERT INTO public.technology_catalog VALUES ('supabase-oss-edge-functions', 'Supabase OSS Edge Runtime', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["serverless-function"]', '{"purpose": "The Edge Runtime container (Deno) of a self-hosted stack: your TypeScript functions served from a mounted volumes/functions directory - deployment is FILES ARRIVING (git checkout, rsync, bind mount), not `supabase functions deploy`. Same function code as the managed platform, radically different operational contract: one always-on container you size, restart and log yourself, not per-invocation isolation that scales to zero.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase OSS round 2 (owner direction) - the deploy-is-files-arriving contract is the load-bearing difference from the managed row.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["edge-runtime container (Deno)", "volumes/functions bind mount", "Git-driven deploy of the functions dir", "Kong-routed invocation", "Container env secrets"], "antiPatterns": ["Treating the self-host runtime as identical to managed - it is one shared container, not per-function isolation", "Secrets inline in function source because .env wiring felt indirect", "Exposing the runtime port beside Kong", "Long-running work inside a function the whole runtime restarts under - that belongs on a worker node"], "bestPractices": ["Deploy by shipping the functions directory from git (CI artifact or checkout) - hand-edited files in the volume are undeployed code", "Read secrets from container env; never commit them into the function source the volume exposes", "Route invocation through Kong (/functions/v1/...) so auth headers are enforced on the same gateway path as everything else", "Keep functions stateless and idempotent - the container restarts as a unit and in-memory state dies with it", "Verify platform-parity per feature: background tasks, regional execution and some limits differ from the managed runtime"]}', '[{"kind": "source", "path": "volumes/functions/"}, {"kind": "config", "path": "docker-compose.yml"}]', '{"deployPath": {"type": "enum", "label": "Deploy mechanism", "default": "git-checkout-ci", "options": ["git-checkout-ci", "bind-mount-dev", "rsync"], "description": "Deployment is files arriving in volumes/functions - own the pipeline"}, "secretsSource": {"type": "enum", "label": "Secrets", "default": "container-env", "options": ["container-env", "mounted-env-file"]}, "invocationPath": {"type": "enum", "label": "Invocation", "default": "kong-functions-route", "options": ["kong-functions-route", "direct-port-internal-only"]}}', '[{"id": "supabase-oss", "reason": "The compose boundary this container runs in"}, {"id": "supabase-oss-db", "reason": "Functions reach Postgres inside the compose network"}, {"id": "supabase-oss-auth", "reason": "Verifies caller JWTs minted by GoTrue"}]', false, NULL, NULL, '2026-08-31 20:06:52.606247+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''alway'':55B ''always-on'':54B ''arriv'':32B ''bind'':36B,79C ''checkout'':34B ''code'':44B ''contain'':12B,57B,76C,93C ''contract'':52B ''deno'':13B,77C ''deploy'':29B,41B,84C ''differ'':50B ''dir'':88C ''directori'':28B ''driven'':83C ''edg'':3A,7A,10B,74C ''edge-runtim'':73C ''env'':94C ''file'':31B ''function'':8A,22B,40B,43B,87C ''git'':33B,82C ''git-driven'':81C ''host'':18B ''invoc'':67B,92C ''isol'':68B ''kong'':90C ''kong-rout'':89C ''log'':62B ''manag'':47B ''mount'':26B,37B,80C ''one'':53B ''oper'':51B ''oss'':2A,6A ''per'':66B ''per-invoc'':65B ''platform'':48B ''radic'':49B ''restart'':60B ''rout'':91C ''rsync'':35B ''runtim'':4A,11B,75C ''scale'':70B ''secret'':95C ''self'':17B ''self-host'':16B ''serv'':23B ''size'':59B ''stack'':19B ''supabas'':1A,5A,39B ''typescript'':21B ''volumes/functions'':27B,78C ''zero'':72B');
INSERT INTO public.technology_catalog VALUES ('supabase-oss', 'Supabase OSS (Self-Hosted)', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_oss.png', '#3ECF8E', '["docker-compose"]', '{"purpose": "The open-source Supabase stack self-hosted as a Docker Compose deployment - this node IS the compose boundary, and the services inside are its containers: Kong (API gateway fronting everything), GoTrue (auth), PostgREST (REST over the schema), Realtime, Storage API (+ imgproxy for transforms), postgres-meta, Studio (dashboard), Edge Runtime (Deno functions), Logflare (analytics), Supavisor (connection pooler), and Postgres itself. Choose it for data residency, air-gapped/compliance postures, or cost control at scale; choose the managed platform node when Supabase should carry the ops. Nest the service nodes this deployment actually enables - the compose file is the source of truth for which containers run.", "configMode": "declarative", "provenance": {"notes": "Authored for the Supabase round (owner direction 2026-08-11). Filed docker-compose: the self-host ships as a compose stack, so the node''s containment IS the implementation structure. Service composition drifts by release - verify the container list against the official docker/ bundle at live-docs sweep.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["docker compose (official bundle)", "Kong gateway", "GoTrue + PostgREST + Realtime + Storage API", "Edge Runtime (Deno)", "Supavisor pooler", "Postgres + WAL backups"], "antiPatterns": ["Running the demo JWT secret and keys from the docs in anything reachable from the internet", "Exposing service containers (Postgres, PostgREST, GoTrue) beside Kong instead of through it", "latest tags on every image, upgraded by accident during an unrelated restart", "Treating the self-host as identical to the managed platform - branching, some auth providers and platform add-ons differ; verify per feature", "One compose stack shared by prod and staging because it was already running"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/self-hosting"}, "bestPractices": ["Start from the official docker/ compose bundle and keep YOUR compose + .env in git - the stack is versioned infrastructure, not a console", "Generate real secrets before first boot: JWT_SECRET plus matching ANON_KEY/SERVICE_ROLE_KEY (the published demo keys are a breach, not a default)", "Put Kong''s exposed ports behind your own TLS terminator/reverse proxy; never publish Postgres or the service containers directly", "Upgrade deliberately: pin image tags, snapshot the database volume, and roll the stack version-by-version - latest-tag drift is how self-hosts die", "Externalize Postgres backups (WAL archiving or scheduled dumps off-host) - the compose volume is not a backup strategy"], "securityGuidance": "The stack''s trust anchor is the JWT secret: everything (GoTrue tokens, PostgREST RLS enforcement, Storage authorization) derives from it, so generate it once, store it as a real secret, and rotating it means reissuing every key. Kong is the only container that should face a network; the service containers trust each other inside the compose network, which makes host/network isolation part of the security model, not an ops nicety."}', '[{"kind": "config", "path": "docker-compose.yml"}, {"kind": "config", "path": ".env"}, {"kind": "config", "path": "volumes/db/init/"}]', '{"edgeExposure": {"type": "enum", "label": "Network exposure", "default": "kong-behind-reverse-proxy", "options": ["kong-behind-reverse-proxy", "kong-direct-tls"]}, "backupStrategy": {"type": "enum", "label": "Postgres backups", "default": "scheduled-dumps-offhost", "options": ["wal-archiving-offhost", "scheduled-dumps-offhost", "volume-snapshots-only"], "description": "volume-snapshots-only is not a backup strategy"}, "enabledServices": {"type": "multiselect", "label": "Enabled services", "default": ["auth-gotrue", "rest-postgrest", "realtime", "storage-api", "studio"], "options": ["auth-gotrue", "rest-postgrest", "realtime", "storage-api", "edge-runtime", "studio", "analytics-logflare", "pooler-supavisor"], "description": "Mirror of the compose file - which containers this deployment runs"}, "containerRuntime": {"type": "enum", "label": "Runtime", "default": "docker-compose", "options": ["docker-compose", "kubernetes-community-charts", "podman-compose"], "description": "The official bundle is compose; k8s runs on community charts with the same containers"}}', '[{"id": "supabase-oss-db", "reason": "The Postgres at the stack core"}, {"id": "supabase-oss-auth", "reason": "GoTrue container in the stack"}, {"id": "supabase-oss-storage", "reason": "Storage API container in the stack"}, {"id": "supabase-oss-realtime", "reason": "Realtime container in the stack"}, {"id": "supabase-oss-edge-functions", "reason": "Edge Runtime container in the stack"}, {"id": "kong", "reason": "The gateway fronting every service"}]', false, NULL, NULL, '2026-08-31 20:06:52.592427+00', '2026-08-31 20:06:52.606247+00', NULL, NULL, '''/compliance'':78B ''actual'':102B ''air'':76B ''air-gap'':75B ''analyt'':63B ''anchor'':139C ''api'':36B,49B,126C ''auth'':41B ''author'':151C ''backup'':134C ''boundari'':27B ''bundl'':119C ''carri'':93B ''choos'':70B,85B ''compos'':20B,26B,105B,117C,190C ''connect'':65B ''contain'':34B,114B,176C,184C ''control'':82B ''cost'':81B ''dashboard'':57B ''data'':73B ''deno'':60B,129C ''deploy'':21B,101B ''deriv'':152C ''docker'':19B,116C ''edg'':58B,127C ''enabl'':103B ''enforc'':149C ''everi'':170C ''everyth'':39B,144C ''face'':179C ''file'':106B ''front'':38B ''function'':61B ''gap'':77B ''gateway'':37B,121C ''generat'':156C ''gotru'':40B,122C,145C ''host'':5A,16B ''host/network'':194C ''imgproxi'':50B ''insid'':31B,188C ''isol'':195C ''jwt'':142C ''key'':171C ''kong'':35B,120C,172C ''logflar'':62B ''make'':193C ''manag'':87B ''mean'':168C ''meta'':55B ''model'':200C ''nest'':96B ''network'':181C,191C ''niceti'':204C ''node'':23B,89B,99B ''offici'':118C ''op'':95B,203C ''open'':10B ''open-sourc'':9B ''oss'':2A,7A ''part'':196C ''platform'':88B ''pooler'':66B,131C ''postgr'':54B,68B,132C ''postgres-meta'':53B ''postgrest'':42B,123C,147C ''postur'':79B ''real'':163C ''realtim'':47B,124C ''reissu'':169C ''resid'':74B ''rest'':43B ''rls'':148C ''rotat'':166C ''run'':115B ''runtim'':59B,128C ''scale'':84B ''schema'':46B ''secret'':143C,164C ''secur'':199C ''self'':4A,15B ''self-host'':3A,14B ''servic'':30B,98B,183C ''sourc'':11B,109B ''stack'':13B,136C ''storag'':48B,125C,150C ''store'':159C ''studio'':56B ''supabas'':1A,6A,12B,91B ''supavisor'':64B,130C ''token'':146C ''transform'':52B ''trust'':138C,185C ''truth'':111B ''wal'':133C');
INSERT INTO public.technology_catalog VALUES ('supabase-realtime', 'Supabase Realtime', 'https://komnpkjlvgfworfbdrya.supabase.co/storage/v1/object/public/icons/Supabase/supabase_managed.png', '#3ECF8E', '["realtime-service"]', '{"purpose": "Supabase''s realtime layer over websockets, three primitives with different costs: Postgres Changes (CDC on tables the client subscribes to), Broadcast (ephemeral fan-out between clients without touching the database), and Presence (who-is-here state). Authorization rides the same RLS/JWT model as the rest of the platform - a subscription is a policy question, not a topic-name convention.", "configMode": "code", "provenance": {"notes": "Authored for the Supabase round (owner direction 2026-08-11) - the missing core service beside auth/db/storage/edge-functions; same-icon convention as its siblings.", "method": "model-knowledge", "verifiedAt": "2026-08-11"}, "typicalTech": ["supabase-js channels", "Postgres Changes (CDC)", "Broadcast + Presence", "RLS-authorized private channels", "Reconnect/resync handling"], "antiPatterns": ["Using Postgres Changes as a message bus between services - server-to-server messaging belongs on a queue/broker node", "Public channels carrying user-specific data because auth felt like friction", "Treating delivery as guaranteed - a dropped websocket plus no resync equals silently stale UI", "Broadcasting large payloads instead of ids the client fetches through the API"], "apiReference": {"docsUrl": "https://supabase.com/docs/guides/realtime"}, "bestPractices": ["Choose the primitive deliberately: Broadcast for ephemeral client-to-client (cursors, typing), Postgres Changes only when the DATABASE row is the event", "Authorize channels with RLS (private channels + realtime.messages policies) - never rely on unguessable channel names", "Scope Postgres Changes to specific tables/filters; a wildcard subscription on a hot table is a self-inflicted load test", "Handle reconnect + missed-event catch-up explicitly: realtime is delivery, the database is truth - resync from a query on reconnect"]}', '[{"kind": "source", "path": "src/realtime/channels.ts"}]', '{"primitives": {"type": "multiselect", "label": "Primitives used", "default": ["postgres-changes"], "options": ["postgres-changes", "broadcast", "presence"], "description": "Each has a different cost model - Broadcast never touches the database"}, "channelAuth": {"type": "enum", "label": "Channel authorization", "default": "rls-private-channels", "options": ["rls-private-channels", "public-channels"]}, "resyncStrategy": {"type": "enum", "label": "Reconnect strategy", "default": "query-resync", "options": ["query-resync", "none"], "description": "Realtime is delivery, the database is truth"}}', '[{"id": "supabase-db", "reason": "Postgres Changes stream from its WAL"}, {"id": "supabase-auth", "reason": "Channel authorization rides its JWTs"}, {"id": "frontend-app", "reason": "The subscribing clients"}]', false, NULL, NULL, '2026-08-31 20:06:52.592427+00', '2026-08-31 20:07:01.887163+00', NULL, NULL, '''author'':43B,78C ''broadcast'':25B,74C ''cdc'':18B,73C ''chang'':17B,72C ''channel'':70C,80C ''client'':22B,31B ''convent'':66B ''cost'':15B ''databas'':35B ''differ'':14B ''ephemer'':26B ''fan'':28B ''fan-out'':27B ''handl'':82C ''js'':69C ''layer'':8B ''model'':48B ''name'':65B ''platform'':54B ''polici'':59B ''postgr'':16B,71C ''presenc'':37B,75C ''primit'':12B ''privat'':79C ''question'':60B ''realtim'':2A,4A,7B ''reconnect/resync'':81C ''rest'':51B ''ride'':44B ''rls'':77C ''rls-author'':76C ''rls/jwt'':47B ''state'':42B ''subscrib'':23B ''subscript'':56B ''supabas'':1A,3A,5B,68C ''supabase-j'':67C ''tabl'':20B ''three'':11B ''topic'':64B ''topic-nam'':63B ''touch'':33B ''websocket'':10B ''who-is-her'':38B ''without'':32B');

ALTER TABLE public.node_roles ENABLE TRIGGER USER;
ALTER TABLE public.technology_catalog ENABLE TRIGGER USER;

-- ── verification: the m5 canonical-gate checks, re-run against the seeded data ──
DO $$
DECLARE bad text; n int;
BEGIN
  SELECT count(*) INTO n FROM public.node_roles;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: node_roles is empty'; END IF;
  SELECT count(*) INTO n FROM public.deployment_targets;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: deployment_targets is empty'; END IF;
  SELECT count(*) INTO n FROM public.scope_archetypes;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: scope_archetypes is empty'; END IF;
  SELECT count(*) INTO n FROM public.cloud_provider_patterns;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: cloud_provider_patterns is empty'; END IF;
  SELECT count(*) INTO n FROM public.technology_catalog;
  IF n = 0 THEN RAISE EXCEPTION 'starter seed: technology_catalog is empty'; END IF;

  SELECT string_agg(DISTINCT t.id, ', ') INTO bad
  FROM public.technology_catalog t,
       jsonb_array_elements_text(COALESCE(t.role_affinities, '[]'::jsonb)) aff
  WHERE NOT EXISTS (SELECT 1 FROM public.node_roles r WHERE r.id = aff);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'starter seed: technologies with unresolved roles (invisible in the palette): %', bad;
  END IF;

  SELECT string_agg(DISTINCT nr.id, ', ') INTO bad
  FROM public.node_roles nr,
       jsonb_array_elements_text(
         CASE jsonb_typeof(nr.can_contain)
           WHEN 'array'  THEN nr.can_contain
           WHEN 'object' THEN COALESCE(nr.can_contain -> 'roleIds', '[]'::jsonb)
           ELSE '[]'::jsonb
         END) c
  WHERE NOT EXISTS (SELECT 1 FROM public.node_roles r WHERE r.id = c);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'starter seed: node_roles can_contain references missing roles: %', bad;
  END IF;

END $$;
